(window.GIM_TP=window.GIM_TP||{})["Z.AddendaI.0"]={"from":0,"a":[[["בְּרֵאשִׁית בָּרָא אֱלֹהִים \"אֶת \"הַשָׁמַיִם \"וְאֶת \"הָאָרֶץ רָאשֵׁי תֵיבִין אהו\"ה דְבֵּיהּ אִתְבְּרִיאוּ שְׁמַיָא וְאַרְעָ'א א\"ה בֵּיה אִתְבְּרִיאוּ שְׁמַיָא וָ\"ה בֵּיה אִתְבְּרִיאַת (אתבריאו) אַרְעָא וְכָל מָה דְּאִית בָּהּ וְהוּא יָהִיב תִּיאוּבְתָּא בְכָל אִילָנִין וְעִשְׂבִּין דִּי בְּאַרְעָא וְהוּא מָה שֶׁאָמְרוּ אֵין לְךָ כָּל עֵשֶׂב וְעֵשֶׂב מִלְמַטָּה שֶׁאֵין מְמוּנֶה עָלָיו מִלְמַעְלָה וְשׁוֹמֵר אוֹתוֹ שְׁמָכֶּה אוֹתוֹ וְאוֹמֵר לוֹ גְדָל שֶׁנֶּאֱמַר (איוב ל״ח:ל״ג) הֲיָדַעְתָּ חוּקוֹת שָׁמַיִם אִם תָּשִׂים מִשְׁטָרוֹ בָּאָרֶץ: :","מַתְנִיתִין קְטוּרֵי רָמָאֵי הוֹרְמָנֵי דְבּוּרְיְירֵי קְרִיבוּ שְׁמָעוּ מָאן מִנְּכוֹן דְסָלִיק וְנָחִית מָאן כְּנַשׁ רוּחָא בִּידוֹי יְקוּם וְיִנְדַּע בְּשַׁעְתָּא דְסָלִיק בִּרְעוּתָא דְרֵישָׁא חִיוָרָא לְמֶעְבָּד יְקָרָא לִיקָרֵיהּ סָלִיק חַד טְהִירוּ סְתִימוּ בְּרִישָׁא דְכֹלָא נָשָׁב בָּהּ וְאַפִּיק קוּמְרִין טְהִירִין מִתְחַבְּרָן כַּחֲדָא כֹּלָּא וּסְלִיקוּ וְנַחְתוּ וְאִתְעֲבִיד כֹּלָּא חַד","וְהַהוּא טְהִירוּ סְתִימוּ כַּד נָשִׁיב בָּהּ וְאַנְהִיר אִקְרֵי אהי\"ה הַהוּא טְהִירוּ סַלְקָא וְנַחְתָא וְזָרִיק זִיקִין נְצִיצִין וְאַנְשִיב בָּהּ (ואפיק בה) וְאַפִּיק חַד חֵילָא טְמִירָא וְאִיקְרֵי שְׁמֵיהּ אֲשֶׁר אהי\"ה בִּגְלִיפוּ טָמִיר וְסָתִים אִינוּן קוּמְרִין טְהִירִין דְּאִתְחַבְּרוּ מִגּוֹ חַד טִינָרָא סָתִים נָפְקֵי (נפקו) בְּגִלּוּפָא בְּחֵילָא דְּהַהוּא טְהִירוּ עִלָּאָה וְאִיקְרֵי יהו\"ה."],[],[[0,"","בְּרֵאשִׁית בָּרָא אֱלֹהִים \"אֵת \"הַשָּׁמַיִם \"וְאֵת \"הָאָרֶץ, רָאשֵׁי תֵבוֹת אהו\"ה, שֶׁבּוֹ נִבְרְאוּ שָׁמַיִם וָאָרֶץ. א\"ה - בּוֹ נִבְרְאוּ הַשָּׁמַיִם. ו\"ה - בּוֹ נִבְרְאָה הָאָרֶץ וְכָל מַה שֶּׁיֵּשׁ בָּהּ. וְהוּא נָתַן תְּשׁוּקָה בְּכָל הָאִילָנוֹת וְהָעֲשָׂבִים שֶׁבָּאָרֶץ, שֶׁהוּא מַה שֶּׁאָמְרוּ, אֵין לְךְ כָּל עֵשֶׂב וְעֵשֶׂב מִלְּמַטָּה שֶׁאֵין מְמֻנֶּה עָלָיו מִלְמַעְלָה וְשׁוֹמֵר אוֹתוֹ, שֶׁמַּכֶּה אוֹתוֹ וְאוֹמֵר לוֹ גְּדַל, שֶׁנֶּאֱמַר (איוב לח) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ:"],[1,"","מִשְׁנָה, קְשָׁרִים רָמִים, שָׂרִים מוֹשְׁלִים בַּמֶּמְשָׁלָה, קִרְבוּ וְשִׁמְעוּ. מִי מִכֶּם שֶׁעָלָה וְיָרַד, מִי כִנֵּס רוּחַ בְּיָדוֹ, יָקוּם וְיֵדַע, בְּשָׁעָה שֶׁעָלָה בְרָצוֹן שֶׁל הָרֹאשׁ הַלָּבָן לַעֲשׂוֹת כָּבוֹד לִכְבוֹדוֹ, עָלָה אוֹר אֶחָד נִסְתָּר בָּרֹאשׁ שֶׁל הַכֹּל, נָשַׁב בָּהּ וְהוֹצִיא קְלִפּוֹת מְאִירוֹת מִתְחַבְּרוֹת הַכֹּל כְּאֶחָד, וְעָלוּ וְיָרְדוּ וְנַעֲשָׂה הַכֹּל אֶחָד,"],[2,"","וְאוֹתוֹ אוֹר נִסְתָּר כְּשֶׁנָּשַׁב בָּהּ וְהֵאִיר נִקְרָא אֶהְיֶ\"ה. אוֹתוֹ אוֹר עָלָה וְיָרַד וְזָרַק נִיצוֹצוֹת וְנָשַׁב בָּהּ, וְהוֹצִיא כֹּחַ טָמִיר אֶחָד, וְנִקְרָא שְׁמוֹ אֲשֶׁר אֶהְיֶ\"ה. בַּחֲקִיקָה טְמִירָה וְנִסְתֶּרֶת, אוֹתָם קְלִפּוֹת מְאִירוֹת שֶׁהִתְחַבְּרוּ מִתּוֹךְ סֶלַע אֶחָד נִסְתָּר, יָצְאוּ בַחֲקִיקָה בְּכֹחַ שֶׁל אוֹתוֹ אוֹת עֶלְיוֹן, וְנִקְרָא יְהֹוָ\"ה."]]],[["תּוּ נָשִׁיב בָּהּ וְאַפִּיק זִיקִין נְצִיצִין זַרְקִין לְכָל עֵיבָר וְאַפִּיק חַד חֵילָא טְמִירָא נָצִיץ לְכָל סְטָר וְאִיקְרֵי א\"ל (חסד). תּוּ הַהוּא טְמִירָא טְהִירוּ סָתִים נָשָׁב בָּהּ וְסַלְקָא וְנַחְתָּא וְסַלִּיק בְּאֶלֶף וּמָאתָן קִיטוּרִין דְנוּרָא וְאַפִּיק חַד חֵילָא טְמִירָא וְאִיקְרֵי אֱלֹהִים וְדָא גְבוּרָה. מֵהַאי מִתְפַּשְּׁטָן חֵילִין טְמִירִין לַהָטִין לְכָל סְטָר מִנְּהוֹן דִּי מִתָקְנָן בְּתִיקוּנֵי יֵאוֹת וּמִנְהוֹן דִּי מִתָקְנָן בְּתִיקוּנֵי אַחֲרָא.","תּוּ נָשִׁיב בָּהּ וְאַפִּיק חַד חֵילָא טְמִירָא דְאִיתְקְרֵי יהו\"ה מִדַּת רַחֲמִים וְאִקְרֵי שָׁמַיִם (תפארת), וְקַיְימָא בֵּין תְרֵין חֵילִין דְאִיקְרוּן צבאו\"ת מֵהַאי נָפְקַן (נפקו) (נפרקו) כָּל חֵילִין וְכָל מַשִׁירְיָין עִילָאִין כָּל חַד וְחַד לִזְנֵיהּ לְקַיְימָא וּלְהַנְהַגָא עָלְמִין עָלֵיהּ כְּתִיב (תהלים פ\"ד) יְיָ צְבָאוֹת אַשְׁרֵי אָדָם בוֹטֵחַ בָּךְ:","כְּתִיב (בראשית א׳:ד׳) וַיִּקְרָא אֱלהִים לָאוֹר יוֹם וּכְתִיב וַיַּרְא אֱלהִים אֶת הָאוֹר כִּי טוֹב. תָּא חֲזֵי הַאי אוֹר דִּלְתַתָּא כַּד נָהִיר מֵחֵילָא דְאִתְיְיהִיב לֵיהּ מִטּוֹב דִלְעֵילָא","וּבְגִין כַּךְ מִנְיָן יְמוֹת הַחַמָּה שס\"ה מ\"ט שָבוּעִים, מִנְּהוֹן לָקֳבֵל הַאי דַרְגָּא דְצַדִיק דְאִיקְרֵי טוֹב וְאִיהוּ שְׁבִיעִי, וְיָנִיק מִנֵּיהּ הַאי שִׁמְשָׁא דִּלְתַתָּא. שִׁבְעָה שָׁבוּעִים שִׁבְעָה זִמְנִין לָקֳבֵל שִׁבְעָה שָׁבוּעִין ז' זִמְנִין דְאִיהוּ יָנִיק מֵאִימָא עִלָּאָה דְאִקְּרֵי יוֹבְלָא, וּלְקֳבְּלָה שְׁנֵי יוֹבֵל דִּלְתַתָּא","אִשְׁתָּאֲרוּ משס\"ה כ\"ב יוֹמִין לָקֳבֵל כ\"ב אַתְוָון דְאוֹרַיְתָא דְעַלְמָא תַתָּאָה אִתְקָיָּים עָלַיְיהוּ. דְהָא צַדִּיק דִלְעֵילָא תּוֹרָה שֶׁבִּכְתָב אִיקְרֵי וְכַד אִשְׁתַּלִּימוּ אִינוּן שס\"ה יוֹמִין תַּיְיבִין תִּנְיָינוּת לְקָבְּלָא מֵהַאי דַּרְגָּא דְּטוֹב דְּהָאי דַּרְגָּא וְכָל אִינוּן שֶׁבַע דַרְגִּין עִלָּאִין תַּיְיבִין תִּנְיָינוּת לְקָבְּלָא מֵאִימָא עִילָאָה","וְהַאי דַּרְגָּא דְסִיהֲרָא דְשָּׁלְטָא בְּלֵילְיָא יַנְקָא מֵהַאי דַּרְגָּא דְאִקְּרֵי שְׁכִינְתָּא תַתָּאָה דְיַנְקָא מֵהַהוּא צַדִּיק וּבְגִין דְּהַהוּא (צדיק) אִמְלֵי לָהּ מֵהֲנְהוּ תָּפְנוּקִין עִילָאִין וְיָנְקָא מִנֵּיהּ (איקרי) סִיהֲרָא. דִּכְּמָה דְּהָאי סִיהֲרָא תַתָּאָה לֵית לָהּ נְהוֹרָא מִגַּרְמָהּ אֶלָּא מַאי דְאִתְיְיהִיב לָהּ מִן שִׁמְשָׁא, הֲכִי נָמֵי הַהוּא דַּרְגָּא דִלְעֵילָא","וְהַאי דַּרְגָּא אִיקְרֵי יַמָא דְחָכְמְתָא לְעֵילָא וְקַיְימֵי תְרֵיסָר שִׁבְטִין עִלָּאִין קַדִּישִׁין תְלָתָא לִצְפוֹנָא וּתְלָתָא לְדָרוֹמָא וּתְלָתָא לְמַעַרְבָא וּתְלָתָא לְמָדִינְחָא, וְהַאי יַמָּא דְחָכְמְתָא עָלַיְיהוּ. וְלָקֳבְלֵיהוֹן לְתַתָּא י\"ב שִׁבְטִין קַיְימִין סָחְרָנֵי מַדְבְּחָא כְּהַאי גַּוְונָא. וְלָקֳבֵל הַאי דַּרְגָּא עֲבָד שְׁלֹמֹה יַמָּא לְתַתָּא עוֹמֵד עַל שְׁנֵים עֲשָׂר בָּקָר.","וְהַאי יַמָּא לְעֵילָא אִיקְרֵי יָ\"ם מָאי טַעְמָא אִקְרֵי יָם אֶלָּא בְּגִין הַהוּא דַרְגָּא דְצַדִיק דְאִמְלֵי לְהַאי יָם אִקְרֵי יוֹם דִּכְתִיב (בראשית א׳:ה׳) וַיִּקְרָא אֱלהִים לָאוֹר יוֹם וּכְתִיב (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק, וְהַאי נָהִיר בְּרָזָא דִּשְׁמָא קַדִּישָׁא דְבֵּיהּ אִמְלֵי לְהַאי יָם דְאִקְּרֵי הֵ\"א תַתָּאָה (בתראה דשמא קדישא).","הֲדָא הוּא דִּכְתִיב (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֵל הַיָּם כָּ\"ל דָּא דַּרְגָּא דְצַדִיק דְאִיקְרֵי כָּל בְּגִין דְכָל תָּפְנוּקִין נַפְקִין מִנֵּיהּ הַנְּחָלִים אִלֵּין חֲמֵשׁ דַרְגִּין דְּעִמֵּיהּ הוֹלְכִים אֵל הַיָּם לְאִמְלֵי (לממלי) לָהּ","וְהַאי דַּרְגָּא אִקְרֵי בַּת שֶׁבַע וְכַד נָהִיר הַאי צַדִּיק לְהַאי דַּרְגָּא בְּרָזָא דְּשִׁבְעָה שָׁבוּעִין שֶׁבַע זִמְנִין שִׁמְשָׁא תַתָּאָה נָהִיר בְּרָזָא דְשֶׁבַע שָׁבוּעִין שֶׁבַע זִמְנִין לְסִיהֲרָא.","בְּגִין כַּךְ שְׁנָת הַלְּבָנָה שנ\"ה יוֹמִין, מ\"ט שָׁבוּעִין מִנְּהוֹן לָקֳבֵל הַאי דַּרְגָּא שְׁבִיעָאָה יַמָּא עִילָאָה דְנָהַרָא מִצַּדִּיק בְּמ\"ט שָׁבוּעִין נְהוֹרִין עִלָּאִין אִשְׁתָּאֲרוּ תְרֵיסָר יוֹמִין לְחוּשְׁבָּן שנ\"ה לְקֳבְּלֵי י\"ב שִׁבְטִין דְסָחְרָנֵי הַאי יַמָּא לְמִיטַר מַטְּרַת מַשְׁכְּנָא בִּתְרֵיסַר תַרְעִין עִלָּאִין דְּאִית בִּירוּשָׁלַיִם עִילָאָה (ומאורחא) וְאוֹרְחָא דְּאִינּוּן תַרְעִין עִלָּאִין יַנְקִין אִינוּן שִׁבְטִין מֵאִימָא תַתָּאָה כָּל חַד לְסִטְרֵיהּ כְּדְקָא חֲזֵי לֵיהּ הֲדָא הוּא דִּכְתִיב (יחזקאל מ״ח:ל״א) שַׁעַר יְהוּדָה אֶחָד","וְעַל דָּא כְּתִיב (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי דָּא דַרְגָּא דְצַדִיק דְּנָהִיר בְּחֵילָא דִּשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו לְאַנְהֲרָא לְהַהוּא אֲתַר דְאִקְּרֵי כְּבוֹדִי בְּרָאתִיו, וְדָא יַמָּא דְחָכְמְתָא דְאִקְּרֵי כְּבוֹד ה' דְאִתְגְּלֵי בְּמַשְׁכְּנָא. יְּצָרְתִיו דָּא רָזָא דְּיוֹם דִּלְתַתָּא דְּאִיהוּ לָקֳבֵל כָּ\"ל דִלְעֵילָא וְעַל דָּא כְּתִיב (ישעיהו מ״ה:ז׳) יוֹצֵר אוֹר וְהַאי צַדִּיק דִּלְעֵילָא לָא כְּתִיב בֵּיהּ יְצִירָה עַד דְּיִתְגַלֵּי עֲבִידְתֵּיהּ לְתַתָּא וְנָהִיר עַלְמָא תַתָּאָה מִנֵּיהּ.","אַף עֲשִׂיתִּיו דָּא סִיהֲרָא לְתַתָּא הֲדָא הוּא דִּכְתִיב וּבוֹרֵא חֹשֶׁךְ כַּד אִתְחַבָּרוּ כְּדֵין עוֹשֶׂה שָׁלוֹם שְׁלָמָא לְעַלְמָא, הֲדָא הוּא דִּכְתִיב (בראשית א׳:ה׳) וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. כְּדֵין יִחוּדָא לְעֵילָא יִחוּדָא לְתַתָּא שְׁלָמָא לְעֵילָא שְׁלָמָא לְתַתָּא.","כְּגווָֹנָא דָּא יוֹסֵף לְתַתָּא דְהָא אֲחִיד בְּצַדִיק דִּלְעֵילָא, וְכַד אִשְׁתְּלִים לְתַתָּא אוֹסִיף שְׁלָמָא בְּכֻלְּהוּ עָלְמִין וּבְכָל יוֹמִין עִלָּאִין. כְּתִיב הָכָא (בראשית ט׳:כ״ו\"ל) וַיְהִי כְּדָבְּרָה אֶל יוֹסֵף יוֹם יוֹם וּכְתִיב הֲתָם (תהילים ס״ח:כ׳) בָּרוּךְ יְיָ יוֹם יוֹם יַעֲמוֹס לָנוּ בְּגִין דְלָא (כד לא) שָׁמַע לָהּ לְאֵשֶׁת פּוֹטִיפַר יוֹם יוֹם, כְּדֵין יוֹמִין עִלָּאִין בִּשְׁלָמָא וּבִרְכָתָא בְּכֻלְּהוּ עָלְמִין.","(בראשית א׳:י״ד) וַיֹּאמֶר אֱלֹהִים יְהִי מְאוֹרוֹת בִּרְקִיעַ הַשָׁמַיִם תַמָּן תָנֵינָן אָמַר רִבִּי יִצְחָק מַאי דִכְתִיב (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעֲיָתִי וּמוּם אֵין בָּךְ תָּא חֲזֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ עֲשָׂאוֹ מֵאוֹתוֹ הָאוֹר הַנֶאֱצָל לְמָעְלָה וּבָרָא אֶת הַשָׁמַיִם מֵאוֹתוֹ רָקִיע (האור) הָרִאשׁוֹן שֶׁהֵכִינוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּבְרָאוֹ בַּתְחִילָה וְאוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל שְׁאָר הַשָׁמַיִם (נ\"א הרקיעים) שְׁנִתְהַווּ מִמֶּנּוּ."],[],[[0,"","עוֹד נָשַׁב בָּהּ וְהוֹצִיא זִיקִים נוֹצְצִים זוֹרְקִים לְכָל עֵבֶר, וְהוֹצִיא כֹּחַ אֶחָד טָמִיר שֶׁנּוֹצֵץ לְכָל צַד וְנִקְרָא אֵ\"ל. עוֹד אוֹתוֹ אוֹר טָמִיר נִסְתָּר נָשַׁב בָּהּ, וְעָלָה וְיָרַד וְעָלָה בְּאֶלֶף וּמָאתַיִם קִשּׁוּרִים שֶׁל אֵשׁ, וְהוֹצִיא כֹּחַ אֶחָד טָמִיר וְנִקְרָא אֱלֹהִים, וְזוֹ הַגְּבוּרָה. מִזֶּה מִתְפַּשְּׁטִים כֹּחוֹת טְמִירִים לוֹהֲטִים לְכָל צַד, מֵהֶם שֶׁמְּתֻקָּנִים בְּתִקּוּנִים יָפִים, וּמֵהֶם שֶׁמְּתֻקָּנִים בְּתִקּוּנִים אֲחֵרִים."],[1,"","עוֹד נָשַׁב בָּהּ וְהוֹצִיא כֹּחַ טָמִיר אֶחָד שֶׁנִּקְרָא יְהֹוָ\"ה, מִדַּת רַחֲמִים, וְנִקְרָא שָׁמַיִם. וְעוֹמֵד בֵּין שְׁנֵי חֲיָלוֹת שֶׁנִּקְרָאִים צְבָאוֹת. מִזֶּה יָצְאוּ כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת הָעֶלְיוֹנִים, כָּל אֶחָד וְאֶחָד לְמִינוֹ לְקַיֵּם וּלְהַנְהִיג אֶת הָעוֹלָמוֹת, עָלָיו כָּתוּב (תהלים פד) ה' צְבָאוֹת אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ:"],[2,"","כָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, וְכָתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. בֹּא רְאֵה, אוֹר זֶה שֶׁלְּמַטָּה, כְּשֶׁמֵּאִיר מִכֹּחַ שֶׁנִּתַּן לוֹ מֵהַטּוֹב שֶׁלְּמַעְלָה,"],[3,"","וְלָכֵן מִנְיַן יְמוֹת הַחַמָּה שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה, אַרְבָּעִים וְתִשְׁעָה שָׁבוּעוֹת. מֵהֶם כְּנֶגֶד דַּרְגָּה זוֹ שֶׁל צַדִּיק שֶׁנִּקְרָא טוֹב, וְהוּא שְׁבִיעִי, וְיוֹנֵק מִמֶּנּוּ הַשֶּׁמֶשׁ הַזֶּה שֶׁלְּמַטָּה. שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים, כְּנֶגֶד שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים, שֶׁהוּא יוֹנֵק מֵהָאֵם הָעֶלְיוֹנָה שֶׁנִּקְרֵאת יוֹבֵל, וּכְנֶגֶד שְׁנוֹת יוֹבֵל שֶׁלְּמַטָּה."],[4,"","נִשְׁאֲרוּ מִשְּׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה עֶשְׂרִים וּשְׁנַיִם יָמִים, כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁל הַתּוֹרָה שֶׁהָעוֹלָם הַתַּחְתּוֹן עוֹמֵד עֲלֵיהֶם. שֶׁהֲרֵי צַדִּיק שֶׁלְּמַעְלָה נִקְרָא תּוֹרָה שֶׁבִּכְתָב, וּכְשֶׁהִשְׁתַּלְּמוּ אוֹתָם שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה יָמִים, שָׁבִים שֵׁנִית לְקַבֵּל מִדַּרְגָּה זוֹ שֶׁל טוֹב, שֶׁדַּרְגָּה זוֹ וְכָל אוֹתָן שֶׁבַע דְרָגוֹת עֶלְיוֹנוֹת שָׁבוֹת שֵׁנִית לְקַבֵּל מִן הָאֵם הָעֶלְיוֹנָה,"],[5,"","וְהַדַּרְגָּה הַזּוֹ שֶׁהַלְּבָנָה שֶׁשּׁוֹלֶטֶת בַּלַּיְלָה יוֹנֶקֶת מֵהַדַּרְגָּה הַזּוֹ שֶׁנִּקְרֵאת שְׁכִינָה תַחְתּוֹנָה, שֶׁיּוֹנֶקֶת מֵאוֹתוֹ צַדִּיק. וּבִגְלַל שֶׁאוֹתוֹ צַדִּיק מְמַלֵּא אוֹתָהּ מֵאוֹתָם תַּפְנוּקִים עֶלְיוֹנִים וְיוֹנֶקֶת מִמֶּנּוּ, (נקראת) לְבָנָה. שֶׁכְּמוֹ שֶׁהַלְּבָנָה הַתַּחְתּוֹנָה הַזּוֹ אֵין לָהּ אוֹר מֵעַצְמָהּ אֶלָּא רַק מַה שֶּׁנִּתָּן לָהּ מֵהַשֶּׁמֶשׁ, כָּךְ גַּם אוֹתָהּ דַּרְגָּה שֶׁלְּמַעְלָה,"],[6,"","וְדַרְגָּה זוֹ נִקְרֵאת יָם הַחָכְמָה לְמַעְלָה. וְעוֹמְדִים שְׁנֵים עָשָׂר שְׁבָטִים עֶלְיוֹנִים קְדוֹשִׁים, שְׁלֹשָׁה לַצָּפוֹן וּשְׁלֹשָׁה לַדָּרוֹם, וּשְׁלֹשָׁה לַמַּעֲרָב וּשְׁלֹשָׁה לַמִּזְרָח, וְיָם הַחָכְמָה הַזֶּה עֲלֵיהֶם. וּכְנֶגְדָּם לְמַטָּה שְׁנֵים עָשָׂר שְׁבָטִים עוֹמְדִים סְבִיב הַמִּזְבֵּחַ כַּדֻּגְמָה הַ את. וּכְנֶגֶד הַדַּרְגָּה הַזּוֹ עָשָׂה שְׁלֹמֹה הַיָּם שֶׁלְּמַטָּה עוֹמֵד עַל שְׁנֵים עָשָׂר בָּקָר,"],[7,"","וְהַיָּם הַזֶּה לְמַעְלָה נִקְרָא יָ\"ם. מָה הַטַּעַם נִקְרָא יָם? אֶלָּא מִשּׁוּם אוֹתָהּ דַּרְגָּה שֶׁל צַדִּיק שֶׁמְּמַלֵּאת הַיָּם הַזֶּה נִקְרָא יוֹם, שֶׁכָּתוּב (בראשית א) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, וְכָתוּב (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק, וְזֶה מֵאִיר בְּסוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁבּוֹ מְמַלֵּא לַיָּם הַזֶּה שֶׁנִּקְרָא הֵ\"א תַחְתּוֹנָה (אחרונה של השם הקדוש)."],[8,"","זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶת הַיָּם, וְכָל זֶה דַּרְגַּת הַצַּדִּיק שֶׁנִּקְרֵאת כֹּל, מִשּׁוּם שֶׁכָּל הַתַּפְנוּקִים יוֹצְאִים מִמֶּנּוּ. הַנְּחָלִים אֵלּוּ חֲמֵשׁ הַדְּרָגוֹת שֶׁעִמּוֹ, הוֹלְכִים אֶל הַיָּם לְמַלֵּא אוֹתָהּ,"],[9,"","וְזוֹ הַדַּרְגָּה נִקְרֵאת בַּת שֶׁבַע. וּכְשֶׁמֵּאִיר הַצַּדִּיק הַזֶּה לַדַּרְגָּה הַזּוֹ בְּסוֹד שֶׁל שִׁבְעָה שָׁבוּעוֹת שֶׁבַע פְּעָמִים הַשֶּׁמֶשׁ הַתַּחְתּוֹנָה מְאִירָה בְּסוֹד שֶׁל שִׁבְעָה שָׁבוּעוֹת, שֶׁבַע פְּעָמִים לַלְּבָנָה."],[10,"","מִשּׁוּם כָּךְ שְׁנַת הַלְּבָנָה שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים וַחֲמִשָּׁה יָמִים, אַרְבָּעִים וְתִשְׁעָה שָׁבוּעוֹת, מֵהֶם כְּנֶגֶד הַדַּרְגָּה הַשְּׁבִיעִית הַזּוֹ הַיָּם הָעֶלְיוֹן, שֶׁמְּאִירָה מֵהַצַּדִּיק בְּתִשְׁעָה וְאַרְבָּעִים שָׁבוּעוֹת אוֹרוֹת עֶלְיוֹנִים. נִשְׁאֲרוּ תְרֵיסַר ימִים לְחֶשְׁבּוֹן שְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וַחֲמִשִּׁים כְּנֶגֶד שְׁנֵים עָשָׂר שְׁבָטִים שֶׁסְּבִיב הַיָּם הַזֶּה לִשְׁמֹר מִשְׁמֶרֶת הַמִּשְׁכָּן בִּתְרֵיסַר שְׁעָרִים עֶלְיוֹנִים שֶׁיֵּשׁ בִּירוּשָׁלַיִם הָעֶלְיוֹנָה, (ומדרך) וְדֶרֶךְ אוֹתָם שְׁעָרִים עֶלְיוֹנִים יוֹנְקִים אוֹתָם שְׁבָטִים מֵאִמָּא תַחְתּוֹנָה, כָּל אֶחָד לְצִדּוֹ כָּרָאוּי לוֹ, זֶהוּ שֶׁכָּתוּב (יחזקאל מח) שַׁעַר יְהוּדָה אֶחָד,"],[11,"","וְעַל זֶה כָּתוּב (ישעיה מג) כֹּל הַנִּקְרָא בִשְׁמִי, זוֹ דַּרְגַּת צַדִּיק שֶׁמֵּאִיר בַּכֹּחַ שֶׁל שְׁמִי. וְלִכְבוֹדִי בְּרָאתִיו - לְהָאִיר לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא כְּבוֹדִי בְּרָאתִיו, וְזֶהוּ יָם הַחָכְמָה שֶׁנִּקְרָא כְּבוֹד ה' שֶׁנִּתְגַּלָּה בַּמִּשְׁכָּן. יְצַרְתִּיו - זֶה סוֹד הַיּוֹם שֶׁלְּמַטָּה שֶׁהוּא כְּנֶגֶד כֹּל שֶׁלְּמַעְלָה, וְעַל כָּךְ כָּתוּב (שם מה) יוֹצֵר אוֹר. וּבַצַּדִּיק הַזֶּה שֶׁלְּמַעְלָה לֹא כָתוּב בּוֹ יְצִירָה, עַד שֶׁיִּתְגַּלֶּה מַעֲשֵׂהוּ לְמַטָּה וּמֵאִיר לָעוֹלָם שֶׁלְּמַטָּה מִמֶּנּוּ."],[12,"","אַף עֲשִׂיתִיו - זוֹ הַלְּבָנָה לְמַטָּה, זֶהוּ שֶׁכָּתוּב וּבוֹרֵא חֹשֶׁךְ. כְּשֶׁהִתְחַבְּרוּ, אָז עוֹשֶׂה שָׁלוֹם, שָׁלוֹם לָעוֹלָם, זֶהוּ שֶׁכָּתוּב (בראשית א) וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. וְאָז יִחוּד לְמַעְלָה יִחוּד לְמַטָּה, שָׁלוֹם לְמַעְלָה שָׁלוֹם לְמַטָּה."],[13,"","כְּמוֹ זֶה יוֹסֵף לְמַטָּה, שֶׁהֲרֵי אָחוּז בַּצַּדִּיק שֶׁלְּמַעְלָה. כְּשֶׁמִּשְׁתַּלֵּם לְמַטָּה, מוֹסִיף שָׁלוֹם בְּכָל הָעוֹלָמוֹת וּבְכָל הַיָּמִים הָעֶלְיוֹנִים. כָּתוּב כָּאן (שם טל) וַיְהִי כְּדַבְּרָה אֶל יוֹסֵף יוֹם יוֹם, וְכָתוּב שָׁם (תהלים סח) בָּרוּךְ ה' יוֹם יוֹם יַעֲמָס לָנוּ. מִשּׁוּם שֶׁלֹּא שָׁמַע לְאֵשֶׁת פּוֹטִיפַר יוֹם יוֹם, אָז יָמִים הָעֶלְיוֹנִים בְּשָׁלוֹם וּבְרָכוֹת בְּכָל הָעוֹלָמוֹת:"],[14,"","וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם (בראשית א), שָׁם שָׁנִינוּ, אָמַר רַבִּי יִצְחָק, מַה זֶּה שֶׁכָּתוּב (שיר ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵיךְ בָּךְ בֹּא? רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, עֲשָׂאוֹ מֵאוֹתוֹ הָאוֹר הַנֶּאֱצָל מִלְמַעְלָה, וּבָרָא אֶת הַשָּׁמַיִם מֵאוֹתוֹ רָקִיעַ הָרִאשׁוֹן שֶׁהֱכִינוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וּבְרָאוֹ בַּתְּחִלָּה, וְאוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל שְׁאָר הָרְקִיעִים שֶׁנִּתְהַוּוּ מִמֶּנּוּ."]]],[["וְאָמַר רַב יְהוּדָה אָמַר רַב אוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל הַמְּאוֹרוֹת מֵאוֹתוֹ הָאוֹר שְׁמְקַבֵּל (מלמעלה) לְמַעְלָה וּכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ רָקִיעַ נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמְּאוֹרוֹת וְהִנִיחָם בְּאוֹתוֹ רָקִיעַ הַנִּקְרָא רְקִיעַ הַשָׁמַיִם, וְאוֹתוֹ רָקִיעַ נִתְהַוָוה מִן הַשָׁמַיִם","דְּאָמַר רִבִּי יְהוּדָה אָמַר רַב הָרָקִיעַ הַעֶלְיוֹן הוֹלִיד אֶת הַשָׁמַיִם אֲשֶׁר תַּחְתָּיו, וְהַשָׁמַיִם הוֹלִידוּ הַאי רָקִיעַ וְנִקְרָא רָקִיעַ הַשָׁמַיִם וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא הֲנֵי מְאוֹרוֹת וּנְתָנָם בּוֹ. הֲדָא הוּא דִכְתִיב (בראשית א׳:י״ז) וַיִּתֵּן אוֹתָם אֱלהִים בִּרְקִיעַ הַשָׁמַיִם.","אָמַר רִבִּי יִצְחָק עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הֲנֵי מְאוֹרוֹת וְהִנִיחָם בְּיָד (נ\"א בזה) הָרָקִיעַ לִהְיוֹת מֶמְשָׁלָה עַל הָאָרֶץ וּלְהִשְׁתָמֵשׁ בָּהֶם הַבְּרִיוֹת וּשְׁנֵיהֶם נָתְנוּ אוֹרָם בְּשָׁוֶה. אָמְרָה הַלְּבָנָה אֵין נָאָה לְהִשְׁתָמֵשׁ וּלְהִתְנָהֵג בִּשְׁנִי כְּתָרִים בְּשָׁוֶה. מָה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הִמְעִיט אוֹתָהּ וְהַיְינוּ הַכָּפַּרָה שֶׁל שֵׂעִיר רֹאשׁ חוֹדֶשׁ שֶׁנְּאֱמַר בּוֹ (במדבר כ״ח:ט״ו) חַטָּאת לַיְיָ.","אָמַר רִבִּי יַעֲקֹב וּבְכַמָּה אֲתַר תָנֵינָן דָּא וְלָא אִתְיָישְׁבָא בְּלִבָּאי עִנְיָינָא, כַּד אֲתָא רַב נַחְמָן אָתוּ וְשָׁיְילוּהוּ, מִּשִׁמְעָן אָמַר (נ\"א כמשמעו). אָמַר רִבִּי יְהוּדָה לְרִבִּי יַעֲקֹב כְּלוּם אַתָּה רוֹצֶה לַעֲבוֹר עַל דִּבְרֵי חַבֵירֶיךָ, אִשְׁתִּיק.","רִבִּי יוֹסֵי בְּרִבִּי שִׁמְעוֹן בֵּן לְקוּנְיָא אֲתָא לְמֵחמֵי לְרִבִּי אֶלְעָזָר חֲתָנֵיהּ (שם ע\"ד) נַפְקַת בְּרַתֵּיהּ וְשַׁקְלָת יְדוֹהִי לְנַשְׁקָא לְהוֹן, וְאֲמָר לָה לְכִי וּמַעֲטִי אֶת עֲצְמֵךְ מִקָמֵיהּ בַּעֲלִיךְ דְּאִיהוּ קַדִּישָׁא. שָׁמַע רִבִּי אֶלְעָזָר. אָמַר, כְּעָן יָדַעְנָא אֲנָא מַדְכָּרְנָא מִלָּה חַד דְאִיהִי מַרְגְלָא יַקִּירָא דְאִתְמָר עַל סִיהֲרָא כְּדְתָנֵינָן דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לְסִיהֲרָא לְכִי וּמַעֲטִי אֶת עֲצְמֵךְ דְחַשְׁבָה סִיהֲרָא דְלָא אִתְיְיהִיב שׁוּלְטָנָא לָהּ, אָמַר לֵיהּ חַמוֹהִי, אֲנָא כַּךְ שְׁמַעְנָא וְכַךְ הֲוָה מְסוּדָר בְּלִבָּאי וּבְגִין דְלָא אֲעְבָּר עַל דַעֲתוֹהִי דְּחַבְרָאי שָׁתַקְתִי.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר (דברים ל״ג:כ״ט) אֲשְׁרֶיךָ יִשְׂרָאֵל מִי כָּמוֹךָ עַם נוֹשָׁע בַּיְיָ מָגֵן עֱזְרֵךָ וַאֲשֶׁר חֶרֶב גָאֲוָתֶּךָ, אָמַר רִבִּי אֶלְעָזָר וְכִי גָאֲוַתָן שֶׁל יִשְׂרָאֵל בַּחֶרֶב הוּא, לָאו הֲכִי, דְהָא חֶרֶב לְעֵשָׂו אִתְיְהִיבַת דִכְתִיב (בראשית כ״ז:מ׳) וְעַל חַרְבְּךָ תִּחְיֶה","אֶלָּא הֲכִי שְׁמַעְנָא מֵאַבוֹי דְּאִלֵין תַּלְמִידֵי חֲכָמִים דְּכָד שַׁמְעִין מִלָּה וְלָא אִתְיָישְׁבָא בְּלִבְּהוֹן וְאִינּוּן מַגִּיחֵי קְרָבָא דֵין עִם דֵין כְּאִינּוּן מַגִּיחֵי קְרָבָא בְּחַרְבָּא וּבַּעְיָין לְקַטְלָא דֵין לְדֵין עֲלָהּ.","וּמִלָּה דָּא דְּקָא אַמְרֵי חַבְרָנָא כַּךְ הִיא וְכַךְ גָּזָרְנָא בְּרָזָא דְּמַתְנִיתִין דִילָן. דְּכָד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לְשִׁמְשָׁא וּלְסִיהֲרָא גָּזָר עַל שִׁמְשָׁא לְמֶהֱוֵי שׁוּלְטָנָא דְעֵשָׂו וְעַל סִיהֲרָא לְמֶהוֵי בְּעָלְמָא דֵין שׁוּלְטָנָא דְיַעֲקֹב וּמָנֵי עֲלֵיהוֹן תַּקִּיפִין רַבְרְבִין עַד דְּיֵיתוּן תְרֵין אוּמַיָּיא אִלֵּין.","וְהַהוּא רַבְרְבָא דְאִתְמֶנִי עַל סִיהֲרָא בְּגִין אוּמָה דְיַעֲקֹב בָּעָא מִן קוּדְשָׁא בְּרִיךְ הוּא דְיִתְיְּיהַב שׁוּלְטָנָא לְסִיהֲרָא בְּעָלְמָא דֵין כְּלוֹמַר אוּמָה דְיַעֲקֹב. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וְכִי מָה אֲנָא בָּעֵי אוּמָה דְיַעֲקֹב (חסר כאן). אֶלָּא בְּעַלְמָא דְאָתֵי לְשַׁלְטָאָה בְּהוּ עַל כָּל אוּמַיָּיא אֲבָל בְּעָלְמָא דֵין לְכִי וּמַעֲטִי אֶת עֲצְמֶךְ וְהִשְׁתַעְבְּדִי בְּגָלוּתָא לְמִזְכֵּי לָךְ בְּעַלְמָא דְאָתֵי.","וְכַד אָתוּ אוּמָה דְיַעֲקֹב וְאִתְרָעֲמוּ קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, עַל דְאִתְנְטָל מִנְּהוֹן שׁוּלְטָנָא וְאִתְיְיהִיב לְעֵשָׂו. אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְכִי מָה אַתּוּן בָעָאן שׁוּלְטָנָא בְּעַלְמָא דֵין דְהָא אֲנָא עֲרַבְנָא לְשַׁלְטָאָה לְכוּ לְעַלְמָא דְאָתֵי עַל כָּל אוּמַיָּיא וּבְגִין כַּךְ הָבִיאוּ כַּפָרָה עֲלַי כְּלוֹמַר עַל אוֹתָהּ הַבְטָחָה שֶׁאֲנִי עָרֶב לְכוּ וְהָבִיאוּ כַּפָרָה וְהִתְעֲסְקוּ בַּתּוֹרָה וְעָלַי לָתֵת לָכֶם שָׂכָר טוֹב וְעָלַי לְהַשְׁלִיט אֶתְכֶם עַל כָּל הָעַמִּים שֶׁעַל מְנָת כֵּן מִיעֲטְתִי אֶת הַיָרֵחַ בָּעוֹלָם","אֲתָא רִבִּי יוֹסֵי וּנְשָׁקֵיהּ בְּרֵישֵׁיהּ וְקָרָא לִבְרַתֵּיהּ וְאָמַר לַהּ קוּטְפִיזָא דְּנְהוֹרִיתָא וּבוֹצִינָא דְּאִתְפָּרְשָׁא בְּטַבְוָון אִית גָּבָּךְ, זַכָּאָה אֲנְתְ וְזָכַּאָה חוּלָקֵיךְ וְזַכָּאָה חוּלָקִי דְזָכֵינָא לְמֶחֱמֵי כַּךְ.","רִבִּי יוֹנָתָן אָמַר זָכוּ יִשְׂרָאֵל דְנָהִיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא וְלֵית אֲנָן צְרִיכִים לְבוֹצִינָא אַחֲרָא דִּכְתִיב (ישעיהו ס׳:י״ט) וְהָיָה לָּךְ יְיָ לְאוֹר עוֹלָם.","אָמַר רִבִּי אֲבְהוּ, כֵּיוָן שְׁנִתְחַלֶף לְהוּ שׁוּלְטָנָא אִינוּן מוֹנִין חוּשְׁבָּנָא לְסִיהֲרָא דְבָּהּ מַנְהגֶת נוֹהֵג כְּצֹאן יוֹסֵף וּמוּם אֵין בָּךְ דְלָא אִשְׁתְּכַח בָּהּ גִּרְעוֹנָה בְּגִין מוֹעֲדִין וְזִמְנִין ע\"כ:","\u0003רַעֲיָא מְהֵימְנָא\u0004 אָמַר לֵיהּ בּוֹצִּינָא קַדִּישָׁא בָּתָר דְּאָמַר (בראשית א׳:כ״ז) נַעֲשֶׂה אָדָם בְּצַּלְמֵנוּ כִּדְמוּתֵנוּ מַאי נִיהוּ דְּאָמַר לְבָתַר וַיִּבְרָא אֱלֹהִים אֶת הַאָדָם בְּצַּלְמוֹ, אָמַר לֵיהּ מָה דְּאוּקְמוּהַ עַל דָּא מָארֵי מַתְנִיתִין דְּמִנְהוֹן אָמְרוּ (הוא) נִבְרָא וּמִנְּהוֹן (אמרו) לָא נִבְרָא וְקוּדְשָׁא בְּרִיךְ הוּא בָּרָא לֵיהּ, דִּכְתִיב (בראשית א׳:כ״ז) וַיִּבְרָא אֱלהִים אֶת הַאָדָם בְּצַּלְמוֹ. אָמַר לֵיהּ אִי הֲכִי אִיהוּ לָא יָהִיב חֳלָקָא בְּיָד חַד מִנַּיְיהוּ וְלָא אִתְעֲבִיד בְּדִיּוּקְנָא דִילְהוֹן אֶלָּא בְּאִיקוּנִין דְּמַלְכָּא בְּצַּלְמוֹ כִּדְמוּתוֹ דְּאִיהוּ צֶּלֶם וּדְמוּת תַבְנִיתוֹ. אָמַר הֲכִי אִשְׁתְּמוֹדָע.","אָמַר חַס וְשָׁלוֹם. אֶלָּא אֲנָא אִימָא דְּאִתְּבְּרֵי בְּכֹלָּא וְאַשְׁלִיטֵיהּ עַל כֹּלָּא. דְּאִי הֲוָה יָהִיב כָּל חַד חוּלָקֵיהּ בְּזִמְנָא דְהֲוָה כַּעֲסֵיהּ עָלֵיהּ כָּל חַד הֲוָה נָטִיל חוּלָקֵיהּ מִנֵּיהּ, כִּי בְּמַה נְחֶשָׁב הוּא."],[],[[0,"","וְאָמַר רַב יְהוּדָה אָמַר רַב, אוֹתוֹ הָרָקִיעַ הוֹלִיד כָּל הַמְּאוֹרוֹת מֵאוֹתוֹ הָאוֹר שֶׁמְּקַבֵּל מִלְמַעְלָה, וּכְשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ רָקִיעַ, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמְּאוֹרוֹת וְהִנִּיחָם בְּאוֹתוֹ רָקִיעַ הַנִּקְרָא רְקִיעַ הַשָּׁמַיִם, וְאוֹתוֹ רָקִיעַ נִתְהַוָּה מִן הַשָּׁמַיִם."],[1,"","שֶׁאָמַר רַבִּי יְהוּדָה אָמַר רַב, הָרָקִיעַ הָעֶלְיוֹן הוֹלִיד אֶת הַשָּׁמַיִם אֲשֶׁר תַּחְתָּיו, וְהַשָּׁמַיִם הוֹלִידוּ אֶת הָרָקִיעַ הַזֶּה, וְנִקְרְאוּ רְקִיעַ הַשָּׁמַיִם, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא הַמְּאוֹרוֹת הַלָּלוּ וּנְתָנָם בּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית א) וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם."],[2,"","אָמַר רַבִּי יִצְחָק, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הַמְּאוֹרוֹת הַלָּלוּ וְהִנִּיחָם בְּזֶה הָרָקִיעַ לִהְיוֹת מֶמְשָׁלָה עַל הָאָרֶץ וּלְהִשְׁתַּמֵּשׁ בָּהֶם הַבְּרִיּוֹת, וּשְׁנֵיהֶם נָתְנוּ אוֹרָם בְּשָׁוֶה. אָמְרָה הַלְּבָנָה, אֵין נָאֶה לְהִשְׁתַּמֵּשׁ וּלְהִתְנַהֵג בִּשְׁנֵי כְתָרִים בְּשָׁוֶה. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִמְעִיט אוֹתָהּ, וְהַיְנוּ הַכַּפָּרָה שֶׁל שְׂעִיר רֹאשׁ חֹדֶשׁ שֶׁנֶּאֱמַר בּוֹ (במדבר כח) חַטָּאת לַה'."],[3,"","אָמַר רַבִּי יַעֲקֹב, בְּכַמָּה מְקוֹמוֹת שָׁנִינוּ אֶת זֶה, וְלֹא הִתְיַשֵּׁב בְּלִבִּי הָעִנְיָן. כְּשֶׁבָּא רַב נַחְמָן, בָּאוּ וְשָׁאֲלוּ אוֹתוֹ. אָמַר כְּמַשְׁמָעוֹ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יַעֲקֹב, כְּלוּם אַתָּה רוֹצֶה לַעֲבֹר עַל דִּבְרֵי חֲבֵרֶיךְ? שָׁתַק."],[4,"","רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא בָּא לִרְאוֹת אֶת רַבִּי אֶלְעָזָר חֲתָנוֹ. יָצְאָה בִתּוֹ וְלָקְחָה יָדָיו לְנַשֵּׁק אוֹתָם. אָמַר לָהּ, לְכִי וּמַעֲטִי עַצְמֵךְ מִלִּפְנֵי בַעְלֵךְ, שֶׁהוּא קָדוֹשׁ. שָׁמַע רַבִּי אֶלְעָזָר וְאָמַר, עַכְשָׁו יָדַעְתִּי, אֲנִי נִזְכָּר בְּדָבָר אֶחָד, שֶׁהִיא מַרְגָּלִית יְקָרָה שֶׁנֶּאֱמַר עַל הַלְּבָנָה, כְּמוֹ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לַלְּבָנָה לְכִי וּמַעֲטִי אֶת עַצְמֵךְ, שֶׁחָשְׁבָה הַלְּבָנָה שֶׁלֹּא נִתָּן לָהּ שִׁלְטוֹן. אָמַר לוֹ חָמִיו, כָּךְ אֲנִי שָׁמַעְתִּי וְכָךְ הָיָה מְסֻדָּר בְּלִבִּי, וּכְדֵי שֶׁלֹּא לַעֲבֹר עַל דַּעַת חֲבֵרַי שָׁתַקְתִּי."],[5,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ עַם נוֹשַׁע בַּה' מָגֵן עֶזְרֶךְ וַאֲשֶׁר חֶרֶב גַּאֲוָתֶךְ. אָמַר רַבִּי אֶלְעָזָר, וְכִי גַאֲוָתָם שֶׁל יִשְׂרָאֵל בַּחֶרֶב הוּא? לֹא כָּךְ! שֶׁהֲרֵי הַחֶרֶב נִתְּנָה לְעֵשָׂו, שֶׁכָּתוּב (בראשית כז) וְעַל חַרְבְּךְ תִחְיֶה."],[6,"","אֶלָּא כָּךְ שָׁמַעְתִּי מֵאָבִי, שֶׁאֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁכַּאֲשֶׁר שׁוֹמְעִים דָּבָר וְלֹא מִתְיַשֵּׁב בְּלִבָּם, וְהֵם עוֹרְכִים קְרָב זֶה עִם זֶה כְּאוֹתָם עוֹרְכֵי קְרָבוֹת בְּחֶרֶב, וְרוֹצִים לַהֲרֹג זֶה אֶת זֶה עָלֶיהָ,"],[7,"","וְדָבָר זֶה שֶׁאָמְרוּ חֲבֵרֵינוּ כָּךְ הִיא, וְכָךְ גָּזַרְנוּ בְּסוֹד מִשְׁנָתֵנוּ."],[8,"","שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַשֶּׁמֶשׁ וְאֶת הַלְּבָנָה, גָּזַר עַל הַשֶּׁמֶשׁ לִהְיוֹת שִׁלְטוֹן שֶׁל עֵשָׂו, וְעַל הַלְּבָנָה לִהְיוֹת בָּעוֹלָם הַזֶּה שִׁלְטוֹן שֶׁל יַעֲקֹב, וּמִנָּה עֲלֵיהֶם גְּדוֹלִים וְתַקִּיפִים עַד שֶׁיָּבאוּ שְׁתֵּי הָאֻמּוֹת הַלָּלוּ, וְאוֹתוֹ גָדוֹל שֶׁהִתְמַנָּה עַל הַלְּבָנָה בִּשְׁבִיל הָאֻמָּה שֶׁל יַעֲקֹב, רָצָה מִן הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּנָּתֵן שִׁלְטוֹן לַלְּבָנָה בָּעוֹלָם הַזֶּה, כְּלוֹמַר לָאֻמָּה שֶׁל יַעֲקֹב. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכִי מָה אֲנִי צָרִיךְ אֻמָּה שֶׁל יַעֲקֹב (חסר כאן). אֶלָּא בָּעוֹלָם הַבָּא, וְלִשְׁלֹט בָּהֶם עַל כָּל הָאֻמּוֹת, אֲבָל בָּעוֹלָם הַזֶּה לְכִי וּמַעֲטִי אֶת עַצְמֵךְ וְהִשְׁתַּעְבְּדִי בַּגָּלוּת לְזַכּוֹת אוֹתָךְ לָעוֹלָם הַבָּא."],[9,"","וּכְשֶׁבָּאוּ אֻמָּה שֶׁל יַעֲקֹב וְהִתְרַעֲמוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁנִּטַּל מֵהֶם הַשִּׁלְטוֹן וְנִתַּן לְעֵשָׂו, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: וְכִי מָה אַתֶּם רוֹצִים שִׁלְטוֹן בָּעוֹלָם הַזֶּה? שֶׁהֲרֵי אֲנִי עָרֵב לְהַשְׁלִיט אֶתְכֶם לָעוֹלָם הַבָּא עַל כָּל הָאֻמּוֹת, וְלָכֵן הָבִיאוּ כַפָּרָה עָלַי. כְּלוֹמַר, עַל אוֹתָהּ הַבְטָחָה שֶׁאֲנִי עָרֵב. לְכוּ וְהָבִיאוּ כַפָּרָה וְהִתְעַסְּקוּ בַתּוֹרָה, וְעָלַי לָתֵת לָכֶם שָׂכָר טוֹב, וְעָלַי לְהַשְׁלִיט אֶתְכֶם עַל כָּל הָעַמִּים, שֶׁעַל מְנָת כֵּן מִעַטְתִּי אֶת הַיָּרֵחַ בָּעוֹלָם."],[10,"","בָּא רַבִּי יוֹסֵי וּנְשָׁקוֹ בְרֹאשׁוֹ, וְקָרָא לְבִתּוֹ וְאָמַר לָהּ, כְּלִי הַגָּדוֹל שֶׁל הָאוֹר וְהַמְּנוֹרָה שֶׁנֶּחְלְקָה בְּטוֹבוֹת יֵשׁ לָךְ. אַשְׁרַיִךְ וְאַשְׁרֵי חֶלְקֵךְ, וְאַשְׁרֵי חֶלְקִי שֶׁזָּכִיתִי לִרְאוֹת כָּךְ."],[11,"","רַבִּי יוֹחָנָן אָמַר, זָכוּ יִשְׂרָאֵל שֶׁהֵאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְאֵינָם צְרִיכִים לְמָאוֹר אַחֵר, שֶׁכָּתוּב (ישעיה ס) וְהָיָה לָךְ ה' לְאוֹר עוֹלָם."],[12,"","אָמַר רַבִּי אַבָּהוּ, כֵּיוָן שֶׁנִּתְחַלֵּף לָהֶם הַשִּׁלְטוֹן, מוֹנִים חֶשְׁבּוֹן לַלְּבָנָה שֶׁבָּהּ מְנַהֶגֶת נֹהֵג כַּצֹּאן יוֹסֵף. וּמוּם אֵין בָּךְ - שֶׁלֹּא נִמְצָא בָּהּ חִסָּרוֹן בִּשְׁבִיל מוֹעֲדִים וּזְמַנִּים:"],[13,"","רַעָיָא מְהֵימְנָא אָמַר לוֹ, מְנוֹרָה הַקְּדוֹשָׁה, אַחַר שֶׁאָמַר (בראשית א) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, מַהוּ שֶׁאָמַר אַחַר כָּךְ וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ? אָמַר לוֹ, מַה שֶּׁבֵּאֲרוּ עַל כָּךְ בַּעֲלֵי הַמִּשְׁנָה, שֶׁמֵּהֶם אָמְרוּ נִבְרָא, וּמֵהֶם אָמְרוּ לֹא נִבְרָא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ, שֶׁכָּתוּב (שם) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ."],[14,"","אָמַר לוֹ, אִם כָּךְ הוּא, לֹא יִתֵּן חֵלֶק בְּיַד אֶחָד מֵהֶם וְלֹא נַעֲשָׂה בַּדְּמוּת שֶׁלָּהֶם, אֶלָּא בְּאִיקוֹנִין שֶׁל הַמֶּלֶךְ, בְּצַלְמוֹ כִּדְמוּתוֹ, שֶׁהוּא צֶלֶם וּדְמוּת תַּבְנִיתוֹ. אָמַר, כָּךְ נוֹדָע? אָמַר, חַס וְשָׁלוֹם, אֶלָּא אֲנִי אוֹמֵר שֶׁנִּבְרָא בַּכֹּל וְהִשְׁלִיטוֹ עַל הַכֹּל, שֶׁאִם הָיָה כָּל אֶחָד נוֹתֵן בּוֹ חֶלְקוֹ, בִּזְמַן שֶׁהָיָה כּוֹעֵס עָלָיו כָּל אֶחָד הָיָה נוֹטֵל חֶלְקוֹ מִמֶּנּוּ, כִּי בַּמֶּה נֶחְשָׁב הוּא?"]]],[["אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בָּרָא לֵיהּ כָּל חַד בְדִיּוּקְנֵיהּ, דָּא מַלְכוּת קַדִּישָׁא דְאִיהִי תְמוּנַת כָּל, דְבָּהּ אִסְתָּכָּל קוּדְשָׁא בְּרִיךְ הוּא וּבָרָא עַלְמָא וְכָל בִּרְיָין דְּבָּרָא בְּעָלְמָא וְכָלַל בָּהּ עִלָּאִין וְתַתָּאִין בְּלָא פִירוּדָא כְּלָל וְכָלַל בָּהּ עֶשֶׂר סְפִירָן וְכָל שְׁמָהָן וּכִנוּיִּין וְהֲוַיָּין וְעִלַּת כָּל כֹּלָּא דְאִיהוּ אֲדוֹן עַל כֹּלָּא וְלֵית אֱלָהָא בָּר מִנֵּיהּ ולָא אִשְׁתְּכַח בְכָל עִלָּאִין וְתַתָּאִין פָּחוֹת מִינֵיהּ. בְּגִין דְּאִיהוּ קֶשֶׁר דְכֻלְּהוּ שְׁלִימוּ דְכֻלְּהוּ לְקַיְימָא בֵּיה וּמַלְכוּתוֹ בַּכָּל מָשָׁלָה. וּבְגִין דְלָא אִשְׁתְּכַח עִלַת עַל כֹּלָּא בְּעִלָּאִין וְתַתָּאִין פָּחוֹת מִינֵיהּ אֲפִילוּ בְּחַד מִנַּיְיהוּ (אתקריאת) אִתְקְרִיבַת אֱמוּנַת יִשְׂרָאֵל. וּמִסִּטְרָא דְּעִלַּת עַל כֹּלָּא אִתְמָר בָּהּ (דברים ד׳:ט״ו) כִּי לא רְאִיתֶם כָּל תְמוּנָה. אֲבָל מִסִּטְרָא דִּשְׁאַר עַמִּין אִתְמָר בְּהוּ (בה) (במדבר י״ב:ח׳) וּתְמוּנַת יְיָ יַבִּיט.","אֲתָא בּוֹצִּינָא קַדִּישָׁא וּשְׁאָר חַבְרַיָּיא ואִשְׁתַּטְחוּ קַמֵּיהּ וְאָמְרוּ כְּעָן לֵית מָאן דְּיָכִיל לְמֵיטַל מִינֵיהּ חוּלָקֵיהּ דְלָא יָהִיב לֵיהּ חַד מֵעָלְמָא אֶלָּא בּוֹרֵא עָלְמִין עִלַת עַל כֹּלָּא, וּבֵיהּ תַלְיָּיא עוֹנְשֵׁיהּ אוֹ אַגְרֵיהּ ולָא בְּמַלְאַךְ וְשָׂרָף וְלָא בְּשׁוּם בִּרְיָה דְעַלְמָא וּבְגִין דָּא אוּקְמוּהָ רָבַּנָן דְּמַתְנִיתִין הַמְשָׁתֵף שֵׁם שָׁמַיִם וּדְבַר אַחֵר נִעֶקַר מִן הָעוֹלָם. ע\"כ:","חִוָורוּ דְאוֹרַיְיתָא וְכַד אִיהוּ אוֹר מִתְלַבֵּשׁ בַּחֹשֶׁךְ אִתְמַר בְּאוֹרַיְיתָא (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה וְכַד אִסְתְּלַק מִתַּמָּן אוֹר דְאִיהוּ חִוָורוּ אָמְרָה אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת וְאוֹרַיְיתָא כְּגווָֹנָא דְּבַת עֵינָא דְאִיהִי אוּכָמָא וְשַׁפִּירָא בְּאוֹר דְּנָהִיר בָּהּ","וּבְגִין דָּא בַּת עֵינָא וְאוֹר דְּנָהִיר בָּהּ אָמְרָה (תהילים כ״ז:א׳) יְיָ אוֹרִי וְיִשְׁעִי מִמִּי אִירָא אוֹרִי אוֹר י' דְאִיהִי בַּת עַיִן וּתְרֵין גַוְנִין אִית לֵיהּ אוֹר מִלְגַאו וְחֹשֶׁךְ מִלְּבַר לְמֶהֱוֵי שָׁלְטָאַה בְּהוּ עַל כָּל קִלוּסִין (קליפין) הֲדָא הוּא דִּכְתִיב (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכָּל מָשָׁלָה.","בִּלְבוּשָׁא דְּאוֹר אִיהִי שַׁלִּיטַת עַל כָּל אִינוּן דְאִתְמָר בְּהוֹן (שמות י׳:כ״ג) וּלְכָל בְּנִי יִשְׂרָאֵל הָיָה אוֹר בְּמוֹשְׁבוֹתָם וּבִלְבוּשָׁא אוּכָמָא שַׁלִּיטַת עַל חַיָּיבַיָּא דְאִתְמָר בְּהוֹן (שמואל א ב׳:ט׳) וּרְשָׁעִים בַּחֹשֶׁךְ יִּדָמוּ.","וְעוֹד אוֹר אִיהוּ מִסִּטְרָא דִיְמִינָא דְּאִיהוּ אוֹר יוֹם קַדְמָאָה דְאִתְמָר בֵּיהּ (בראשית א׳:ה׳) יְהִי אוֹר דָּא אַבְרָהָם וַיִּקְרָא אֱלהִים לָאוֹר יוֹם. חֹשֶׁךְ מִסִּטְרָא דִשְׂמָאלָא דְאִתְמָר בֵּיהּ בְּיִצְחָק (בראשית כ״ז:א׳) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת וְלַחֹשֶׁךְ קָרָא לָיְלָה יַעֲקֹב דְאִתְלַבַּשׁ מִתַּרְוַיְהוּ בְּאוֹר דִיְמִינָא וּבַחֹשֶׁךְ דִשְׂמָאלָא","וּבְתַּרְוַיְהוּ עַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ עַמּוּד. (שמות י״ג:כ״ב) עַמּוּד הֶעָנָן יוֹמָם וְעַמּוּד הָאֵשׁ לָיְלָה לִפְנֵי הֲעָם. עָנָן מִסִּטְרָא דִילֵיהּ מַיָא, חֹשֶׁךְ מִסִּטְרָא דִילֵיהּ אֶשָׁא עַמּוּד אִיהוּ שָׁלוֹם בֵּינַיְיהוּ. הֲדָא הוּא דִּכְתִיב (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו וְכַד אִיהוּ בְּאֶמְצָעִיתָא (שמות י״ד:כ׳) וְלָא קָרָב זֶה אֶל זֶה כָּל הַלַּיְלָה, לָא קָרִיב מַיָא לְאֶשָּׁא וְלָא אֶשָׁא לְמַיָּא דְאִיהוּ אַפְרִישׁ בֵּינַיְיהוּ. וְדָא אִיהוּ מַחֲלוֹקֶת בֵּית הִלֵּל וּבֵית שַׁמַּאי שֶׁהִיא לְשֵׁם שָׁמַיִם.","וּלְקָבְלַיְיהוּ תְרֵין אֱמוֹרָאֵי דִּרְקִיעָא מִיכָאֵל וְגָבְרִיאֵל וְשָׂר שָׁלוֹם מַכְרִיעֲ בֵּינֵיהֶם דְאִיהוּ נוּרִיאֵ\"ל, אוּרִיאֵל אִתְקְרֵי מִסִּטְרָא דִיְמִינָא נוּרִיאֵל מִסִּטְרָא דִשְׂמָאלָא וְאִיהוּ אָדָם דִלְתַתָּא מטטרו\"ן שְׁמֵיהּ שָׁלִיט עַל כָּל מָארֵי מַתְנִיתִין הֲדָא הוּא דִּכְתִיב (בראשית א׳:כ״ו) וְיֵּרְדוּ בִּדְגַת הַיָּם אִלֵּין תַּלְמִידֵי חֲכָמִים דְּמִתְרַבִּין בְּיַמָּא דְאוֹרַיְיתָא דְיָרְתֵי מִתַּמָּן נֶפֶשׁ חַיָּה. וּבְעוֹף הַשָׁמַיִם אִלֵּין מָארֵי דְזַכְוָון דְּבִזְכוּתְהוֹן פַּרְחִין לְעֵילָא וְיַרְתִין מִתַּמָּן רוּחָא דְאִיהוּ עוֹף יְעוֹפֵף בְגַדְפִין בְּפִקּוּדִין דַּעֲשֶׂה. וּבַבְּהֵמָה אִלֵּין עַמֵּי הָאָרֶץ דְאִתְמָר בְּהוֹן (במדבר י״ד:ט׳) אַל תִּירְאוּ אֶת עַם הָאָרֶץ כִּי לַחְמֵנוּ הֵם.","כך נְהוֹרָא אִיהוּ (תהילים ל״ג:א׳) רַנְנוּ צַדִּיקִים בַּיְיָ וְדָא דַרְגָּא דְצַדִיק חַי עָלְמִין וּמִתַּמָן רִנָּה וּבֵיהּ פּוּרְקָנָא הֲדָא הוּא דִּכְתִיב (ירמיהו כ״ג:ה׳) צְמָח צַדִּיק וַדָאי דְאִיהוּ עֲשִׂירָאָה וְצַדִּיק נָטִיל מִשְּׂמָאלָא וְעַמּוּדָא דְאֶמְצָעִיתָא מִימִינָא הֲדָא הוּא דִּכְתִיב (דברים ל\"ג) מִימִינוֹ אֵשׁ דָּת לָמוֹ.","תָּא חֲזֵי כָּל אַתְוָון אִינוּן מִסִּטְרָא דְּאַתְוָון דְאוֹרַיְיתָא דִכְלִילָן בִּשְׁכִינְתָּא וְצַדִּיק אִיהוּ נָטִיל לִשְׂמָאלָא קֵץ חַי דְאִיהוּ יִצְחָק בְּהִפּוּךְ חַי עָלְמִין קָשִׁיר בִשְׂמָאלָא","וּשְׁכִינְתָּא תַתָּאָה מִסִּטְרָא דִשְׂמָאלָא אִתְמָר בָּהּ וְהָאָרֶץ הָיְתָה מִסִּטְרָא דִיְמִינָא תוֹהוּ וָבֹהוּ בּוֹ הוּא מִסִּטְרָא דְעֲמוּדָא דְאֶמְצָעִיתָא וְחֹשֶׁךְ עַל פְּנִי תְּהוֹם דָּא שְׁכִינְתָּא תַתָּאָה","וּמָאן גָּרִים לֵיהּ (לה) הַאי אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא קוֹדֶם דְּבָּרָא עַלְמָא הֲוָה סָתִים יהו\"ה לְבָתַר אִתְפַּשְׁטַת ה' לְתַתָּא וְאִתְּמַר בָּהּ וְהָאָרֶץ הָיְתָה תוֹהוּ וָבֹהוּ וְרָזָא דְמִלָה אֵלֶה \"תּוֹלְדוֹת \"הַשָּׁמַיִם \"וְהָאָרֶץ בְּהִבָּרְאָם בה' בְּרָאָם הֲרֵי לְךָ דַהֲוָה לְבוּשָׁהָא תוֹהוּ.","וּבְגִין דָּא כִּי לֹא הִמְטִיר יְיָ אֱלֹהִים עַד לָא הֲוָה נָחִית נְבִיעוּ עֲלָהּ בְּגִין דְּאָדָם אַיִן דַהֲוָה בַּעְלָהּ לְעֵילָא סָתִים בְּאַיִן עַד דְאִתְפְּשַׁט ה' מִן יה\"ו דְאִיהוּ בִּינָה דְאִיהוּ מְקוֹרָא דִנְבִיעוּ דְאִיהִי נְקוּדָה סְתִימָא וּמִתַּמָן וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה","וְקוֹדֶם דְּנַחְתַת הֲוָה קוּדְשָׁא בְּרִיךְ הוּא בוֹנֵה עוֹלָמוֹת וּמַחֲרִיבָן, בְּגִין דָּא הֲוָה נְבִיעוּ נָחִית בְּהַהוּא זִמְנָא הוּא שֵׁירוּתָא מֵחֶסֶד הֲדָא הוּא דִּכְתִיב (תהלים פ\"ט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וּבְגִין דָּא לא תוֹהוּ בְּרָאָהּ לָשֶׁבֶת יְצָרָהּ וְאִתְּמַר בָּהּ לא טוֹב היוֹת הַאָדָם לְבַדּוֹ דְלָא תוֹהוּ בְּרָאָהּ."],[],[[0,"","אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אוֹתוֹ כָּל אֶחָד בִּדְמוּתוֹ, זוֹהִי מַלְכוּת הַקְּדוֹשָׁה שֶׁהִיא תְּמוּנַת כֹּל, שֶׁבָּהּ הִסְתַּכֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא וּבָרָא אֶת הָעוֹלָם וְכָל הַבְּרִיּוֹת שֶׁבָּרָא בָּעוֹלָם, וְכָלַל בָּהּ עֶלְיוֹנִים וְתַחְתּוֹנִים בְּלִי פֵּרוּד כְּלָל, וְכָלַל בָּהּ עֶשֶׂר סְפִירוֹת, וְכָל הַשֵּׁמוֹת וְהַכִּנּוּיִים וְהַהֲוָיוֹת, וְעִלַּת עַל הַכֹּל שֶׁהוּא אָדוֹן עַל הַכֹּל, וְאֵין אֱלוֹהַּ מִבִּלְעָדָיו, וְלֹא נִמְצָא בְּכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים פָּחוֹת מִמֶּנּוּ. בִּגְלַל שֶׁהוּא קֶשֶׁר שֶׁל כֻּלָּם וְהַשְּׁלֵמוּת שֶׁל כֻּלָּם, לְקַיֵּם בּוֹ וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. וּבִגְלַל שֶׁלֹּא נִמְצָא עִלַּת עַל הַכֹּל בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים פָּחוֹת מִמֶּנּוּ אֲפִלּוּ בְּאֶחָד מֵהֶם, הִיא (נקראת) הִתְקָרְבָה אֱמוּנַת יִשְׂרָאֵל. וּמִצַּד שֶׁל עִלַּת עַל הַכֹּל נֶאֱמַר בָּהּ (דברים ד) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. אֲבָל מִצַּד שֶׁל שְׁאָר הָעַמִּים נֶאֱמַר בָּהֶם (בה) (במדבר יב) וּתְמוּנַת ה' יַבִּיט."],[1,"","בָּא הַמְּנוֹרָה הַקְּדוֹשָׁה וּשְׁאָר הַחֲבֵרִים וְהִשְׁתַּחֲווּ לְפָנָיו וְאָמְרוּ, כָּעֵת אֵין מִי שֶׁיָּכוֹל לִטֹּל מִמֶּנּוּ אֶת חֶלְקוֹ, שֶׁלֹּא נָתַן לוֹ אֶחָד מֵהָעוֹלָם, אֶלָּא בּוֹרֵא הָעוֹלָמוֹת עִלַּת עַל הַכֹּל, וּבוֹ תָלוּי עָנְשׁוֹ אוֹ שְׂכָרוֹ, וְלֹא בְמַלְאָךְ וְשָׂרָף וְלֹא בְּשׁוּם בְּרִיָּה מֵהָעוֹלָם, וּבִגְלַל כָּךְ פֵּרְשׁוּהָ חַכְמֵי הַמִּשְׁנָה, הַמְשַׁתֵּף שֵׁם שָׁמַיִם וְדָבָר אַחֵר נֶעֱקָר מִן הָעוֹלָם: ע\"כ."],[2,"","לֹבֶן שֶׁל הַתּוֹרָה, וּכְשֶׁאוֹתוֹ אוֹר מִתְלַבֵּשׁ בַּחֹשֶׁךְ, נֶאֱמַר בַּתּוֹרָה שְׁחוֹרָה אֲנִי וְנָאוָה. וּכְשֶׁמִּתְעַלֶּה מִשָּׁם אוֹר שֶׁהוּא לָבָן, אוֹמֶרֶת אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, וְהַתּוֹרָה כְּמוֹ שֶׁבַּת עַיִן, שֶׁהִיא שְׁחוֹרָה וְיָפָה בָּאוֹר שֶׁמֵּאִיר בָּהּ,"],[3,"","וְלָכֵן בַּת עַיִן וְהָאוֹר שֶׁמֵּאִיר בָּהּ אָמְרָה ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא. אוֹרִי - אוֹר י', שֶׁהִיא בַּת עַיִן, וּשְׁנֵי גְוָנִים יֵשׁ לָהּ - אוֹר מִבִּפְנִים וְחֹשֶׁךְ מִבַּחוּץ, לִהְיוֹת שׁוֹלֵט בָּהֶם עַל כָּל הַקִּלּוּסִים (קלפות). זֶהוּ שֶׁכָּתוּב (תהלים קג) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה."],[4,"","בִּלְבוּשׁ שֶׁל אוֹר הִיא שׁוֹלֶטֶת עַל כָּל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שמות י) וּלְכָל בְּנֵי יִשְׂרָאֵל הָיָה אוֹר בְּמוֹשְׁבֹתָם, וּבִלְבוּשׁ שָׁחֹר שׁוֹלֶטֶת עַל הָרְשָׁעִים שֶׁנֶּאֱמַר בָּהֶם (שמואל א ב) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ."],[5,"","וְעוֹד, אוֹר הוּא מִצַּד הַיָּמִין (חסד), שֶׁהוּא אוֹר שֶׁל יוֹם רִאשׁוֹן שֶׁנֶּאֱמַר בּוֹ יְהִי אוֹר, זֶה אַבְרָהָם, וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. חֹשֶׁךְ מִצַּד הַשְּׂמֹאל, שֶׁנֶּאֱמַר בּוֹ בְּיִצְחָק (שם כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, וְלַחֹשֶׁךְ קָרָא לָיְלָה. יַעֲקֹב שֶׁהָיָה לָבוּשׁ מִשְּׁנֵיהֶם בָּאוֹר שֶׁל יָמִין וּבַחֹשֶׁךְ שֶׁל שְׂמֹאל,"],[6,"","וּבִשְׁנֵיהֶם עַמּוּד הָאֶמְצָעִי הוּא עַמּוּד. עֵמּוּד הֶעָנָן יוֹמָם וְעַמּוּד הָאֵשׁ לַיְלָה לִפְנֵי הָעָם. הֶעָנָן מִצַּד שֶׁלּוֹ מַיִם. הַחֹשֶׁךְ מִצַּד שֶׁלּוֹ אֵשׁ. עַמּוּד הוּא שָׁלוֹם בֵּינֵיהֶם. זֶהוּ שֶׁכָּתוּב (איוב כח) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וּכְשֶׁהוּא בָּאֶמְצַע - וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה. לֹא קָרַב הַמַּיִם לָאֵשׁ, וְלֹא אֵשׁ לַמַּיִם, שֶׁהוּא מַפְרִיד בֵּינֵיהֶם. וְזוֹהִי מַחֲלֹקֶת בֵּית הִלֵּל וּבֵית שַׁמַּאי שֶׁהִיא לְשֵׁם שָׁמַיִם, וּכְנֶגְדָּם שְׁנֵי אָמוֹרָאִים שֶׁל הָרָקִיעַ, מִיכָאֵל וְגַבְרִיאֵל, וְשַׂר שָׁלוֹם מַכְרִיעַ בֵּינֵיהֶם, שֶׁהוּא נוּרִיאֵל. אוּרִיאֵל נִקְרָא מִצַּד הַיָּמִין, נוּרִיאֵל מִצַּד הַשְּׂמֹאל, וְהוּא אָדָם שֶׁלְּמַטָּה, מטטרו\"ן שְׁמוֹ, שׁוֹלֵט עַל כָּל בַּעֲלֵי הַמִּשְׁנָה. זֶהוּ שֶׁכָּתוּב (בראשית א) וְיִּרְדּוּ בִּדְגַת הַיָּם, אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁמִּתְרַבִּים בְּמֵי הַתּוֹרָה, שֶׁיּוֹרְשִׁים מִשָּׁם נֶפֶשׁ חַיָּה."],[7,"","וּבְעוֹף הַשָּׁמַיִם - אֵלּוּ בַּעֲלֵי זְכֻיּוֹת, שֶׁבִּזְכוּתָם פּוֹרְחִים לְמַעְלָה, וְיוֹרְשִׁים מִשָּׁם רוּחַ שֶׁהוּא עוֹף יְעוֹפֵף בַּכְּנָפַיִם בְּמִצְווֹת עֲשֵׂה. וּבַבְּהֵמָה - אֵלּוּ עַמֵּי הָאָרֶץ שֶׁנֶּאֱמַר בָּהֶם (במדבר יד) אַל תִּירְאוּ אֶת עַם הָאָרֶץ כִּי לַחְמֵנוּ הֵם. ע\"כ."],[8,"","כְּשֶׁהָאוֹר הוּא, רַנְּנוּ צַדִּיקִים בַּה', וְזוֹ דַּרְגָּה שֶׁל צַדִּיק חַי הָעוֹלָמִים, וּמִשָּׁם רִנָּה וּבוֹ הַגְּאֻלָּה. זֶהוּ שֶׁכָּתוּב (ירמיה כג) צֶמַח צַדִּיק, וַדַּאי שֶׁהוּא עֲשִׂירִי, וְצַדִּיק נוֹסֵעַ מִשְּׂמֹאל, וְעַמּוּד הָאֶמְצַע מִיָּמִין. זֶהוּ שֶׁכָּתוּב מִימִינוֹ אֵשׁ דָּת לָמוֹ."],[9,"","בֹּא רְאֵה, כָּל הָאוֹתִיּוֹת הֵן מִצַּד אוֹתִיּוֹת הַתּוֹרָה שֶׁכְּלוּלוֹת בַּשְּׁכִינָה, וְצַדִּיק נוֹסֵעַ מִשְּׂמֹאל, קֵץ חַי שֶׁהוּא יִצְחָק בְּהִפּוּךְ. חַי הָעוֹלָמִים קָשׁוּר בִּשְׂמֹאל,"],[10,"","וּשְׁכִינָה תַּחְתּוֹנָה מִצַּד שְׂמֹאל נֶאֱמַר בָּהּ וְהָאָרֶץ הָיְתָה. מִצַּד הַיָּמִין תֹּהוּ וָבֹהוּ, בּוֹ הוּא מִצַּד עַמּוּד הָאֶמְצָעִי. וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם - זוֹ שְׁכִינָה הַתַּחְתּוֹנָה."],[11,"","וּמִי גָרַם לָהּ אֶת זֶה? אֶלָּא הַקָבָּ\"ה קֹדֶם שֶׁבָּרָא אֶת הָעוֹלָם הָיָה נִסְתָּר יְהֹוָ\"ה, אַחַר כָּךְ הִתְפַּשְּׁטָה ה' לְמַטָּה, וְנֶאֱמַר בָּהּ וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ, וְסוֹד הַדָּבָר - אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. הֲרֵי לְךְ שֶׁהָיָה לְבוּשָׁהּ תֹּהוּ."],[12,"","וּבִגְלַל זֶה כִּי לֹא הִמְטִיר ה' אֱלֹהִים, עֲדַיִן לֹא הָיָה יוֹרֵד הַשֶּׁפַע שֶׁלָּהּ בִּגְלַל שֶׁאָדָם אַיִן, שֶׁהָיָה בַּעְלָהּ נִסְתָּר בְּאַיִן. עַד שֶׁהִתְפַּשֵּׁט ה' מִן יה\"ו, שֶׁהוּא בִּינָה, שֶׁהוּא מְקוֹר הַשֶּׁפַע, שֶׁהִיא נְקֻדָּה נִסְתֶּרֶת, וּמִשָּׁם הִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה."],[13,"","וְקֹדֶם שֶׁיָּרְדָה הָיָה הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן, בִּגְלַל זֶה הָיָה הַשֶּׁפַע יוֹרֵד בְּאוֹתוֹ זְמַן הִיא רֵאשִׁית מֵחֶסֶד, זֶהוּ שֶׁכָּתוּב (תהלים פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. וּבִגְלַל זֶה לֹא תֹהוּ בְּרָאָהּ לָשֶׁבֶת יְצָרָהּ, וְנֶאֱמַר בָּהּ לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ, שֶׁלֹּא תֹהוּ בְּרָאָהּ."]]],[["וּבְזִמְנָא דַהֲוָה תוֹהוּ אָמַר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ' קֵץ דְּיִצְחָק דְאִתְמָר בֵּיה כִּי אוֹתְךָ רָאִיתִי צַדִּיק לְפָנַי דְּאִי אֲנְתְ הֲוִית בָּעֵי רַחֲמֵי עָלַיְיהוּ לָא אִתְחֲרָבוּ וְאִיהוּ הֲוָה אָמַר לֵיהּ בְּרֶמֶז בְּגִין דְיִבְעֵי רַחֲמֵי עָלַיְיהוּ וְלֹא יְמוּת מָשִׁיחַ דְאִיהוּ מִסִּטְרָא דִשְׂמָאלָא.","אָמַר לֵיהּ וְהָא בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן קוֹדֶם דְּאִתְבַּרֵי עַלְמָא הֲוָה אֶלָּא מַגִּיד מֵרֵאשִׁית אַחֲרִית דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בְּמַחְשַׁבְתֵּיהּ כָּל דָרִין דַהֲוָה בּוֹנֶה וְאִתְחַרִיבוּ קוֹדֶם דְאִתְבְּרִיאוּ חֲזָא דַהֲווּ עָבְדִין עוֹבָדִין דְיִתְחַרִיבוּ וְכֵיוָן דְּבָּרָא חַשָׁב כְּאִילוּ חַרִיב לוֹן וְדָא מְמַלֵּל עַד סוֹף יוֹמִין דְאִלֵּין תּוֹלָדִין בִּישִׁין וַהֲווּ גַרְמִין דְנָהָר יֶחרַב וְיָבֵשׁ יֶחרַב בְּבַיִת רִאשׁוֹן וְיָבֵשׁ בְּבַיִת שֵׁנִי נְבִיעוּ דִילֵיהּ בִּתְרֵין עָלְמִין שְׁכִינְתָּא עִלָּאָה וּשְׁכִינְתָּא תַתָּאָה","וּלְנֹחַ אִתְגַלְיָיא מָה דַהֲוָה וּמָה דְעָתִיד לְמֶהֱוֵי וְלָא בָּעָא רַחֲמֵי עָלַיְיהוּ עַד דְּאָתָא מֹשֶׁה וּבָעָא רַחֲמֵי דְּעֲתִידִין הֲווּ יִשְׂרָאֵל דְלָא יִפְקוּן אֶלָּא חַד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה מִסִּטְרָא דִגְבוּרָה דַּהֲוֵי דַּיְינִין וְיִתְחַזַּר עַלְמָא לְתֹהוּ. וּבְגִין דְּבָעָא מֹשֶׁה רַחֲמִין עָלַיְיהוּ שְׂמֹאל דּוֹחֶה וְלָא יִפְקוּן בֵּיה יִשְׂרָאֵל","וְיָמִין מְקְּרָבָא דְאִיהִי יַמִּינָא מָטֵי כְּלַפֵּי חֶסֶד וּמֹשֶׁה בְּגִין דְּיָהַב גַּרְמֵיהּ עָלַיְיהוּ יָהַב תוּקְפָא לְדַרְגֵּיהּ דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא דְאִיהִי אוֹרַיְיתָא דְאִתְיְיהִיבַת בִּימִינָא הֲדָא הוּא דִּכְתִיב (דברים ל\"ג) מִימִינוֹ אֵשׁ דָּת לָמוֹ וּבְגִין דָּא פּוּרְקָנָא בֵּיה תַלְיָּיא הֲדָא הוּא דִּכְתִיב (בראשית מ״ט:י׳) לָא יָסוּר שֵׁבֶט מִיְהוּדָה עַד כִּי יָבֹא שִׁילֹה דְאִיהוּ מֹשֶׁה בְּחוּשְׁבָּנָא.","יְסוֹד צַדִּיק בֵּיה סוֹ\"ד תְּהֵא שְׂמֹאל דּוֹחָה אַף עַל גַּב דְּאוֹקִימְנָא בֵּיה (בראשית מ״ו:כ״ו) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה שִׁשִּׁים וָשֵׁשׁ בְּגִין דְאִתְקַשַׁר בִּשְׂמָאלָא וְיָמִין מֵקַרֶבֶת בְּגִין דְּתַלְיָא מִנֵּיהּ עַמּוּדָא דְאֶמְצָעִיתָא","דס\"ו אִינוּן שִׁשִּׁים מַסֶּכְתּוֹת וְשִׁיתָּא סִדְרֵי מִשְׁנָה דְּאִתְיְיהִיבוּ מִגְּבוּרָה דְאִיהִי שְׂמָאלָא שִׁשִּׁים גִּבּוֹרִים אִתְקְרִיאוּ דְנַטְלָן מִגְּבוּרָה דְּתַמָּן אוֹרַיְיתָא דְבְּעַל פֶּה דְאִיהִי שְׁכִינְתָּא תַתָּאָה כְּלָלָא דס' מַסֶּכְתּוֹת וְשִׁיתָּא סִדְרֵי מִשְׁנָה","דְתוֹרָה שֶׁבִּכְתָב לְפוּמָא לָא גָלֵי בְּגִין דַּעֲתִידָה שְׂמֹאל דְאִיהִי פּוּמָא לְאַדְחַיָּיא. וּבְגִין כַּךְ אִיהוּ סָתִים הֲכִי פּוּרְקָנָא בְּלִבָּא וּפוּמָא דְאִיהוּ גַּלְּיָיא לָא אִתְגְּלֵי פּוּרְקָנָא","וּבְגִין דְכֹלָא תַלְיָּיא בִּימִינָא אָמַר הַנָּבִיא (ישעיהו נ״ג:א׳-ב׳) וּזְרוֹעַ יְיָ עַל מִי נִגְלָתָה עַל מִי וַדָאי דְאִתְמָר בֵּיה (איכה ב) מִי יִרְפָּא לָךְ","הֲדָא הוּא דִּכְתִיב (איכה ב׳:י״ג) מָ\"ה אֲעִידֶךְ מָ\"ה אֲדַמֶה לָךְ (שמות ג׳:י״ג) וְאָמְרוּ לִי מָה שְׁמוֹ בְּמָ\"ה יֵיתֵי זִמְנָא וּבְמָ\"ה אַסְוָותָא הֲדָא הוּא דִּכְתִיב (איכה ב׳:י״ג) מָה אַשְוֶה לָךְ וַאֲנַחָמֶךְ וְגוֹ' מִי יִרְפָּא לָךְ, דְמֹשֶׁה אִיהוּ מָה שְׁמוֹ וּבֵיהּ תְּהֵא נָחַמָתֶךְ וּבְגִין דָּא כָּפָל קוּדְשָׁא בְּרִיךְ הוּא שְׁמֵיהּ מֹשֶׁה מֹשֶׁה חַד עַל פּוּרְקָנָא קַדְמָאָה וְחַד עַל בַּתְרַיְיתָא וּבְגִין דָּא (שמות יד) אָז יָשִׁיר מֹשֶׁה אָז שָׁר לא נֶאֱמַר אֶלָּא אָז יָשִׁיר.","עֲשִׂירָאָה בִּתְפִלָּה וְדָא שְׁכִינְתָּא עֲלָהּ אִתְמַר (תהילים י״ז:א׳) תְפִלָּה לְדָוִד שִׁמְעָה יְיָ צֶדֶק וְדָוִד בְּרוּחַ קוּדְשָׁא אָמַר בְּאַחֲרִית יוֹמִין דְגַלוּתָא, אָמַר עַל יִשְׂרָאֵל (תהילים י״ז:ג׳) בַּחָנְתָּ לִבִּי פַּקַדְתָּ לָיְלָה. וְלֵית לָיְלָה אֶלָּא גָּלוּת וְאִיוֹב מָה דְּאָמַר כוּלָא הוּא מָשָׁל עַל יִשְׂרָאֵל דְּאָמַר (איוב ז׳:ט׳) כַלָּה עָנָן וַיֵּלַךְ, וְשָׂטָן בָּעָא לְקַטְרְגָא לֵיהּ וְאָמַר קוּדְשָׁא בְּרִיךְ הוּא (איוב לה) אִיוֹב לא בְּדַעַת יְדַבֵּר אוּף בְּיַעֲקֹב בְּגִין דְּחָזָא בְּרוּחָא דְּקוּדְשָׁא דוֹחֲקָא דְגַלוּתָא","זְרַע אַבְרָהָם אוֹהֲבִי. לֵית מָאן דְּקָאִים קָמֵיהּ תַרְעָא דִצְלוֹתָא וְעָלֵיהּ אִתְמַר (תהילים קכ״ז:ה׳) לא יֵבוֹשׁוֹ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָׁעַר דְאִיהוּ תַרְעָא דְמַלְכָּא בְּגִין דִצְלוֹתָא אִיהִי מִצְוָה וְדָא שְׁכִינְתָּא וְאוֹרַיְיתָא דָּא קוּדְשָׁא בְּרִיךְ הוּא וְלָא צָרִיךְ הַפְסָקָה בֵּינַיְיהוּ וְצָרִיךְ לְסַלְקָא תּוֹרָה וּמִצְוָה בִּדְחִילוּ וּרְחִימוּ דְכָל פִקּוּדִין דַּעֲשֵׂה וְלָא תַעֲשֶׂה כֻּלְּהוּ תַלְיָין מִן שֵׁם יהו\"ה כְּמָה דְאוֹקִימְנָא רָזָא דָּא שְׁמִ\"י עִם י\"ה שס\"ה מִצְוֹת לֹא תַעֲשֶׂה וְזֶּה זִכְ\"רִי עִם וָ\"ה רְמַ\"ח מִצְוֹת עֲשֵׂה","וְהָא הָכָא רמ\"ח ושס\"ה וְאִינּוּן רמ\"ח תֵיבִין בְּקִרְיַת שֵׁמַע וְאִתְיַיהִיבוּ מִרְחִימוּ וּדְחִילוּ דְאוֹת ה' וּבְגִין דָּא תַקִּינוּ הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה וְאִינּוּן כְּלִילָן בְּאַבְרָהָם דְאִתְמָר בֵּיהּ (ישעיהו מ״א:ח׳) זְרַע אַבְרָהָם אוֹהֲבִי.","תְּפִילִין אִינוּן עוֹז דְּאִתְיְיהִיבוּ מֵיִרְאָה דְאִיהוּ לִשְׂמָאלָא וְדָא פַּחַד יִצְחָק דְּתַמָּן כָּל מְקַטְרְגִין סָלְקִין לְמִתְבַּע כָּל דִינִין וּבְגִין דָּא (ישעיהו ס״ב:ח׳) וּבִזְרוֹעַ עוּזוֹ, דָּא תְּפִילִין י\"ה בְּיִרְאָה וָ\"ה בְּאַהֲבָה הֲדָא הוּא דִּכְתִיב (תהילים ל״א:כ״ד) אֵהֶבוּ אֶת יְיָ כָּל חַסִידָיו תָּא חֲזֵי (ס\"א ת\"ת) יהו\"ה כָלִיל כֹּלָּא וּבְגִין דָּא אִתְמָר בְּיַעֲקֹב (בראשית כט) וְהִנֵּה יהו\"ה נִצָב עָלָיו דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא לְבָתָר דְאִתְקַם. (כתוב בדפוס עד בדיוקנא דמאהה ודאי)","דְּכַד צְלוֹתָא דִילֵיהּ סַלְקָא לְעֵילָא כָּרוֹזָא נָפִיק מִרְקִיעִין וְיֵימָא הָבוּ יְקָרָא לְדִיּוּקְנָא דְמַלְכָּא וְלֵית תַרְעָא דְּקָאֵים קָמֵיהּ הַאי צְלוֹתָא, (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח לְאַפָּקָא מְזוֹנָא לִבְנִין קַדִּישִׁין דִּבְּהָאי הֵיכָלָא תַמָּן מְזוֹנָא.","בְּנֵי חַיֵּי וּמְזוֹנֵי מִסִּטְרָא דְעֲמוּדָא דְאֶמְצָעִיתָא דְאִיהוּ (שמות ה) בְּנִי בְכוֹרִי יִשְׂרָאֵל וְאִיהוּ עֵץ הַחַיִּים דְנָפִיק מֵחַיִּים דִלְעֵילָא וְאִיהוּ אִילָנָא דְמָזוֹן לְכוֹלָא בֵּיה"],[],[[0,"","וּבִזְמַן שֶׁהָיָה תֹהוּ, אָמַר אֱלֹהִים לְנֹחַ, קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ', קֵץ שֶׁל יִצְחָק שֶׁנֶּאֱמַר בּוֹ כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי, שֶׁאִם אַתָּה הָיִיתָ מְבַקֵּשׁ רַחֲמִים עֲלֵיהֶם, לֹא נֶחְרְבוּ. וְהוּא הָיָה אוֹמֵר לוֹ בְּרֶמֶז כְּדֵי שֶׁיְּבַקֵּשׁ רַחֲמִים עֲלֵיהֶם, וְלֹא יָמוּת מָשִׁיחַ שֶׁהוּא מִצַּד הַשְּׂמֹאל."],[1,"","אָמַר לוֹ, וַהֲרֵי הָיָה בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן קֹדֶם שֶׁנִּבְרָא הָעוֹלָם? אֶלָּא מַגִּיד מֵרֵאשִׁית אַחֲרִית, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בְמַחֲשַׁבְתּוֹ כָּל הַדּוֹרוֹת שֶׁהָיָה בּוֹנֶה, וְנֶחְרְבוּ קֹדֶם שֶׁנִּבְרְאוּ. רָאָה שֶׁהָיוּ עוֹשִׂים מַעֲשִׂים שֶׁיֶּחֶרְבוּ, וְכֵיוָן שֶׁבָּרָא, חָשַׁב כְּאִלּוּ הֶחֱרִיבָם, וְזֶה מְדַבֵּר עַד סוֹף הַיָּמִים שֶׁאֵלֶּה תּוֹלָדוֹת רָעוֹת, וְהָיוּ גוֹרְמִים דְּנָהָר יֶחֱרַב וְיָבֵשׁ. יֶחֱרַב בְּבַיִת רִאשׁוֹן, וְיָבֵשׁ בְּבַיִת שֵׁנִי. הַנְּבִיעָה שֶׁלּוֹ בִּשְׁנֵי עוֹלָמוֹת, שְׁכִינָה עֶלְיוֹנָה וּשְׁכִינָה תַּחְתּוֹנָה."],[2,"","וּלְנֹחַ הִתְגַּלָּה מַה שֶּׁהָיָה וּמַה שֶּׁעָתִיד לִהְיוֹת, וְלֹא בִקֵּשׁ עֲלֵיהֶם רַחֲמִים, עַד שֶׁבָּא מֹשֶׁה וּבִקֵּשׁ רַחֲמִים, שֶׁעֲתִידִים הָיוּ יִשְׂרָאֵל שֶׁלֹּא יֵצְאוּ אֶלָּא אֶחָד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה, מִצַּד הַגְּבוּרָה שֶׁהָיוּ דָנִים, וְהֻחְזַר הָעוֹלָם לְתֹהוּ. וּבִגְלַל שֶׁמֹּשֶׁה בִּקֵּשׁ עֲלֵיהֶם רַחֲמִים, הַשְּׂמֹאל דּוֹחָה וְלֹא יָצְאוּ בָהּ בְּנֵי יִשְׂרָאֵל,"],[3,"","וְיָמִין מְקָרֶבֶת שֶׁהִיא יָמִין מַטֶּה כְּלַפֵּי חֶסֶד. וּמֹשֶׁה, בִּגְלַל שֶׁנָּתַן עַצְמוֹ עֲלֵיהֶם, נָתַן תֹּקֶף לְדַרְגָּתוֹ, שֶׁהִיא עַמּוּד הָאֶמְצָעִי, שֶׁהִיא תּוֹרָה שֶׁנִּתְּנָה בְּיָמִין. זֶהוּ שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ, וּבִגְלַל זֶה הַגְּאֻלָּה תְּלוּיָה בּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית מט) לֹא יָסוּר שֵׁבֶט מִיהוּדָה, עַד כִּי יָבֹא \"שִׁילֹה\", שֶׁהוּא מֹשֶׁה בְּחֶשְׁבּוֹן."],[4,"","יְסוֹד צַדִּיק בּוֹ סוֹ\"ד תְּהֵא שְׂמֹאל דּוֹחָה, אַף עַל פִּי שֶׁפֵּרַשְׁנוּ בוֹ כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה שִׁשִּׁים וָשֵׁשׁ, בִּגְלַל שֶׁנִּקְשָׁר בִּשְׂמֹאל, וְיָמִין מְקָרֶבֶת כִּי תָלוּי מִמֶּנָּה עַמּוּד הָאֶמְצָעִי,"],[5,"","שֶׁשִּׁשִּׁים וָשֵׁשׁ הֵם שִׁשִּׁים מַסֶּכְתּוֹת, וְשִׁשָּׁה סִדְרֵי מִשְׁנָה שֶׁנִּתְּנוּ מִגְּבוּרָה שֶׁהִיא שְׂמֹאל. שִׁשִּׁים גִּבּוֹרִים נִקְרְאוּ שֶׁנּוֹסְעִים מִגְּבוּרָה, שֶׁשָּׁם תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהִיא שְׁכִינָה תַּחְתּוֹנָה, כְּלָל שֶׁל שִׁשִּׁים מַסֶּכְתּוֹת וְשִׁשָּׁה סִדְרֵי מִשְׁנָה."],[6,"","שֶׁתּוֹרָה שֶׁבִּכְתָב, לַפֶּה לֹא הִתְגַּלְּתָה, בִּגְלַל שֶׁעָתִיד שְׂמֹאל, שֶׁהִיא פֶּה, לְהִדָּחוֹת. וְלָכֵן הוּא מַסְתִּיר כָּךְ הַגְּאֻלָּה בַּלֵּב, וְהַפֶּה שֶׁהוּא גָלוּי לֹא מִתְגַּלָּה הַגְּאֻלָּה,"],[7,"","וּבִגְלַל שֶׁהַכֹּל תָּלוּי בַּיָּמִין, אָמַר הַנָּבִיא (ישעיה נג) וּזְרוֹעַ ה' עַל מִי נִגְלָתָה. עַל מִי וַדַּאי, שֶׁנֶּאֱמַר בָּהּ מִי יִרְפָּא לָךְ,"],[8,"","זֶהוּ שֶׁכָּתוּב (איכה ב) מָ\"ה אֲעִידֵךְ מָ\"ה אֲדַמֶּה לָּךְ, וְאָמְרוּ לִי מַ\"ה שְּׁמוֹ, בְּמַ\"ה יָבא הַזְּמַן, וּבְמַ\"ה תָּבא רְפוּאָה. זֶהוּ שֶׁכָּתוּב (שם) מָה אַשְׁוֶה לָּךְ וַאֲנַחֲמֵךְ וְגוֹמֵר, מִ\"י יִרְפָּא לָךְ, שֶׁמֹּשֶׁה הוּא מַ\"ה שְּׁמוֹ וּבוֹ תְּהֵא נֶחָמָתֵךְ. וּבִגְלַל כָּךְ כָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁמוֹ מֹשֶׁה מֹשֶׁה, אֶחָד עַל גְּאֻלָּה הָרִאשׁוֹנָה, וְאֶחָד עַל הָאַחֲרוֹנָה, וּבִגְלַל זֶה אָז יָשִׁיר מֹשֶׁה. אָז שָׁר לֹא נֶאֱמַר, אֶלָּא אָז יָשִׁיר."],[9,"","עָשִׂירִי בַּתְּפִלָּה, וְזוֹ שְׁכִינָה, וְעָלֶיהָ נֶאֱמַר (תהלים יז) תְּפִלָּה לְדָוִד שִׁמְעָה ה' צֶדֶק. וְדָוִד בְּרוּחַ הַקֹּדֶשׁ אָמַר בְּאַחֲרִית הַיָּמִים שֶׁל הַגָּלוּת, אָמַר עַל יִשְׂרָאֵל (שם) בָּחַנְתָּ לִבִּי פָּקַדְתָּ לַּיְלָה, וְאֵין לַיְלָה אֶלָּא גָּלוּת, וּמַה שֶּׁאָמַר אִיּוֹב הַכֹּל הָיָה מָשָׁל עַל יִשְׂרָאֵל שֶׁאָמַר כָּלָה עָנָן וַיֵּלַךְ, וְהַשָּׁטָן רָצָה לְקַטְרֵג לוֹ, וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִיּוֹב לֹא בְדַעַת יְדַבֵּר. אַף בְּיַעֲקֹב כָּךְ, בִּגְלַל שֶׁרָאָה בְּרוּחַ קָדְשׁוֹ אֶת דּחַק הַגָּלוּת: ע\"כ."],[10,"","זֶרַע אַבְרָהָם אֹהֲבִי. אֵין מִי שֶׁעוֹמֵד לִפְנֵי שַׁעַר הַתְּפִלָּה, וְעָלָיו נֶאֱמַר (שם קכז) לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אֹיְבִים בַּשָּׁעַר, שֶׁהוּא שַׁעַר הַמֶּלֶךְ, בִּגְלַל שֶׁתְּפִלָּה הִיא מִצְוָה, וְזוֹ שְׁכִינָה, וְתוֹרָה זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא צָרִיךְ בֵּינֵיהֶם הַפְסָקָה, וְצָרִיךְ לְהַעֲלוֹת תּוֹרָה וּמִצְוָה בְּיִרְאָה וְאַהֲבָה, שֶׁכָּל מִצְווֹת עֲשֵׂה וְלֹא תַעֲשֶׂה תְּלוּיוֹת מִשֵּׁם יְהֹוָ\"ה, כְּמוֹ שֶׁבֵּאַרְנוּ סוֹד זֶה שְּׁמִי עִם י\"ה - שס\"ה מִצְווֹת לֹא תַעֲשֶׂה, וְזֶה זִכְרִי עִם ו\"ה - רמ\"ח מִצְווֹת עֲשֵׂה,"],[11,"","וַהֲרֵי כָּאן מָאתַיִם וּשְׁמוֹנָה וְאַרְבָּעִים, וּשְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִּׁים, וְהֵן מָאתַיִם וּשְׁמוֹנֶה וְאַרְבָּעִים תֵּבוֹת שֶׁבִּקְרִיאַת שְׁמַע, וְנִתְּנוּ מֵאַהֲבָה וְיִרְאָה שֶׁל אוֹת ה', וּמִשּׁוּם כָּךְ תִּקְּנוּ הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה, וְהֵם כְּלוּלִים בְּאַבְרָהָם שֶׁנֶּאֱמַר בּוֹ (ישעיה מא) זֶרַע אַבְרָהָם אֹהֲבִי."],[12,"","תְּפִלִּין הֵן עֹז שֶׁנִּתְּנוּ מִיִּרְאָה שֶׁהִיא לִשְׂמֹאל, וְזֶה פַּחַד יִצְחָק, שֶׁשָּׁם כָּל הַמְקַטְרְגִים עוֹלִים לִתְבֹּעַ כָּל הַדִּינִים, וְלָכֵן וּבִזְרוֹעַ עֻזּוֹ - זֶה תְּפִלִּין, י\"ה בְּיִרְאָה, ו\"ה בְּאַהֲבָה. זֶהוּ שֶׁכָּתוּב (תהלים לא) אֶהֱבוּ אֶת ה' כָּל חֲסִידָיו. בּא רְאֵה, יְהֹוָ\"ה כּוֹלֵל הַכֹּל, וְלָכֵן נֶאֱמַר בְּיַעֲקֹב וְהִנֵּה יְהֹוָ\"ה נִצָּב עָלָיו, שֶׁהוּא עַמּוּד הָאֶמְצָעִי לְאַחַר שֶׁהוּקַם. (כתוב בדפוס, עד בדמות של רבונו ודאי)"],[13,"","שֶׁכַּאֲשֶׁר תְּפִלָּתוֹ עוֹלָה לְמַעְלָה, הַכָּרוֹז יוֹצֵא מִן הָרְקִיעִים וְיֹאמַר הָבוּ כָבוֹד לִדְיוֹקַן הַמֶּלֶךְ, וְאֵין שַׁעַר שֶׁעוֹמֵד לִפְנֵי הַתְּפִלָּה הַזּוֹ. אֲדנָי שְׂפָתַי תִּפְתָּח - לְהוֹצִיא מָזוֹן לַבָּנִים הַקְּדוֹשִׁים, שֶׁבַּהֵיכָל הַזֶּה שָׁם הַמָּזוֹן."],[14,"","בָּנִים חַיִּים וּמְזוֹנוֹת מִצַּד עַמּוּד הָאֶמְצָעִי, שֶׁהוּא בְּנִי בְכֹרִי יִשְׂרָאֵל, וְהוּא עֵץ הַחַיִּים שֶׁיּוֹצֵא מֵהַחַיִּים שֶׁלְּמַעְלָה, וְהוּא הָעֵץ שֶׁבּוֹ מָזוֹן לְכֻלָּם."]]],[["וּבְנִין דִשְׁכִינָה אִינוּן יִשְׂרָאֵל לְתַתָּא, חַיִּים דִּילָהּ אוֹרַיְיתָא, מְזוֹנָא דִּילָה צְלוּתָא דְּחַשִׁיבָא לְקָרְבָּנָא. וּבְגָלוּתָא אִתְמַר לְגַבֵּי יִשְׂרָאֵל (בראשית לכ) הָבָה לִי בָּנִים וּשְׁכִינְתָּא אִיהִי קָרְבָּנָא לְקוּדְשָׁא בְּרִיךְ הוּא דִמְקַבֵּל לָהּ בִּימִינָא וּשְׂמָאלָא וְגוּפָא וְיִחוּדָא דִּילֵיהּ עִמָּהּ בְּצַדִיק דְאִיהוּ אוֹת תְּפִילִין וְשַׁבָּת וְיָמִים טוֹבִים.","וְאִית לְמִשְׁאַל לָמָה מְצַלְאָן לְקוּדְשָׁא בְּרִיךְ הוּא בְּכַמָּה דַרְגִּין, זִמְנִין מַצְלִין לֵיהּ בִּסְפִירָה יְדִיעָא וּבְמִדָּה יְדִּיעָא לְזִמְנִין צְלוֹתָא לִימִינָא הֲדָא הוּא דְאִתְמָר הָרוֹצֶה לְהַחְכִּים יַדְרִים. לְזִמְנִין לִשְׂמָאלָא, הֲדָא הוּא דְאִתְמָר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, לְזִמְנִין דְּאַבָּא וְאִימָא לִימִינָא וְלִשְׂמָאלָא אִינוּן לְזִמְנִין לְעַמּוּדָא דְאֶמְצָעִיתָא לְזִמְנִין לְצַדִּיק כָּל צְלוֹתָא סַלְקָא לְדַרְגָּא יְדִיעָא.","אֶלָּא וַדָאי יהו\"ה אִיהוּ בְּכָל סְפִירָה וּסְפִירָה וּצְלוֹתָא אִיהִי שְׁכִינְתָּא. בְּזִמְנָא דְּבָּעֵי לְרַחֲמָא עַל עַלְמָא סְלִיקַת בִּימִינָא וּבְזִמְנָא דְּבָעֵי לְמֶעְבָּד דִּינָא בְּעַלְמָא סְלִיקַת בִּשְׂמָאלָא וְכוֹלָא לְגַבֵּי יהו\"ה דְאִיהוּ בְּכָל אֲתַר וּבְגִין דָּא זֹאת תּוֹרַת הָעוֹלָה עוֹלָה לַיְיָ וְדָא צְלוֹתָא דְּאִיהִי שְׁכִינְתָּא קָרְבָּן לַיְיָ וְדָא צְלוֹתָא דְּאִיהִי קָרְבָּנָא דִּילֵיהּ וְכַד סַלְקָא לְגַבֵּיהּ צָרִיךְ לְאַכְלָלָא עִמָּהּ כָּל סְפִירָן דְּלֵית קְדוּשָׁה פָּחוֹת מֵעֲשָׂרָה.","מִדְרָשׁ רוּת: הַצַּדִּיק אֲבַד כָּל זְמָן שֶׁלֹּא יָבֹא הַשֶׁפַע אֲבַד וְעָלָיו נֶאֱמַר (ישעיהו י״ט:ה׳) וְנָהָר יֶחרַב וְיָבֵשׁ וּבְעֵת הַבְּרָכָה נְאֶמָר (תהילים ה׳:י״ג) כִּי אַתָּה תְּבָרֵךְ צַדִּיק בְּרָכוֹת לְרֹאשׁ צַדִּיק:","סֵפֶר הַבָּהִיר: תָּנָא עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים וּכְשְׁיֶשׁ צַדִּיקִים מִתְגַבֵּר וְאִם לָאו מִתְחַלֵשׁ וְהוּא סוֹבֵל כָּל הָעוֹלָם דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם וְאִם חָלַשׁ לא יוּכַל לְהִתְקַיֵּים הָעוֹלָם ע\"כ:","\u0003סִתְרֵי תּוֹרָה\u0004 וַיוֹלֶד בִּדְמוּתּוֹ כְּצַּלְמוֹ וַיִּקְרָא אֶתּ שְׁמוֹ שֵׁתּ אוֹלִיפְּנָא מֵהָכָא דְאֲחַרִינָן לָא הֲווּ בְּדִיּוּקְנָא דִילֵיהּ וְדָא בִּדְמוּתּוֹ כְּצַּלְמוֹ אִתְּעֲבִיד בְּתִּיקוּנא דְּגוּפֵּיהּ וּבְתִּיקוּנָא דְּנַפְּשָׁא בְּאוֹרַח מֵישַׁר כְּדְקָא יִאוֹתּ. תּא חֲזֵי נָחָשׁ אַטִיל זוֹהֲמָא בְּחַוָּה וְהַהוּא זוֹהֲמָא הֲוָה מֵכַּשְׁכֵּשָׁא בִּמְעָהָא וְלָא יָכִיל לְאִצְּטַיְירָא","בְּגִין דְּעַד לָא חַטָא אָדָם הֲווּ אַתְּוָון בְּאַלְפָּא בֵּיתָּא מִתְּתַּקְנֵי בֵּיה וְאִתְּצַּיְּירָן בֵּיה בְּהַאי עַלְמָא עַד דְמַטָתּ לְאָתּ כ\"ף אִתְּתְּקָנוּ דְכָר וְנוּקְבָא בְּחַבִיבוּ בְּגִנְתָּא וּמַלְאֲכֵי עִלָּאֵי קַמַּיְיהוּ מִיָד אֲבְאִישׁ לְסמ\"אל בִּרְקִיעָא וְנָחַתּ וְרָכָב עַל נָחָשׁ תַּקִיף וְאַחְזִי קַמֵּיהּ מַיָא אִתְּעֲרְבוּ אַתְּוָון","כְּדֵין אִתְּחַבָּר סמ\"אל בְּהַהוּא נָחָשׁ וְאִתְּעֲבִידוּ חַד, וְנָטְלוּ אַתְּוָון וְעָבִידוּ מִתַּמָּן וַהֲלְאָה אוּמָנוּתָּא בִּישָׁא בְּאַתְּוון צּ\"ד צּי\"ד וְהַיְינוּ צּ\"ץ וְצָּדוּ לְהוּ בְּפִּתּוּיָא בִּישָׁא וַעֲבְדוּ אוּמָנוּתָּא יַתִּיר בְּאַתְּוון ק\"ר אוּמָנוּתּ דְשִׁקְרָא בְּגִין דְאִתְּהֲדָרוּ לְאַפְּכָא (להפכא) אַתְּוָון בְּאוּמָנוּתָּא בִּישָׁא. קו\"ף דְלָא יָכִיל לְקַיְימָא דְּלֵיתּ לָהּ רַגְלִין קוֹפָּא קַמֵּיהּ בְּנֵי נָשָׁא לֵיתּ לֵיהּ קִיוּמָא. רי\"ש רָע, אִלֵּין אִתְּהֲפָּכוּ בְּאוּמָנוּתָּא בִּישָׁא עַל דְנַפְּלוּ אָדָם וְאִתְּתֵּיהּ","וּבְאִלֵּין אַתְּוָון ק\"ר אוֹלִידוּ בְּנִין ולא הֲווּ בְּקִיּוּמָא בְּדִיל זוֹהֲמָא דְנָחָשׁ דְאִשְׁתָּאִיב בְּחַוָּה מֵהַהוּא זוֹהֲמָא מַמָּשׁ אִתְּיְלִיד קַיִן וּבְגִין דָּא אִשְׁתְּכַח קָטוֹלָא בְּגִין דְנָחָשׁ אוּמָנוּתָּא דִּילֵיהּ קָטוֹלָא הוּא וְאִתְּעֲכְּבוּ אַתְּוָון עַד הָכָא.","בְּשַׁעֲתָא דְּתָּב אָדָם בְּתִּיּוּבְתָּא וְאַהֲדַר כְּמִלְקַדְמִין לְשָׁמְשָׁא בְּנוּקְבֵיהּ מָה כְּתִּיב וַיוֹלֶד בּדמוּתּוֹ כְּצַּלְמוֹ דָּא הֲוָה מֵתִּיקוּנָא דְרוּחָא וְגוּפָּא כְּדְקָא יֵאוֹתּ וּכְדֵין כְּתִּיב (קהלת ה') יְשִׁ הֶבֶל אֲשֶׁר נַעֲשָׂה על הָאָרֶץ ואֲהַדְרוּ אַתְּוָון בְּשֵׁירוּתָּא דשי\"ן ותּי\"ו דִּכְתִּיב (בראשית ד׳:כ״ה) כִּי שָׁתּ לִי אֱלהִים זְרַע אַחֵר תַּחַתּ הֶבֶל שֵׁתּ הוּא בְּצֶּלֶם וּדְמוּתּ דְקַדְמָאֵי לָאו הֲכִי וּמֵהָכָא אִתְּבְּנֵי עַלְמָא בְּגווָֹנָא אַחָרָא דְאַלְפָּא בֵּיתָּא, קֵינָן וּמַהֲלַלְאֵל יֶרֶד, אִתּוֹסַף לְאַתְּקְנָא","סִידוּרָא דְעַלְמָא בְּשֶׁבַע קִטְרִין סְגָלְגֶלָן. שֶׁבַע אַרְצּוֹתּ אִינוּן דּא לְעֵילָא מִן דָּא כְּמָה דְּאִינּוּן שִׁבְעָה רְקִיעִין דָּא לְעֵילָא מִן דָּא וְאִינּוּן אֶרֶץ אֲדָמָה אַרְקָא גֵיא נְשִׁיָּה צִּיָּה תֵּבֵל. תֵּבֵל לְעֵילָא מִכֻּלְּהוּ, דִכְתִּיב (תהלים ט') והוּא יִשְׁפּוֹט בְּצֶּדֶק","כַּד נָפַּק אָדָם מִגִּנְתָּא דְעֵדֶן וְאִתְּתַּרַךָ מִתַּמָּן אִתְּרַמֵי לְהַהוּא דְאִיקְרֵי אֶרֶץ ואִיהוּ אֲתַּר חשוּךְּ דְּלֵיתּ תַּמָּן נְהִירוּ כְּלָל וְלָא מְשַׁמֵּשׁ כְּלוּם וְכֵיוָן דְּאָדָם עָאל תַּמָּן דָחִיל דְּחִילוּ סַגִּי ולהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ הֲוָה מֵלָהַטָא בְּכָל סִטְרִין גּוֹ אֶרֶץ.","כֵּיוָן דְּנָפַּק שַׁבָּתּ וְהִרְהֵר תְּשׁוּבָה אַפִּיק קוּדְשָׁא בְּרִיךָ הוּא לֵיהּ לְהַהוּא אֲתַּר דְאִקְּרֵי אֲדָמָה דִּכְתִּיב (בראשית ג׳:כ״ג) לַעֲבוֹד אֶתּ הָאֲדָמָה, בְּהַאי אִיתּ נְהִירוּ דְנָהִיר וְדִיּוּקְנִין דְכֹכְבַיָּא וּמַזָּל,","וְתַּמָּן יוֹמָא וְצִּיּוּרִין דִּבְנֵי נַשָׁא עִלָּאִין גַבְרִין דְּנַפְּקוּ מֵאָדָם בְּמֵאָה וּתְּלָתִּין שְׁנִין דְּקָא הֲוָה משמּש בְּרוּחֵי נוּקְבֵי ואִינּוּן עֲצִּיבִין תָּדִיר, תַּלְיָא בְּהוּ חֶדְוָה ואִלֵּין מֵשָׁטְטֵי וְנָפְּקֵי לְעַלְמָא דָּא וּמִתְּהַפְּכָן לְסִטְרָא בִּישָׁא וּמִתְּהַדְרָן תַּמָּן וְצָּלַאן צְּלוֹתָּא וּמִתְּיָישְׁבָן בְּדוּכְתָּיְיהוּ תַּמָּן, וְזַרְעִין זַרְעִין בְּרֵיחִין, ואַכְלֵי. וְחִטִין לֵיתּ תַּמָּן וְלָא חַד מִז' מִינֵי תְּבוּאָה. בְּהַאי אֲתַּר אִתְּיְלִיד קַיִן וְהֶבֶל,"],[],[[0,"","וּבְנֵי הַשְּׁכִינָה הֵם יִשְׂרָאֵל לְמַטָּה, הַחַיִּים שֶׁלָּהּ תּוֹרָה, הַמָּזוֹן שֶׁלָּהּ תְּפִלָּה, שֶׁחֲשׁוּבָה כְּקָרְבָּן, וּבַגָּלוּת נֶאֱמַר אֵצֶל יִשְׂרָאֵל הָבָה לִּי בָנִים, וּשְׁכִינָה הִיא קָרְבָּן לַקָּדוֹשׁ-בָּרוּךְ- הוּא שֶׁמְּקַבֵּל אוֹתָהּ בְּיָמִין וּשְׂמֹאל וְגוּף, וְיִחוּדוֹ עִמָּהּ בְּצַדִּיק, שֶׁהוּא אוֹת תְּפִלִּין וְשַׁבָּת וְיָמִים טוֹבִים."],[1,"","וְיִשִׁ לִשְׁאֹל, לָמָּה מִתְפַּלְלִים אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכַמָּה דְרָגוֹת? לִפְעָמִים מִתְפַּלְלִים אֵלָיו בִּסְפִירָה יְדוּעָה וּבְמִדָּה יְדוּעָה, לִפְעָמִים תְּפִלָּה לְיָמִין - זֶהוּ שֶׁנֶּאֱמַר הָרוֹצֶה לְהַחְכִּים יַדְרִים, לִפְעָמִים לִשְׂמֹאל - זֶהוּ שֶׁנֶּאֱמַר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, לִפְעָמִים שֶׁל אָב וָאֵם הֵם לְיָמִין וְלִשְׂמֹאל, וְלִפְעָמִים לָעַמּוּד הָאֶמְצָעִי, לִפְעָמִים לְצַדִּיק, כָּל תְּפִלָּה עוֹלָה לְדַרְגָּה יְדוּעָה. אֶלָּא וַדַּאי יְהֹוָ\"ה הוּא בְּכָל סְפִירָה וּסְפִירָה, וּתְפִלָּה הִיא שְׁכִינָה."],[2,"","בִּזְמַן שֶׁמְּבַקֵּשׁ לְרַחֵם עַל הָעוֹלָם עוֹלָה בְּיָמִין, וּבִזְמַן שֶׁמְּבַקֵּשׁ לַעֲשׂוֹת דִּין בָּעוֹלָם עוֹלָה בִּשְׂמֹאל, וְהַכֹּל אֶל יְהֹוָ\"ה שֶׁהוּא בְּכָל מָקוֹם, וְלָכֵן זֹּאת תּוֹרַת הָעֹלָה, עוֹלָה לַה', וְזוֹ תְּפִלָּה שֶׁהִיא שְׁכִינָה קָרְבָּן לַה', וְזוֹ תְּפִלָּה שֶׁהִיא קָרְבָּנוֹ, וּכְשֶׁעוֹלָה אֵלָיו, צָרִיךְ לְהַכְלִיל עִמָּהּ אֶת כָּל הַסְּפִירוֹת, שֶׁאֵין קְדֻשָּׁה פָּחוֹת מֵעֲשָׂרָה: ע\"כ."],[3,"","הַצַדִּיק אָבָד - כָּל זְמַן שֶׁלֹּא יָבֹא הַשֶּׁפַע אָבַד, וְעָלָיו נֶאֱמַר (ישעיה יט) וְנָהָר יֶחֱרַב וְיָבֵשׁ. וּבְעֵת הַבְּרָכָה - (תהלים ה) כִּי אַתָּה תְבָרֵךְ צַדִּיק, בְּרָכוֹת לְרֹאשׁ צַדִּיק: ע\"כ."],[4,"","לָמַדְנוּ, עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים, וּכְשֶׁיֵּשׁ צַדִּיקִים - מִתְגַּבֵּר, וְאִם לָאו - מִתְחַלֵּשׁ, וְהוּא סוֹבֵל כָּל הָעוֹלָם, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חַלָּשׁ, לֹא יוּכַל לְהִתְקַיֵּם הָעוֹלָם: ע\"כ."],[5,"","וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת. לָמַדְנוּ מִכָּאן, שֶׁהָאֲחֵרִים לֹא הָיוּ בַּדְּמוּת שֶׁלּוֹ, וְזֶה בִּדְמוּתוֹ כְּצַלְמוֹ נַעֲשָׂה, בְּתִקּוּן הַגּוּף וּבְתִקּוּן הַנֶּפֶשׁ, בְּדֶרֶךְ יָשָׁר כָּרָאוּי. בֹּא רְאֵה, הַנָּחָשׁ הִטִּיל זֻהֲמָה בְּחַוָּה, וְאוֹתָה זֻהֲמָה הָיְתָה מְכַשְׁכֶּשֶׁת בְּמֵעֶיהָ וְלֹא יָכְלָה לְהִצְטַיֵּר,"],[6,"","מִשּׁוּם שֶׁעַד שֶׁלֹּא חָטָא אָדָם, הָיוּ אוֹתִיּוֹת הָא\"ב מְתֻקָּנִים בּוֹ וּמִצְטַיְּרִים בּוֹ בָּעוֹלָם הַזֶּה, עַד שֶׁהִגִּיעוּ לָאוֹת כָּ\"ף, נִתְקְנוּ זָכָר וּנְקֵבָה בַּחֲבִיבוּת בַּגַּן, וּמַלְאָכִים עֶלְיוֹנִים לִפְנֵיהֶם. מִיָּד הֵרַע לְסמא\"ל בָּרָקִיעַ, וְיָרַד וְרָכַב עַל נָחָשׁ חָזָק וְנִרְאָה לְפָנָיו. מִיָּד הִתְעָרְבוּ הָאוֹתִיּוֹת,"],[7,"","וְאָז הִתְחַבֵּר סמא\"ל עִם אוֹתוֹ הַנָּחָשׁ וְנַעֲשׂוּ אֶחָד, וְלָקְחוּ אוֹתִיּוֹת, וְעָשׂוּ מִשָּׁם וָהָלְאָה אֻמָּנוּת רָעָה בְּאוֹתִיּוֹת צ\"ד צי\"ד, וְהַיְנוּ צ\"ץ, וְצָדוּ אוֹתָם בְּפִתּוּי רַע, וְעָשׂוּ אֻמָּנוּת יְתֵרָה בְּאוֹתִיּוֹת ק\"ר, אֻמָּנוּת שֶׁל שֶׁקֶר, מִשּׁוּם שֶׁחָזְרוּ לַהֲפֹךְ אוֹתִיּוֹת בְּאֻמָּנוּת רָעָה. קוֹ\"ף, שֶׁלֹּא יָכוֹל לַעֲמֹד, שֶׁאֵין לוֹ רַגְלַיִם. קוֹף לִפְנֵי בְּנֵי אָדָם אֵין לוֹ קִיּוּם. רֵי\"שׁ, רַע אֵלּוּ הִתְהַפְּכוּ בְּאֻמָּנוּת רָעָה עַד שֶׁנָּפְלוּ אָדָם וְאִשְׁתּוֹ,"],[8,"","וּבָאוֹתִיּוֹת הַלָּלוּ ק\"ר הוֹלִידוּ בָנִים וְלֹא הָיוּ בְּקִיּוּם בִּשְׁבִיל זֻהֲמַת הַנָּחָשׁ שֶׁנִּשְׁאֲבָה בְּחַוָּה, מֵאוֹתָהּ זֻהֲמָה מַמָּשׁ נוֹלַד קַיִן, וְלָכֵן נִמְצָא הַהֶרֶג, מִשּׁוּם שֶׁאֻמָּנוּת הַנָּחָשׁ הִיא הֶרֶג, וְהִתִעַכְּבוּ הָאוֹתִיּוֹת עַד כָּאן."],[9,"","בְּשָׁעָֹה שֶׁאָדָם שָׁב בִּתְשׁוּבָה וְחָזַר כְּמוֹ קֹדֶם לְשַׁמֵּשׁ עִם נְקֵבָתוֹ, מַה כָּתוּב? וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, זֶה הָיָה מִתִּקּוּן שֶׁל רוּחַ וְגוּף כָּרָאוּי, וְאָז כָּתוּב (קהלת ח) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, וְחָזְרוּ הָאוֹתִיּוֹת בַּהַתְחָלָה שֶׁל שִׁי\"ן וְתָי\"ו, שֶׁכָּתוּב (בראשית ד) כִּי 'שָׁת' לִי אֱלֹהִים זֶרַע אַחֵר תַּחַת הֶבֶל. שֵׁת הוּא בְּצֶלֶם וּדְמוּת, שֶׁהָרִאשׁוֹנִים לֹא כָּךְ, וּמִכָּאן נִבְנָה הָעוֹלָם בְּגָוֶן אַחֵר שֶׁל אַלְפָא בֵּיתָא. קֵינָן וּמַהֲלַלְאֵל יֶרֶד,"],[10,"","נוֹסַף לְתַקֵּן סִדּוּר הָעוֹלָם בְּשִׁבְעָה קְשָׁרִים. שֶׁבַע אֲרָצוֹת הֵן זוֹ לְמַעְלָה מִזּוֹ, כְּמוֹ שֶׁאוֹתָם שִׁבְעָה רְקִיעִים זֶה לְמַעְלָה מִזֶּה, וְהֵם: אֶרֶץ, אֲדָמָה, אַרְקָא, גֵּיא, נְשִׁיָּה, צִיָּה, תֵּבֵל. תֵּבֵל הִיא לְמַעְלָה מִכֻּלָּם, שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק."],[11,"","כְּשֶׁיָּצָא אָדָם מִגַּן עֵדֶן וְגֹרַשׁ מִשָּׁם, הוּא נִזְרַק לְאוֹתָהּ שֶׁנִּקְרֵאת אֶרֶץ, וְהוּא מָקוֹם חָשׁוּךְ שֶׁאֵין שָׁם אוֹר כְּלָל וְלֹא מְשַׁמֵּשׁ כְּלוּם. כֵּיוָן שֶׁאָדָם נִכְנַס לְשָׁם, הוּא פָּחַד פַּחַד גָּדוֹל, וְלַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת הָיְתָה לוֹהֶטֶת בְּכָל הַצְּדָדִים בְּכָל הָאָרֶץ."],[12,"","כֵּיוָן שֶׁיָּצְאָה שַׁבָּת וְהִרְהֵר תְּשׁוּבָה, הוֹצִיא אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה, שֶׁכָּתוּב (בראשית ג) לַעֲבֹד אֶת הָאֲדָמָה. בָּזֹאת יֵשׁ אוֹר שֶׁמֵּאִיר וּדְמֻיּוֹוֹת שֶׁל כּוֹכָבִים וּמַזָּלוֹת,"],[13,"","וְשָׁם יוֹם, וְצִיּוּרִים שֶׁל בְּנֵי אָדָם עֶלְיוֹנִים, גְּבָרִים שֶׁיָּצְאוּ מֵאָדָם בְּמֵאָה וּשְׁלֹשִׁים הַשָּׁנִים שֶׁהָיָה מְשַׁמֵּשׁ עִם רוּחוֹת נְקֵבוֹת, וְהֵם תָּמִיד עֲצוּבִים, שֶׁאֵין בָּהֶם חֶדְוָה, וְאֵלֶּה מְשׁוֹטְטִים וְיוֹצְאִים לָעוֹלָם הַזֶּה וּמִתְהַפְּכִים לְצַד רַע, וְחוֹזְרִים לְשָׁם וּמִתְפַּלְלִים תְּפִלָּה, וּמִתְיַשְּׁבִים בִּמְקוֹמָם שָׁם, וְזוֹרְעִים זְרָעִים בָּרֵחַיִם וְאוֹכְלִים, וְאֵין שָׁם חִטִּים. וְלָא אֶחָד מִז' מִינֵי תְבוּאָה. בְּזְהִ הַמָּקוֹם נוֹלְדוּ קַיִן וְהֶבֶל,"]]],[["כֵּיוָן דְחָטָא קַיִן אָחִיתּ לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא מֵהַהוּא אֲתַּר דְאִקְּרֵי אֲדָמָה כְּתִּיב (בראשית ד׳:י״ד) הֵן גֵרַשְׁתָּ אוֹתִּי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה מֵהַהוּא אֲתַּר דְאִקְרֵי אֲדָמָה והֲיִיתִּי נָע ונָד בָּאָרֶץ בְּגִין דְּתַּמָּן אִתְּדַחָא וְאִתְּתַּרַךָ. וְהָיָה כָּל מוֹצְּאִי יַהֲרְגֵנִי בְּהַהוּא לַהַט הַחֶרֶב הַמִּתְּהַפֶּכֶתּ","וַהֲוָה דָחִיל וְהִרְהֵר תְּשׁוּבָה וְסָלִיק לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא לְאַרְקָא וַהֲוָה תַּמָּן וְאוֹלִיד בְּנִין בְּאַרְקָא וּבְאַרְקָא אִיתּ נְהִירוּ דְנָהִיר מִגּוֹ שִׁמְשָׁא, וְזַרְעִין זַרְעִין וְנָטְעִין אִילָנִין וְלֵיתּ תַּמָּן חִטִין ולא מֵאִינוּן שֶׁבַע זִינֵי תְּבוּאָה.","כָּל אִינוּן דְּתַּמָּן אִינוּן מִתּוֹלָדִין דְּקַיִן וְאִינּוּן בִּתְּרֵין רֵישִׁין מִנְּהוֹן גַבְרִין עִלָּאִין וּמִנְהוֹן גַבְרִין זְעִירִין וְלֵיתּ בְּהוּ דַּעְתָּא שְׁלִים כִּשְׁאָר בְּנֵי נַשָׁא דְהָכָא, לְזִמְנִין אִינוּן זַכָּאִין ואִתְּהֲדְרָן לְסִטְרָא טָבָא וּלְזִמְנִין אִתְּהֲדְרָן לְסִטְרָא בִּישָׁא וּמוֹלִידִין וּמֵתִּין כִּשְׁאַר בְּנֵי נָשָׁא.","אָדָם הֲוה בְּאֲדָמָה (וארקא) עַד דְּאוֹלִיד שֵׁתּ וּמִתַּמָן סָלִיק לְעֵילָא ד' דַרְגִּין וְסָלִיק לְהַאי אֲתַּר דְאִקְּרֵי תֵּבֵל וְדָא תֵּבֵל אִיהוּ עִלָּאָה דְכֻלְּהוּ דַרְגִּין. כֵּיוָן דְסָלִיק סָלִיק לַאֲתָּר בֵּיתּ מַקְדְּשָׁא דְאִקְּרֵי בְּאִינוּן שְׁמָהָן דַהֲוָה דִּיוֹרֵיהּ בָּהּ אֶרֶץ אֲדָמָה דְהַכִי אִקְרֵי","דָּלִיג אָדָם תְּלָתּ דוּכְתֵּי גֵיא, נְשִׁיָּה, צִּיָּה, גֵיא אִיהוּ אֲתַּר וְדּוּכְתָּא סַגִּי כְּהַאי פּוּתְּיָא וְאַרְכָּא דִּגֵיהִנָּם בַּגַּיא וּנְשִׁיָּה וְצִּיָּה אִתְּבַּדָּרוּ דְבָּנוּ מַגְדְּלָא ואוֹלִידוּ תַּמָּן על דְאַרְגִיזוּ לְמַלְכָּא עִלָּאָה בְּגִין דָּא קָרִיב לְנוּרָא דְּדָלִיק. וְאִיתּ בְּנֵי נָשָׁא יְקִירֵי בְּכָל עוּתְּרָא וְעֲפְּרוֹתּ זָהָב וְאַבְנִין יְקִירִין מָאן דְּעָאל תַּמָּן וַהֲוָה מִתֵּבֵל בְּחַמִידוּ דְּהַהוּא עוּתְּרָא יָהֲבִין לֵיהּ וְסָלִיק לְזִמְנִין לְדּוּכְתָּא דְאִקְּרֵי נְשִׁיָּה כְּגוֹן דְּאִתְּנָשׁוּ תַּמָּן ונָחִיתּ לְהַאי גֵיא וְלָא יָדַע אֲתַּר דַּהֲוָה מִתַּמָּן.","גֵיא דָּא הוּא בְּאֶמְצָּעוּתָּא דְּעֵילָּא וְתַּתָּא וְדָא אִיקְּרֵי גֵיא בֵּן הִנוֹם. וּרְצּוּעָה חֲדָא נָפְּקָא מִתַּמָּן לְעֵילָא לְהַאי תֵּבֵל וְאִיקְּרֵי אוּף הֲכִי גֵיא בֵּן הִנוֹם וְתַּמָּן פִּתְּחָא דְּגֵיהִנָּם. אִינוּן בְּנֵי נָשָׁא דְּתַּמָּן כּוּלְהוּ יָדְעֵי חַרְשִׁין וחַכָּמָאן יְקִירִין וְתַּמָּן זַרְעֵי ונַטְעֵי אִילָנִין ולֵיתּ תַּמָּן חִטִין וְלָא חַד מִשִׁבְעַתּ הַמִינִים.","בִּנְשִׁיָה אִיתּ בְּנֵי נָשָׁא כּוּלְהוּ קְטִיעִין זְעִירִין וְלֵיתּ לְהוֹן חוֹטְמִין בָּר תְּרֵין נוּקְבִין דְנָפִּיק בְּהוּ רוּחָא וְכָל מָה דְּעַבְדֵי מִיָד מִשִׁתַּכְּחֵי וְעַל דָּא אִיקְרֵי נְשִׁיָּה וזַרְעֵי ונַטְעֵי אִילָנִין ולֵיתּ תַּמָּן חִטִין ולֹא מִשִׁבְעַתּ הַמִינִים.","צִּיָ\"ה אִיהוּ אֲתַּר כִּשְׁמֵיהּ בֵּיה יְבֵשׁוּתָּא בְּכוֹלָא וְתַּמָּן בְּנֵי נָשָׁא שַׁפִּירָן בְּחֵיזוּ וּמִגוֹ דְאִיהוּ צִּיָּה כַּד יַדְעֵי אֲתַּר דִּמְקוֹרָא דְּמַיִין נָבְעִין עָאלִין תַּמָּן וּלְזִמְנִין דְּסָלְקִין מִגּוֹ אֲתַּר דְמַיָּא וְסָלְקִין לְהַאי תֵּבֵל וְאִינּוּן בְּנֵי מְהֵימְנוּתָּא יַתִּיר מִבְּנֵי נָשָׁא אָחֳרָנִין וּבֵינַיְיהוּ דִיוּרִין טָבִין וְעוּתְּרָא סַגִּי וְזַרְעֵי מִגּוֹ יְבֵשׁוּתָּא דְּהָתָּם וְנַטְעֵי אִילָנִין ולא מַצְּלִיחִין וְתִּיאוּבְתָּא דִילְהוֹן לִבְנֵי נָשָׁא דְהָכָא.","וּמִכֻּלְּהוּ לֵיתּ דְאַכְלֵי נַהֲמָא כַּד (ס\"א בר) אִלֵּין דְהָכָא דְבְּתֶּבֶל הַכָא לְעֵילָא מִכָּל אִלֵּין תֵּבֵל וּכְתִּיב (תהילים ט׳:ט׳) והוּא ישְׁפּוֹט תֵּבֵל בְּצֶּדֶק. כְגַוְונָא דְכָל אִלֵּין אַרְעָאן אִיתּ בְּהַאי תֵּבֵל וְכָל אִלֵּין שְׁמָהָן אִיתּ לָהּ אוּף הֲכִי בְּגִין דְאִיהִי שְׁבִיעָאָה אִיתּ הָכָא כְּגווֹנָא דְּאִינּוּן דוּכְתֵּי תְּחוּמִין וְדוּכְתֵּי הָכָא וְאִיקְּרֵי כּל חַד וְחַד כְּגווָֹנָא דְּהַהוּא דּוּכְתָּא דִלְתַּתָּא. וְכָל אִלֵּין בְּדִיוּרִין דִבְנֵי נָשָׁא מְשַׁנְיָין אִלֵּין מֵאִלֵּין (תהילים ק״ד:כ״ד) מָה רָבּוּ מַעֲשֶׂיךָ יְיָ כֻּלָּם בְּחָכְמָה עָשִׂיתָּ מָלְאָה הָאָרֶץ קִנְיָנְךָ ע\"כ:","רַבִּי חִזְקִיָּה אָמַר זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוֹן וְיָהַב לְהוֹן אוֹרַיְיתָא קַדִּישָׁא וְאַזְהָר לוֹן וְיָהַב לוֹן עֵיטָא לְאִסְתַּמְרָא מֵעֵילָא וְתַתָּא בְּגִין דְלָא יִשְׁלוֹט בְּהוּ בָּר קוּדְשָׁא בְּרִיךְ הוּא וְאִינּוּן יַדְעֵי לְדַּחֲיָא מִנַּיְיהוּ כָּל מְקַטְרְגִין וְכָל קַסְטִירִין בְּגִין דִיְהוֹן חוּלָקָא דְעֲדְבֵיהּ וְאַחֲסַנְתֵּיהּ כְּמָא דְאַתְּ אָמֵר (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","תָּא חֲזֵי בְּיוֹמָא דְּרֹאשׁ הַשָׁנָה קוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עַלְמָא וְכָל בְּנֵי עַלְמָא יַתְבֵי בְּחוּשְׁבָּנָא וְלָא אִית מָאן דְלָא עָאל בְּחוּשְׁבָּנָא וְסִפְרִין דְּחַיִין וּמֵתִין פְּתִיחָן בְּהַהוּא יוֹמָא וְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְאִתְרָעֵי בְּהוּ יָהַב לוֹן עֵיטָא לְאִשְׁתֵּזָבָא מִכָּל קִטְרוּגִין דִלְעֵילָא דְּאִינּוּן אִתְמָנָן וְכֵן בְּכָל זִמְנָא דְּדִינָא שַׁרְיָיא עַל עַלְמָא.","בְּהָאי יוֹמָא אִזְדָמְנָן יִשְׂרָאֵל לְאִתְעָרָא רַחֲמֵי עָלַיְיהוּ וּבְמָה בְּשׁוֹפָר. דְּהָא קָלָא דְנָפִיק סָלִיק לְעֵילָא וְאִתְעַר שׁוֹפָר דִלְעֵילָא כְּדֵין (מתערי) אִתְעֲרוּ רַחֲמֵי מֵאַתְרַיְיהוּ וְקוּדְשָׁא בְּרִיךְ הוּא קָם מִכּוּרְסַיָּיא דְּדִינָא וְיָתִיב בְּכוּרְסַיָּיא דְּרַחֲמֵי וְרָחִים עָלַיְיהוּ דְּיִשְׂרָאֵל וְלָא אִתְיְיהִיב רֵשׁוּ לְמְקַטְרְגָא. וְיִשְׂרָאֵל יַתְבֵי קַמֵי קוּדְשָׁא בְּרִיךְ הוּא בְּתִיּוּבְתָּא וְתַקְעֵי שׁוֹפָר (ומתערי) וְאִתְעֲרוּ רַחֲמֵי דְּהָא הַהוּא קָלָא דְנָפִיק אִתְעָרוּתָא דְּרַחֲמֵי אִיהוּ וּכְדֵין דַלְטוּרָא לָא יָכִיל לְקַיְימָא קַמֵי כוֹרְסַיָּיא דְּרַחֲמֵי דְּהָא לָא אָתֵי מֵהַהוּא סִטְרָא וְלָא אִשְׁתְּכַח קַטֵיגוֹרְיָיא.","בְּיוֹמָא דְכִּפּוּרֵי דְּאִיהוּ חַתִימָא דְּדִינָא וְקַיְימֵי יִשְׂרָאֵל בִּקְדוּשָׁתָא דְמָרַיְיהוּ בְּהַהוּא יוֹמָא בְּגִין דְלָא יִקְרָב דַלְטוּרָא לְמַקְדְּשָׁא יָהֲבִין לֵיהּ שָׂעִיר דְאָתֵי מִסִּטְרָא דְרוּחָא מְסָאָבָא וְהוּא מְסָאָבָא וְרוּחַ מְסָאָבָא אִתְהַנֵי בֵּיהּ (והוא) הוּא אִתְעַסַּק בֵּיהּ וְלָא אִתְקַרָב לְמַקְדְּשָׁא לְסָאַבָא (מסאבא) וּכְדֵין אַנְפִּין נְהִירִין וְיִשְׂרָאֵל מִשְׁתַזְבִין מִנֵּיהּ.","בְּזִמְנָא אַחֲרָא כַּד סָגִי (סגיין) חוֹבֵי בְּנֵי נָשָׁא הַאי דַלְטוּרָא בְּשַׁעְתָּא דְּדִינָא אִתְעָר עַל חוֹבֵי עַלְמָא כְּדֵין אִיהוּ אָתֵי וְאִשְׁתְּכַּח דַלְטוּרָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא וְיִסְתָאַב מַקְדְּשָׁא וְכָל אַנְפִּין עֲצִיבִין וְדִינָא אִשְׁתְּכַח וְעַל דָּא (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, בָּא לְפָנַי וַדָאי לְמִתְבַּע חוֹבֵי עַלְמָא בְּגִין דְּאִינּוּן גָּרְמוּ:"],[],[[0,"","כֵּיוַן דְחָטָא קַיִן הוֹרִיד אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה, שֶׁכָּתוּב (שם ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא אֲדָמָה. וְהָיִיתִי נָע וָנָד בָּאָרֶץ, מִשּׁוּם שֶׁשָּׁם נִדְחָה וְגֹרַשׁ. וְהָיָה כָל מֹצְאִי יַהַרְגֵנִי - אוֹתָהּ לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת,"],[1,"","וְהָיָה פּוֹחֵד, וְהִרְהֵר תְּשׁוּבָה, וְהֶעֱלָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַרְקָא, וְהָיָה שָׁם וְהוֹלִיד בָּנִים בְּאַרְקָא, וּבְאַרְקָא יֵשׁ אוֹר שֶׁמֵּאִיר מִתּוֹךְ הַשֶּׁמֶשׁ, וְזוֹרְעִים זְרָעִים וְנוֹטְעִים אִילָנוֹת, וְאֵין שָׁם חִטִּים וְלֹא מֵאוֹתָם שִׁבְעָה מִינֵי תְבוּאָה."],[2,"","כָּל אוֹתָם שֶׁשָּׁם הֵם מִתּוֹלְדוֹת קַיִן, וְהֵם עִם שְׁנֵי רָאשִׁים, מֵהֶם גְּבָרִים עֶלְיוֹנִים וּמֵהֶם גְּבָרִים קְטַנִּים, וְאֵין בָּהֶם דַּעַת שְׁלֵמָה כִּשְׁאָר בְּנֵי אָדָם שֶׁכָּאן. לִפְעָמִים הֵם צַדִּיקִים וְחוֹזְרִים לַצַּד הַטּוֹב, וְלִפְעָמִים חוֹזְרִים לַצַּד הָרָע, וּמוֹלִידִים וּמֵתִים כִּשְׁאָר בְּנֵי הָאָדָם."],[3,"","אָדָם הָיָה בַּאֲדָמָה (וארקא), עַד שֶׁהוֹלִיד שֵׁת, וּמִשָּׁם עָלָה לְמַעְלָה אַרְבַּע דְּרָגוֹת, וְעָלָה לַמָּקוֹם הַזֶּה שֶׁנִּקְרָא תֵּבֵל. וְתֵבֵל זוֹ הִיא הָעֶלְיוֹנָה שֶׁל כָּל הַדְּרָגוֹת. כֵּיוָן שֶׁעָלָה, עָלָה לִמְקוֹם בֵּית הַמִּקְדָּשׁ שֶׁנִּקְרָא בְּאוֹתָם שֵׁמוֹת שֶׁדִּיּוּרוֹ הָיָה בָּהֶם, אֶרֶץ אֲדָמָה כָּךְ נִקְרָא."],[4,"","דִּלֵּג אָדָם שְׁלֹשָׁה מְקוֹמוֹת - גֵּיא, נְשִׁיָּה, צִיָּה. גֵּיא הוּא אֲתַר וּמָקוֹם גָּדוֹל כְּמוֹ רֹחַב וְאֹרֶךְ הַגֵּיהִנֹּם. בְּגֵיא וּנְשִׁיָּה וְצִיָּה הִתְפַּזְּרוּ אוֹתָם שֶׁבָּנוּ מִגְדָּל וְהוֹלִידוּ שָׁם עַל שֶׁהִרְגִּיזוּ אֶת הַמֶּלֶךְ הָעֶלְיוֹן, לָכֵן זֶה קָרוֹב לָאֵשׁ הַדּוֹלֶקֶת. וְיִשִׁ בְּנֵי אָדָם נִכְבָּדִים בְּכָל עֹשֶׁר וְעַפְרוֹת זָהָב וַאֲבָנִים יְקָרוֹת. מִי שֶׁנִּכְנַס לְשָׁם וְהָיָה מִתֵּבֵל, בְּחֶמְדַּת אוֹתוֹ הָעֹשֶׁר נוֹתְנִין לוֹ, וְלִפְעָמִים עוֹלֶה לְמָקוֹם שֶׁנִּקְרָא נְשִׁיָּה, מִשּׁוּם שֶׁנִּשְׁכָּח שָׁם. יוֹרֵד לַגֵּיא הַזֶּה וְלֹא יוֹדֵעַ אֶת הַמָּקוֹם שֶׁהָיָה מִשָּׁם."],[5,"","גֵּיא הוּא בָּאֶמְצַע שֶׁל מַעְלָה וּמַטָּה, וְזֶה נִקְרָא גֵּיא בֶן הִנֹּם, וּרְצוּעָה אַחַת יוֹצֵאת מִשָּׁם לְמַעְלָה לַתֵּבֵל הַזֹּאת, וְנִקְרֵאת אַף כָּךְ גֵּיא בֶן הִנֹּם, וְשָׁם פֶּתַח הַגֵּיהִנֹּם. אוֹתָם בְּנֵי אָדָם שֶׁשָּׁם, כֻּלָּם יוֹדְעִים כְּשָׁפִים וְחָכְמוֹת נִכְבָּדוֹת, וְשָׁם זוֹרְעִים וְנוֹטְעִים עֵצִים, וְאֵין שָׁם לֹא חִטִּים וְלֹא אֶחָד מִשִּׁבְעַת הַמִּינִים."],[6,"","בַּנְּשִׁיָּה יֵשׁ בְּנֵי אָדָם כֻּלָּם קְטוּעִים קְטַנִּים, וְאֵין לָהֶם חֳטָמִים, פְּרָט לִשְׁנֵי נְקָבִים שֶׁיּוֹצֵאת בָּהֶם רוּחַ, וְכָל מַה שֶּׁעוֹשִׂים מִיָּד שׁוֹכְחִים, וְעַל כָּךְ נִקְרֵאת נְשִׁיָּה, וְזוֹרְעִים וְנוֹטְעִים עֵצִים, וְאֵין שָׁם חִטִּים וְלֹא מִשִּׁבְעַת הַמִּינִים."],[7,"","צִיָּ\"ה הוּא מָקוֹם כִּשְׁמוֹ, יֵשׁ שָׁם יֹבֶשׁ שֶׁל הַכֹּל, וְשָׁם בְּנֵי אָדָם יָפִים לְמַרְאֶה, וּמִתּוֹךְ שֶׁהוּא צִיָּה, כְּשֶׁיּוֹדְעִים מָקוֹם שֶׁל מְקוֹר מַיִם נוֹבְעִים, נִכְנָסִים לְשָׁם, וְלִפְעָמִים שֶׁעוֹלִים מִתּוֹךְ הַמָּקוֹם שֶׁל הַמַּיִם וְעוֹלִים לַתֵּבֵל הַזּוֹ, וְהֵם בְּנֵי אֱמוּנָה יוֹתֵר מִבְּנֵי אָדָם אֲחֵרִים, וּבֵינֵיהֶם דִּיּוּרִים טוֹבִים וְעֹשֶׁר רַב, וְזוֹרְעִים מְעַט מִתּוֹךְ הַיֹּבֶשׁ שֶׁל שָׁם, וְנוֹטְעִים עֵצִים וְלֹא מַצְלִיחִים, וּתְשׁוּקָתָם לִבְנֵי אָדָם שֶׁל כָּאן,"],[8,"","וּמִכֻּלָּם אֵין אוֹכְלֵי לֶחֶם - כְּמוֹ (רק) אֵלֶּה שֶׁכָּאן בַּתֵּבֵל, כָּאן מֵעַל כָּל אֵלֶּה תֵּבֵל, וְכָתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. כְּמוֹ שֶׁכָּל אֵלּוּ הָאֲרָצוֹת יֵשׁ בַּתֵּבֵל הַ את, וְכָל אֵלֶּה הַשֵּׁמוֹת יֵשׁ לָהֶם אַף כָּךְ, מִשּׁוּם שֶׁהוּא שְׁבִיעִי, יֵשׁ כָּאן כְּמוֹ שֶׁל אוֹתָם מְקוֹמוֹת תְּחוּמִים וּמְקוֹמוֹת כָּאן, וְנִקְרָא כָּל אֶחָד וְאֶחָד כְּמוֹ שֶׁאוֹתוֹ מָקוֹם שֶׁלְּמַטָּה, וְכָל אֵלֶּה בַּדִּיּוּרִים שֶׁל בְּנֵי אָדָם מְשֻׁנִּים אֵלֶּה מֵאֵלֶּה, שֶׁכָּתוּב (שם קד) מָה רַבּוּ מַעֲשֶׂיךְ ה' כֻּלָּם בְּחָכְמָה עָשִׂיתָ מָלְאָה הָאָרֶץ קִנְיָנֶךְ: ע\"כ מההשמטות."],[9,"","רַבִּי חִזְקִיָּה אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהִתְרַצָּה בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וְנָתַן לָהֶם תּוֹרָה הַקְּדוֹשָׁה, וְהִזְהִיר אוֹתָם וְנָתַן לָהֶם עֵצָה לְהִשָּׁמֵר מִמַּעְלָה וּמִמַּטָּה כְּדֵי שֶׁלֹּא יִשְׁלֹט בָּהֶם - רַק הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם יוֹדְעִים לִדְחוֹת מֵהֶם כָּל הַמְקַטְרְגִים וְכָל הָרוּחוֹת, כְּדֵי שֶׁיִּהְיוּ חֵלֶק גּוֹרָלוֹ וִירֻשָּׁתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[10,"","בֹּא רְאֵה, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם יוֹשְׁבִים בְּחֶשְׁבּוֹן, וְאֵין מִי שֶׁלֹּא נִכְנָס בְּחֶשְׁבּוֹן, וְסִפְרֵי חַיִּים וּמֵתִים נִפְתָּחִים בְּאוֹתוֹ יוֹם. וּבִגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, נָתַן לָהֶם עֵצָה לְהִנָּצֵל מִכָּל הַקִּטְרוּגִים שֶׁל מַעְלָה שֶׁהֵם הִתְמַנּוּ, וְכֵן בְּכָל זְמַן שֶׁהַדִּין שׁוֹרֶה עַל הָעוֹלָם. בְּיוֹם זֶה מֻזְמָנִים יִשְׂרָאֵל לְעוֹרֵר עֲלֵיהֶם רַחֲמִים, וּבַמֶּה? בַּשּׁוֹפָר, שֶׁהַקּוֹל הַזֶּה שֶׁיּוֹצֵא עוֹלֶה לְמַעְלָה וּמְעוֹרֵר שׁוֹפָר הָעֶלְיוֹן, אָז מִתְעוֹרְרִים רַחֲמִים מִמְּקוֹמָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָם מִכִּסֵּא דִין וְיוֹשֵׁב בְּכִסֵּא רַחֲמִים וּמְרַחֵם עַל יִשְׂרָאֵל, וְלֹא נִתֶּנֶת רְשׁוּת לַמְקַטְרֵג."],[11,"","וְיִשְׂרָאֵל יוֹשְׁבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְשׁוּבָה וְתוֹקְעִים בַּשּׁוֹפָר (ומעוררים) וּמִתְעוֹרְרִים רַחֲמִים, שֶׁהֲרֵי אוֹתוֹ קוֹל שֶׁיּוֹצֵא הוּא הִתְעוֹרְרוּת הָרַחֲמִים, וְאָז הַמַּלְשִׁין לֹא יָכוֹל לַעֲמֹד לִפְנֵי כִּסֵּא הָרַחֲמִים, שֶׁהֲרֵי לֹא בָא מֵאוֹתוֹ צַד וְלֹא נִמְצָא קָטֵגוֹרְיָא."],[12,"","בְּיוֹם הַכִּפּוּרִים שֶׁהוּא חֲתִימַת הַדִּין, וְיִשְׂרָאֵל עוֹמְדִים בִּקְדֻשַּׁת רִבּוֹנָם, בְּאוֹתוֹ יוֹם, כְּדֵי שֶׁלֹּא יִקְרַב מַלְשִׁין לַמִּקְדָּשׁ, נוֹתְנִים לוֹ שָׂעִיר, שֶׁבָּא מִצַּד רוּחַ הַטֻּמְאָה וְהוּא טָמֵא, וְרוּחַ טֻמְאָה נֶהֱנֶה מִמֶּנּוּ. (והוא) הוּא מִתְעַסֵּק בּוֹ, וְלֹא מִתְקָרֵב לַמִּקְדָּשׁ לְטַמֵּא, וְאָז הַפָּנִים מְאִירוֹת, וְיִשְׂרָאֵל נִצּוֹלִים מִמֶּנּוּ."],[13,"","בִּזְמַן אַחֵר, כְּשֶׁרַבִּים חֲטָאֵי בְּנֵי הָאָדָם, הַמַּלְשִׁין הַזֶּה בִּשְׁעַת הַדִּין מִתְעוֹרֵר עַל חֲטָאֵי הָעוֹלָם, אָז הוּא בָּא, וְנִמְצֵאת הַלְשָׁנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַמִּקְדָּשׁ נִטְמָא, וְכָל הַפָּנִים עֲצוּבוֹת וְנִמְצָא הַדִּין, וְעַל זֶה (בראשית ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי, בָּא לְפָנַי וַדַּאי, לִתְבּעַ חֲטָאֵי הָעוֹלָם מִשּׁוּם שֶׁהֵם גָּרְמוּ: (ע\"כ מההשמטות)."]]],[["צִוָּה ה'. אָמַר רַבִּי יוֹסֵי זַכָּאִין אִינוּן יִשְׂרָאֵל דְאִתְיְיהִיב לְהוֹן אוֹרַיְתָא קַדִּישָׁא וְאִינּוּן מִשְׁתַּדְלֵי בָּהּ יְמָמָא וְלֵילֵי. תָּא חֲזֵי דְהָא מַשְׁמַע דְאִלוּלֵי דְאִשְׁתַּכַּח נֹחַ עִם תֵּיבוּתָא בְּאִתְחַבְּרוּתָא כַּחֲדָא לָא אִשְׁתֵּזִיב (ובגין כך) אַסְתִּים מִן עֵינָא בְּגוֹ תֵּיבוּתָא. קָמוּ וְאָזְלוּ. אָמַר הַהוּא יוּדָאי בְּוַדַּאי כְּתִיב עֲשֵׂה לְךָ תֵּיבַת עֲצֵי גוֹפֶר, לְךָ לְגַרְמָךְ בְּגִין לְאִתְחַבְּרָא בַּהֲדָהּ וּלְאִשְׁתֵּזָבָא בָּהּ מָה כְּתִיב וַיַּעֲשֹׁ נֹחַ כְּכָל אֲשֶׁר צִוָהוּ וְגוֹ'.","\u0003סִתְרֵי תּוֹרָה\u0004 (מזוהר ישן) מָה הֵשִׁיב הַקָּדוֹשׁ בָּרוּךָ הוּא לְנֹחַ כְּשֶׁיָּצָּא מִן הַתֵּיבָה וְרָאָה אֶתּ הָעוֹלָם חָרֵב והִתְּחִיל לִבְכּוֹתּ לְפָּנָיו וְאָמַר רִבּוֹנוֹ שֶׁל עוֹלָם נִקְרֵאתָּ רַחוּם הָיָה לְךָ לְרַחֵם עַל בְּרִיוֹתֶּךָ וְכוּ'. הֶשִׁיבוֹ הַקָּדוֹשׁ בָּרוּךָ הוּא וְאָמַר. רַעֲיאָ שָׁטְיָיא, הַשְׁתָּא אֲמַרְתָּ דָּא, לָמָה לֹא אֲמַרְתָּ בְּשַׁעְתָּא דְאֲמָרִיתּ לָךָ, כִּי אוֹתְּךָ רָאִיתִּי צַּדִּיק לְפָּנַי וְגוֹ'. וְאַחַר כָּךָ, הִנְנִי מֵבִיא אֶתּ הַמַּבּוּל מַיִם. וְאַחַר כָּךָ, עשה לְךָ תֵּיבַתּ עֲצֵּי גוֹפֶּר. כָּל הַאי אִתְּעֲכָּבִיתּ ואֲמָרִיתּ לָךָ בְּגִין דְּתַּבְעֵי רַחֲמִין עַל עַלְמָא. וּמִכְּדֵין שְׁמָעְתָּא דְתִּשְׁתְּזִיב בְּתֵּיבוּתָּא לָא עָאל בְּלִבָּךָ לְמִבְעֵי רַחֲמִין על יִשׁוּבָא דְעַלְמָא ועֲבָדְתּ תֵּיבוּתָּא וְאִשְׁתְּזִיבַתּ וּכְעַן דְּאִתְּאֲבִיד עַלְמָא פַּתָּחְתּ פּוּמָךָ לְמַלְּלָא קֳדָמָי בַּעְיָין וְתַּחֲנוּנִים. כֵּיוָן דְחָזָא נֹחַ כָּךָ, אַקְרִיב קָרֵבָּנִין ועֲלָוָון דִּכְתִּיב (בראשית ח׳:כ׳) וַיִּקַּח מִכָּל הַבְּהֵמָה הַטְהוֹרָה וּמִכָּל הַעוֹף הַטָהוֹר וְגוֹ'.","אָמַר רַבִּי יוֹחָנָן בֹּא וּרְאֵה מָה בֵּין צַּדִּיקִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל אַחַר נֹחַ וּבֵין נֹחַ, נֹחַ לא הֵגִין עַל דוֹרוֹ וְלֹא הִתְּפָּלֵל עֲלֵיהֶם כְּאַבְרָהָם, דְּכֵיוָן דְּאָמַר קוּדְשָׁא בְּרִיךָ הוּא לְאַבְרָהָם (בראשית י״ח:כ״ג) זַעֲקָתּ סְדוֹם וַעֲמוֹרָה כִּי רַבָּה מִיָד וַיִּגַּשׁ אַבִרָהָם וַיֹּאמַר וְגוֹ' וְהִרְבָּה תַּחֲנוּנִים לִפְּנִי הַקָּדוֹשׁ בָּרוּךָ הוּא עַד שְׁשָׁאל שְׁאִם יִמְצָּא עֲשָׂרָה צַּדִּיקִים שֶׁיְכַפֶּר לְכָל הַמָּקוֹם בַּעֲבוּרָם, וְחַשָׁב אַבְרָהָם שֶׁהָיוּ בָּעִיר עִם לוֹט וְאִשְׁתּוֹ וּבְנוֹתָּיו עֲשָׂרָה צַּדִּיקִים וּלְפִּיכָךָ לא הִתְּפָּלֵל.","אַחַר כַּךָ בָּא מֹשֶׁה וְהִתְּפָּלֵל וְהֵגִין עַל דוֹרוֹ כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךָ הוּא (שמות ל״ב:ח׳) סָרוּ מָהֵר מִן הַדֶּרֶךָ. מִיָד עֲמָד מֹשֶׁה בַּתְּפִּלָה וַיְּחַל משֹה וְגוֹ' עַד שֶׁאַחַזָתּוֹ חַלְחַלָה. רָבַּנָן אַמְרֵי, לֹא הִנִּיחַ משהֹ לְקוּדְשָׁא בְּרִיךָ הוּא עַד שֶׁנָתַּן נַפְּשׁוֹ עֲלֵיהֶם מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא דִּכְתִּיב (שם) וְאִם אַיִן מְחֵנִי נָא מִסִּפְּרֶךָ אשר כַּתָּבְתָּ אָמַר רַבִּי יוֹסֵי מֵהָכָא (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵא מֹשֶׁה בְּחִירוֹ עָמָד בַּפֶּרֶץ לְפָּנָיו.","אָמַר רַבִּי יְהושֹֹעַ, מָה רָאָה נֹחַ שֶׁלּא בִּיקֵשׁ רַחֲמִים עַל דוֹרוֹ. אָמַר בְּלִבּוֹ אוּלַי לֹא אַמָלֵט דִּכְתִּיב (בראשית ז׳:א׳) כִּי אוֹתְּךָ רָאִיתִּי צַּדִּיק לְפָּנַי בָּדוֹר הַזֶּה כְּלוֹמַר לְפִּי הַדוֹר וּלְפִּיכָךָ לא בִּיקֵשׁ רַחֲמִים עֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר אֲפִּילוּ (הכי) הֵכִּיר הֲוָה לֵיהּ לְמִבְעֵי רַחֲמִין עַל עַלְמָא בְּגִין דְּנִיחָא לֵיהּ לְקוּדְשָׁא בְּרִיךָ הוּא, מָאן דְיֵימָר טָבָא עַל בְּנוֹי. מְנָא לָן מִגִדְעוֹן בָּר יוֹאַשׁ דְלָא הֲוָה זַכָּאי וְלָא בָּר זַכָּאי וּמִשׁוּם דְּאָמַר טִיבוּתָּא עַל יִשְׂרָאֵל, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא, (שופטים ו׳:י״ד) לֵךָ בְּכֹחַךָ זְה וְהוֹשָׁעְתָּ אֶתּ יִשְׂרָאֵל מִיָּד מִדְיָן. מָהוּ בְּכֹחַךָ זֶה טִיבוּתָּא דְּאַמָרַתּ עַל בָּנַי.","עוֹד פָּתַח הַהוּא יְנוֹקָא וְאָמַר (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנְיךָ טוֹבִים. לְרֵיחַ מָאן, אֶלָּא אִית רֵיחַ וְאִית רֵיחַ. רֵיחַ הַקָּרְבָּן וְרֵיחַ הַקְּטוֹרֶת. רֵיחַ הַקָּרְבָּן מַקְרִיב וּמְיַיחֵד כָּל אִינוּן שִׁבְטַיָּא דְּהֵיכָלָא דְּבֵּית דָוִד וְרֵיחַ הַקְּטוֹרֶת מַקְרִיב וּמְיַיחֵד וְאַנְהִיר אִינוּן בּוֹצִינִין עִלָּאִין נָהִיר (נהרי) אֲפַרְסְמוֹנָא דַכְיָא","וְעַל דָּא תְרֵין מָדְבְּחִין הֲווּ, מִזְבֵּחַ הַקְּטוֹרֶת וּמִזְבֶּחַ הָעוֹלָה מִזְבַּח הַקְּטוֹרֶת אִיהוּ פְּנִימָאָה מִזְבַּח הָעוֹלָה אִיהוּ לְבַר. רֵיחַ מִזְבַּח הָעוֹלָה מַתְקִין לְאַנְהֲרָא בּוֹצִינִין תַּתָּאִין, רֵיחַ מִזְבַּח הַקְּטוֹרֶת מַתְקִין לְאַנְהֲרָא בּוֹצִינִין עִלָּאִין. וְעַל דָּא לְרֵיחַ שְׁמָנֶיךָ טוֹבִים לְרֵיחַ דְּהַהוּא קְטוֹרֶת שְׁמָנְיךָ טוֹבִים.","בֹּא וּרְאֵה שְׁתֵּי מִזְבֶּחוֹת הֵן מִזְבֵּחַ פְּנִימִי לְעֵילָא מִזְבֵּחַ חִיצוֹן לְתַתָּא. מִזְבֵּחַ הַפְּנִימִי הוּא שָׁלֵם וְזֶהוּ דִּכְתִיב הַמִּזְבֵּחָה בְּתוֹסֶפֶת הֵ\"א וְכָךְ הוּא בְכָל מָקוֹם. וּמִזְבֵּחַ הַחִיצוֹן הוּא חָסֵר הֵ\"א כְּמוֹ נַעֲרָה נַעַר חָסֵר ה'","אִשְׁתְּכַח דְמִאִתְעַרוּתָּא דְמִזְבֵּחַ הַפְּנִימִי (ס\"א החיצון) שֶׁל מַטָּה אִתְעָר מִזְבֵּחַ הַפְּנִימִי שֶׁל מַעְלָה וּבְמָה אִתְעָר בְּרֵיחַ (ס\"א דמאתערותא דמזבח החיצון של מטה אתער מזבח החיצון של מעלה ובמה אתער בריח הקרבנות. ובריח הקטורת של מזבח הפנימי של מטה אתער מזבח הפנימי של מעלה, ובמה אתער בריח הקטורת. ועל דא) הַקְּטוֹרֶת. הַקְּטוֹרֶת שֶׁל מַעְלָה וְאִתְעָר רֵיחַ הַקָּרְבָּן שֶׁל מַטָּה וְעַל דָּא (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים אִינוּן בּוֹצִינִין נַהֲרִין וְנָצִיצִין. כְּתִיב הָכָא טוֹבִים וּכְתִיב הֲתָם (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב:"],[],[[0,"","צִוָּה ה'. אָמַר רַבִּי יוֹסֵי, אַשְׁרֵי יִשְׂרָאֵל שֶׁנִּתְּנָה לָהֶם תּוֹרָה קְדוֹשָׁה וְהֵם מִשְׁתַּדְּלִים בָּהּ יָמִים וְלֵילוֹת. בּא רְאֵה, שֶׁהֲרֵי מַשְׁמָע שֶׁלּוּלֵא שֶׁנִּמְצָא נֹחַ עִם הַתֵּבָה בְּהִתְחַבְּרוּת כְּאֶחָד, לֹא הָיָה נִצָּל, (ולכן) נִסְתַּר מִן הָעַיִן בְּתוֹךְ הַתֵּבָה. קָמוּ וְהָלְכוּ. אָמַר אוֹתוֹ יְהוּדִי, כָּתוּב עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר, לְךְ וּלְעַצְמְךְ, כְּדֵי לְהִתְחַבֵּר עִמָּהּ וּלְהִנָּצֵל בָּהּ. מַה כָּתוּב? וַיַּעַשׂ נֹחַ כְּכָל אֲשֶׁר צִוָּהוּ וְגוֹמֵר."],[1,"","מַה הֵשִׁיב הַקָּדוֹשׁ בָּרוּךְ הוּא לְנֹחַ כְּשֶׁיָּצָא מֵהַתֵּבָה וְרָאָה אֶת הָעוֹלָם חָרֵב, וְהִתְחִיל לִבְכּוֹת לְפָנָיו וְאָמַר: רִבּוֹנוֹ שֶׁל עוֹלָם, נִקְרֵאתָ רַחוּם, הָיָה לְךְ לְרַחֵם עַל בְּרִיּוֹתֶיךְ וְכוּ'? הֱשִׁיבוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר: רוֹעֶה שׁוֹטֶה, עַכְשָׁו אַתָּה אוֹמֵר אֶת זֶה? לָמָּה לֹא אָמַרְתָּ בְּשָׁעָה שֶׁאָמַרְתִּי לְךְ כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי וְגוֹ', וְאַחַר הִנְנִי מֵבִיא אֶת הַמַּבּוּל מַיִם, וְאַחַר כָּךְ עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר? כָּל זֶה הִתְעַכַּבְתִּי וְאָמַרְתִּי לְךְ כְּדֵי שֶׁתְּבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם, וּמֵאָז שֶׁשָּׁמַעְתָּ שֶׁתִּנָּצֵל בַּתֵּבָה, לֹא נִכְנַס בְּלִבְּךְ לְבַקֵּשׁ רַחֲמִים עַל יִשּׁוּב הָעוֹלָם, וְעָשִׂיתָ תֵּבָה וְנִצַּלְתָּ, וְכָעֵת, אַחַר שֶׁנֶּאֱבַד הָעוֹלָם, פָּתַחְתָּ פִּיךְ לוֹמַר לְפָנַי בַּקָּשׁוֹת וְתַחֲנוּנִים!? כֵּיוָן שֶׁרָאָה נֹחַ כָּךְ, הִקְרִיב קָרְבָּנוֹת וְעוֹלוֹת, שֶׁכָּתוּב (בראשית ח) וַיִּקַּח מִכֹּל הַבְּהֵמָה הַטְּהֹרָה וּמִכֹּל הָעוֹף הַטָּהוֹר וְגוֹמֵר."],[2,"","אָמַר רַבִּי יוֹחָנָן, בֹּא רְאֵה מַה בֵּין צַדִּיקִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל אַחַר נֹחַ וּבֵין נֹחַ. נֹחַ לֹא הֵגֵן עַל דּוֹרוֹ וְלֹא הִתְפַּלֵּל עֲלֵיהֶם כְּאַבְרָהָם, שֶׁכֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם (שם יח) זַעֲקַת סְדֹם וַעֲמֹרָה כִּי רָבָּה - מִיָּד נִגַּשׁ אַבְרָהָם וַיֹּאמַר וְגוֹמֵר, וְהִרְבָּה תַחֲנוּנִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד שֶׁשָּׁאַל שֶׁאִם יִמְצָא עֲשָׂרָה צַדִּיקִים, שֶׁיְּכַפֵּר לְכָל הַמָּקוֹם בַּעֲבוּרָם, וְחָשַׁב אַבְרָהָם שֶׁהָיוּ בָּעִיר עִם לוֹט וְאִשְׁתּוֹ וּבְנוֹתָיו עֲשָׂרָה צַדִּיקִים, וּלְפִיכָךְ לֹא הִתְפַּלֵּל."],[3,"","אַחַר כָּךְ בָּא מֹשֶׁה וְהִתְפַּלֵּל וְהֵגֵן עַל דּוֹרוֹ. כֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) סָרוּ מַהֵר מִן הַדֶּרֶךְ - מִיָּד עָמַד מֹשֶׁה בִּתְפִלָּה, וַיְחַל מֹשֶׁה וְגוֹמֵר, עַד שֶׁאֲחָזַתּוּ חַלְחָלָה. רַבּוֹתֵינוּ אָמְרוּ, לֹא הִנִּיחַ מֹשֶׁה לַקָּדוֹשׁ-בָּרוּךְ-הוּא עַד שֶׁנָּתַן נַפְשׁוֹ עֲלֵיהֶם מִן הָעוֹלָם הַזֶּה וּמִן הָעוֹלָם הַבָּא, שֶׁכָּתוּב (שם) וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. אָמַר רַבִּי יוֹסֵי, מִכָּאן (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו."],[4,"","אָמַר רַבִּי יְהוֹשֻׁעַ, מָה רָאָה נֹחַ שֶׁלֹּא בִקֵּשׁ רַחֲמִים עַל דּוֹרוֹ? אָמַר בְּלִבּוֹ, אוּלַי לֹא אֲמַלֵּט, שֶׁכָּתוּב (בראשית ז) כִּי אֹתְךְ רָאִיתִי צַדִּיק לְפָנַי בַּדּוֹר הַזֶּה, כְּלוֹמַר לְפִי הַדּוֹר, וּלְפִיכָךְ לֹא בִקֵּשׁ רַחֲמִים עֲלֵיהֶם. אָמַר רַבִּי אֶלְעָזָר, אֲפִלּוּ כָּךְ הָיָה לוֹ לְבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם, מִשּׁוּם שֶׁנּוֹחַ לַקָּדוֹשׁ-בָּרוּךְ- הוּא מִי שֶׁיֹּאמַר טוֹב עַל בָּנָיו, מִנַּיִן לָנוּ? מִגִּדְעוֹן בֶּן יוֹאָשׁ, שֶׁלֹּא הָיָה צַדִּיק וְלֹא בֶּן צַדִּיק, וּמִשּׁוּם שֶׁאָמַר טוֹב עַל יִשְׂרָאֵל, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שופטים ו) לֵךְ בְּכֹחֲךְ זֶה וְהוֹשַׁעְתָּ אֶת יִשְׂרָאֵל מִיַּד מִדְיָן. מַה זֶּה בְּכֹחֲךְ זֶה? הַטּוֹב שֶׁאָמַרְתָּ עַל בָּנַי. ע\"כ מההשמטות."],[5,"","עוֹד פָּתַח אוֹתוֹ תִּינוֹק וְאָמַר, (שיר השירים א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, לְרֵיחַ מִי? אֶלָּא יֵשׁ רֵיחַ וְיֵשׁ רֵיחַ, רֵיחַ הַקָּרְבָּן וְרֵיחַ הַקְּטֹרֶת. רֵיחַ הַקָּרְבָּן מַקְרִיב וּמְיַחֵד כָּל אוֹתָם שְׁבָטִים שֶׁל הֵיכַל בֵּית דָּוִד, וְרֵיחַ הַקְּטֹרֶת מַקְרִיב וּמְיַחֵד וּמֵאִיר אוֹתָם נִרוֹת עֶלְיוֹנִים נַהֲרוֹת אֲפַרְסְמוֹן זַךְ."],[6,"","וְעַל זֶה הָיוּ שְׁנֵי מִזְבְּחוֹת - מִזְבַּח הַקְּטֹרֶת וּמִזְבַּח הָעוֹלָה. מִזְבַּח הַקְּטֹרֶת הוּא פְּנִימִי, מִזְבַּח הָעוֹלָה הוּא חִיצוֹנִי. רֵיחַ מִזְבַּח הָעוֹלָה מַתְקִין לְהָאִיר מְנוֹרוֹת תַּחְתּוֹנוֹת, רֵיחַ מִזְבַּח הַקְּטֹרֶת מַתְקִין לְהָאִיר מְנוֹרוֹת עֶלְיוֹנוֹת. וְעַל זֶה לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, לָרֵיחַ שֶׁל אוֹתָהּ הַקְּטֹרֶת, שְׁמָנֶיךְ טוֹבִים."],[7,"","בֹּא רְאֵה שְׁתֵּי מִזְבֶּחוֹת הֵן מִזְבֵּחַ פְּנִימִי לְמַעְלָה מִזְבֵּחַ חִיצוֹן לְמַטָּה. מִזְבֵּחַ הַפְּנִימִי הוּא שָׁלֵם. וְזֶהוּ שֶׁכָּתוּב הַמִּזְבֵּחָה, בְּתוֹסֶפֶת הֵ\"א, וְכָךְ הוּא בְּכָל מָקוֹם. וּמִזְבֵּחַ הַחִיצוֹן הוּא חָסֵר הֵ\"א, כְּמוֹ נַעֲרָה, נַעַר חָסֵר ה'."],[8,"","נִמְצָא שֶׁמֵּהִתְעוֹרְרוּת הַמִּזְבֵּחַ (החיצון) שֶׁל מַטָּה מִתְעוֹרֵר מִזְבֵּחַ הַפְּנִימִי שֶׁל מַעְלָה, וּבַמֶּה מִתְעוֹרֵר? בְּרֵיחַ (שמהתעוררות מזבח החיצון של מטה מתעורר מזבח החיצון של מעלה, ובמה מתעורר? בריח הקרבנות, ובריח הקטרת של מזבח הפנימי של מטה מתעורר מזבח הפנימי של מעלה, ובמה מתעורר? בריח הקטרת, ועל זה) הַקְּטֹרֶת שֶׁל מַטָּה. וְעַל זִה (שם) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים, אוֹתָם נִרוֹת מְאִירִים נוֹצְצִים. כָּתוּב כָּאן טוֹבִים, וְכָתוּב שָׁם (בראשית א) וַיַּרְא אֶלֹהִים אֶת הָאוֹר כִּי טוֹב: ע\"כ מההשמטות."]]],[["וַיְהִי כְּבוֹא אַבְרָם מִצְרַיְמָה, כְּבוֹאָם מִּבָּעֵי לֵיהּ וְשָׂרָה הֵיכָן הָיְתָה. אֶלָּא אַבְרָהָם אַעֲלָה בְּתֵיבוּתָּא וְסָגַר עֲלָהּ כֵּיוָן דְּמָטָא לְמִצְרָיִם אֲמְרוּ לֵיהּ הַב מִכְסָּא אָמַר אֲנָא יָהִיב מִכְסָּא. אֲמְרוּ לֵיהּ מָאנִין אַתְּ טָעִין אָמַר אֲנָא יָהִיב דְמָאנִין אָמְרוּ לֵיהּ מַטְכְּסָא אַתְּ טָעִין אָמַר אֲנָא יָהִיב דְּמַטְכְּסָא. אָמְרוּ לֵיהּ מַרְגֶלָאן אַתְּ טָעִין, אָמַר לְהוּ אֲנָא יָהִיב מִכְסָּא דְּמַרְגֶלָאן, אָמְרוּ לֵיהּ אִי אֶפְשָׁר, אֶלָּא לְמִפְתַּח תֵּיבוּתָא וְנֶחזֵי מָה בְּגַוָוהּ. כֵּיוָן דְּפַתְחוּ תֵּיבוּתָא אִתְנָהַרָא אַרְעָא דְמִצְרָיִם מִנְּהוֹרָא דִּילָה הֲדָא הוּא דִּכְתִיב (שם) וַיִּרְאוּ הַמִצְרִים אֶת הַאִשָׁה וְגוֹ' אָמַר רַבִּי יְהוּדָה וַיְהִי בְּבוֹאָם מִצְרַיְמָה, הֲוָה לֵיהּ לְמֵימָר אֶלָּא בַּתֵיבָה וְכוּ':","חֲמִשִׁים הֵם כְּנֶגֶד חֲמִשִׁים שַׁעֲרֵי בִּינָה וְהֵם רְאוּיִים לְהַצִּיל כָּל הָעוֹלָם בְּצִּדְקַתָם וַיְיָ הוֹדָה לִדְבַרֶיהָ וּכְשְׁרָאַתָה שֶׁלֹּא מָצְּאָה אָמְרָה (בראשית י״ח:כ״ח) אוּלַי יַחְסְרוּן חֲמִשִׁים הַצַּדִּיקִים חֲמִשָׁה, כְּלוֹמַר אוּלַי יֵשׁ בָּהֶם בְּנֵי אָדָם שְׁעַסְקוּ בִּיְדִיעַת שִׁמְךָ שֶׁהוּא הַשֵׁם בִּמְלוֹאוֹ שֶׁהוּא מָ\"ה יוֹ\"ד הֵ\"א וא\"ו הֵ\"א כְּמִסְפָר אָדָם שֶׁנֶּאֱמַר (דברים י׳:י״ב) וְעַתָּה יִשְׂרָאֵל מָה יְיָ אֱלהֶיךָ שׁוֹאֵל, וּכְשְׁלֹא מָצְּאָה חוֹזֶרֶת לוֹמַר, אוּלַי יִמָצְּאוּן שָׁם אַרְבָּעִים (ככתוב בדפוס)","עוֹד פוֹתָחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם אוּלַי יִמָצְּאוּן שָׁם שְׁלֹשִׁים כְּלוֹמַר אוּלַי יִשׁ בֵּינֵיהֶם צַּדִּיקִים שְׁעַסְקוּ והִשִּׂיגוּ אוֹתָם הַשְׁלשִֹׁים מַעֲלוֹת הַרְמוּזוֹת בִּנְבוּאַת יְחֶזְקֵאל בַּפָסוּק וַיְהִי בִּשְׁלֹשִׁים (שנה) וְגוֹ' וְהֵם כְּלוּלִים בְּלֵ\"ב נְתִיבוֹת חָכְמָה שֶׁהֵם כ\"ב אוֹתִיּוֹת וי' סְפִירוֹת.","וכֵן אוּלַי יְשׁ בֵּינֵיהֶם אֲנָשִׁים צַּדִּיקִים יְחִידִי סְגוּלָה הַמְיַחֲדִים שִׁמְךָ ב' פַּעֲמִים בַּיוֹם בַּפָסוּק שְׁמַע יִשְׂרָאֵל שֶׁבָּה כְּלוּלִים י' סְפִירוֹת בְּמִלַּת אֶחָד האל\"ף עִם החי\"ת הֵם תִשְׁעָה וְהַמִלָה א' הֲרֵי עֲשָׂרָה והד' אָמַר דָוִד הַמֶּלֶךְ עָלָיו הַשָׁלוֹם עֲלָהּ (תהילים קי״ח:כ׳) זֶה הַשַׁעַר לַיְיָ צַּדִּיקִים יָבוֹאוּ בּוֹ וְד\"לת מִלָשׁוֹן שַׁעַר וּשְׁנֵי פַּעֲמִים בַּיוֹם הֲרֵי עֶשְׂרִים.","וּכְשֶאֵינָה מוֹצְּאָה, חוֹזֶרֶת וּפוֹתָחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָצְּאוּן שָׁם עֲשָׂרָה כְּלוֹמַר אוּלַי יִמָצֵּא בֵּינֵיהֶם מִי שֶׁעוֹסֵק בַּעֲשָׂרָה מַאֲמָרוֹת וּבְעֲשֶׂרֶת הַדִבְּרוֹת בְּכָל יוֹם וְכֵן אוּלַי יִמָצְּאוּן בֵּינֵיהֶם עֲשָׂרָה שֶׁמַקְדִימִים לְבֵית הַכְּנֶסֶת דְהָא תְּנַן כָּל (הנמצא) הַנִמְנָה מֵעֲשָׂרָה רִאשׁוֹנִים בְּבֵית הַכְּנֶסֶת נוֹטֵל שָׂכָר כְּנֶגֶד כּוּלָם שֶׁבָּאִים אַחֲרָיו, מָה כְּתִיב, לא אַשְׁחִית בַּעֲבוּר הַעֲשָׂרָה.","כָּל זֶה יְשׁ לְנִשְׁמַת הַצַּדִּיק לְלָמֵד סְנֵגוֹרְיָיא וּזְכוּת עַל הָרְשָׁעִים לְהַשְׁקִיט הַאַף וְהַחֵמָה וכֵיוָן שֶׁלֹּא מָצְּאָה שׁוּם זְכוּת לְלָמֵד מָה כְּתִיב (בראשית י״ח:ל״ג) וַיֵּלֶךְ יְיָ כַּאֲשֶׁר כִּלָה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. מַהוּ לִמְקוֹמוֹ, לְמָקוֹם מָעַלָתוֹ הַיְדוּעָה. ואָז נִסְתָלַק הֲדָיַין וְנִסְתָלַק הַסָינֵגוֹר וְהַקַטֵיגוֹר מֵקַטְרֵג וזֶהוּ (בראשית י״ט:א׳) וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב וְגוֹ'","ולוֹט הוּא שָׂטָן הוּא יִצֶּר הָרָע יוֹשֵׁב בְּשָׁעַר סְדוֹם כִּי שָׁם בֵּיתוֹ דִּכְתִיב (בראשית ד׳:ז׳) לַפֶּתַח חַטָאת רוֹבֵץ. וּמִתְחַבֵּר עִם בְּנִי אָדָם וּמַטְעֵה אוֹתָם עַד שְׁמוֹרִידָם לִבְאֵר שָׁחַת וְהוּא גַּם כֵּן עִמָהֵם נִידוֹן עַל שֶׁהִטְעָה אוֹתָם ויוֹרֵד עַד צָּעֲרָה דְגִהֵינָם וזֶהוּ (בראשית י״ט:כ׳) הִנֵּה נָא הָעִיר הֲזֹאת קְרוֹבָה לָנוּס שָׁמָּה. הַרוֹצֵּחַ, הוּא עֵשָׂו שׁוֹפֵךְ דָּמִים וְהִיא מִצְּעַר ואַף עַל פִּי שֶׁיוֹרֶד ונִידוֹן שָׁם עִם כָּל זְה תַאָוַתוֹ וְחֶשְׁקוֹ לַחֲזוֹר וּלְהַטְעוֹת לַאֲחֵרִים וְזְהוּ (בראשית י״ט:ל׳) וַיָּעַל לוֹט מִצּוֹעַר:","לְאַבְרָהָם. זִמְנָא חֲדָא נָפַק רַבִּי שִׁמְעוֹן וְחָמָא (וחזא) עַלְמָא דְחַשִׁיךְ וְאַפִיל וְאִסְתַתָם נְהוֹרֵיהּ. אָמַר לֵיהּ לְרַבִּי אֶלְעָזָר, תָּא וְנֶחֱזֵי מָה בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבָּד בְּעַלְמָא. אָזְלוּ וְאַשְׁכָּחוּ חַד מַלְאֲכָא דְּדָמֵי לְטוּרָא רַבְרְבָא וְאַפִּיק תְּלָתִין שַׁלְהוֹבִין דְּנוּרָא מִפּוּמֵיהּ.","אָמַר לֵיהּ רַבִּי שִׁמְעוֹן מָה אַתְּ בָּעֵי לְמֵעְבָּד. אָמַר לֵיהּ בָּעֵינָא לְמֵחַרְבֵּיהּ לְעַלְמָא בְּגִין דְלָא שְׁכִיחֵי תְּלָתִין זַכָּאִין בְּדָרָא דְהַכִי גָּזָר קוּדְשָׁא בְּרִיךְ הוּא עַל אַבְרָהָם דִּכְתִיב (בראשית י\"ח) הָיוֹ יִהְיֶה בְּגִימַטְרִיָּא תְּלָתִין. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן בְּמָטוּ מִינָךְ, זִיל קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא וְאִימָא לֵיהּ, בָּר יוֹחָאי שָׁכִיחַ בְּאַרְעָא.","אֲזַל הַהוּא מַלְאֲכָא קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וְאָמַר לֵיהּ, מָארֵיהּ דְעַלְמָא גָּלֵי קַמָּךְ מָה דְּאָמַר לִי בָּר יוֹחָאי. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא זִיל אֲחַרְבֵיה לְעַלְמָא וְלָא תַשְׁגָּח בְּבַר יוֹחָאי.","כַּד אֲתָא חַזְיֵיה ר' שִׁמְעוֹן לְמַלְאֲכָא אָמַר לֵיהּ אִי לָא תֵּיזִיל, גּוֹזַרְנָא עֲלָךְ דְלָא תֵּיעוּל לִשְׁמַיָּיא וְתֶּהֱוֵי בַאֲתַר עֲזָא וְעֲזָאֵל וְכַד תֵּיעוּל קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִימָא לֵיהּ אִי לֵית תְּלָתִין זַכָּאִין בְּעַלְמָא לֶיהֱוָון עַשְׂרִין דְהַכִי כְּתִיב לא אֱעֶשֶׂה בַּעֲבוּר הַעֶשְׂרִים וְאִי לֵית עֶשְׂרִים לִיהווּ עֲשָׂרָה דְהַכִי כְּתִיב לא אַשְׁחִית בַּעֲבוּר הַעֲשָׂרָה וְאִי לֵית עֲשָׂרָה לֵיהווּ תְרִין דְּאִינּוּן אֲנָא וּבְרִי, דְהַכִי כְּתִיב (דברים י״ט:ט״ו) עַל פִּי שְׁנַיִם עֵדִים יָקוּם דָּבָר, וְאֵין דָּבָר אֶלָּא עוֹלָם דִּכְתִיב (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעֲשׁוֹּ. וְאִי לֵית תְרֵין, הַא אִית חַד וַאֲנָא הוּא דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. בָּהּ שַׁעְתָּא קָל מִן שְׁמַיָּיא נָפַק וְאָמַר, זַכָּאָה חוּלָקָךְ רַבִּי שִׁמְעוֹן. דְּקוּדְשָׁא בְּרִיךְ הוּא גָּזָר לְעֵילָא וְאָתְּ מְבַטֵּל לְתַתָּא בְּוַדַאי עֲלָךְ אִתְמַר (תהילים קמ״ה:י״ט) רָצוֹן יְרֵאָיו יָעֲשֶׂה:"],[],[[0,"","וַיְהִי כְּבוֹא אַבְרָם מִצְרָיְמָה (שם יב). כְּבוֹאָם הָיָה צָרִיךְ (לכתב) ! וְשָׂרָה הֵיכָן הָיְתָה? אֶלָּא אַבְרָהָם הִכְנִיסָהּ לְתֵבָה וְסָגַר עָלֶיהָ. כֵּיוָן שֶׁהִגִּיעַ לְמִצְרַיִם, אָמְרוּ לוֹ: שַׁלֵּם מֶכֶס. אָמַר: אֲנִי אֶתֵּן מֶכֶס. אָמְרוּ לוֹ: כֵּלִים אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל כֵּלִים. אָמְרוּ לוֹ: בִּגְדֵי מֵשִּׁי מְשׁוּבָּח אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל בִּגְדֵי מֵשִּׁי מְשׁוּבָּח. אָמְרוּ לוֹ: מַרְגָּלִיּוֹת אַתָּה טוֹעֵן. אָמַר לָהֶם: אֶתֵּן מֶכֶס שֶׁל מַרְגָּלִיּוֹת. אָמְרוּ לוֹ: אִי אֶפְשָׁר אֶלָּא לִפְתֹּחַ אֶת הַתֵּבָה וְנִרְאֶה מַה בְּתוֹכָהּ. כֵּיוָן שֶׁפָּתְחוּ אֶת הַתֵּבָה, הֵאִירָה אֶרֶץ מִצְרַיִם מֵהָאוֹר שֶׁלָּהּ, זֶהוּ שֶׁכָּתוּב (שם) וַיִּרְאוּ הַמִּצְרִים אֶת הָאִשָּׁה וְגוֹמֵר. אָמַר רַבִּי יְהוּדָה, וַיְהִי כְּבוֹאָם מִצְרַיְמָה הָיָה לוֹ לוֹמַר! אֶלָּא בַּתֵּבָה וְכוּ':"],[1,"","חֲמִשִּׁים הֵם כְּנֶגֶד חֲמִשִּׁים שַׁעֲרֵי בִינָה, וְהֵם רְאוּיִים לְהַצִּיל כָּל הָעוֹלָם בְּצִדְקָתָם, וַה' הוֹדָה לִדְבָרֶיהָ. וּכְשֶׁרָאֲתָה שֶׁלֹּא מָצְאָה, אָמְרָה (שם יח) אוּלַי יַחְסְרוּן חֲמִשִּׁים הַצַּדִּיקִים חֲמִשָּׁה, כְּלוֹמַר, אוּלַי יֵשׁ בָּהֶם בְּנֵי אָדָם שֶׁעָסְקוּ בִּידִיעַת שְׁמֶךְ, שֶׁהוּא הַשֵּׁם בְּמִלּוּאוֹ, שֶׁהוּא חֲמִשָּׁה וְאַרְבָּעִים, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, כְּמִסְפַּר אָדָם, שֶׁנֶּאֱמַר (דברים י) וְעַתָּה יִשְׂרָאֵל מָה ה' אֱלֹהֶיךְ שֹׁאֵל. וּכְשֶׁלֹּא מָצְאָה, חוֹזֶרֶת לוֹמַר אוּלַי יִמָּצְאוּן שָׁם אַרְבָּעִים."],[2,"","עוֹד פּוֹתַחַת וְאוֹמֶרֶת, רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָּצְאוּן שָׁם שְׁלֹשִׁים, כְּלוֹמַר, אוּלַי יֵשׁ בֵּינֵיהֶם צַדִּיקִים שֶׁעָסְקוּ וְהִשִּׂיגוּ אוֹתָם הַשְּׁלֹשִׁים מַעֲלוֹת הָרְמוּזוֹת בִּנְבוּאַת יְחֶזְקֵאל בַּפָּסוּק וַיְהִי בִּשְׁלֹשִׁים (שנה), וְהֵם כְּלוּלִים בִּשְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה, שֶׁהֵם עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת וְעֶשֶׂר סְפִירוֹת,"],[3,"","וְכֵן אוּלַי יֵשׁ בֵּינֵיהֶם אֲנָשִׁים צַדִּיקִים יְחִידֵי סְגֻלָּה הַמְיַחֲדִים שְׁתֵּי פְעָמִים בַּיּוֹם בְּפָסוּק שְׁמַע יִשְׂרָאֵל, שֶׁבָּהּ כְּלוּלִים עֶשֶׂר סְפִירוֹת בְּמִלַּת אֶחָד. הָאָלֶ\"ף עִם הַחֵי\"ת הֵם תִּשְׁעָה, וְהַמִּלָּה א' הֲרֵי עֲשָׂרָה, וְהַד' אָמַר דָּוִד הַמֶּלֶךְ עָלָיו הַשָּׁלוֹם עָלֶיהָ (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבוֹאוּ בוֹ, וְדָלֶ\"ת מִלְּשׁוֹן שַׁעַר, וּשְׁתֵּי פְעָמִים בַּיּוֹם הֲרֵי עֶשְׂרִים."],[4,"","וּכְשֶׁאֵינָהּ מוֹצְאָה, חוֹזֶרֶת וּפוֹתַחַת וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה, כְּלוֹמַר, אוּלַי יִמָּצֵא בֵינֵיהֶם מִי שֶׁעוֹסֵק בַּעֲשָׂרָה מַאֲמָרוֹת וּבַעֲשֶׂרֶת הַדִּבְּרוֹת בְּכָל יוֹם. וְכֵן אוּלַי יִמָּצְאוּן בֵּינֵיהֶם עֲשָׂרָה שֶׁמַּקְדִּימִים לְבֵית הַכְּנֶסֶת, שֶׁהֲרֵי שָׁנִינוּ, כָּל (הנמצא) הַנִּמְנֶה מֵעֲשָׂרָה רִאשׁוֹנִים לְבֵית הַכְּנֶסֶת, נוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרָיו. מַה כָּתוּב? לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה."],[5,"","כָּל זֶה יֵשׁ לְנִשְׁמַת הַצַּדִּיק לְלַמֵּד סָנֵגוֹרְיָה וּזְכוּת עַל הָרְשָׁעִים, לְהַשְׁקִיט הָאַף וְהַחֵמָה. וְכֵיוָן שֶׁלֹּא מָצְאָה שׁוּם זְכוּת לְלַמֵּד, מַה כָּתוּב? (בראשית יח) וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקֹמוֹ. מַהוּ לִמְקוֹמוֹ? לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה, וְאָז נִסְתַּלֵּק הַדַּיָּן וְנִסְתַּלֵּק הַסָּנֵגוֹר, וְהַקָּטֵגוֹר מְקַטְרֵג. וְזֶהוּ (שם יט) וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב וְגוֹמֵר."],[6,"","וְלוֹט הוּא שָׂטָן, הוּא יֵצֶר הָרָע, יוֹשֵׁב בְּשַׁעַר סְדם כִּי שָׁם בֵּיתוֹ, שֶׁכָּתוּב לַפֶּתַח חַטָּאת רֹבֵץ, וּמִתְחַבֵּר עִם בְּנֵי אָדָם וּמַטְעֶה אוֹתָם עַד שֶׁמּוֹרִידָם לִבְאֵר שַׁחַת, וְהוּא גַּם כֵּן עִמָּהֶם נִדּוֹן עַל שֶׁהִטְעָה אוֹתָם, וְיוֹרֵד עַד צַעֲרָהּ שֶׁל גֵּיהִנֹּם, וְזֶהוּ (שם) הִנֵּה נָא הָעִיר הַזֹּאת קְרֹבָה לָנוּס שָׁמָּה. הָרוֹצֵחַ הוּא עֵשָׂו שׁוֹפֵךְ דָּמִים, וְהוּא מִצְעָר. וְאַף עַל פִּי שֶׁיּוֹרֵד וְנִדּוֹן שָׁם עַל כָּל זֶה, תַּאֲוָתוֹ וְחִשְׁקוֹ לַחֲזר וּלְהַטְעוֹת לַאֲחֵרִים, וְזֶהוּ (שם) וַיַּעַל לוֹט מִצּוֹעַר: ע\"כ מההשמטות."],[7,"","פַּעַם אַחַת יָצָא רַבִּי שִׁמְעוֹן וְרָאָה (וראה) שֶׁהָעוֹלָם חָשׁוּךְ וְאָפֵל וְנִסְתָּם אוֹרוֹ. אָמַר לוֹ רַבִּי אֶלְעָזָר, בּא רְאֵה מָה רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת בָּעוֹלָם. הָלְכוּ וּמָצְאוּ מַלְאָךְ אֶחָד שֶׁדּוֹמֶה לְהַר גָּבוֹהַּ וּמוֹצִיא שְׁלֹשִׁים שַׁלְהָבוֹת מִפִּיו."],[8,"","אָמַר לוֹ רַבִּי שִׁמְעוֹן, מָה אַתָּה רוֹצֶה לַעֲשׂוֹת? אָמַר לוֹ, רְצוֹנִי לְהַחֲרִיב אֶת הָעוֹלָם, מִשּׁוּם שֶׁלֹּא נִמְצָא שְׁלֹשִׁים צַדִּיקִים בַּדּוֹר, שֶׁכָּךְ גָּזַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַל אַבְרָהָם, שֶׁכָּתוּב (בראשית יח) הָיוֹ 'יִהְיֶה', בְּגִימַטְרִיָּא שְׁלֹשִׁים. אָמַר לוֹ רַבִּי שִׁמְעוֹן, בְּבַקָּשָׁה מִמְּךְ, לֵךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וֶאֱמֹר לוֹ, בַּר יוֹחַאי מָצוּי בָּאָרֶץ."],[9,"","הָלַךְ אוֹתוֹ מַלְאָךְ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר לוֹ: רִבּוֹן הָעוֹלָם, גָּלוּי וְיָדוּעַ לְפָנֶיךְ מַה שֶּׁאָמַר לִי בַּר יוֹחַאי? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֵךְ תַּחֲרִיב אֶת הָעוֹלָם וְאַל תַּשְׁגִּיחַ בְּבַר יוֹחַאי."],[10,"","כְּשֶׁבָּא, רָאָה רַבִּי שִׁמְעוֹן אֶת הַמַּלְאָךְ. אָמַר לוֹ: אִם לֹא תֵלֵךְ, גּוֹזְרַנִי עָלֶיךְ שֶׁלֹּא תִכָּנֵס לַשָּׁמַיִם, וְתִהְיֶה בַּמָּקוֹם שֶׁל עֲזָא וַעֲזָאֵל, וּכְשֶׁתִּכָּנֵס לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֱמֹר לוֹ, אִם אֵין שְׁלֹשִׁים צַדִּיקִים בָּעוֹלָם - שֶׁיִּהְיוּ עֶשְׂרִים, שֶׁכָּךְ כָּתוּב: (בראשית יח) לֹא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים. וְאִם אֵין עֶשְׂרִים - שֶׁיִּהְיוּ עֲשָׂרָה, שֶׁכָּךְ כָּתוּב: לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה, וְאִם אֵין עֲשָׂרָה - שֶׁיִּהְיוּ שְׁנַיִם, שֶׁהֵם אֲנִי וּבְנִי, שֶׁכָּךְ כָּתוּב: (דברים יט) עַל פּיּ שּנַיּם שְׁנֵי עֵדִים יָקוּם דָּבָר, וְאֵין דָּבָר אֶלָּא עוֹלָם, שֶׁכָּתוּב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ, וְאִם אֵין שְׁנַיִם - הֲרֵי יֵשׁ אֶחָד, וַאֲנִי הוּא, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. בְּאוֹתָהּ שָׁעָה יָצָא קוֹל מִשָּׁמַיִם וְאָמַר: אַשְׁרֵי חֶלְקְךְ רַבִּי שִׁמְעוֹן, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר לְמַעְלָה - וְאַתָּה מְבַטֵּל לְמַטָּה. בְּוַדַּאי עָלֶיךְ נֶאֱמַר (שם קמה) רְצוֹן יְרֵאָיו יַעֲשֶׂה: ע\"כ מההשמטות."]]],[["מֵחֲמִשִׁים עַד עֲשָׂרָה דְאִיהוּ שֵׁירוּתָא עַד עֲשָׂרָה דְאִיהוּ עֲשָׂרָה סוֹפָא דְּדַרְגִּין וְכֵיוָן דְּמָטָא עַד עֲשָׂרָה אָמַר, מִכָּאן וּלְתַתָּא לָאו אֲתַר לְקַיְימָא בִּתְשׁוּבָה וְתָב וְאָמַר אַרְבָּעִים בְּגִין דְיִשְׁתַזְבוּן ד' קִרְיָין, וְתַב וְאָמַר שְׁלֹשִׁים בְּגִין דְיִשְׁתַזְבוּן ג' קִרְיָין, וְתַב וְאָמַר עֶשְׂרִים בְּגִין דְיִשְׁתַזְבוּן תְרֵין קִרְיָין, וְתָב וְאָמַר עֲשָׂרָה בְּגִין דְיִשְׁתֵזִיב קַרְתָּא חֲדָא מֵאִינוּן חֲמִשָׁה בְּגִינֵי כָּךְ לָא נָחִית לְתַתָּא מִן עֲשָׂרָה:","וַיַּשְׁכֵּם אַבְרָהָם בַבֹּקֶר וכו' רַבִּי בְּרוֹקָא אָמַר, מָהוּ שָׂם עַל שִׁכְמָהּ אֶלָּא שֶׁהִזְהִירָה עַל עוֹל הָאֱמוּנָה וְלַעֲמוֹד בְּמָה שֶׁהָיְתָה בַּתְחִילָה כְּתִיב הַכָא שָׂם עַל שִׁכְמָהּ וּכְתִיב הֲתָם (שמותט\"ו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. מָה לְהַלָן עַל הַשְׁכִינָה, אוּף הַכָא עַל הַשְׁכִינָה. מָה עֲשְׂתָה כֵּיוָן שְׁרָאֲתָה עַצְמָהּ יוֹצֵאת מִרְשׁוּתוֹ שֶׁל אַבְרָהָם חָזְרָה לְקִלְקוּלָה דִּכְתִיב וְתֵלֵךְ וַתֵּתָע מָהוּ וַתֵּתָע שֶׁתִעְתֵעָה אַחַר עֲבוֹדָה זָרָה וְגִּלּוּלֵי בֵּית אָבִיהָ כְּתִיב הַכָא וַתֵּתָע וּכְתִיב הֲתָם (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֶׂה תִּעְתּוּעִים:","כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכָּל אֲשֶׁר בְּחֲרַבָה מֵתוּ. שָׁאַל רַבִּי חִיָּיא לְר' אַבָּא אֲמַרְתּוּן דְנִשְׁמָתָא לָא עֲיְילָא בְּבַר נָשׁ עַד דְּאִסְתַכְּלָת בְּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּכְדֵין לֵיהֱוֵי לֵיהּ הַהִיא נִשְׁמָתָא. וְאַמְרִיתוּן דְנִשְׁמָתָא הִיא קַדִּישָׁא מַעַלְיָא עַל כֹּלָּא אִם כֵּן מַאי הוּא דְּאָמַר קְרָא כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים וְגוֹ', הוֹאִיל וַהֲוָה לְהוּ נִשְׁמָתָא, הֲוָה לְהוּ לְאִשְׁתֵּזָבָא. לָא הֲוָה בִּידֵיהּ.","אָתוּ שָׁיְילוּהָ לְר' אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן אָמַר לְהוּ כַּךְ הוּא, וְהָא קְרָא מְסַיֵּיעַ לֵיהּ דְהַכִי אָמַר אֲבוֹי (אבא), דְכִי אֲתָא טוֹפָנָא לָא חַזָא (הוה) בָּר נָשׁ דְּיַעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ, אֶלָּא נֹחַ. וּזְכוּתֶיהּ לָא הֲוָה אֶלָּא לְאַגָּנָא עֲלֵיהוֹן וְעַל בָּתֵיהוֹן דְלָא הֲוָה זְכוּתֵיהּ כָּל כַּךְ לְאַגָּנָא עַל כָּל דָרָא","וְאִינּוּן דַהֲווּ זַכָּאִין בְקַדְמִיתָא כְּגוֹן חֲנוֹךְ יֶרֶד דַהֲווּ לְהוּ נִשְׁמְתָא קַדִּישָׁא, וְחַזְיָּיאן לְמֶעְבָּד קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהוֹן בְּחַרְבָּא מֵתוּ. וְהַיְינוּ דְּאָמַר כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו אִינוּן דְנִשְׁמַתָא קַדִּישָׁא הֲוָה בְּהוֹן וְלָא תֵימָא דְעַל אִינוּן דַהֲווּ בְּטוֹפָנָא אָמַר, אֶלָּא אֲתָא קְרָא וְאָמַר מִכָּל אֲשֶׁר בְּחֲרַבָה מֵתוּ:","אוֹסְרִי לַגֶּפֶן עִירֹ\"ה וְלַשׂוֹרֵקָ\"ה בְּנִי אֲתוֹנוֹ כִּבֵּס בָּיַיִן לְבוּשׁוּ וּבְדַם עֲנָבִים סוּתֹה. תְמַנְיָא דַרְגִּין כְּלִילָן בְּהָאי קְרָא. אַרְבַּע מִנְּהוֹן דַּמְיָין אַהֲדָדֵי, תְרֵין מִנְּהוֹן דַּמְיָין אַהֲדָדֵי, וּתְרֵין אָחֳרָנִין דַּמְיָין אַהֲדָדֵי. אַרְבַּע דְּדַמְיָין אַהֲדָדֵי אִינוּן גֶּפֶן שׂוֹרֵקָה, הַיְינוּ גֶּפֶן הַיְינוּ שׂוֹרֵקָה דְּמִנְהוֹן נָפְקִין עֲנָבִים וּמִנְהוֹן מִתְעֲבִיד חַמְרָא דְאִיקְרֵי יַּיִן וְכֻלְּהוּ רָזָא חֲדָא וּמִשָׁרְשָׁא חַד נָפְקִין וְנַגְדִּין. וּתְרֵין דְּדַמְיָין אַהֲדָדֵי עִירֹה אֲתוֹנוֹ, הַיְינוּ עִירֹה הַיְינוּ אֲתוֹנוֹ וְרָזָא חֲדָא נִינְהוּ וּבְדַרְגָּא חֲדָא כְּלִילָן וּמְרָזָא חֲדָא נַגְדִּין.","לְבוּשׁ\"וֹ סוּתֹ\"ה הַיְינוּ מִלָּה חֲדָא וְרָזָא חַדָא (שמות כ\"ג) כִּי הִיא כְּסוּתוֹ לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעוֹרוֹ. זִמְנָא קַרְיֵיהּ כְּסוּת וְזִמְנָא אַחֲרָא קַרְיֵיהּ לְבוּשׁ וְזִמְנָא אַחֲרָא קַרְיֵיהּ שִׂמְלָה וְכֻלְּהוּ מִשָׁרְשָׁא חֲדָא נַגְדִּין וּמִלָּה חֲדָא עָבְדִין וְחִלוּפָא דִּשְׁמָהָן רָזִין עִלָּאִין כְּלִילָן בְּהוּ, וּמָאן דְדָיִיק טַעִים מִידִי. וּמָאן דְלָא דָיִיק, לָא טַעִים וְלָא מִידִי. וְהָנִי תְמַנְיָא דַרְגִּין רָזִין עִלָּאִין רְמִיזִין בְּהוּ, אֲבָל קְרָא בִּפְשָׁטֵיה קָאֵי.","תָּא חֲזֵי, יַעֲקֹב שְׁלֵימָא דְאַבָּהָן הֲוָה, כְּמָא דְאַתְּ אָמֵר (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם וְגוֹ' מַאי אִישׁ תָּם דְּאִשְׁתַּכְלַּל מֵחָכְמָתָא דִלְעֵילָא וּמְחָכְמָתָא דִלְתַתָּא וְהַיְינוּ דִכְתִיב יוֹשֵׁב אֹהָלִים, תְרֵין אֹהָלִים נִינְהוּ. אֹהֶל דְאִיקְרֵי לְפָנִים מִן הַפַּרְגּוֹד וְאֹהֶל דְאִיקְרֵי אֲחוֹרֵי הַפַּרְגּוֹד וְכַלִיל הֲוָה מִתְּרֵין סִטְרִין, מִבָּתֵּי גָּוָאי וּמִבָּתֵּי בָּרָאי","וּמָאן אוֹלִיף לֵיהּ לְיַעֲקֹב כּוּלֵי הַאי. תָּא חֲזֵי דְּהָא אִינוּן שָׁנִי דַהֲוָה טָמִיר וְגָנִיז בַּהֲדַיְיהוּ דְשֵׁם וְעֵבֶר, שֵׁם אוֹלִיף לֵיהּ חָכְמָתָא עִלָּאָה דְּבָתֵּי גָּוָאי. וְעֵבֶר אוֹלִיף לֵיהּ חַרָשָׁתָא (ס\"א חכמתא) תַתָּאָה וְסִימָנִיךְ (יהושע כ״ד:ב׳) בְּעֵבֶר הַנָהָר יַשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם.","מַאי בְּעֵבֶר הַנָהָר אֶלָּא רָזָא הוּא דְכָל יוֹמֵיהוֹן דְּאִינּוּן קַדְמָאֵי לָא הֲווּ אוּלִיפָן אֶלָּא חָכְמָתָא תַתָּאָה דְּאַתְיָיא מִבָּתֵּי בָּרָאי דְאִיקְרֵי אֲחוֹרֵי הַפַּרְגּוֹד וּבְאִינוּן דְאֲחוֹרֵי הַפַּרְגּוֹד הֲווּ מִתְדַּבְּקִין וַהֲווּ מוֹדִיעִין לוֹן מִילִין דַּעֲתִידִין לְמֵיתֵי לְעַלְמָא בִּישׁ אוֹ טָב וּכְדֵין הֲווּ כָּל אִינוּן דָרִין","עַד דְּאָתָא הַהוּא סִטְרָא דִקְדוּשָׁא עִלָּאָה וְאֲמְשִׁיךְ לֵיהּ לְאַבְרָהָם וְאוֹדָע לֵיהּ מִלִּין דְשָׁרְשָׁא דְאִתְמָשֶׁכָאן לְעַלְמָא דִלְהוֹן (מנהון) מִבָּתֵּי גָּוָאי וּמִתַּמָן שֹׁאֲבִין כָּל אִינוּן דְאִקְּרוּן בָּתֵּי בָּרָאי וּמִתַּמָן מִתֶהוָון קְצָת מִילִין לָא כֹּלָּא, וְסִימָנִיךְ מִתַּמְצִית גּוּפָה שֶׁל אֶרֶץ יִשְׂרָאֵל הָעוֹלָם שׁוֹתֵה."],[],[[0,"","שֶׁהוּא רֵאשִׁית עַד עֲשָׂרָה, שֶׁהוּא עֲשָׂרָה סוֹף הַדְּרָגוֹת. וְכֵיוָן שֶׁמַּגִּיעַ עַד עֲשָׂרָה אָמַר: מִכָּאן וּלְמַטָּה אֵין מָקוֹם לַעֲמֹד בִּתְשׁוּבָה. וְשָׁב וְאָמַר אַרְבָּעִים כְּדֵי שֶׁיִּנָּצְלוּ אַרְבַּע קְרָיוֹת, וְשָׁב וְאָמַר שְׁלֹשִׁים כְּדֵי שֶׁיִּנָּצְלוּ שָׁלֹשׁ קְרָיוֹת, וְשָׁב וְאָמַר עֶשְׂרִים כְּדֵי שֶׁיִּנָּצְלוּ שְׁתֵּי קְרָיוֹת, וְשָׁב וְאָמַר עֲשָׂרָה כְּדֵי שֶׁתִּנָּצֵל קִרְיָה אַחַת מֵאוֹתָן הֶחָמֵשׁ, מִשּׁוּם כָּךְ לֹא יָרַד לְמַטָּה מִן עֲשָׂרָה:"],[1,"","וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וְגוֹמֵר (בראשית כא). רַבִּי בְּרוֹקָא אָמַר, מַה זֶּה שָׂם עַל שִׁכְמָהּ? אֶלָּא שֶׁהִזְהִירָהּ עַל עֹל הָאֱמוּנָה וְלַעֲמֹד בְּמַה שֶּׁהָיְתָה בַּתְּחִלָּה. כָּתוּב כָּאן שָׂם עַל שִׁכְמָהּ, וְכָתוּב שָׁם (שמות טו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. מַה לְּהַלָּן עַל הַשְּׁכִינָה, אַף כָּאן עַל הַשְּׁכִינָה. מֶה עָשְׂתָה? כֵּיוָן שֶׁרָאֲתָה עַצְמָהּ יוֹצֵאת מֵרְשׁוּתוֹ שֶׁל אַבְרָהָם, חָזְרָה לְקִלְקוּלָהּ, שֶׁכָּתוּב (בראשית כא) וַתֵּלֶךְ וַתֵּתַע. מַה זֶּה וַתֵּתַע? שֶׁתִּעְתְּעָה אַחַר עֲבוֹדָה זָרָה וְגִלּוּלֵי בֵּית אָבִיהָ. כָּתוּב כָּאן וַתֵּתַע, וְכָתוּב שָׁם (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים:"],[2,"","כָּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּם בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ (בראשית ז). שָׁאַל רַבִּי חִיָּיא אֶת רַבִּי אַבָּא, אֲמַרְתֶּם שֶׁנְּשָׁמָה לֹא נִכְנֶסֶת לְבֶן אָדָם עַד שֶׁמִּסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז תִּהְיֶה לוֹ אוֹתָהּ נְשָׁמָה, וַאֲמַרְתֶּם שֶׁהַנְּשָׁמָה הִיא קְדוֹשָׁה מְעֻלָּה עַל הַכֹּל. אִם כֵּן, מַה זֶּה שֶׁאָמַר הַכָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים וְגוֹ'? הוֹאִיל וְהָיְתָה לָהֶם נְשָׁמָה, הָיָה לָהֶם לְהִנָּצֵל! לֹא הָיָה בְיָדוֹ."],[3,"","בָּאוּ וְשָׁאֲלוּ אֶת רַבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן. אָמַר לָהֶם, כָּךְ הוּא, וּפָסוּק זֶה מְסַיֵּעַ לוֹ, שֶׁכָּךְ אָמַר אָבִיו (אבי), שֶׁכַּאֲשֶׁר בָּא הַמַּבּוּל, לֹא רָאָה (היה) אָדָם שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁבִילוֹ אֶלָּא נֹחַ, וּזְכוּתוֹ לֹא הָיְתָה אֶלָּא לְהָגֵן עֲלֵיהֶם וְעַל בָּתֵּיהֶם, שֶׁלֹּא הָיְתָה זְכוּתוֹ כָּל כָּךְ לְהָגֵן עַל כָּל הַדּוֹר,"],[4,"","וְאוֹתָם שֶׁהָיוּ צַדִּיקִים בַּתְּחִלָּה, כְּמוֹ חֲנוֹךְ וְיֶרֶד, שֶׁהָיְתָה לָהֶם נְשָׁמָה קְדוֹשָׁה וּרְאוּיִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲשֶׂה בִּשְׁבִילָם - בֶּחָרָבָה מֵתוּ. וְהַיְנוּ שֶׁאָמַר כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו, אוֹתָם שֶׁנְּשָׁמָה קְדוֹשָׁה הָיְתָה בָהֶם. וְאַל תֹּאמַר שֶׁעַל אֵלּוּ שֶׁהָיוּ בַּמַּבּוּל הוּא אָמַר, אֶלָּא בָּא הַכָּתוּב וְאָמַר מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ:"],[5,"","אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְּנִי אֲתֹנוֹ כִּבֵּס בַּיַּיִן לְבֻשׁוֹ וּבְדַם עֲנָבִים סוּתֹה (בראשית מט). שְׁמוֹנֶה דְרָגוֹת כְּלוּלוֹת בְּפָסוּק זֶה. אַרְבַּע מֵהֶן דּוֹמוֹת זוֹ לָזוֹ, שְׁתַּיִם מֵהֶן דּוֹמוֹת זוֹ לָזוֹ, וּשְׁתַּיִם אֲחֵרוֹת דּוֹמוֹת זוֹ לָזוֹ. אַרְבַּע שֶׁדּוֹמוֹת זוֹ לָזוֹ הֵן גֶּפֶן שּרֵקָה, הַיְנוּ גֶפֶן הַיְנוּ שּׁרֵקָה, שֶׁמֵּהֶם יוֹצְאִים עֲנָבִים וּמֵהֶם נַעֲשֶׂה יַיִן שֶׁנִּקְרָא יַיִן, וְכֻלָּן סוֹד אֶחָד וּמִשֹּׁרֶשׁ אֶחָד יוֹצְאוֹת וְשׁוֹפְעוֹת. וּשְׁתַּיִם שֶׁדּוֹמוֹת זוֹ לָזוֹ - עִירֹה אֲתֹנוֹ, הַיְנוּ עִירֹה הַיְנוּ אֲתֹנוֹ, וְסוֹד אֶחָד הֵם, וּבְדַרְגָּה אַחַת כְּלוּלוֹת וּמִסּוֹד אֶחָד שׁוֹפְעוֹת."],[6,"","לְבֻשׁוֹ סוּתֹה זֶה דָּבָר אֶחָד וְסוֹד אֶחָד, (שמות כב) כִּי הִיא כְסוּתֹה לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעֹרוֹ. פַּעַם קוֹרֵא לוֹ כְּסוּת, וּפַעַם אַחֶרֶת קוֹרְאֵהוּ לְבוּשׁ, וּפַעַם אַחֶרֶת קוֹרְאֵהוּ שִׂמְלָה, וְכֻלָּם מִשֹּׁרֶשׁ אֶחָד שׁוֹפְעִים וְדָבָר אֶחָד עוֹשִׂים, וְחִלּוּף הַשֵּׁמוֹת כְּלוּלִים בָּהֶם סוֹדוֹת עֶלְיוֹנִים, וּמִי שֶׁדִּיֵּק טָעַם מַשֶּׁהוּ, וּמִי שֶׁלֹּא דִיֵּק - לֹא טָעַם וְלֹא מַשֶּׁהוּ. וּשְׁמוֹנֶה הַדְּרָגוֹת הַלָּלוּ רְמוּזִים בָּהֶן סוֹדוֹת עֶלְיוֹנִים, אֲבָל הַפָּסוּק עוֹמֵד כִּפְשׁוּטוֹ."],[7,"","בֹּא רְאֵה, יַעֲקֹב הַשָּׁלֵם שֶׁבָּאָבוֹת הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כה) וְיַעֲקֹב אִישׁ תָּם וְגוֹ'. מַה זֶּה אִישׁ תָּם? שֶׁנִּתְקַן מִן הַחָכְמָה שֶׁלְּמַעְלָה וּמֵהַחָכְמָה שֶׁלְּמַטָּה, וְהַיְנוּ שֶׁכָּתוּב יֹשֵׁב אֹהָלִים. שְׁנֵי אֹהָלִים הֵם - אֹהֶל שֶׁנִּקְרָא לִפְנִים מִן הַפַּרְגּוֹד, וְאֹהֶל שֶׁנִּקְרָא אֲחוֹרֵי הַפַּרְגּוֹד, וְכָלוּל הָיָה מִשְּׁנֵי צְדָדִים - מִבָּתִּים פְּנִימִיִּים וּמִבָּתִּים חִיצוֹנִיִּים,"],[8,"","וּמִי לִמֵּד אֶת יַעֲקֹב כָּל זֶה? בֹּא רְאֵה, שֶׁהֲרֵי אוֹתָן שָׁנִים שֶׁהָיָה טָמוּן וְגָנוּז עִם שֵׁם וָעֵבֶר, שֵׁם לִמֵּד אוֹתוֹ חָכְמָה עֶלְיוֹנָה שֶׁל בָּתִּים פְּנִימִיִּים. וְעֵבֶר לִמֵּד אוֹתוֹ כִּשְׁפוּת (חכמה) תַּחְתּוֹנָה, וְסִימָן לַדָּבָר - (יהושע כד) בְּעֵבֶר הַנָּהָר יָשְׁבוּ אֲבוֹתֵיכֶם מֵעוֹלָם."],[9,"","מַה זֶּה בְּעֵבֶר הַנָּהָר? אֶלָּא סוֹד הוּא, שֶׁכָּל יְמֵיהֶם שֶׁל אוֹתָם קַדְמוֹנִים לֹא הָיוּ לוֹמְדִים אֶלָּא חָכְמָה תַּחְתּוֹנָה שֶׁבָּאָה מִבָּתִּים חִיצוֹנִיִּים שֶׁנִּקְרָאִים אֲחוֹרֵי הַפַּרְגּוֹד, וּבְאוֹתָם שֶׁאֲחוֹרֵי הַפַּרְגּוֹד הָיוּ דְבֵקִים, וְהָיוּ מוֹדִיעִים לָהֶם דְּבָרִים שֶׁעֲתִידִים לָבא לָעוֹלָם, טוֹב אוֹ רַע, וְאָז הָיוּ כָּל אוֹתָם דּוֹרוֹת,"],[10,"","עַד שֶׁבָּא אוֹתוֹ צַד הַקְּדֻשָּׁה וְהִמְשִׁיךְ לוֹ לְאַבְרָהָם וְהוֹדִיעוֹ דְבָרִים שֶׁל שֹׁרֶשׁ שֶׁנִּמְשָׁכִים לָעוֹלָם שֶׁלָּהֶם מִבָּתִּים פְּנִימִיִּים, וּמִשָּׁם שׁוֹאֲבִים כָּל אֵלּוּ שֶׁנִּקְרָאִים בָּתִּים חִיצוֹנִיִּים, וּמִשָּׁם מִתְהַוִּים קְצָת דְּבָרִים, לֹא הַכֹּל, וְסִימָן לַדָּבָר - מִתַּמְצִית גּוּפָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הָעוֹלָם שׁוֹתֶה."]]],[["וּמֵהָאי שַׁעְתָּא דְּקָאִים אַבְרָהָם אָבִינוּ עָלָיו הַשָׁלוֹם עַל הַהוּא סִטְרָא קַדִּישָׁא דְּמִינֵּיהּ כוּלָא נָפִיק וְנָגִיד וּבֵיהּ כֹּלָא תַלְיָין נָפַק לֵיהּ לְשָׁעֲתֵיה מֵהַאי סִטְרָא דְּאִינּוּן בְּנֵי עֵבֶר הַנָהַר וְאָתָא לֵיהּ לְאִשְׁתַּעְשְׁעָא בְּאַרְעָא קַדִּישָׁא. הָדָא הוּא דִּכְתִיב, (יהושע כ״ד:ג׳) וַאֵקָח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָהָר וָאוֹלֶךְ אוֹתוֹ בְּכָל אֶרֶץ כְּנָעַן אֶרֶץ כְּנָעַן מַמָּשׁ אַרְעָא דִּשְׁאָר חֲיָילִין עִלָּאִין תְבִירִין תְּחוֹתָהּ תַמָּן וְלֵית לְהוֹן קִיוּמָא בַּהֲדָהּ:","וְשָׁחֲטוּ הַפֶּסַח אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא מִבְּעֲשוֹר לַחֹדֶשׁ סְבוּ דַחֲלָא דְמִצְרָיִם וְתִפְסוּן לֵיהּ וְיְהֵא אָסוּר וְתָפִיס תְלָתָא יוֹמִין וּבְיוֹמָא רְבִיעִאָה אַפִּיקוּ לֵיהּ לְדִינָא וְאִתְכְּנָשׁוּ עָלֵיהּ לְקַטְלֵיהּ, וְיֵחְמוּן לֵיהּ מִצְרָאֵי הֵיךְ אָתּוּן עַבְדִין בֵּיה דִּינָא. וְדָא קַשְׁיָא לְהוּ מִכָּל מַכְתָּשִׁין דְּעָבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אִינוּן דִינִין דְּעָבְדוּ בְּדָחַלֵיהוֹן.","לְבָתַר דָיְינִין לֵיהּ בְּנוּרָא בְּגִין דִּכְתִיב (דברים ז׳:כ״ה) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֶשׁ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא (שמות י״ב:ט׳) אַל תֹאכְלוּ מִמֶּנּוּ נָא, דְלָא יֵימְרוּן בְתִיאוּבְתָּא דְּדָחַלָא אַכְלִין לֵיהּ, אֶלָּא אַתְקִינוּ לֵיהּ צְלִּי וְלֹא מֵבוּשָׁל דְאִילוּ מֵבוּשָׁל יְהֵא טָמִיר וְלָא יְחְמוּן לֵיהּ, אֶלָּא תַקִּינוּ לֵיהּ מוֹקְדָא בְּנוּרָא דְרֵיחֵיהּ נוֹדֶף.","וְתוּ רֵישֵׁיהּ עָלֵיהּ, דְלָא יֵימְרוּן דְּחַיָּה אוֹ דְמִלָה אַחֲרָא הִיא. וְתוּ עֶצֶם לֹא תִשְׁבֶּרוּ בּוֹ, אֶלָּא דְיֵחְמוּן גָּרְמוֹי רָמָאן בְּשׁוּקָא וְלָא יַכְלִין לְשֵׁזָבָא לֵיהּ וְעַל דָּא כְּתִיב (במדבר ל״ג:ד׳) וּבֵאלֹהֵיהֶם עָשָׂה יְיָ שְׁפָטִים.","הַהוּא קַדְמָאָה דְאִשְׁתַּכַּח בְּבֵי כְּנִישְׁתָּא וְאָרִיךְ בְּבֵי כְּנִישְׁתָּא זַכָּאָה חוּלָקֵיהּ דְּאִיהוּ קַיָימָא בְּדַרְגָּא דְצַדִיק בַּהֲדֵי שְׁכִינְתָּא, וְדָא אִיהוּ רָזָא (משלי ח׳:י״ז) וּמְשָׁחַרָי יִמְצָאוּנְנִי, דָּא סָלִיק בִּסְלִיקוּ עִלָּאָה. וְאִי תֵימָא הַא תָנֵינָן בְּשַׁעְתָּא דְאָתֵי קוּדְשָׁא בְּרִיךְ הוּא לְבֵי כְּנִישְׁתָּא וְלָא אַשְׁכָּח תַמָּן עֲשָׂרָה מִיָד כּוֹעֵס.","לְמַלְכָּא דְשָׁלַח לְכָל מַלְכֵי (ס\"א אנשי) מְדִינְתָּא דְּיִשְׁתַּכְּחוּן עִמֵּיהּ בְּיוֹם פְּלַן בְּדוּךְ פְּלַן. עַד דַהֲווּ מְזָמְנֵי גַרְמַיְיהוּ אִינוּן בְּנֵי מַתָּא אַקְדִים חַד וְאָתָא לְהַהוּא אֲתַר בֵּין כַּךְ וּבֵין כַּךְ אֲתָא מַלְכָּא אַשְׁכָּח לְהַהוּא בָּר נָשׁ דְאַקְדִּים תַמָּן. אָמַר לֵיהּ בְּנֵי מַתָּא פְּלוֹנִית אָן אִינוּן. אָמַר לֵיהּ, מָארֵי, אֲנָא אֲקְדִימְנָא מִנַּיְיהוּ וְהָא אִינוּן אַתְיָין אֲבַתְרָאי לְפִקוּדָא דְמַלְכָּא. כְּדֵין טָב בְּעֵינֵי מַלְכָּא וְיָתִיב תַמָּן בַּהֲדֵיהּ וּמִשְׁתָּעֵי עִמֵּיהּ וְאִתְעֲבִיד רְחִימָא דְמַלְכָּא. בֵּין כַּךְ אָתוּ כָּל עַמָּא וְאִתְפַּיָּיס עִמָיְיהוּ. אֲבָל אִי בְנֵי מַתָּא לָא אַתְיָין וְחַד לָא אַקְדִים וְאִשְׁתָּעֵי קַמֵי מַלְכָּא לְאַחֲזָאָה (לאתחזאה) בְּגִינֵהוֹן. מִיָד כַּעָס מַלְכָּא. מָה כְּתִיב (ישעיהו נ׳:ב׳) מַדּוּעַ בָּאתִי וְאֵין אִישׁ.","וּמָאן דְּאִשְׁתָּעֵי בְּבֵי כְּנִישְׁתָּא וַוי לֵיהּ דְּאַחְזֵי פִּרוּדָא. וַוי לֵיהּ דְּגָרַע מְהֵימְנוּתָא, וַוי לֵיהּ דְּלֵית לֵיהּ חוּלָקָא בֶּאֱלָהָא דְּיִשְׂרָאֵל דְּאַחְזֵי דְּלֵית לֵיהּ אֱלָהָא. וְלָא אִשְׁתְּכַח תַמָּן, וְאַנְהִיג קְלָנָא בְּתַּקִּיפָא עִלָּאָה.","כָּל גּווָֹנִין טָבִין בְּחֶלְמָא בָּר מִתְכֵלָא בְּגִין דְאִיהוּ כּוּרְסַיָּיא לְמֵידָן דִינִין דְּנִשְׁמָתִין וְהָא דַרְגָּא חֲדָא אִיהוּ. אֶלָּא בְּשַׁעְתָּא דְּקַיְימֵי בְּדִינֵי נַפְשָׁא כְּדֵין אִיהוּ גּווָֹן תְכֵלָא וְהָא אוּקִימְנָא. וּבְשַׁעֲתָא דְּחָמֵי בָּר נָשׁ לְהַאי גּווָֹן אִדְכַּר בָּר נָשׁ לְמֶעְבָּד פִקוּדָא דְּמָארֵיהּ כְּגווָֹנָא דְנָחָשׁ דַהֲווּ חֲמָאן לֵיהּ וַהֲווּ דַּחֲלֵי מִקָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וּמְנַטְרִין גַרְמַיְיהוּ, וּבְהַהוּא דְּחִילוּ דְּקוּדְשָׁא בְּרִיךְ הוּא סַלְקָא עָלַיְיהוּ מַיָא וְאִתְכַסְּיָין. מָאן גָרַם לוֹן, הַהוּא נָחָשׁ, הַהוּא רְצוּעָה דְּמִסְתָּכְּלָאן בֵּיה אוּף הֲכִי תְּכֵלֶת וּרְאִיתֶם אוֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת יְיָ מֵהַהוּא דְּחִילוּ דִילֵיהּ: (עד כאן מההשמטות)","תָּא חֲזֵי הַאי הַר לִישָׁנָא דְּתַקִיפוּ הוּא. אִינוּן הָרִים לְעֵילָא וְאִלֵּין צַדִּיקִים דַאֲחִידָן בְּכְּנֶסֶת יִשְׂרָאֵל וְאִקְּרוּן הַר צִיּוֹן הָרִים דְסָחְרָנֵי יְרוּשָׁלַיִם בְּגִין דְּאִינּוּן מְצוּיָינִין וְאָמְרִין הָאי לְהָאי בְּסִטְרָא דְּיִחוּדָא לִשְׁפּוֹט אֶת הַר עֵשָׂו דְּקַטְרִיגּוּ מְקַטְרְגָא מִסִּטְרָא דִשְׂמָאלָא","בְּהַהוּא זִמְנָא (עובדיה א׳:כ״א) וְהָיְתָה לַיְיָ הַמְלוּכָה. בְּקַדְמִיתָא אִקְרֵי מַמְלָכָה בְּגִין דְיַנְקָא לִתְרֵין סִטְרִין לִימִינָא וְלִשְׂמָאלָא. וְהַשְׁתָּא מְלוּכָה אִקְרֵי בְּגִין דְיַנְקָא לִימִינָא. הֲדָא הוּא דִּכְתִיב (הושע ב׳:כ״א) וְאֱרָשְׂתִּיךְ לִי לְעוֹלָם. וּבְגִין דְגַלוּתָא לָאו לְעוֹלָם הוּא דְהָא יַתְבָא בְּגָלוּתָא.","תָּא חֲזֵי דְסָמִיךְ לֵיהּ (זכריה י״ד:ט׳) וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד בְּגִין דְּעַד הַשְׁתָּא כַּד יִשְׂרָאֵל בְּגָלוּתָא שְׁכִינְתָּא עִמְּהוֹן וּמַלְכָּא בְּלֹא מַטְרוֹנִיתָא לָאו מַלְכָּא אִיהוּ. אֲבָל הַהוּא זִמְנָא וְהָיָה יְיָ לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ אֶחָד וּשְׁמוֹ אֶחָד, כַּד אִתְדַבְּקַת שְׁכִינְתָּא בְּצַדִיק כְּדֵין הוּא יִחוּדָא"],[],[[0,"","וּמִשָּׁעָה זוֹ שֶׁעָמַד אַבְרָהָם אָבִינוּ, עָלָיו הַשָּׁלוֹם, עַל אוֹתוֹ צַד הַקְּדֻשָּׁה, שֶׁמִּמֶּנּוּ הַכֹּל יוֹצֵא וְשׁוֹפֵעַ וּבוֹ הַכֹּל תָּלוּי, יָצָא לוֹ לִשְׁעָתוֹ מִצַּד זֶה שֶׁהֵם בְּנֵי עֵבֶר הַנָּהָר, וּבָא לוֹ לְהִשְׁתַּעֲשֵׁעַ בָּאָרֶץ הַקְּדוֹשָׁה. זֶהוּ שֶׁכָּתוּב (יהושע כד) וָאֶקַּח אֶת אֲבִיכֶם אֶת אַבְרָהָם מֵעֵבֶר הַנָּהָר וָאוֹלֵךְ אוֹתוֹ בְּכָל אֶרֶץ כְּנָעַן, אֶרֶץ כְּנַעַן מַמָּשׁ, אֶרֶץ שֶׁשְּׁאָר הַחֲיָלוֹת הָעֶלְיוֹנִים נִשְׁבָּרִים תַּחְתֶּיהָ שָׁם, וְאֵין לָהֶם קִיּוּם עִמָּהּ: ע\"כ מההשמטות"],[1,"","וְשַׁחֲטוּ הַפָּסַח. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מִבֶּעָשׂוֹר לַחֹדֶשׁ קְחוּ יִרְאָתָם שֶׁל מִצְרַיִם וְתִפְסוּ אוֹתוֹ, וְיִהְיֶה אָסוּר וְתָפוּס שְׁלֹשָׁה יָמִים, וּבַיּוֹם הָרְבִיעִי הוֹצִיאוּ אוֹתוֹ לְדִין וְתִתְכַּנְּסוּ עָלָיו לְהָרְגוֹ, וְיִרְאוּ אוֹתוֹ הַמִּצְרִים אֵיךְ אַתֶּם עוֹשִׂים בּוֹ דִּין, וְזֶה קָשֶׁה לָהֶם מִכָּל הַמַּכּוֹת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵלּוּ הַדִּינִים שֶׁעָשׂוּ בֵאלֹהֵיהֶם."],[2,"","וְאַחַר כָּךְ דָּנִים אוֹתוֹ בָּאֵשׁ, מִשּׁוּם שֶׁכָּתוּב (דברים ז) פְּסִילֵי אֱלֹהֵיהֶם תִּשְׂרְפוּן בָּאֵשׁ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, (שמות יב) אַל תֹּאכְלוּ מִמֶּנּוּ נָא, שֶׁלֹּא יֹאמְרוּ בְּתֵאָבוֹן שֶׁל פַּחַד אָכְלוּ אוֹתוֹ, אֶלָּא תְּתַקְּנוּ אוֹתוֹ צָלִי וְלֹא מְבֻשָּׁל. שֶׁאִם הָיָה מְבֻשָּׁל, יְהֵא מֻסְתָּר וְלֹא יִרְאוּ אוֹתוֹ. אֶלָּא תַּקְּנוּ אוֹתוֹ צָלוּי בָּאֵשׁ, שֶׁרֵיחוֹ נוֹדֵף."],[3,"","וְעוֹד, רֹאשׁוֹ עָלָיו, שֶׁלֹּא יֹאמְרוּ שֶׁחַיָּה אוֹ דָבָר אַחֵר הִיא. וְעוֹד, עֶצֶם לֹא תִשְׁבְּרוּ בוֹ, אֶלָּא שֶׁיִּרְאוּ עַצְמוֹתָיו מֻשְׁלָכִים בַּשּׁוּק וְלֹא יִהְיוּ יְכוֹלִים לְהַצִּיל אוֹתוֹ, וְעַל זֶה כָּתוּב (במדבר לג) וּבֵאלֹהֵיהֶם עָשָׂה ה' שְׁפָטִים."],[4,"","אוֹתוֹ רִאשׁוֹן שֶׁנִּמְצָא בְּבֵית הַכְּנֶסֶת וּמַאֲרִיךְ בְּבֵית הַכְּנֶסֶת, אַשְׁרֵי חֶלְקוֹ, שֶׁהוּא עוֹמֵד בְּמַדְרֵגָה שֶׁל צַדִּיק עִם הַשְּׁכִינָה, וְזֶהוּ סוֹד (משלי ח) וּמְשַׁחֲרַי יִמְצָאֻנְנִי. זֶה עוֹלֶה בְמַדְרֵגָה רִאשׁוֹנָה. וְאִם תֹּאמַר, הֲרֵי שָׁנִינוּ, בְּשָׁעָה שֶׁבָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבֵית הַכְּנֶסֶת וְלֹא מוֹצֵא שָׁם עֲשָׂרָה - מִיָּד כּוֹעֵס."],[5,"","מָשָׁל לְמֶלֶךְ שֶׁשָּׁלַח לְכָל מַלְכֵי (אנשי) הַמְּדִינָה שֶׁיִּמָּצְאוּ עִמּוֹ בְּיוֹם פְּלוֹנִי בְּמָקוֹם פְּלוֹנִי. עַד שֶׁהָיוּ מְכִינִים עַצְמָם אֵלּוּ בְּנֵי הָעִיר, הִקְדִּים אֶחָד וּבָא לְאוֹתוֹ מָקוֹם. בֵּין כָּךְ וּבֵין כָּךְ בָּא הַמֶּלֶךְ וּמָצָא לְאוֹתוֹ אָדָם שֶׁהִקְדִּים שָׁם. אָמַר לוֹ, בְּנֵי עִיר פְּלוֹנִית הֵיכָן הֵם? אָמַר לוֹ, אֲדוֹנִי, אֲנִי הִקְדַּמְתִּי מֵהֶם וְהִנֵּה הֵם בָּאִים אַחֲרַי לְצִוּוּי הַמֶּלֶךְ. אָז טוֹב בְּעֵינֵי הַמֶּלֶךְ וְיוֹשֵׁב שָׁם עִמּוֹ וּמְדַבֵּר עִמּוֹ וְנַעֲשֶׂה אָהוּב שֶׁל הַמֶּלֶךְ. בֵּין כָּךְ בָּאוּ כָּל הָעָם וְהִתְפַּיֵּס עִמָּהֶם. אֲבָל אִם בְּנֵי הָעִיר לֹא בָאִים וְאֶחָד לֹא מַקְדִּים וּמְדַבֵּר לִפְנֵי הַמֶּלֶךְ לְהֵרָאוֹת בִּשְׁבִילָם, מִיָּד כּוֹעֵס הַמֶּלֶךְ. מַה כָּתוּב? (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ."],[6,"","וּמִי שֶׁמְּדַבֵּר בְּבֵית הַכְּנֶסֶת - אוֹי לוֹ שֶׁמַּרְאֶה פֵרוּד! אוֹי לוֹ שֶׁגּוֹרֵעַ מֵהָאֱמוּנָה! אוֹי לוֹ שֶׁאֵין לוֹ חֵלֶק בֵּאלֹהֵי יִשְׂרָאֵל, שֶׁמַּרְאֶה שֶׁאֵין לוֹ אֱלוֹהַּ וְלֹא נִמְצָא שָׁם, וּמַנְהִיג קָלוֹן בַּגְּבוּרָה הָעֶלְיוֹנָה."],[7,"","כָּל הַצְּבָעִים טוֹבִים בַּחֲלוֹם חוּץ מִתְּכֵלֶת, מִשּׁוּם שֶׁהוּא כִּסֵּא לָדוּן דִּינִים שֶׁל הַנְּשָׁמוֹת, וַהֲרֵי מַדְרֵגָה אַחַת הִיא. אֶלָּא בְּשָׁעָה שֶׁעוֹמְדִים בְּדִינֵי נְפָשׁוֹת, אָז הוּא צֶבַע תְּכֵלֶת, וַהֲרֵי בֵּאַרְנוּ. וּבְשָׁעָה שֶׁרוֹאֶה אָדָם לְזֶה הַצֶּבַע, נִזְכָּר אָדָם לַעֲשׂוֹת מִצְוַת אֲדוֹנוֹ, כְּגוֹן הַנָּחָשׁ שֶׁהָיוּ רוֹאִים אוֹתוֹ וְהָיוּ יְרֵאִים מִפְּנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹמְרִים עַצְמָם, וּבְאוֹתָהּ יִרְאָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עָלָה עֲלֵיהֶם מַיִם וּמִתְכַּסִּים. מִי גָרַם לָהֶם? אוֹתוֹ הַנָּחָשׁ, אוֹתָהּ רְצוּעָה שֶׁמִּסְתַּכְּלִים בָּהּ. אַף כָּךְ הַתְּכֵלֶת - וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת ה'. מֵאוֹתָהּ יִרְאָה שֶׁלּוֹ:"],[8,"","בֹּא רְאֵה, הָהָר הַזֶּה, לָשׁוֹן קָשָׁה הוּא. אוֹתָם הָרִים לְמַעְלָה, וְצַדִּיקִים הָאֵלּוּ שֶׁאֲחוּזִים בִּכְנֶסֶת יִשְׂרָאֵל, וְנִקְרָאִים הַר צִיּוֹן אוֹתָם הָרִים שֶׁסְּבִיב יְרוּשָׁלַיִם, בִּגְלַל שֶׁהֵם מְצֻיָּנִים וְאוֹמְרִים זֶה לָזֶה בְּצַד הַיִּחוּד (עובדיה א) לִשְׁפֹּט אֶת הַר עֵשָׂו, שֶׁקִּטְרוּג הַמְקַטְרֵג מִצַּד הַשְּׂמֹאל."],[9,"","בְּאוֹתוֹ זְמַן, וְהָיְתָה לַה' הַמְּלוּכָה. בַּהַתְחָלָה נִקְרֵאת מַמְלָכָה, מִשּׁוּם שֶׁמֵּינִיקָה לִשְׁנֵי צְדָדִים - לְיָמִין וְלִשְׂמֹאל. וְעַכְשָׁו נִקְרֵאת מְלוּכָה, בִּגְלַל שֶׁמֵּינִיקָה לְיָמִין. זֶהוּ שֶׁכָּתוּב (הושע ב) וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם. וּבִגְלַל שֶׁהַגָּלוּת לֹא לְעוֹלָם הִיא, שֶׁהֲרֵי יוֹשֶׁבֶת בַּגָּלוּת."],[10,"","בֹּא רְאֵה, שֶׁסָּמוּךְ לוֹ (זכריה יד) וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בִּגְלַל שֶׁעַד עַכְשָׁו, כְּשֶׁיִּשְׂרָאֵל בַּגָּלוּת - שְׁכִינָה עִמָּהֶם, וּמֶלֶךְ בְּלִי גְבִירָה אֵינוֹ מֶלֶךְ, אֲבָל אוֹתוֹ זְמַן, וְהָיָה ה' מֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. כְּשֶׁנִּדְבֶּקֶת הַשְּׁכִינָה בְּצַדִּיק, אָז הוּא הַיִּחוּד. שֶׁכָּךָ לָמַדְנוּ בַּסּוֹד שֶׁל קְרִיאַת שְׁמַע, שֶׁצָּרִיךְ אָדָם לְיַחֵד לַאֲדוֹנוֹ וּלְקַשֵּׁר קִשְׁרֵי הָאֱמוּנָה בִּרְצוֹן הַלֵּב."]]],[["דְהַכִי אוֹלִיפְנָא בְּרָזָא דִּקְרִיָת שְׁמַע דְּבָעֵי בָּר נָשׁ לְיַחֲדָא לְמָארֵיהּ וּלְקַשְׁרָא קִשְׁרִין דִמְהֵימְנוּתָא בִּרְעוּתָא דְלִבָּא. וְכַד מָטֵי לְאֶחָד אִבָּעֵי לֵיהּ לְכַוְונָא בְּא' סְתִימָא עַתִּיקָא (ס\"א עמיקא) דְּכֹלָּא וְח' תְמַנְיָא דַרְגִּין עִלָּאִין מֵחָכְמָה עִלָּאָה עַד צַדִּיק. וְד' רַבְּתָא אִתְדַבְּקוּתָא דְּכְּנְסֵת יִשְׂרָאֵל דְאִיהִי חוּלָקֵיהּ דְדָוִד דְאִקְּרֵי עָנִי וְאֶבְיוֹן כַּד אִתְדַּבְּקַת לְאִינוּן דַרְגִּין דִלְעֵילָא דִּרְמִיזִין בְּא\"ח. כְּדֵין אִיהִי רַבְּתָא וְעָלְמָא כּוּלֶיהּ יָנִיק מִינָהּ וְאִינּוּן שָׁדַיִם דְּאִינּוּן (שיר השירים ח׳:י׳) כַּמִּגְדָּלוֹת אָז הָיִיתִי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם.","תָּא חֲזֵי הָאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְמַר כַּד אִיהִי בְּגָלוּתָא עִם בְּנָהָא בֵּין אוּמִין דְעַלְמָא אִקְרֵי זְעִירָא הֲדָא הוּא דִּכְתִיב (שם) אָחוֹת לָּנוּ קְטַנָּה וְעַד יִשְׂרָאֵל אִתְדַבָּרוּ בְּאוֹרַיְיתָא וְאַזְלִין בְּאֹרַח קְשׁוֹט כְּדֵין אִתְמָלְיָּיא וְשָׁלוֹם אִתְחַבָּר בְּהוּ. אֲתִיבַת אִיהִי וְאַמְרַת אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת. בְּהַהוּא זִמְנָא דְאִתְחַבַּר עִמִי אָ\"ז וְשָׁלוֹ\"ם. א' רָזָא דְעַתִּיקָא קַדִּישָׁא דְכֹלָא, ז' שֶׁבַע דַרְגִּין וְשָׁלוֹ\"ם דְאִקְּרֵי צַדִּי\"ק כֵּיוָן דְּהָנֵי דַרְגִּין מִתְחַבְּרָן כְּדֵין אָ\"ז הֲיִיתִּי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם. וּמָאן עַיְינִין. אִינוּן ז' דַרְגִּין דְּאִקְרוּן עֵינֵי יְיָ, פְּנֵי יְיָ, וּכְדֵין שְׁלָמָא לְעַלְמָא וְשַׁרְיָיא טִיבוּ דְעַתִּיקָא בַּאֲתַר דְּדַכָר וְנוּקְבָא וּבְגִין כָּךְ פַּקָּד מֹשֶׁה בְּאוֹרַיְיתָא וְאָמַר (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ אֱלהֵינוּ יְיָ אֶחָד. לְקַשְׁרָא כּוּלְהוּ קִשְׁרִין דִמְהֵימְנוּתָא.","תָּא חֲזֵי, כָּל הַמַאֲרִיךְ בְּאֶחָד מָאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָּיו. מַאי טַעְמָא בְּגִין דְאִיהוּ אֲתַר דְכָל יוֹמִין וּשְׁנִין דְעַלְמָא בֵּיה תַלְיָין בְּרָזָא דְּאִינּוּן דַרְגִּין דִּרְמִיזִין בְּאֶחָד וְאִינּוּן עֲשָׂרָה וְכֻלְּהוּ חַד וְאִתְעָרוּ בֵּיה חַבְרַיָּיא וְאָמְרוּ בדל\"ת וְשַׁפִּיר. בְּגִין דְּהָאי אַתְרָא דְּדל\"ת הִיא וְלֵית לָה נְהוֹרָא מִדִּילֵיהּ. וּבָעֵי בָּר נָשׁ לְאַרָכָא בָּהּ וּלְאַמְשָׁכָא לָה בִּרְכָאָן מֵאִינוּן שִׁית סִטְרִין שִׁית בְּנִין עִלָּאִין עַל יְדֵי דְצַדִיק","וְאִינּוּן שִׁית סִטְרִין רְמִיזִין בח' בְּרָזָא דִּתְמָנְיָיא. שִׁית אִלֵּין וּתְרֵין לְעֵילָא חָכְמָה וּבִינָה אַבָּא וְאִימָא לְאוֹסָפָא וּלְאַכְלָלָא לְהוּ לְעֵילָא, וּלְמֵיהַב לְהוּ בִּרְכָאָן מֵאַבָּא וְאִימָא עִלָּאָה. דְהָא לָא שַׁרְיָיא טִיבוּ דְעַתִּיקָא אֶלָּא בַּאֲתַר דְשָׁלִים, בַּאֲתַר דְאִשְׁתַּכַּח דְכַר וְנוּקְבָא. הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:י״א) צְאֵינָה וּרְאֵינָה בְּנוֹת צִיּוֹן בַּמֶלֶךְ שְׁלֹמֹה וְגוֹ' בְּיוֹם חֲתוּנָתוֹ וְגוֹ'. בְּיוֹם חֲתוּנָתוֹ דַּיְיקָא.","וְעַל דָּא אֲמְרוּ וּבִּלְבַד שֶׁלֹּא יַחְטוֹף בַחי\"ת אֶלָּא בָּעֵי לְאַמְשָׁכָא בִּרְכָאָן מֵאֲתַר עִלָּאָה דְכוֹלָא. וּלְאַרָקָא בְּאִינוּן שִׁית בְּנִין. לְבָתָר לְהַאי בַּת דְּלֵית לָה אַחֲסָנָא בְּבֵית אֲבוּהָ וְאִימָא אֶלָּא הַאי בְּרָא. וּמִכָּאן אוֹלִיפְנָא דִּבְרָא יָרִית לְאַבָּא וּלְאִימָא וּבְרַתָּא לָא, אֶלָּא דְּאִית לָה מְזוֹנֵי מִן בְּרָא אֶלָּא בָּעֵי לְאַרָכָא בְּהָאי דל\"ת.","וְתַמָּן אַמְרֵי כַּמָה בָּעֵי בָּר נָשׁ לְאַרָכָא בַּהּ, כְּשִׁיעוּרָא דְיַמְלִיךְ יָתָהּ לְעֵילָא וּלְתַתָּא וּלְאַרְבַּע זִוְויָין דְעַלְמָא, רָזָא דְשִׁית סִטְרִין עִלָּאִין דְכֻלְּהוּ יִתְחַבְּרוּן עִמָּהּ וְלָא יִתְפָּרְשׁוּן לְעָלְמִין. וְכַד בָּר נָשׁ מַאֲרִיךְ בְּהָאי כָּל אִינוּן יוֹמִין וּשְׁנִין עִלָּאִין מוֹסְרִין בִּרְכָאָן עַל רֵישֵׁיהּ וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אַתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאַר.","תָּא חֲזֵי כְּלָלָא דְאוֹרַיְיתָא בְּהָאי קְרָא רְמִיזִין וּכְלָלָא דְכָל אִינוּן אֲמִירָן דְּאִתְבַּרֵי בְּהוֹן עַלְמָא בְּאֶחָד רְמִיזִין הֲדָא הוּא דִכְתִיב (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֵנוּ וְנַפְשׁוֹ אִוְתָהּ וַיַעֲשׂ. וּבְהוֹן אִתְבְּרֵי עַלְמָא וְעַל דָּא תָנֵינָן בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם וְכוּ' וְאוֹקִימְנָא דְּכוּלְהוּ י' וְכֻלְּהוּ כְּלִילָן בְּקְרָא קַדְמָאָה דְאוֹרַיְיתָא:","בְּרֵאשִׁית רָזָא דְחָכְמָ\"ה. בָּרָא. עִלָּאָה סְתִימָא דְלָא אִתְיְּידָע (כתר) אֱלֹהִי\"ם בִּינָ\"ה. אֶ\"ת כְּלָלָא דְּחֶסֶ\"ד וּגְבוּרָ\"ה. הַשָׁמַיִם תִפְאֶרֶ\"ת וְאֶ\"ת כְּלָלָא דְּנֶצַ\"ח וְהוֹ\"ד. וא\"ו דְּוְאֶת לְאַכְלָלָא צַדִּי\"ק. הָאָרֶץ כְּלָלָא דְּכְּנְסֵת יִשְׂרָאֵל אֶרֶץ הַחַיִּים וּבָתַר פְּרָטָא דְאוֹרַיְיתָא בְּרָזָא דְּאִינּוּן יוֹמִין עִלָּאִין. בְּרֵאשִׁית מַאֲמָר הוּא לָקֳבֵל דַרְגָּא דְחָכְמָ\"ה וְאִקְרֵי רֵאשִׁית.","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר לָקֳבֵל דַרְגָּא דְּחֶסֶ\"ד דְאִיהוּ לִימִינָא. דְהָא מִתַּמָּן נָפִיק נְהוֹרָא לְכֻלְּהוּ עָלְמִין בְּרָזָא דְיוֹם, הֲדָא הוּא דִכְתִיב (תהילים נ״ב:ג׳) חֶסֶד אֵל כָּל הַיּוֹם וּלְקֳבְלֵיהּ לְתַתָּא אַבְרָהָם דְאֲחִיד בְּהָאי חוּלָקָא. וּבְגִין כָּךְ כְּתִיב הָכָא יוֹם אֶחָד, וְהָכָא (יחזקאל לג) אֶחָד הָיָה אַבְרָהָם וּבֵיהּ כְּתִיב (ישעיהו מ״א:ב׳) מִי הֶעִיר מִמִּזְרָח בְּרָזָא דְּאוֹר דְנָפִיק מִמִּזְרָח.","וְתָא חֲזֵי לָא תִשְׁכַּח בְכֻלְּהוּ ז' זַכָּאִין דַאֲחִידָן לְעֵילָא בְּרָזָא דִשְׁמָהַתְהוֹן בְּשֵׁירוּתָא אָלֶף אֶלָּא אַבְרָהָם וְאַהֲרֹן דַאֲחִידָן בְהָאי חֶסֶ\"ד דְהָא כֹּהֲנִים מִסִּטְרָא דְחֶסֶ\"ד אָתוּ. וְאַף עַל גַּב דְאֲחִיד אַהֲרֹן בְּהוֹד, בְּחֶסֶ\"ד נָמֵי אֲחִיד וּמֹשֶׁה אַף עַל גַּב דְאֲחִיד בְּנֶצַח, בְּתִפְאֶרֶת נָמֵי אֲחִיד. לְאַחֲזָאָה דְכוֹלָא חַד וְאַבְרָהָם רֵישָׁא לְכֻלְּהוּ זַכָּאִין וּמִנֵּיהּ אִתַּפְרָשׁוּ לְתַתָּא דְאִיהוּ לִימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא וְאִקְרֵי כֹּהֵן הֲדָא הוּא דִכְתִיב (תהילים ק״י:ד׳) אַתָּה כֹּהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. וְאַהֲרֹן בְּגִין דְאִיהוּ כֹּהֵן אֲחִיד בְּהָאי, אֲבָל דַרְגָּא דִילֵיהּ הוֹ\"ד אִיהוּ:"],[],[[0,"","וּכְשֶׁמַּגִּיעַ לְ\"אֶחָד\", צָרִיךְ לוֹ לְכַוֵּן בְּא' נִסְתֶּרֶת עַתִּיקָה (עמקה) שֶׁל הַכֹּל, וְח' - שְׁמוֹנֶה דְרָגוֹת עֶלְיוֹנוֹת מֵחָכְמָה עֶלְיוֹנָה עַד צַדִּיק. וְד' גְּדוֹלָה - הִתְדַּבְּקוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא חֶלְקוֹ שֶׁל דָּוִד שֶׁנִּקְרָא (תהלים פו) עָנִי וְאֶבְיוֹן, כְּשֶׁנִּדְבֶּקֶת לְאוֹתָן דְּרָגוֹת שֶׁלְּמַעְלָה שֶׁרְמוּזוֹת בְּא\"ח. אָז הִיא גְּדוֹלָה וְכָל הָעוֹלָם יוֹנֵק מִמֶּנָּה, וְאוֹתָם שָׁדַיִם שֶׁהֵם כַּמִּגְדָּלוֹת, (שיר ח) אָז הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. בֹּא רְאֵה, פָּסוּק זֶה עַל כְּנֶסֶת יִשְׂרָאֵל נִתְבָּאֵר. כְּשֶׁהִיא בַּגָּלוּת עִם בָּנֶיהָ בֵּין אֻמּוֹת הָעוֹלָם נִקְרֵאת קְטַנָּה, זֶהוּ שֶׁכָּתוּב (שם) אָחוֹת לָנוּ קְטַנָּה. וּכְשֶׁיִּשְׂרָאֵל נִדְבָּקִים בַּתּוֹרָה וְהוֹלְכִים בְּדֶרֶךְ אֱמֶת, אָז מִתְמַלֵּאת, וְשָׁלוֹם מִתְחַבֵּר בָּהֶם. מְשִׁיבָה הִיא וְאוֹמֶרֶת, אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת."],[1,"","בְּאוֹתוֹ זְמַן שֶׁהִתְחַבֵּר עִמִּי, אָז וְשָׁלוֹם. א' סוֹד הָעַתִּיק הַקָּדוֹשׁ שֶׁל הַכֹּל. ז' שֶׁבַע דְּרָגוֹת, וְשָׁלוֹם שֶׁנִּקְרָא צַדִּיק. כֵּיוָן שֶׁהַדְּרָגוֹת הַלָּלוּ מִתְחַבְּרוֹת, אָז הָיִיתִי בְעֵינָיו כְּמוֹצְאֵת שָׁלוֹם. וְאֵיזֶה עֵינַיִם אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁנִּקְרָאוֹת עֵינֵי ה', פְּנֵי ה', וְאָז שָׁלוֹם לָעוֹלָם, וְשׁוֹרֶה הַטּוֹב שֶׁל הָעַתִּיק בְּמָקוֹם שֶׁל זָכָר וּנְקֵבָה, וְלָכֵן צִוָּה מֹשֶׁה בַּתּוֹרָה וְאָמַר (דברים יד) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. לְקַשֵּׁר אֶת כָּל קִשְׁרֵי הָאֱמוּנָה."],[2,"","בֹּא רְאֵה, כָּל הַמַּאֲרִיךְ בְּאֶחָד, מַאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָיו. מָה הַטַּעַם בִּגְלַל שֶׁהוּא מָקוֹם שֶׁכָּל יְמֵי וּשְׁנוֹת הָעוֹלָם בּוֹ תְּלוּיִים בְּסוֹד אוֹתָם הַדְּרָגוֹת שֶׁרְמוּזוֹת בְּאֶחָד, וְהֵם עֲשָׂרָה, וְכֻלָּם אֶחָד. וְהִתְעוֹרְרוּ בוֹ הַחֲבֵרִים וְאָמְרוּ, בְּדָלֶ\"ת וְיָפֶה, בִּגְלַל שֶׁמָּקוֹם זֶה שֶׁל דָּלֶ\"ת הוּא, וְאֵין לָהּ אוֹר מִשֶּׁלָּהּ, וְצָרִיךְ אָדָם לְהַאֲרִיךְ בָּהּ וְלִמְשֹׁךְ לָה בְּרָכוֹת מֵאוֹתָם שִׁשָּׁה צְדָדִים, שִׁשָּׁה בָנִים עֶלְיוֹנִים עַל יְדֵי הַצַּדִּיק, וְאוֹתָם שִׁשָּׁה צְדָדִים רְמוּזִים בְּח', בְּסוֹד שֶׁל שְׁמוֹנָה."],[3,"","שֵׁשֶּׁת אֵלֶּה, וּשְׁנַיִם לְמַעְלָה - חָכְמָה וּבִינָה, אָב וָאֵם - לְהוֹסִיף וּלְהַכְלִילָם לְמַעְלָה וְלָתֵת לָהֶם בְּרָכוֹת מֵאָב וָאֵם הָעֶלְיוֹנִים, שֶׁהֲרֵי אֵין שׁוֹרֶה הַטּוֹב שֶׁל הָעַתִּיק אֶלָּא בְּמָקוֹם שָׁלֵם, בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹמֵר. בְּיוֹם חֲתֻנָּתוֹ וְגוֹמֵר. בְּיוֹם חֲתֻנָּתוֹ דַּוְקָא."],[4,"","וְעַל זֶה אָמְרוּ, וּבִלְבַד שֶׁלֹּא יַחֲטֹף בְּחֵי\"ת, אֶלָּא צָרִיךְ לִמְשֹׁךְ בְּרָכוֹת מִמָּקוֹם עֶלְיוֹן שֶׁל הַכֹּל, וּלְהָרִיק בְּאוֹתָם שִׁשָּׁה בָנִים. אַחַר כָּךְ לַבַּת הַ את שֶׁאֵין לָהּ יְרֻשָּׁה בְּבֵית אָבִיהָ וְאִמָּהּ, אֶלָּא רַק הַבֵּן הַזֶּה. וּמִכָּאן לָמַדְנוּ שֶׁבֵּן יוֹרֵשׁ אָב וָאֵם, וּבַת לֹא, אֶלָּא שֶׁיֵּשׁ לָהּ מְזוֹנוֹת מִן הַבֵּן, אֶלָּא צָרִיךְ לְהַאֲרִיךְ בַּדָּלֶ\"ת הַ את."],[5,"","וְשָׁם אוֹמְרִים כַּמָּה צָרִיךְ אָדָם לְהַאֲרִיךְ בָּהּ, כְּשִׁעוּר שֶׁיַּמְלִיךְ אוֹתָהּ לְמַעְלָה וּלְמַטָּה וּלְאַרְבַּע זָוִיּוֹת הָעוֹלָם, סוֹד שֶׁל שִׁשָּׁה צְדָדִים עֶלְיוֹנִים שֶׁכֻּלָּם יִתְחַבְּרוּ עִמָּהּ וְלֹא יִפָּרְדוּ לְעוֹלָמִים, וּכְשֶׁאָדָם מַאֲרִיךְ בָּזֶה, כָּל אוֹתָם יָמִים וְשָׁנִים עֶלְיוֹנִים מוֹשְׁכִים בְּרָכָה עַל רֹאשׁוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא לוֹ (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[6,"","בֹּא רְאֵה, כְּלַל הַתּוֹרָה בַּפָּסוּק הַזֶּה רְמוּזִים, וּכְלָל שֶׁל כָּל אוֹתָן הָאֲמִירוֹת שֶׁבָּהֶן נִבְרָא הָעוֹלָם רְמוּזִים בְּאֶחָד. זֶהוּ שֶׁכָּתוּב (איוב כג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ וְנַפְשׁוֹ אִוְּתָה וַיָּעַשׂ. וּבָהֶם נִבְרָא הָעוֹלָם. וְעַל זֶה שָׁנִינוּ, בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם וְכוּ', וּפֵרַשְׁנוּ שֶׁכֻּלָּם עֲשָׂרָה, וְכֻלָּם כְּלוּלִים בַּפָּסוּק הָרִאשׁוֹן שֶׁל הַתּוֹרָה."],[7,"","בְּרֵאשִׁית - סוֹד הַחָכְמָה. בָּרָא - הָעֶלְיוֹן הַנִּסְתָּר שֶׁלֹּא נוֹדָע. אֱלֹהִים - בִּינָה. אֵת - כְּלָל שֶׁל חֶסֶד וּגְבוּרָה. הַשָּׁמַיִם - תִּפְאֶרֶת. וְאֵת - כְּלָלוּת שֶׁל נֵצַח וְהוֹד. וָא\"ו שֶׁל \"וְאֶת\" - לְהַכְלִיל הַצַּדִּיק. הָאָרֶץ - כְּלָלוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, אֶרֶץ הַחַיִּים, וְאַחַר כָּךְ פְּרָט שֶׁל תּוֹרָה בְּסוֹד אוֹתָם יָמִים עֶלְיוֹנִים. בְּרֵאשִׁית הוּא מַאֲמָר, כְּנֶגֶד הַדַּרְגָּה שֶׁל חָכְמָה, וְנִקְרָא רֵאשִׁית."],[8,"","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר - כְּנֶגֶד הַדַּרְגָּה שֶׁל חֶסֶד שֶׁהִיא לְיָמִין, שֶׁהֲרֵי מִשָּׁם יוֹצֵא אוֹר לְכָל הָעוֹלָמוֹת בְּסוֹד שֶׁל יוֹם, זֶהוּ שֶׁכָּתוּב (תהלים נב) חֶסֶד אֵל כָּל הַיּוֹם. וּכְנֶגְדּוֹ לְמַטָּה, אַבְרָהָם שֶׁאוֹחֵז בַּחֵלֶק הַזֶּה, וְלָכֵן כָּתוּב כָּאן יוֹם אֶחָד, וְכָאן - אֶחָד הָיָה אַבְרָהָם, וּבוֹ כָּתוּב (ישעיה מא) מִי הֵעִיר מִמִּזְרָח, בְּסוֹד שֶׁל אוֹר שֶׁיּוֹצֵא מִמִּזְרָח."],[9,"","וּבֹא רְאֵה, לֹא תִמְצָא בְּכָל שִׁבְעַת הַצַּדִּיקִים שֶׁאֲחוּזִים לְמַעְלָה בְּסוֹד שֶׁל שְׁמוֹתֵיהֶם בַּתְּחִלָּה אָלֶף, אֶלָּא אַבְרָהָם וְאַהֲרֹן שֶׁאֲחוּזִים בַּחֶסֶד הַזֶּה, שֶׁהֲרֵי כֹּהֲנִים מִצַּד הַחֶסֶד בָּאִים. אַף עַל גַּב שֶׁאַהֲרֹן אָחוּז בְּהוֹד, גַּם בְּחֶסֶד הוּא אָחוּז. וּמֹשֶׁה, אַף עַל גַּב שֶׁאָחוּז בְּנֵצַח, גַּם בְּתִפְאֶרֶת אָחוּז הוּא, לְהַרְאוֹת שֶׁהַכֹּל אֶחָד. וְאַבְרָהָם רֹאשׁ לְכָל הַצַּדִּיקִים, וּמִמֶּנּוּ נִפְרְדוּ לְמַטָּה, שֶׁהוּא לִימִין הַקָּדוֹשׁ בָּרוּךְ הוּא, וְנִקְרָא כֹּהֵן, זֶהוּ שֶׁכָּתוּב (תהלים קי) אַתָּה כֹהֵן לְעוֹלָם עַל דִּבְרָתִי מַלְכִּי צֶדֶק. וְאַהֲרֹן אָחוּז בָּזֶה בִּגְלַל שֶׁהוּא כֹּהֵן, אֲבָל דַּרְגָּתוֹ הוּא הוֹד."]]],[["וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל וְכוּ' לָקֳבֵל דַרְגָּא דִּגְבוּרָ\"ה דְאֲחִיד תַמָּן יִצְחָק וּלְקִבְלֵיהּ תִפְאֶרֶת (ס\"א לקבליה. תא חזי) מַיָא אוֹלִידוּ אֶשָׁא בְּגִין כָּךְ יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל. וּבְגִין כָּךְ לְתַתָּא אַבְרָהָם הוֹלִיד אֶת יִצְחָק (ובההוא יומא) וּבְיוֹמָא הַהוּא אִתְבְּרֵי גֵּיהִנָם דְנָפִיק מֵהַהוּא אֶשָׁא תַקִּיפָא בְּהַהוּא מַחֲלוֹקֶת וּבְגִין כָּךְ הַהוּא יוֹמָא, יוֹמָא דְדִינָא:","וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמָּיִם לָקֳבֵל דָא דַרְגָּא דְּתִפְאֶרֶ\"ת דְאִקְּרֵי קַו הָאֶמְצָעִי וּלְקִבְלֵיהּ דְיַעֲקֹב דְאִיהוּ תְּלִיתָאֵי וְנָטִיל תְרֵין חוּלָקִין בְּהַהוּא דְּאֵשׁ וּמַיִם (דאש השמים) מִשָׁמַיִם וּלְקִבְלֵיהּ יוֹם תְּלִיתָאֵי וְעַל דָא דְאִקְּרֵי יַעֲקֹב (בראשית כ״ה:כ״ז) אִישׁ תָּם יוֹשֵׁב אֹהָלִים. שְׁלִים בְּכוֹלָא. שְׁלִים בְּחֶסֶד. שְׁלִים בְּדִינָא. שְׁלִים בְּמַיָּא שְׁלִים בְּאֶשָׁא. יוֹשֵׁב אֹהָלִים תְרֵין, חֶסֶ\"ד וּגְבוּרָ\"ה וְנָטִיל כֹּלָּא וְאִתְעֲבִיד בִידֵיהּ רַחֲמִין:","וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹ'. דַּרְגָא דְּצַדִּיק דְּאִקְרֵי עֵץ הַחַיִּים וְאִיהוּ עוֹשֶׂה פְּרִי, דְּהָא לֵית בְּכֻלְּהוּ דְּיַעֲבִיד פֶּרִי בָּר אִיהוּ. זַרְעוֹ בּוֹ עַל הָאָרֶץ דַּיְיקָא. וּלְקִבְלֵיהּ לְתַתָּא (בראשית מ״ט:כ״ב) בֵּן פּוֹרָת יוֹסֵף בֵּן פּוֹרָת עֲלֵי עַיִן. וְאִקְרֵי בְּרִית שְׁלָמָא.","וּבְגִין כָּךְ תְּרֵי זִמְנֵי בְּהַאי יוֹמָא כִּי טוֹב, חַד לְקֳבֵל דַּרְגָא דְּתִפְאֶרֶ\"ת וְחַד לְקֳבֵל דַּרְגָא דְּצַדִּיק דְּאִיהוּ יוֹמָא דְשַׁבְּתָא דִּלְעֵילָא וְעֲבִידְתָּא אַחֲרָא לֵית בֵּיהּ אֶלָּא זִווּג לְאַפָּקָא פֶּרִי נִשְׁמָתִין לְעָלְמָא, פֶּרִי עוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא. הָכִי נָמֵי לְתַתָּא דְּזִווּגָא שָׁרֵי בֵּיהּ מִשַׁבָּת לְשַׁבָּת.","תָּא חֲזֵי רָזָא עִלָּאָה דְּאוֹרַיְיתָא, מַאי עֵץ פֶּרִי עוֹשֶׂה פֶּרִי, לְקֳבֵל יוֹמָא דְשַׁבְּתָא אִיהוּ. ומַאי טַעְמָא אִתְכְּלִיל בְּיוֹם תְּלִיתָאִי, רָזָא עִלָּאָה אִיהוּ. בְּגִין דְּתָנֵינָן רִבִּי שִׁמְעוֹן בֵּן יוֹחָאי אוֹמֶר מַאי טַעְמָא כְּתִיב בְּאוֹרַיְיתָא (דברים כ״ד:א׳) כִּי יִקַּח אִישׁ אִשָּׁה וְלָא כִּי תִּלָקַח אִשָּׁה לְאִישׁ בְּגִין דְּאֹרְחֵיהּ דְּבַּר נָשׁ לְאָהַדְּרָא וּלְמִתְבַּע אִנְתּוּ. מְתַל לְבַּר נָשׁ דְּאִתְאֲבִיד לֵיהּ אַבֵדַתָא מָארֵי דְּאַבֵדַתָא מֵחַזֶר לְמִתְבַּע אַבֵידַתָא דִילֵיהּ,","וְהַאי צַדִּיק אִישׁ אִקְרֵי. הֲדָא הוּא דִכְתִיב (בראשית מ״ג:י״א) וְהוֹרִידוּ לָאִישׁ מִנְחָה כְּדְּאוֹקִימְנָא. וכְּנֶסֶת יִשְׂרָאֵל דִּרְמִיזָא בְּיוֹם רְבִיעָאִי בְּרָזָא דִמְאֹרֹת חָסֵר סַמְכָא רְבִיעָאָה מַלְכוּתָא דְדָוִד. בְּגִין כָּךְ אַף עַל גַּב דְּאַתְרֵיהּ דְּהַאי צַדִּיק יוֹמָא דְשַׁבְּתָא אִתְכְּלִיל וְאִתְרְמִיז בְּיוֹמָא תְּלִיתָאִי לְמֶהֱוֵי סָמִיךְ לְיוֹם רְבִיעָאִי וְאִיהוּ אִנְתּוּ דִילֵיהּ בְּגִין כָּךְ מָארֵיהּ דְּאַבֵידַתָא מֵחַזֶר עַל אַבֵדָתוֹ וּבְגִין כָּךְ כְּתִיב לְתַתָּא (בראשית מ״ב:ו׳) וְיוֹסֵף הוּא הַשָׁלִיט עַל הָאָרֶץ.","אֲבָל בְּזִמְנָא דְאָתֵי דְּאִיהוּ בְּאַחֲרִית הַיָּמִים בְּיוֹם שְׁתִיתָאִי דְּאִיהוּ אַלְפָא שְׁתִיתָאָה כַּד יֵיתֵי מְשִׁיחָא, דְּיוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא אֶלֶף שְׁנִין אַף עַל גַּב דְּכְּנֶסֶת יִשְׂרָאֵל חוּלָקָא דִּידָהּ יוֹמָא רְבִיעָאָה, אַזְלָא וְאִתְרְמִיזָא בְּיוֹמָא שְׁתִיתָאָה לְמֶהֱוֵי סְמִיכָא לְבַעְלָה דְּאִקְרֵי צַדִּיק יוֹמָא דְשַׁבְּתָא לְתַקְנָא לֵיהּ פָתוֹרָא וְהַאי דִכְתִיב (ירמיהו ל״א:כ״ב) כִּי בָּרָא יְיָ חֲדָשָׁה בָּאָרֶץ נְקֵבָה תְּסוֹבֵב גָּבֶר דָא אִיהוּ בְּזִמְנָא דִמְשִׁיחָא דְאִיהִי בְּיוֹמָא שְׁתִיתָאָה","וּבְגִין כָּךְ כְּתִיב וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם הַשִׁשִׁי. ומַאי טַעְמָא אִתּוֹסַף ה' מָה דְלָא הֲוָה כֵּן בִּשְׁאָר יוֹמֵי. אֲבָל בְכָל אַתְרָא ה' דָא כְּנֶסֶת יִשְׂרָאֵל דְּאַתְיָיא לְאִזְדַּוְּוגָא בְּבַעְלָהּ יוֹמָא דְשַׁבְּתָא, כַּד יֵיתֵי לְבַעְלָהּ (ס\"א לה בעלה) לְאַקָּמָא לָהּ מֵעַפְרָא. וּבְגִין כָּךְ כְּתִיב (ישעיהו כ״ז:י״ג) וָבָאוּ הַאוֹבְדִים בְּאֶרֶץ אַשּׁוּר. דָא צַדִּיק וּכְּנֶסֶת יִשְׂרָאֵל.","דָבָר אֲחֵר מַאי טַעְמָא אִתְכְּלִיל בְּיוֹם תְּלִיתָאִי רָזָא דְּצַדִּיק בְּגִין דִתְּלַת דַּרְגִּין מִימִינָא וּתְלָתָא מִשְּׂמָאלָא וְאִיהוּ הֲוָה אֱמְצָעִיתָּא דְּגוּפָא לְאַשְׁקָאָה לְכוֹלָא בְּגִין לְמִנְגָד שַׁקְיוּתֵיהּ לְיוֹם רְבִיעָאִי דְאִיהִי כְּנֶסֶת יִשְׂרָאֵל דְּלֵית לָה נְהוֹרָא מִגַּרְמָהּ, סָמִיךְ לְהַאי צַדִּיק. וְתָּא חֲזֵי הַאי יוֹמָא דְשַׁבְּתָא אֲסִיר לְמֶעְבָּד עֲבִידְתָּא בְּגִין כָּךְ אִתְכְּלִילוּ בֵּיהּ תְּרֵין וַיֹּאמֶר, לְקֳבֵל תְּרֵין דַּרְגִּין וְהוּכְפָּל בֵּיהּ כִּי טוֹב.","וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת לְקֳבֵל דַּרְגָא דְצֶדֶ\"ק, מַלְכוּ\"ת דִּלְעֵילָא דְּלֵית לָה נְהוֹרָא מִדִילָה אֶלָּא מָה דְאִתְיְיהִיב לָה עַל יְדֵי דְּצַדִּיק וּבְגִין כָּךְ דָוִד לְתַתָּא עָנִי וְאֶבְיוֹן אֲחִיד בָּהּ וְאִצְטְרִיךְ לְאוֹסָפָא לֵיהּ יוֹמִין וּשְׁנִין וְהָא אוֹקִימְנָא שִׁבְעִים שָׁנָה דַּיְיקָא וְאִקְרֵי יוֹם רְבִיעָאִי:","וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמָּיִם. לְקֳבֵל דַּרְגָא דְנֶצָ\"ח דְּאִיהוּ סַמְכָא יְמִינָא דְּאוֹרַיְיתָא וּלְקִבְלֵיהּ מֹשֶׁה לְתַתָּא סָמִיךְ לְעָלְמָא בְּאוֹרַיְיתָא הֲדָא הוּא דִכְתִיב (ירמיהו ל״ג:כ״ה) אִם לא בְּרִיתִי יוֹמָם וָלַיְלָה וְגוֹ':","וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ לְקֳבֵל דַּרְגָא דְהוֹ\"ד דְאֲחִיד אַהֲרֹן וְאִקְרֵי יוֹם שְׁתִיתָאִי. תָּא חֲזִיִ אַהֲרֹן לְתַתָּא אַף עַל גַּב דְאָתֵי מִחֶסֶ\"ד אֲחִיד לְתַתָּא בְּיוֹם שְׁתִיתָאִי דְּאִקְרֵי הוֹ\"ד וְעָבִיד קָרְבָּנִין בְּאִינוּן מִינֵי בְּעִירָן דַּכְיָין וְאִתְבְּרִיאוּ בְּיוֹמָא דִילֵיהּ (לקרבא) לְאַקְרָבָא כְּנֶסֶת יִשְׂרָאֵל דְאִתְרְמִיזָא בֵּיהּ (בצד\"ק) בְּצָדִי\"ק לְקַשְׁרָא דַּרְגִּין דִמְהֵימְנוּתָא וּלְנַחֲתָא רַחֲמֵי לְעָלְמָא:","וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. הַאי אֲמִירָא לְקֳבֵל דַּרְגָא עִלָּאָה דְכֹלָא סְתִימָאָה דִּסְתִימִין. בָּעָא לְמֶעְבָּד יְקָרָא לְדִיּוּקְנָא בְּרָזָא דְּאָדָם וּבְכֻלְּהוּ דַּרְגִּין לְתַתָּא יָהִיב חֵילָא לְאַפָּקָא כָּל חַד כְּדְקָא חָזֵי לֵיהּ וְעָבַד אָדָם דְּשַׁלִּיט בְּכֹלָּא בְּעִלָּאֵי וְתַתָּאֵי."],[],[[0,"","וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל וְכוּ' - כְּנֶגֶד הַדַּרְגָּה שֶׁל גְּבוּרָה שֶׁשָּׁם אָחוּז יִצְחָק, וּכְנֶגְדּוֹ תִּפְאֶרֶת. הַמַּיִם הוֹלִידוּ אֵשׁ, בִּגְלַל כָּךְ יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל, וּבִגְלַל כָּךְ לְמַטָּה (בראשית כה) אַבְרָהָם הוֹלִיד אֶת יִצְחָק, וּבְאוֹתוֹ יוֹם נִבְרָא גֵיהִנֹּם, שֶׁיָּצָא מֵאוֹתָהּ אֵשׁ חֲזָקָה בְּאוֹתָהּ מַחֲלֹקֶת, וְלָכֵן אוֹתוֹ יוֹם הוּא יוֹם הַדִּין."],[1,"","וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם - כְּנֶגֶד דַּרְגַּת תִּפְאֶרֶת שֶׁנִּקְרָא קַו הָאֶמְצָעִי, וּכְנֶגֶד יַעֲקֹב שֶׁהוּא שְׁלִישִׁי, וְנוֹטֵל שְׁנֵי חֲלָקִים בְּאוֹתוֹ שֶׁל אֵשׁ וּמַיִם (של אש השמים) מִשָּׁמַיִם, וּכְנֶגְדּוֹ יוֹם שְׁלִישִׁי, וְעַל זֶה נִקְרָא יַעֲקֹב (שם) אִישׁ תָּם יֹשֵׁב אֹהָלִים. שָׁלֵם בַּכֹּל. שָׁלֵם בְּחֶסֶד. שָׁלֵם בְּדִין. שָׁלֵם בְּמַיִם. שָׁלֵם בְּאֵשׁ. יֹשֵׁב אֹהָלִים - שְׁנַיִם, חֶסֶד וּגְבוּרָה, וְנוֹטֵל הַכֹּל, וְנַעֲשֶׂה בְיָדָיו רַחֲמִים."],[2,"","וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי וְגוֹמֵר. הַדַּרְגָּה שֶׁל צַדִּיק שֶׁנִּקְרָא עֵץ הַחַיִּים, וְהוּא עוֹשֶׂה פְּרִי, שֶׁהֲרֵי אֵין בְּכֻלָּם שֶׁיַּעֲשֶׂה פְּרִי פְּרָט לוֹ. זַרְעוֹ בוֹ עַל הָאָרֶץ, דַּוְקָא, וּכְנֶגְדּוֹ לְמַטָּה (שם מט) בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן, וְנִקְרָא בְּרִית שָׁלוֹם."],[3,"","וְלָכֵן פַּעֲמַיִם בַּיּוֹם הַזֶּה כִּי טוֹב, אֶחָד כְּנֶגֶד דַּרְגַּת תִּפְאֶרֶת, וְאֶחָד כְּנֶגֶד דַּרְגַּת צַדִּיק, שֶׁהוּא יוֹם הַשַּׁבָּת שֶׁלְּמַעְלָה, וּמַעֲשֶׂה אַחֵר אֵין בּוֹ אֶלָּא זִוּוּג לְהוֹצִיא פְּרִי נְשָׁמוֹת לָעוֹלָם, פְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. כָּךְ גַּם לְמַטָּה, שֶׁזִּוּוּג מֻתָּר בּוֹ מִשַּׁבָּת לְשַׁבָּת."],[4,"","בֹּא רְאֵה סוֹד עֶלְיוֹן שֶׁל הַתּוֹרָה, מַה זֶּה עֵץ פְּרִי עֹשֶׂה פְּרִי, הוּא כְּנֶגֶד יוֹם הַשַּׁבָּת, מָה הַטַּעַם נִכְלָל בְּיוֹם שְׁלִישִׁי סוֹד עֶלְיוֹן הוּא, בִּגְלַל שֶׁשָּׁנִינוּ, רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי אוֹמֵר, מָה הַטַּעַם כָּתוּב בַּתּוֹרָה (דברים כד) כִּי יִקַּח אִישׁ אִשָּׁה, וְלֹא כִּי תִלָּקַח אִשָּׁה לְאִישׁ בִּגְלַל שֶׁדֶּרֶךְ הָאִישׁ לְחַזֵּר וּלְבַקֵּשׁ אִשָּׁה. מָשָׁל לְאָדָם שֶׁאָבְדָה לוֹ אֲבֵדָה, בַּעַל הָאֲבֵדָה מְחַזֵּר אַחַר אֲבֵדָתוֹ. וְצַדִּיק (יסוד) זֶה נִקְרָא אִישׁ. זֶהוּ שֶׁכָּתוּב (בראשית מג) וְהוֹרִידוּ לָאִישׁ מִנְחָה, כְּפִי שֶׁבֵּאַרְנוּ."],[5,"","וּכְנֶסֶת יִשְׂרָאֵל שֶׁרְמוּזָה בְּיוֹם רְבִיעִי בְּסוֹד שֶׁל מְאֹרֹת חָסֵר, הָעַמּוּד הָרְבִיעִי מַלְכוּת שֶׁל דָּוִד, לָכֵן אַף עַל גַּב שֶׁמְּקוֹמוֹ שֶׁל צַדִּיק זֶה יוֹם הַשַּׁבָּת, נִכְלַל וְנִרְמַז בַּיּוֹם הַשְּׁלִישִׁי, לִהְיוֹת סָמוּךְ לְיוֹם רְבִיעִי, וְהִיא אִשְׁתּוֹ, לָכֵן בַּעַל הָאֲבֵדָה מְחַזֵּר עַל אֲבֵדָתוֹ, וְלָכֵן כָּתוּב לְמַטָּה (שם מב) וְיוֹסֵף הוּא הַשַּׁלִּיט עַל הָאָרֶץ."],[6,"","אֲבָל לֶעָתִיד לָבֹא, שֶׁהוּא בְּאַחֲרִית הַיָּמִים, בַּיּוֹם הַשִּׁשִּׁי שֶׁהוּא הָאֶלֶף הַשִּׁשִּׁי, כְּשֶׁיָּבֹא הַמָּשִׁיחַ, שֶׁיּוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלֶף שָׁנָה, אַף עַל גַּב שֶׁחֶלְקָהּ שֶׁל כְּנֶסֶת יִשְׂרָאֵל הוּא יוֹם הָרְבִיעִי, הָלְכָה וְנִרְמְזָה בַּיּוֹם הַשִּׁשִּׁי לִהְיוֹת סְמוּכָה לְבַעְלָהּ שֶׁנִּקְרָא צַדִּיק, יוֹם הַשַּׁבָּת, לְתַקֵּן לוֹ שֻׁלְחָן. וְזֶהוּ שֶׁכָּתוּב (ירמיה לא) כִּי בָרָא ה' חֲדָשָׁה בָּאָרֶץ נְקֵבָה תְּסוֹבֵב גָּבֶר. זֶהוּ בִּזְמַן הַמָּשִׁיחַ שֶׁהוּא בַּיּוֹם הַשִּׁשִּׁי,"],[7,"","וְלָכֵן כָּתוּב וַיְהִי עֶרֶב וַיְהִי בקֶר יוֹם הַשִּׁשִּׁי. מָה הַטַּעַם נוֹסָף ה', מַה שֶּׁלֹּא הָיָה כֵּן בִּשְׁאָר הַיָּמִים אֲבָל בְּכָל מָקוֹם ה' זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁבָּאָה לְהִזְדַּוֵּג עִם בַּעְלָהּ בְּיוֹם שַׁבָּת, כְּשֶׁיָּבא בַּעְלָהּ לַהֲקִימָהּ מִן הֶעָפָר. וּבִגְלַל כָּךְ כָּתוּב (ישעיה כז) וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר, זֶה צַדִּיק וּכְנֶסֶת יִשְׂרָאֵל."],[8,"","דָּבָר אַחֵר, מָה הַטַּעַם נִכְלָל הַיּוֹם הַשְּׁלִישִׁי הַסּוֹד שֶׁל צַדִּיק בִּגְלַל שֶׁשָּׁלֹשׁ דְּרָגוֹת מִיָּמִין וְשָׁלֹשׁ מִשְּׂמֹאל, וְהוּא הָיָה בְּאֶמְצַע הַגּוּף לְהַשְׁקוֹת לַכֹּל כְּדֵי לְהַשְׁפִּיעַ הַשְׁפָּעָתוֹ לְיוֹם רְבִיעִי שֶׁהוּא כְּנֶסֶת יִשְׂרָאֵל, שֶׁאֵין לָהּ אוֹר מֵעַצְמָהּ סָמוּךְ לַצַּדִּיק הַזֶּה. וּבֹא תִרְאֶה, יוֹם הַשַּׁבָּת הַזֶּה אָסוּר לַעֲשׂוֹת בּוֹ מְלָאכָה, מִשּׁוּם כָּךְ נִכְלְלוּ בוֹ שְׁנֵי וַיֹּאמֶר, כְּנֶגֶד שְׁתֵּי דְרָגוֹת, וְהֻכְפַּל בּוֹ כִּי טוֹב."],[9,"","וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת - כְּנֶגֶד דַּרְגָּה שֶׁל צֶדֶק, מַלְכוּת שֶׁלְּמַעְלָה שֶׁאֵין לָהּ אוֹר מִשֶּׁלָּהּ אֶלָּא מַה שֶּׁנּוֹתֵן לָהּ עַל יְדֵי צַדִּיק, וְלָכֵן דָּוִד לְמַטָּה עָנִי וְאֶבְיוֹן אָחוּזּ בָּהּ, וְהִצְטָרֵךְ לְהוֹסִיף לוֹ יָמִים וְשָׁנִים, וַהֲרֵי בֵּאַרְנוּ דַּוְקָא שִׁבְעִים שָׁנָה, וְנִקְרָא יוֹם רְבִיעִי."],[10,"","וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמַּיִם - כְּנֶגֶד דַּרְגָּה שֶׁל נֵצַח, שֶׁהוּא עַמּוּד יָמִין שֶׁל הַתּוֹרָה, וּכְנֶגְדּוֹ מֹשֶׁה לְמַטָּה סוֹמֵךְ לָעוֹלָם בַּתּוֹרָה. זֶהוּ שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה וְגוֹמֵר."],[11,"","וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ - כְּנֶגֶד דַּרְגָּה שֶׁל הוֹד שֶׁאוֹחֵז אַהֲרֹן, וְנִקְרֵאת יוֹם שִׁשִּׁי. בֹּא רְאֵה, אַהֲרֹן לְמַטָּה אַף עַל גַּב שֶׁבָּא מֵחֶסֶד, אָחוּז לְמַטָּה בַּיּוֹם הַשִּׁשִּׁי שֶׁנִּקְרָא הוֹד, וְעוֹשֶׂה קָרְבָּנוֹת בְּאוֹתָם מִינֵי בְהֵמוֹת טְהוֹרוֹת שֶׁנִּבְרְאוּ בַּיּוֹם שֶׁלּוֹ, לְקָרֵב אֶת כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּרְמְזָה בְּצַדִּיק, לִקְשֹׁר דַּרְגוֹת הָאֱמוּנָה וּלְהוֹרִיד רַחֲמִים לָעוֹלָם."],[12,"","וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם. הָאֲמִירָה הַזּוֹ כְּנֶגֶד הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁל הַכֹּל נִסְתֶּרֶת הַנִּסְתָּרִים, רָצָה לַעֲשׂוֹת כָּבוֹד לִדְמוּתוֹ בְּסוֹד שֶׁל אָדָם, וּבְכָל הַדְּרָגוֹת לְמַטָּה נָתַן כֹּחַ לְהוֹצִיא, כָּל אֶחָד כָּרָאוּי לוֹ, וְעָשָׂה אָדָם שֶׁשּׁוֹלֵט בַּכֹּל, בְּעֶלְיוֹנִים וְתַחְתּוֹנִים."]]],[["וְתָא חֲזֵי עַד לָא אֲשְׁלִימוּ אִינוּן שֶׁבַע דַּרְגִּין יוֹמִין עִלָּאִין לָא אִשְׁתְּלִים אָדָם לְעֵילָא. כֵּיוָן דְּאִשְׁתְּלִים לְעֵילָא אָדָם עִלָּאָה, אִשְׁתְּלִים לְתַתָּא אָדָם תַּתָּאָה. וְכֻלְהוּ עָלְמִין בִשְׁלִימוּ. בְּגִין כָּךְ שָׁלְטֵיה לְאָדָם תַּתָּאָה עַל כָּל דְּאִתְבַּרֵי בְּעַלְמָא בְּגִין דְּאָדָם עִלָּאָה שָׁלִיט עַל כֹּלָּא. וּבְגִין כָּךְ רָמַז בְּהַאי קְרָא שֶׁבַע דַּרְגִּין. דְּאִית בֵּיהּ שֶׁבַע דַּרְגִּין עִלָּאִין דְּאִקְרֵי בְּהוּ אָדָם דִּלְעֵילָא וְאִשְׁתְּלִים בְּהוּ. בְּגִין כָּךְ נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ, לְמֵיהַב לֵיהּ שֶׁפַע מֵהַהוּא אַתְרָא דְּאִקְרֵי חֶסֶד.","תָּא חֲזֵי, מַאן דְּהַאי צוּלְמָא עָלֵיהּ, חֶסֶד אֵל לָא אַעְדֵי מִנֵּיהּ וְיַתְבָא עַל רֵישֵׁיהּ וְאִתְחַבְּרַת בֵּיהּ שְׁכִינְתָּא בְסֵיפָא (בסופא) דְיוֹמוֹי בְּגִין דְּהַאי חֶסֶ\"ד יוֹם רִאשׁוֹן וְאִיהוּ רֵישָׁא דְכָל יוֹמִין דִּלְעֵילָא וְהַאי צוּלְמָא דְּאַתְיָא לֵיהּ מִנֵּיהּ לָא אִסְתְּלַק עַד דְּאִשְׁתְּלִימוּ יוֹמוֹי בְּהַהוּא דַּרְגָא דְאִקְּרֵי אַחֲרִית הַיָּמִים וְהוּא דַּרְגָא דְצֶדֶק וְאִיהִי שְׁבִיעָאָה, שְׁנָת הַשְׁמִיטָה בְּהַהוּא דַּרְגָא אַשְׁלִימוּ יוֹמוֹי דְּבָּר נָשׁ כַּד אִשְׁתַּלִּימוּ שִׁבְעִין שְׁנִין לְקֳבֵל שֶׁבַע דַּרְגִּין, עֲשָׂרָה לְכָל דַּרְגָא. הֲדָא הוּא דִכְתִיב (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה. מַאן בָּהֶם, בְּאִינוּן יוֹמִין וּשְׁנִין דִּלְעֵילָא.","וְאִם בִּגְבוּרוֹת שְׁמֹנִים. תָּא חֲזֵי, בְּנֵי חַיֵּי וּמְזוֹנֵי לָאו בִּזְכוּתָא תַלְיָא מִלְּתָא. רָזָא דְּאִינוּן שָׁב בְּדַרְגִּין (לדעתי צ\"ל שבע דרגין) דִבְּהוֹן זְכוּת וְחוֹבָא בְּרָזָא דְחֶסֶ\"ד וּגְבוּרָה. דְּאִי הֲכִי לָא הֲוָה לֵיהּ לְבַר נָשׁ לְמֶהֱוִי חָי בָּר מִשִׁבְעִין. אֶלָּא בְּמַזָּלָא עִלָּאָה עַתִּיקָא דְכֹלָא תַלְיָין. בְּגִין כָּךְ אִיהוּ מוֹסִיף עַל כָּל יוֹמוֹי דְכָל בַּר נָשׁ כִּרְעוּתֵיהּ.","וְתָּא חֲזֵי הֲכִי אוֹלִיפְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, דְּבֵּלְילְיָא בַּתְרָאָה דְחַגָא, אִי יִסְתָּכַּל בַּר נָשׁ בְּצוּלְמָא דִילֵיהּ וַחֲזֵי לֵיהּ שְׁלִים, לָא אִתְגְּזַר עֲלוֹי מִיתָה. וּמָאי טַעְמָא בְּהַאי לֵילְיָא, בְּגִין דְז' יוֹמִין דְחַגָא לְקֳבֵל שִׁבְעָא יוֹמִין עִלָּאִין אִינוּן. דְכָל יוֹמִין וּשְׁנִין דְּעָלְמָא בְּהוּ תַלְיָין, וְאִינוּן רְמִיזִין בְּקְרָא (דברי הימים א כט) דְּלְךָ יְיָ' הַגְּדוּלָה וְגוֹ' שֵׁירוּתָא דִלְהוֹן חֶסֶ\"ד וְסִיּוּמָא דִלְהוֹן מַמְ\"לָכָה, כְּנֶסֶת יִשְׂרָאֵל, אֲחַרִי\"ת הַיָּמִים. אִשְׁתְּכַח שְׁבִיעָאָה אַחֲרִית. וְכַד אַתְיָא הַאי לֵילְיָא דִשְׁבִיעִי אִתְחֲזֵי אִי אִשְׁתַּלִּימוּ יוֹמוֹי בְּהַאי אַחֲרִית. וְאִי הַאי צוּלְמָא עִלָּאָה חֲזֵי עָלֵיהּ, חֶסֶ\"ד אֵל יִתְהַדָר עָלֵיהּ כְּדִּבְקַדְמֵיתָא וְלָא מִסְתַּפֵּי מֵהָאי דִינָא דְצֶדֶ\"ק וְאִיהִי בַּהֲדֵיהּ בִשְׁלִימוּ בְּחֶדְוָותָא וְאַהְדַּרַת לֵיהּ אַנְפִּין.","וּבְגִין כָּךְ אַזְהַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל לְאִשְׁתֵּזָבָא מִדִינוֹי דְּהַאי צֶדֶ\"ק, וּלְחַפָאַה סֻכַּת שְׁלָמָא עָלַיְיהוּ וּלְמֵיתַב בְּצִלָא דִמְהֵימְנוּתָא. הֲדָא הוּא דִכְתִיב (ויקרא כ״ג:מ״ב) בַּסֻכּוֹת תְּשְׁבוּ שִׁבְעַת יָמִים לְאַכְלָלָא לְהַאי דַּרְגָא דִּלְעֵילָא וּלְאוֹסָפָא בֵּיהּ בְּרָכָה מַיִּם (ממיין) עִלָּאִין, בְגִין דְּהַאי יוֹמָא שְׁבִיעָאָה אִיהוּ כְּנֶסֶת יִשְׂרָאֵל אֲנָן מָקִיפִין לְהַאי מִזְבֵּחַ עִלָּאָה בְּאִינוּן תְּרֵין לִמּוּדִים דְּאִינוּן עַרְבֵי נַחַל וְעַבְדִין בָּהּ נִסוּךְ הַמָּיִם וְיָהִיב צַדִּי\"ק בְּאִינוּן שִׁתִּין דְּאִינוּן מִו' יְמֵי בְּרֵאשִׁית כֹּלָּא בְּרָזָא דְחָכְמְתָא.","וּלְבָתָר (במדבר כ״ט:ל״ה) בְּיוֹם הַשְׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. עָבְדוּ כְּנִישְׁתָּא לְאִינוּן שֶׁבַע יוֹמִין עִלָּאִין וְעָבְדוּ יוֹמָא טָבָא, בְּגִין דְאִשְׁתָזְבְתוּן מִדִינוֹי דְּהַהוּא יוֹמָא שְׁבִיעָאָה. בְּגִין כָּךְ כְּתִיב בְּצַלְמֵנוּ","כִּדְמוּתֵנוּ לְקֳבֵל יוֹמָא תִנְיָנָא גְבוּרָה, חוּלָקֵיהּ דְיִצְחָק. כְּדֵין אִית לְבַּר נָשׁ לְמִשְׁוֵי לְהַאי דְמוּתֵנוּ וּלְאִתְדָמֵי בְּעוֹבָדוֹי לְאִינוּן עִלָּאִין. וְכָל דָא לָמָה בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב בִּידֵי דְּבַר נָשׁ, דְּאִי בָּעֵי בַּר נָשׁ לְמִדְמֵי גַּרְמֵיהּ לְאִינוּן דִּלְעֵילָא אִשְׁתְּלִים בְּהוּ וְלָא מִסְתַּפֵּי מֵהָאי מִדַּת דִינָא עִלָּאָה.","וְיֵּרְדוּ בִּדְגַת הַיָּם לְקֳבֵל דַּרְגָא דְנֶצָ\"ח דְאֲחִיד בֵּיהּ מֹשֶׁה דְגָּת הַיָּם בְּהַהוּא דַּרְגָא אִתְבְּרִיאוּ וְיָהִיב לוֹן סְתִימָא דִּסְתִימִין חֵילָא לְמִשְׁלַט עָלַיְיהוּ, אִי דָמֵי בָּר נָשׁ לְעִלָּאִין, וְאִי לָא דָמֵי לְעִלָּאִין יֵרְדוּ. וְנוּנִי יַמָּא שַׁלְטִין בְּהוּ בִּבְנֵי נָשָׁא. וּבְגִין כָּךְ אַזְהִירָת לוֹן אוֹרַיְיתָא דְאִתְיְיהִיבַת עַל יְדֵי דְמֹשֶׁה (דברים ל׳:י״ט) וּבָחַרְתָּ בַּחַיִּים.","תָּא חֲזֵי מֹשֶׁה כַּד אִתְרַמֵי לְיַמָּא לֹא שָׁלְטוּ עָלֵיהּ נוּנֵי יַמָּא וְלֹא אִסְתָפֵי מִנַּיְיהוּ בְּגִין דְּאִיהוּ הֲוָה זַמִּין לִקְרָבָא לְעֵילָא וּלְאִתְדַּבְּקָא בְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְבָתָר כַּד אִתְדַבַּק שָׁלִיט עַל נוּנֵי יַמָּא. וְרָמַז לְאַהֲרֹן אֲחוּי דְּיִמְחֵי יָת יַמָּא וִימוּתוּן נוּנִי וְאִיהוּ לָא עֲבִיד הֲכִי, בְּגִין דְהַהִיא דַּרְגָא דִילֵיהּ שָׁלִיט עָלַיְיהוּ וּבֵיהּ אִתְבְּרִיאוּ וְלא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִמְחֵי אִיהוּ, בְּגִין לְאִתְהַפְּכָא לְהוּ לְאוֹיֵב. וְכַד בַּר נָשׁ אֲזִיל בְּאָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא כְּתִיב עָלֵיהּ (ישעיהו מ״ג:ב׳) כִּי תַעֲבוֹר בַּמַיִם אִיתְךְ אֲנִי וְגוֹ'. דְּהָא וְיֵּרְדוּ בִּדְגַת הַיָּם","וּבְעוֹף הַשָׁמַיִם לְקֳבֵל דַּרְגָא דְּשָׁמַיִם. דְּבְהַהוּא דַּרְגָא שָׁלִיט עָלַיְיהוּ וְדָא תִפְאֶרֶ\"ת. וְאַף עַל גַּב דִּבְדַרְגָּא דְנֶצָ\"ח אִתְעֲבִידוּ כָּל נוּנִי יַמָּא וְעוֹפֵי, לָא כְּתִיב תַמָּן אֶלָּא עוֹף כַּנַף אֲבָל הַשְׁתָּא קָרֵי לְהוּ עוֹף הַשָׁמַיִם בְּגִין דְּבַּר נָשׁ לָא שָׁלִיט עָלַיְיהוּ אֶלָּא מִסִּטְרָא דְּשָׁמַיִם.","וּבַבְּהֵמָה שָׁלִיט עָלַיְיהוּ בְּרָזָא דְהוֹ\"ד דְּיָהִיב לֵיהּ סִיוּעָא דְּהָא בְּהַהוּא יוֹמָא אִתְבְּרִיאוּ בְּעִירָן. וּבְכָל הָאָרֶץ שָׁלִיט בְּרָזָא דְצָדִי\"ק דְּאִקְרֵי כָּ\"ל וְאִיהוּ שָׁלִיט עַל הָאָרֶץ אַרְעָא עִלָּאָה. הָכִי נָמֵי בַּר נָשׁ לְתַתָּא שָׁלִיט עַל אַרְעָא תַּתָּאָה בְּגִין דְכוֹלָא בֵּיהּ. וּבְכָל הָרֹמֵשֹׁ הַרוֹמֵשׂ עַל הָאָרֶץ שָׁלִיט עָלַיְיהוּ בָּר נָשׁ מִסִיוּעָא דְאִתְיְיהִיב לֵיהּ מֵאֶרֶץ הַחַיִּים מַלְכוּת עִלָּאָה:"],[],[[0,"","וּבֹא רְאֵה, עַד שֶׁלֹּא הִשְׁתַּלְּמוּ אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁל יָמִים עֶלְיוֹנִים, לֹא הִשְׁתַּלֵּם אָדָם לְמַעְלָה. כֵּיוָן שֶׁהִשְׁתַּלֵּם לְמַעְלָה אָדָם הָעֶלְיוֹן, הִשְׁתַּלֵּם לְמַטָּה אָדָם הַתַּחְתּוֹן וְכָל הָעוֹלָמוֹת בִּשְׁלֵמוּת. לָכֵן הִשְׁלִיט אֶת הָאָדָם הַתַּחְתּוֹן עַל כָּל מַה שֶּׁנִּבְרָא בָּעוֹלָם, בִּגְלַל שֶׁאָדָם הָעֶלְיוֹן שׁוֹלֵט עַל הַכֹּל. וְלָכֵן רָמַז בְּפָסוּק זֶה שֶׁבַע דְּרָגוֹת, שֶׁיֵּשׁ בּוֹ שֶׁבַע דְּרָגוֹת עֶלְיוֹנוֹת שֶׁנִּקְרָא בָהֶם אָדָם שֶׁלְּמַעְלָה וְהִשְׁתַּלֵּם בָּהֶם. בִּגְלַל כָּךְ, נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ, לָתֵת לוֹ שֶׁפַע מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא חֶסֶד."],[1,"","בֹּא רְאֵה, מִי שֶׁצֶּלֶם זֶה עָלָיו, חֶסֶד אֵל לֹא זָז מִמֶּנּוּ וְיוֹשֵׁב עַל רֹאשׁוֹ, וּמִתְחַבֶּרֶת בּוֹ שְׁכִינָה בְּסוֹף יָמָיו, בִּגְלַל שֶׁחֶסֶד זֶה הוּא יוֹם רִאשׁוֹן, וְהוּא רֹאשׁ שֶׁל כָּל הַיָּמִים שֶׁלְּמַעְלָה. וְצֶלֶם זֶה שֶׁבָּא לוֹ מִמֶּנּוּ לֹא מִסְתַּלֵּק, עַד שֶׁנִּשְׁלָמִים יָמָיו בְּאוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת אַחֲרִית הַיָּמִים. וְהִיא הַדַּרְגָּה שֶׁל צֶדֶ\"ק, וְהִיא שְׁבִיעִית, שְׁנַת הַשְּׁמִטָּה. וּבְאוֹתָהּ דַּרְגָּה נִשְׁלָמִים יְמֵי הָאָדָם, כְּשֶׁנִּשְׁלְמוּ שִׁבְעִים שָׁנָה כְּנֶגֶד שֶׁבַע דְּרָגוֹת, עֶשֶׂר לְכָל דַּרְגָּה. זֶהוּ שֶׁכָּתוּב (תהלים צ) יְמֵי שְׁנוֹתֵינוּ בָהֶם שִׁבְעִים שָׁנָה. מַה זֶּה בָּהֶם בְּאוֹתָם יָמִים וְשָׁנִים שֶׁלְּמַעְלָה,"],[2,"","וְאִם בִּגְבוּרֹת שְׁמוֹנִים. בֹּא רְאֵה, בָּנִים חַיִּים וּמְזוֹנוֹת לֹא בִזְכוּת תְּלוּיִים הַדְּבָרִים, הַסּוֹד שֶׁל אוֹתָן שֶׁבַע דְּרָגוֹת שֶׁבָּהֶן זְכוּת וְחוֹבָה בְּסוֹד חֶסֶד וּגְבוּרָה, שֶׁאִם כָּךְ לֹא הָיָה לוֹ לָאָדָם לִהְיוֹת חַי פְּרָט לְשִׁבְעִים, אֶלָּא שֶׁבַּמַּזָּל הָעֶלְיוֹן הָעַתִּיק שֶׁל הַכֹּל תְּלוּיִים, בִּגְלַל כָּךְ הוּא מוֹסִיף עַל כָּל יְמֵי הָאָדָם כִּרְצוֹנוֹ."],[3,"","וּבֹא רְאֵה, כָּךְ לָמַדְנוּ בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁבַּלַּיְלָה הָאַחֲרוֹן שֶׁל חַג, אִם יִסְתַּכֵּל אָדָם בְּצַלְמוֹ וְיִרְאֶה אוֹתוֹ שָׁלֵם, לֹא נִגְזְרָה עָלָיו מִיתָה. וּמָה הַטַּעַם בַּלַּיְלָה הַזֶּה בִּגְלַל שֶׁשִּׁבְעַת יְמֵי הֶחָג כְּנֶגֶד שִׁבְעָה יָמִים עֶלְיוֹנִים הֵם, שֶׁכָּל הַיָּמִים וְהַשָּׁנִים שֶׁל הָעוֹלָם תְּלוּיִים בָּהֶם, וְהֵם רְמוּזִים בַּכָּתוּב שֶׁל (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְגוֹמֵר. רֵאשִׁיתָם חֶסֶד וְסִיּוּמָם מַמְלָכָה. כְּנֶסֶת יִשְׂרָאֵל. אַחֲרִית הַיָּמִים שֶׁנִּמְצֵאת שְׁבִיעִית אַחֲרִית. וּכְשֶׁבָּא לֵיל הַשְּׁבִיעִי הַזֶּה, נִרְאֶה אִם הִשְׁתַּלְּמוּ הַיָּמִים בָּאַחֲרִית הַ את. וְאִם הַצֶּלֶם הָעֶלְיוֹן הַזֶּה נִרְאֶה עָלָיו, אָז חֶסֶד אֵל כָּל הַיּוֹם יַחֲזֹר עָלָיו כְּבַתְּחִלָּה, וְלֹא פוֹחֵד מֵהַדִּין הַזֶּה שֶׁל צֶדֶק, וְהִיא עִמּוֹ בִּשְׁלֵמוּת בְּחֶדְוָה וּמַחֲזִירָה לוֹ פָּנִים."],[4,"","וְלָכֵן הִזְהִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לְהִנָּצֵל מִדִּינֵי הַצֶּדֶק הַזּוֹ, וּלְכַסּוֹת סֻכַּת שָׁלוֹם עֲלֵיהֶם, וְלָשֶׁבֶת בְּצֵל הָאֱמוּנָה. זֶהוּ שֶׁכָּתוּב (ויקרא כג) בַּסֻּכֹּת תֵּשְׁבוּ שִׁבְעַת יָמִים, לְהַכְלִיל אֶת הַדַּרְגָּה הַזּוֹ לְמַעְלָה וּלְהוֹסִיף בָּהּ בְּרָכָה מִמַּיִם הָעֶלְיוֹנִים, בִּגְלַל שֶׁיּוֹם זֶה הוּא שְׁבִיעִי הוּא כְּנֶסֶת יִשְׂרָאֵל. אָנוּ מַקִּיפִים אֶת הַמִּזְבֵּחַ הַזֶּה הָעֶלְיוֹן בְּאוֹתָם שְׁנֵי לִמּוּדִים שֶׁהֵם עַרְבֵי נַחַל, וְעוֹשִׂים בָּהּ נִסּוּךְ הַמַּיִם, וְנוֹתֵן צַדִּיק בְּאוֹתָם שִׁתִּין שֶׁהֵם מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, הַכֹּל בְּסוֹד הַחָכְמָה."],[5,"","וּלְאַחַר מִכֵּן (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, תַּעֲשׂוּ כִנּוּס לְאוֹתָם שִׁבְעָה יָמִים עֶלְיוֹנִים, וַעֲשׂוּ יוֹם טוֹב בִּגְלַל שֶׁנִּצָּלְתֶם מִדִּינוֹ שֶׁל אוֹתוֹ יוֹם שְׁבִיעִי. בִּגְלַל כָּךְ כָּתוּב בְּצַלְמֵנוּ"],[6,"","כִּדְמוּתֵנוּ, כְּנֶגֶד יוֹם שֵׁנִי גְּבוּרָה, חֶלְקוֹ שֶׁל יִצְחָק, וְאָז יֵשׁ לָאָדָם לָשִׂים אֶת 'דְּמוּתֵנוּ' הַזֹּאת וּלְהִדָּמוֹת בְּמַעֲשָׂיו לְאוֹתָם הָעֶלְיוֹנִים. וְכָל זֶה לָמָּה בִּגְלַל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן בִּידֵי הָאִישׁ, אִם רוֹצֶה הָאִישׁ לְדַמּוֹת עַצְמוֹ לְאוֹתָם שֶׁלְּמַעְלָה, מִשְׁתַּלֵּם בָּהֶם, וְלֹא פוֹחֵד מִמִּדַּת הַדִּין הָעֶלְיוֹנָה."],[7,"","וְיִרְדּוּ בִדְגַת הַיָּם - כְּנֶגֶד הַדַּרְגָּה שֶׁל נֵצַח שֶׁאָחוּז בָּהּ מֹשֶׁה, שֶׁדְּגַת הַיָּם נִבְרְאוּ בְּאוֹתָהּ דַּרְגָּה (ספירה), וְנָתַן לָהֶם נִסְתַּר הַנִּסְתָּרִים כֹּחַ לִשְׁלֹט עֲלֵיהֶם אִם דּוֹמֶה אָדָם לָעֶלְיוֹנִים, וְאִם לֹא דוֹמֶה לָעֶלְיוֹנִים - יִרְדּוּ, וּדְגֵי הַיָּם שׁוֹלְטִים בָּהֶם בִּבְנֵי אָדָם, וְלָכֵן הִזְהִירָה אוֹתָם הַתּוֹרָה שֶׁנִּתְּנָה עַל יְדֵי מֹשֶׁה, (דברים ל) וּבָחַרְתָּ בַּחַיִּים."],[8,"","בֹּא רְאֵה, מֹשֶׁה, כְּשֶׁנִּזְרַק לַיָּם, לֹא שָׁלְטוּ עָלָיו דְּגֵי הַיָּם וְלֹא פָחַד מֵהֶם, בִּגְלַל שֶׁהוּא הָיָה עָתִיד לְהִתְקָרֵב לְמַעְלָה וְלִדְבֹּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלְאַחַר שֶׁנִּדְבַּק, שָׁלַט עַל דְּגֵי הַיָּם, וְרָמַז לְאַהֲרֹן אָחִיו שֶׁיַּכֶּה אֶת הַיָּם וְיָמוּתוּ הַדָּגִים, וְהוּא לֹא עָשָׂה כָּךְ, בִּגְלַל שֶׁאוֹתָהּ דַּרְגָּה שֶׁלּוֹ שׁוֹלֶטֶת עֲלֵיהֶם וּבָהּ נִבְרְאוּ, וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּכֶּה הוּא בִּשְׁבִיל לְהִתְהַפֵּךְ לָהֶם לְאוֹיֵב. וּכְשֶׁאָדָם הוֹלֵךְ בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, כָּתוּב עָלָיו (ישעיה מג) כִּי תַעֲבֹר בַּמַּיִם אִתְּךְ אָנִי וְגוֹמֵר. שֶׁזֶּה וְיִרְדּוּ בִדְגַת הַיָּם"],[9,"","וּבְעוֹף הַשָּׁמַיִם. כְּנֶגֶד דַּרְגָּה שֶׁל שָׁמַיִם, שֶׁבְּאוֹתָהּ דַּרְגָּה שׁוֹלֵט עֲלֵיהֶם, וְזוֹ תִפְאֶרֶת. וְאַף עַל גַּב שֶׁבְּדַרְגַּת הַנֶּצַח נַעֲשׂוּ כָּל דְּגֵי הַיָּם וְהָעוֹפוֹת, לֹא כָתוּב שָׁם אֶלָּא עוֹף כָּנָף, אֲבָל עַכְשָׁו קָרָא לָהֶם עוֹף הַשָּׁמַיִם, בִּגְלַל שֶׁבֶּן אָדָם לֹא שׁוֹלֵט עֲלֵיהֶם אֶלָּא מִצַּד שֶׁל שָׁמַיִם."],[10,"","וּבַבְּהֵמָה - שׁוֹלֵט עֲלֵיהֶם בְּסוֹד שֶׁל הוֹד שֶׁנּוֹתֵן לוֹ סִיּוּעַ, שֶׁהֲרֵי בְּאוֹתוֹ יוֹם נִבְרְאוּ הַבְּהֵמוֹת. וּבְכָל הָאָרֶץ - שׁוֹלֵט בְּסוֹד שֶׁל צַדִּיק שֶׁנִּקְרָא כֹּל, וְהוּא שׁוֹלֵט עַל הָאָרֶץ, אֶרֶץ הָעֶלְיוֹנָה. כָּךְ גַּם אָדָם לְמַטָּה שׁוֹלֵט עַל אֶרֶץ הַתַּחְתּוֹנָה, מִשּׁוּם שֶׁהַכֹּל בּוֹ. וּבְכָל הָרֶמֶשׂ הָרֹמֵשׂ עַל הָאָרֶץ - שׁוֹלֵט עֲלֵיהֶם אָדָם מִסִּיּוּעַ שֶׁנִּתָּן לוֹ מֵאֶרֶץ הַחַיִּים, הַמַּלְכוּת הָעֶלְיוֹנָה: (ע\"כ מההשמטות)"]]],[["וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זוֹרֵעַ זֶרַע לְקֳבֵל דַּרְגָא דְבִּינָ\"ה דְּאִקְרֵי אֱלֹהִים דְּכֵיוָן דְּאִימָא עִלָּאָה חָמָאת לוֹן שְׁלֵמִין יָהִיב לוֹן תָּפְנוּקִין מִלְּעֵילָא לְאִתְקַיְימָא בְּעַלְמָא.","תָּא חֲזֵי, אָדָם קַדְמָאָה קוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ כָּל עֵשֶׂב זוֹרֵעַ זֶרַע וְלָא יָהַב לֵיהּ רֵשׁוּ לְמֵיכָל בְּעִירֵי וְעוֹפֵי שְׁמַיָא, בְּגִין דְגַלֵּי קַמֵּיהּ דְהוּא זַמִּין לְאִתְפַּתָאַה בְּהַהוּא נָחָשׁ דְּאִיהוּ עֲרוּם מִכָּל חַיַּת הַשָּׂדֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֲרְחֵקִינֶיהּ מִנֵּיהּ וְלָא יְהֵא לֵיהּ עֵסֶק בֵּיהּ וְלָא בִּבְעִירֵי וְלָא בְּעוֹפֵי בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא אָרִים לֵיהּ לְבַּר נָשׁ מִכְשׁוֹל מִקָמֵיהּ, מְאִים יִתְקַיַּים בְּעַלְמָא.","אֲבָל כַּד אֲתָא נֹחַ דְּאִקְרֵי צַדִּיק מָה כְּתִיב בֵּיהּ (בראשית ח׳:כ׳) וַיִּבֶן נֹחַ מִזְבֵּחַ לַיְיָ וְהָא אוּקִימְנָא הַהוּא מִזְבֵּחַ דְאַקְרִיב בֵּיהּ אָדָם הָרִאשׁוֹן. ומַאי טַעְמָא וַיִּבֶן בְּגִין דְחַיָיבֵי עַלְמָא עַבְדֵי בָּהּ פְּגִימוּ. אֲתָא נֹחַ וְקָרִיב הַהוּא מִזְבֵּחַ בְּבַעְלָהּ הֲדָא הוּא דִכְתִיב וַיָּעַל עֹלֹת בַּמִזְבֵּחַ חָסֵר,","כַּד חָמָא קוּדְשָׁא בְּרִיךְ הוּא דְאִתְקְרִיב הַהוּא מִזְבֵּחַ וְקָרִיב הַנְהוּ בְּעִירֵי דַכְיֵי יָהַב לֵיהּ רֵשׁוּ לְמֵיכָל כֻּלְּהוּ בְּעִירֵי. מַאי טַעְמָא, בְּגִין דְאַתְקִיף בְּהַהוּא בְּרִית עֵץ הַחַיִּים, וְקָרִיב לֵיהּ בְּעֵץ הַדַּעַת וְעָבַד יִחוּדָא בְּקַדְמִיתָא אֶלָּא דִּלְבָתַר אִתְפָּתָא דְּבָעָא לְמִבְדַּק בְּהַהוּא חוֹבָה וְלָא לְאִתְדַבַּק בֵּיהּ וַאֲפִילּוּ הֲכִי לָא אִשְׁתֵּזִיב מִנֵּיהּ וְנָצִיב הַהוּא כַּרְמָא.","תָּא חֲזֵי, אָדָם דְּזַמִּין לְאִתְפַּתָאַה בְּאִילָנֵי לָא יָהַב לֵיהּ אִילָנֵי וְאַרְחֶקִינְהוּ מִנֵּיהּ דְּהָא לָא אִדְכָּר לוֹן אֶלָּא דְּאִיהוּ עָבַד גַּרְמֵיהּ חוֹל וְנָצִיב הַהוּא כַּרְמָא דְּאִקְרֵי בֵּית יִשְׂרָאֵל. בְּקַדְמִיתָא אִשְׁתְּלִים בֵּיהּ וְחַפְיָא עָלֵיהּ (ואשתזיב) אִשְׁתֵּזִיב בָּהּ. וּמַאן אִיהִי בֵּית יִשְׂרָאֵל דָא תֵּיבָה דְּאִקְרֵי אֲרוֹן הַבְּרִית.","וְהַשְׁתָּא כַּד בָּעָא לְמִבְדַּק, מָה כְּתִיב (בראשית ט׳:כ״א) וַיֵּשְׁתְ מִן הַיָּיִן, כְּמָה דְאַתְּ אָמֵר, וַתִּקַּח מִפִּרְיוֹ. לְבָתָר וַיִתְגָּל בְּתוֹךְ אֲהֹלֹה. גָלֵי הַהוּא פִּרְצָה בְּקַדְמִיתָא בְּגוֹ מַשְׁכְּנֵיהּ בְּגוֹ לְגוֹ. וְאִי לָאו הַהוּא מַדְבְּחָא דְאַגִינָת עָלֵיהּ מִשׁוּם דְאִתְדַבָּק בָּהּ בְּקַדְמִיתָא הֲוָה נִתְפָּס מִיָד. וְעִם כָּל דָּא כַּד לָא עֲבַד לֵיהּ אֶלָּא לְמִבְדַּק, כָּסֵי עָלֵיהּ אוֹרַיְיתָא וְלָא פַרְסְמֵיה כְּמָה דְפִרְסֵם לְאָדָם. וְהַהוּא מַדְבְּחָא הוּא כַּפָּרָה עָלֵיהּ.","תָּא חֲזֵי, מִזְבַּח שֶׁל בֵּית עוֹלָמִים הוּא תְּלָתִין וּתְרֵין עַל תְּלָתִין וּתְרֵין אָמָה (והיא) הִיא רְמִיזָא בִּתְרֵין וּתְלָתִין נְתִיבוֹת פְּלִיאוֹת חָכְמָה. דְּהָא חָכְמָה תַּתָּאָה אִקְרֵי,","עָלָהּ אָמָה וְכָּנָס אָמָה, זְהוּ יְסוֹ\"ד לְקֳבֵל (צדיק) צֶדֶ\"ק דִּלְעֵילָא דְּהָא כְּגווָֹנָא דְּכוּלְהוּ דַּרְגִּין אִית בָּהּ וְכֻלְּהוּ אִתְחַזְיָין בָּהּ דְּהָא מַרְאָה אִקְרֵי. עֲלָהּ חֲמֵשׁ וְכָּנָס אָמָה, זְהוּ סוֹבֵב לְקֳבֵל הַהוּא דַּרְגָא דְאִתְדַבָּק בָּהּ דְּאִיהוּ סוֹבֵב לְהַהוּא מִזְבֵּחַ הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְּחַבְּקֵנִי דְּהָא מִיְסוֹ\"ד עַד הַהוּא דַּרְגָא חֲמִשָׁה דַּרְגִּין אִינוּן.","עָלָהּ שָׁלשׁ וְכָּנָס אָמָה, אֵלּוּ קְרָנוֹת לְקֳבֵל אִינוּן תְלָתָא דַּרְגִּין דְאַתְיָין לָה מִנַּיְיהוּ תְּקִיפוּ עִלָּאָה וְשֶׁפַע. וּבְגִין כָּךְ דָוִד שְׁנִמְשָׁח בְּקֶרֶן נִמְשְׁכָה מַלְכוּתוֹ בְּגִין דְּאִיהוּ בְּאִינוּן קְרָנוֹת הַמִּזְבֵּחַ תְּקִיפוּ דְמַדְבְּחָא עִלָּאָה.","תָּא חֲזֵי, אַרְבַּע קְרָנוֹת, אָמָה עַל אָמָה אִית בֵּיהּ בַּמִזְבֵּחַ, בְּגִין דְּאִיהוּ כִּסֵּא דָוִד יוֹם רְבִיעָאִי לָתֵת לָה שֶׁפַע מֵאִינוּן שְׁלֹשׁ אַמּוֹת לְאִינוּן אַרְבַּע קְרָנוֹת.","וְכַד הֲווּ מַקְרִיבִין כְּהָנֵי מִסִּטְרָא דְחֶסֶ\"ד עֹלַת הַתָּמִיד לְגַבֵּי מִזְבֵּחַ הֲווּ מַקְרִיבִין לֵיהּ הַהוּא אַתְרָא דְּאִקְרֵי מִזְבֵּחַ. וְכַד הֲווּ עַבְדִין מָתָנוֹת מִדָּמָא דְעוֹלָה הֲווּ סָלְקִין וַהֲווּ אַזְלִין בְּהַהוּא סוֹבֵב דְּאִיהוּ דַּרְגָא דִידְהוּ וְחוּלָקֵיהּ דַאֲבוּהוֹן דְיַהֲבִין שְׁתֵּי מָתָנוֹת שְׁהֵן אַרְבַּע לְקֳבֵל הַהוּא אַתְרָא דְּאִקְרֵי עוֹלָה.","וְלָקֳבֵל שְׁתֵּי מָתָּנוֹת דְּהַהוּא בוּכְרָא דְנָטִיל תְּרֵין חוּלָקִין הֲדָא הוּא דִכְתִיב (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם יוֹשֵׁב אֹהָלִים רַחֲמֵי וְדִינָא וְנָסִיב הַהוּא צַדִּיק תְּרֵין חוּלָקִין דִּידֵיהּ הֲדָא הוּא דִכְתִיב (דברי הימים א ה׳:א׳) נִתָּנָה בְּכֹרָתוֹ לְיוֹסֵף וּתְרֵין חוּלָקִין דְאָבוֹי וְנָסִיב כֹּלָּא הַאי כָּ\"ל וְאַמְלֵי לְהַהוּא אַתְרָא דְאִקְּרֵי יַם. הֲדָא הוּא דִכְתִיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. הַאי מִזְבַּח הָעוֹלָה הֲוָה גַּבֵּיהּ,","הַא (האי) ט' אַמּוֹת לְקֳבֵל ט' דַּרְגִּין דְאִיכָּא עַד צַדִּיק תְשִׁיעָאָה דְכוֹלָא טוֹ\"ב וַדַּאי. וְאִיהוּ כְבִּנְיַן אוֹצָר רְחַבָה מִלְמַטָּה וּקְצָרָה מִלְמַעְלָה הֲדָא הוּא דִכְתִיב וַיִּבֶן יְיָ אֱלהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הַאָדָם לְאִשָׁה. וְהַאי מִזְבֵּחַ עִלָּאָה הִיא אִשְׁתּוֹ דְּאָדָם דִּלְעֵילָא וּבְגִין כָּךְ אִקְרֵי מִזְבֵּחַ עוֹלָה כְּמָה דְאַתְּ אָמֵר (יהושע ג׳:ו׳) אֲרוֹן הַבְּרִית וְדָא כְּנֶסֶת יִשְׂרָאֵל וְאִקְרֵי מִזְבֵּחַ","מַאי טַעְמָא אִקְרֵי הֲכִי בְּגִין דְּכַד בְּנֵי עַלְמָא לָא מַכְשְׁרָן עוֹבַדָיְיהוּ אִיהִי דַבְחָא לוֹן הֲדָא הוּא דִכְתִיב (ויקרא כ״ו:כ״ח) וְהִכְּתִי אֶתְכֶם אַף אֲנִי. דְּהָא כָּל מָאנֵי קְרָבָא דְמַלְכָּא בִּידֵיהּ אִתְמְסָרוּ הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָה. וּבְגִין כָּךְ אוֹרַיְיתָא שְׁלֵימָתָא קוּדְשָׁא בְּרִיךְ הוּא יַהֲבָה לוֹן לְיִשְׂרָאֵל לְמִזְכֵּי בָּהּ לְחַיֵּי עַלְמָא לְאִשְׁתֵּזָבָא מִדִינוֹי דְּהַהוּא מִזְבֵּחַ. מָה דְּלֵית רֵשׁוּ לְגַבְרָא אַחֲרָא לְקָרְבָא לְגַבָּהּ.","וְכִי תֵימָא הָא חֲמֵינָא מֹשֶׁה קָרִיב לְגַבָּהּ שִׁבְעָה יוֹמִין בְּקַדְמִיתָא, תָּא חֲזֵי כְּתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. הַאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְּמָר כַּד אִיהִי שַׁרְיָיא בְּאַרְעָא בְּכָל אִינוּן שִׁבְעָה יוֹמִין כֻּלְּהוּ בִשְׁלִימוּ הֲדָא הוּא דִכְתִיב (ויקרא ח׳:ל״ג) שִׁבְעַת יָמִים יְמָּלֵא אֶת יֵדְּכֶם וּבְגִין כָּךְ אִקְרוּן שִׁבְעַת יְמֵי הַמִלוּאִים דַּיְיקָא."],[],[[0,"","וַיֹּאמֶר אֱלֹהִים הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זרֵעַ זֶרַע - כְּנֶגֶד הַדַּרְגָּה שֶׁל בִּינָה שֶׁנִּקְרֵאת אֱלֹהִים. שֶׁכֵּיוָן שֶׁהָאֵם הָעֶלְיוֹנָה רָאֲתָה אוֹתָם שְׁלֵמִים, נָתְנָה לָהֶם תַּפְנוּקִים מִלְמַעְלָה לְהִתְקַיֵּם בָּעוֹלָם."],[1,"","בֹּא רְאֵה, לְאָדָם הָרִאשׁוֹן נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל עֵשֶׂב זֹרֵעַ זֶרַע, וְלֹא נָתַן לוֹ רְשׁוּת לֶאֱכֹל בְּהֵמוֹת וְעוֹפוֹת הַשָּׁמַיִם, מִשּׁוּם שֶׁגָּלוּי לְפָנָיו שֶׁהָיָה עָתִיד לְהִתְפַּתּוֹת בְּאוֹתוֹ נָחָשׁ שֶׁהוּא (בראשית ג) עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַרְחִיק אוֹתוֹ מִמֶּנּוּ, וְלֹא יִהְיֶה לוֹ עֵסֶק עִמּוֹ וְלֹא עִם הַבְּהֵמוֹת וְלֹא עִם הָעוֹפוֹת, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֵרִים לָאָדָם מִכְשׁוֹל מִלְּפָנָיו אוּלַי יִתְקַיֵּם בָּעוֹלָם."],[2,"","אֲבָל כְּשֶׁבָּא נֹחַ, שֶׁנִּקְרָא צַדִּיק, מַה כָּתוּב בּוֹ? (בראשית ח) וַיִּבֶן נֹחַ מִזְבֵּחַ לַה'. הֲרֵי פֵּרַשְׁנוּ אוֹתוֹ הַמִּזְבֵּחַ שֶׁבּוֹ הִקְרִיב אָדָם הָרִאשׁוֹן. וּמָה הַטַּעַם וַיִּבֶן? מִשּׁוּם שֶׁרִשְׁעֵי הָעוֹלָם עָשׂוּ בָהּ פְּגָם, בָּא נֹחַ וְהִקְרִיב אוֹתוֹ מִזְבֵּחַ לְבַעְלָהּ. זֶהוּ שֶׁכָּתוּב וַיַּעַל עֹלֹת בַּמִּזְבֵּחַ, חָסֵר."],[3,"","כְּשֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּקְרַב אוֹתוֹ מִזְבֵּחַ וְהִקְרִיב אוֹתָם בְּהֵמוֹת טְהוֹרוֹת, נָתַן לוֹ רְשׁוּת לֶאֱכֹל כָּל הַבְּהֵמוֹת, מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא הֶחֱזִיק בְּאוֹתוֹ בְּרִית עֵץ הַחַיִּים וְקֵרַב אוֹתוֹ לְעֵץ הַדַּעַת, וְעָשָׂה יִחוּד כְּבָרִאשׁוֹנָה, אֶלָּא שֶׁאַחַר כָּךְ הִתְפַּתָּה שֶׁרָצָה לִבְדֹּק אֶת אוֹתוֹ הַחֵטְא וְלֹא לִדְבֹּק בּוֹ, אֲפִלּוּ כָּךְ לֹא נִצַּל מִמֶּנּוּ וְהִצִּיב אוֹתוֹ כֶּרֶם. ס"],[4,"","תָּא חֲזֵי, אָדָם דְּזַמִּין לְאִתְפַּתָאַה בְּאִילָנֵי לָא יָהַב לֵיהּ אִילָנֵי וְאַרְחֶקִינְהוּ מִנֵּיהּ דְּהָא לָא אִדְכָּר לוֹן אֶלָּא דְּאִיהוּ עָבַד גַּרְמֵיהּ חוֹל וְנָצִיב הַהוּא כַּרְמָא דְּאִקְרֵי בֵּית יִשְׂרָאֵל. בְּקַדְמִיתָא אִשְׁתְּלִים בֵּיהּ וְחַפְיָא עָלֵיהּ (ואשתזיב) אִשְׁתֵּזִיב בָּהּ. וּמַאן אִיהִי בֵּית יִשְׂרָאֵל דָא תֵּיבָה דְּאִקְרֵי אֲרוֹן הַבְּרִית."],[5,"","וְהַשְׁתָּא כַּד בָּעָא לְמִבְדַּק, מָה כְּתִיב (בראשית ט) וַיֵּשְׁתְ מִן הַיָּיִן, כְּמָה דְאַתְּ אָמֵר, וַתִּקַּח מִפִּרְיוֹ. לְבָתָר וַיִתְגָּל בְּתוֹךְ אֲהֹלֹה. גָלֵי הַהוּא פִּרְצָה בְּקַדְמִיתָא בְּגוֹ מַשְׁכְּנֵיהּ בְּגוֹ לְגוֹ. וְאִי לָאו הַהוּא מַדְבְּחָא דְאַגִינָת עָלֵיהּ מִשׁוּם דְאִתְדַבָּק בָּהּ בְּקַדְמִיתָא הֲוָה נִתְפָּס מִיָד. וְעִם כָּל דָּא כַּד לָא עֲבַד לֵיהּ אֶלָּא לְמִבְדַּק, כָּסֵי עָלֵיהּ אוֹרַיְיתָא וְלָא פַרְסְמֵיה כְּמָה דְפִרְסֵם לְאָדָם. וְהַהוּא מַדְבְּחָא הוּא כַּפָּרָה עָלֵיהּ."],[6,"","בֹּא רְאֵה, מִזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הָיָה שְׁלֹשִׁים וּשְׁתַּיִם עַל שְׁלֹשִׁים וּשְׁתַּיִם אַמָּה, וְהִיא רְמוּזָה בִּשְׁלֹשִׁים וּשְׁנַיִם נְתִיבוֹת פְּלִיאוֹת חָכְמָה, שֶׁהֲרֵי חָכְמָה תַחְתּוֹנָה נִקְרֵאת. עָלָה אַמָּה נִכְנַס אַמָּה - זֶהוּ יְסוֹד, כְּנֶגֶד (צדיק) צֶדֶק שֶׁלְּמַעְלָה, שֶׁהֲרֵי כְּמוֹ שֶׁיֵּשׁ בָּהּ אֶת כָּל הַדְּרָגוֹת וְכֻלָּם נִרְאִים בָּהּ, שֶׁהֲרֵי נִקְרֵאת מַרְאָה."],[7,"","עָלָה חָמֵשׁ וְכָנַס אַמָּה - זֶהוּ סוֹבֵב, כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁנִּדְבָּק בָּהּ, שֶׁהִיא סוֹבֶבֶת אֶת אוֹתוֹ הַמִּזְבֵּחַ. זֶהוּ שֶׁכָּתוּב (שיר ב) וִימִינוֹ תְּחַבְּקֵנִי, שֶׁהֲרֵי מִיסוֹד עַד אוֹתָהּ דַּרְגָּה חָמֵשׁ דְּרָגוֹת הֵן."],[8,"","עָלָה שָׁלֹשׁ וְכָנַס אַמָּה - אֵלּוּ קְרָנוֹת, כְּנֶגֶד אוֹתָן שָׁלֹשׁ דְּרָגוֹת שֶׁרָאוּ לָהּ מֵהֶם הַתֹּקֶף הָעֶלְיוֹן וְשֶׁפַע, וּמִשּׁוּם כָּךְ דָּוִד שֶׁנִּמְשַׁח בְּקֶרֶן, נִמְשְׁכָה מַלְכוּתוֹ, מִשּׁוּם שֶׁהוּא בְּאוֹתָן קַרְנוֹת הַמִּזְבֵּחַ, תֹּקֶף הַמִּזְבֵּחַ הָעֶלְיוֹן."],[9,"","בֹּא רְאֵה, אַרְבַּע קְרָנוֹת אַמָּה עַל אַמָּה יֵשׁ בַּמִּזְבֵּחַ, מִשּׁוּם שֶׁהִיא כִּסֵּא דָוִד, יוֹם הָרְבִיעִי לָתֵת לָהּ שֶׁפַע מֵאוֹתָן שָׁלֹשׁ אַמּוֹת לְאוֹתָן אַרְבַּע קְרָנוֹת."],[10,"","וּכְשֶׁהָיוּ מַקְרִיבִים הַכֹּהֲנִים מֵהַצַּד שֶׁל חֶסֶד עוֹלַת הַתָּמִיד אֵצֶל הַמִּזְבֵּחַ, הָיוּ מַקְרִיבִים אוֹתוֹ לְאוֹתוֹ הַמָּקוֹם שֶׁנִּקְרָא מִזְבֵּחַ (מלכות). וּכְשֶׁהָיוּ עוֹשִׂים מַתָּנוֹת מִדַּם הָעוֹלָה, הָיוּ עוֹלִים וְהָיוּ הוֹלְכִים בְּאוֹתוֹ הַסּוֹבֵב שֶׁהוּא הַדַּרְגָּה שֶׁלָּהֶם וְחֵלֶק אֲבִיהֶם, וְנוֹתְנִים שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע כְּנֶגֶד אוֹתוֹ מָקוֹם שֶׁנִּקְרָא עוֹלָה."],[11,"","וּכְנֶגֶד שְׁתֵּי מַתָּנוֹת שֶׁל אוֹתוֹ בְּכוֹר שֶׁנּוֹטֵל שְׁנֵי חֲלָקִים. זֶהוּ שֶׁכָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם יֹשֵׁב אֹהָלִים, רַחֲמִים וְדִין, וְלָקַח אוֹתוֹ צַדִּיק שְׁנֵי חֲלָקִים שֶׁלּוֹ. זֶהוּ שֶׁכָּתוּב (דברי הימים א ה) נִתְּנָה בְּכֹרָתוֹ לִבְנֵי יוֹסֵף, וּשְׁנֵי חֲלָקִים שֶׁל אָבִיו, וְלָקְחָה הַכֹּל כֹּל הַזֹּאת, וּמְמַלֵּא אוֹתוֹ מָקוֹם שֶׁנִּקְרָא יָם. זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. זֶה מִזְבַּח הָעוֹלָה הָיָה אֶצְלוֹ."],[12,"","תֵּשַׁע אַמּוֹת הַלָּלוּ כְּנֶגֶד תֵּשַׁע דְּרָגוֹת שֶׁיֵּשׁ עַד הַצַּדִּיק הַתְּשִׁיעִי שֶׁל הַכֹּל, טוֹב וַדַּאי, וְהִיא כְּבִנְיַן אוֹצָר, רְחָבָה מִלְּמַטָּה וּקְצָרָה מִלְמַעְלָה. זֶהוּ שֶׁכָּתוּב (בראשית ב) וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. וְהַמִּזְבֵּחַ הָעֶלְיוֹן הַזֶּה הוּא אִשְׁתּוֹ שֶׁל אָדָם שֶׁלְּמַעְלָה, וְלָכֵן נִקְרָא מִזְבַּח הָעוֹלָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע ג) אֲרוֹן הַבְּרִית, וְזוֹ כְּנֶסֶת יִשְׂרָאֵל, וְנִקְרֵאת מִזְבֵּחַ."],[13,"","מָה הַטַּעַם נִקְרֵאת כָּךְ? מִשּׁוּם שֶׁכַּאֲשֶׁר בְּנֵי הָעוֹלָם אֵין מַעֲשֵׂיהֶם כְּשֵׁרִים, הִיא זוֹבַחַת אוֹתָם. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְהִכֵּיתִי אֶתְכֶם אַף (גם) אֲנִי, שֶׁהֲרֵי כָּל כְּלֵי הַקְּרָב שֶׁל הַמֶּלֶךְ נִמְסְרוּ בְיָדָהּ. זֶהוּ שֶׁכָּתוּב (שיר א) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְיִשְׂרָאֵל תּוֹרָה שְׁלֵמָה לִזְכּוֹת בָּהּ לְחַיֵּי עוֹלָם וּלְהִנָּצֵל מִדִּין אוֹתוֹ הַמִּזְבֵּחַ, מַה שֶּׁאֵין רְשׁוּת לְאִישׁ אַחֵר לִקְרַב אֵלֶיהָ."],[14,"","וְאִם תֹּאמַר, הֲרֵי רָאִינוּ שֶׁמֹּשֶׁה קָרַב אֵלֶיהָ שִׁבְעָה יָמִים בַּהַתְחָלָה - בּא רְאֵה, כָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. הַפָּסוּק הַזֶּה נֶאֱמַר עַל כְּנֶסֶת יִשְׂרָאֵל, כְּשֶׁהִיא שׁוֹרָה בָּאָרֶץ הַקְּדוֹשָׁה בְּכָל אוֹתָם שִׁבְעָה יָמִים כֻּלָּם בִּשְׁלֵמוּת. זֶהוּ שֶׁכָּתוּב (ויקרא ח) שִׁבְעַת יָמִים יְמַלֵּא אֶת יֶדְכֶם, וְלָכֵן נִקְרָאִים שִׁבְעַת יְמֵי הַמִּלּוּאִים דַּוְקָא."]]],[["וּמֹשֶׁה דְּאִיהוּ לֵוִי מִסִּטְרָא דָא קָרִיב בְּקַדְמִיתָא לְגַבֵּי הַאי מִזְבֵּחַ. הֲדָא הוּא דִכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי מַאי רֹאשִׁי אֶלָּא בְּרֵישָׁא כַּד אִתְדַבְּקַת הַאי מִזְבֵּחַ בְּהַהוּא עוֹלָה שְׂמֹאלוֹ אִתְקְרֵי בְּקַדְמִיתָא, וְעִם כָּל דָּא אִתְעָרוּ חַבְרַיָּיא בְּחַלוּק לָבָן שֶׁאֵין בּוֹ אִימְרָא שִׁימֶּשׁ. הֲדָא הוּא דִכְתִיב, (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן אֲשֶׁר עַל הַמָקְלוֹת. בְּגִין דְּאַף עַל גַּב דְּאִיהוּ מִסִּטְרָא דְדִינָא אִתְלַבַּשׁ בְּחֶסֶ\"ד וְקָרִיב לְגַבָּהּ וְאִתְעַר חֶסֶ\"ד עִלָּאָה בְּעַלְמָא.","וּמַאי קָרִיב פָּר בְּרֵישָׁא תָמִיד שֶׁל שָׁחַר עוֹלָה וַדַּאי. וּלְבָתָר קָרִיב פָּר חַטָּאת לְמֵיהַב שְׁלָמָא בֵּין הַהוּא פָּר חַטָּאת וְאַהֲרֹן דְּחָב לְגַבָּהּ כַּד עֲבָד עֶגְלָא (ס\"א עולה) וְדָא כְּנֶסֶת יִשְׂרָאֵל וְהַחֲטָאת לְקֳבְּלָה אִיהוּ. וְדָא פָּר כֹּהֵן מָשִׁיחַ כַּד אִיהוּ חָב לְגַבֵּי מִזְבֵּחַ מָה דְלָא אִית בְּגֶבֶר אַחֲרָא אֶלָּא נוּקְבְתָא לְחַטָּאת וּלְבָתָר קָרִיב עוֹלָה לְגַבָּהּ. כֵּיוָן דְאִתְקְרִיב עוֹלָה לְגַבֵּי הַאי מִזְבֵּחַ כְּדֵין מִלוּאִים הוּא. מִלוּאִים לְעֵילָא מִלוּאִים לְתַתָּא וְכֻלְהוּ עָלְמִין בְּחֶדְוָה, דְּהָא מַטְרוֹנִיתָא אִתְחַבְּרַת בְּבַעְלָהּ וּכְדֵין קָרִיב לְגַבֵּי הַהוּא מִזְבֵּחַ אֵיל הַמִלוּאִים. וְיָהִיב מֵהַהוּא דָּמָא עַל תַנוֹךְ אוּדְנָא דְאֲהַרֹן בְּגִין דְּתְהוֵי רְכִיכָא לְמִשְׁמָע בִּרְכִיכוּ וְלָא בְּקַשְׁיוּ. וִיְקַבֵּל מִלֵּי דְּאוֹרַיְיתָא דְלָא לְאַפְרָדָא תּוֹרָה שֶׁבְּעַל פֶּה מִתּוֹרָה שֶׁבִּכְתָב וּלְאַשְׁלָמָא עָלְמִין כֻּלְּהוּ וְכֵן לִבְנוֹי.","וּפַקִּיד לוֹן דְּיָתְבוּן בְּהַהוּא תַרְעָא דְּהַהוּא אֹהֶל לְמִיטַר הַהוּא אַתְרָא דְלָא יִתְקְרַב עָרֵל וְטָמֵא וְיִשְׁתַּלְּמוּן (כלהו) כֻּלְּהוֹן שִׁבְעָה יוֹמִין עִלָּאִין וְיִסְתָלְקוּן בְּהַהוּא דַּרְגָא דְחֶסֶ\"ד דְּאִיהוּ מִתַּתָּא לְעֵילָא שְׁבִיעָאָה דְּהָא אִינוּן בְּקַדְמִיתָא אִתְדַבְּקוּ בְּהַהוּא פֶּתַח אֹהֶל מוֹעֵד וּלְבָתָר אִסְתַּלְקוּ לְעֵילָא.","וּלְבָתָר מָה כְּתִיב וִימִינוֹ תְּחַבְּקֵנִי הֲדָא הוּא דִכְתִיב (ויקרא ט׳:א׳) וַיְהִי בְּיוֹם הַשְׁמִינִי קָרָא מֹשֶׁה לְאַהֲרֹן וּפַקִּיד לֵיהּ לְמִיסַב הַהוּא עֵגֶל דְּחָב בֵּיהּ וִיקַרְבִינֶיה לְגַבֵּיהּ הַהוּא מִזְבֵּחַ וְאִיהוּ הֲוָה כַּסִיף לְקָרְבָא לְגַבֵּיהּ דְדָחִיל מִשָׁלְהוֹבוֹי. אָמַר לֵיהּ מֹשֶׁה (שם) קְרָב אֶל הַמִּזְבֵּחַ וַעֲשֵׂה אֶת חֲטָאתְךָ בְּקַדְמִיתָא וְהַב מֵהַהוּא דָּמָא בְּאִינוּן קְרָנוֹת בְּגִין דְחָב בְּקַדְמִיתָא לְגַבַּיְיהוּ וּמָנַע מִנְּהוֹן בִּרְכָאָן","וּלְבָתָר (שם) וְאֶת הַדָּם יַצָק אֶל יְסוֹד הַמִּזְבֵּחַ לְאַצְקָא בָּהּ הַהוּא יְסוֹד. מַאי יַצָק כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״ג) וַיַעֲשׂ אֶת הַיָּם מוּצָק. וּלְבָתָר קָרִיב לְהַהוּא מִזְבֵּחַ הַהוּא עוֹלָה וַעֲבַד בְּקַדְמִיתָא רֹאשׁ וּלְבָתָר רֶגֶל. וּלְבָתָר עַל יִשְׂרָאֵל קָרִיב שֵׂעִיר עִזִים דְּהָא מֵהַהוּא סִטְרָא דְיֶצֶר הַרָע אִתְדַבְּקוּ בַּעֲבוֹדָה זָרָה","וּלְבָתָר עֵגֶל וְכֶבֶשׂ לְעוֹלָה. תָּא חֲזֵי בְּקַדְמִיתָא עֵגֶל לְחַטָּאת כֵּיוָן דְקָרִיב לֵיהּ בִשְׁלִימוּ לְגַבֵּיהּ אִמֵּיהּ לְבָתָר קָרִיב לֵיהּ לְגַבֵּי אֲבוֹי. הֲדָא הוּא דִכְתִיב לְעוֹלָה, וּלְבָתָר שׁוֹר וַאֲיִל לִשְׁלָמִים דְּהָא שְׁלָמָא בְכֻלְּהוּ עָלְמִין וְהַאי שׁוֹר דְּסִטְרָא דִשְׂמָאלָא. וְאֵילוֹ דְיִצְחָק לָא עַבְדִין דִּינָא אֶלָּא לִשְׁלָמִים שְׁלָמָא לְעֵילָא שְׁלָמָא לְתַתָּא","וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא פָּתַח עָלַיְיהוּ (תהילים קל״ג:א׳) הִנֵּה מָה טוֹב וּמָה נָעִים שֶׁבֶת אַחִים גַּם יַחַד. שֶׁבֶתשֶׁבֶת אַחִים יְמִינָא וּשְׂמָאלָא מֹשֶׁה וְאַהֲרֹן. גַּם לְאַכְלָלָא לִכְּנְסֶת יִשְׂרָאֵל יַחַד. צַדִּי\"ק כֹּלָּא בְּיִחוּדָא (שלימא) שְׁלֵימָתָא כְּדֵין מָה כְּתִיב כַּשֶׁמֶן הַטּוֹב עַל הָרֹאשׁ יוֹרֵד עַל הַזָּקָן כֵּיוָן דְּאִתְחַבְּרוּ דְכָר וְנוּקְבָא שְׁלִים בְּגִין כָּךְ כַּשֶׁמֶן הַטּוֹב עַל הָרֹאשׁ בְּקַדְמִיתָא עַתִּיקָא דְכוֹלָא רֵישָׁא דְכָל רֵישִׁין. יוֹרֵד עַל הַזָּקָן דָא חֶסֶ\"ד וּגְבוּרָ\"ה וְתִפְאֶרֶת דְּכוּלְהוּ אִקְרוּן זָקֵן. (בראשית כ״ד:א׳) וְאַבְרָהָם זָקֵן. (שם כ\"ז) וַיְהִי כִּי זָקֵן יִצְחָק. (שם מ\"ח) וְעֵינֵי יִשְׂרָאֵל כַּבְדוּ מִזֹקֵן. עַל פִּי מִדוֹתָיו. דָא צַדִּיק וְאִיהִי פִּי מִדוֹתָיו.","וּלְבָתָר כְּטָל חֶרְמוֹן שֶׁיוֹרֶד עַל הֲרְרֵי צִיּוֹן. אִלֵּין שֶׁבַע הָרִים דְאִקְּרוּן הֲרְרֵי צִיּוֹן. כִּי שָׁם צִוָּה יְיָ אֶת הַבְּרָכָה. כֵּיוָן דְּאִתְחַבְּרוּ. חַיִּים עַד הָעוֹלָם דָא עֵץ חַיִּים בְּהַהוּא עוֹלָם. וְכָל דָא בְּגִין הַנְהוּ קָרְבָּנִין דְּמִתְעָרִין טִיבוּ לְעֵילָא וְתַתָּא.","וּלְבָתָר הֲכִי כְּהָנֵי דְמִסִטְרָא דְחֶסֶ\"ד קְרֵבִין לְגַבֵּיהּ דְּהַהוּא מִזְבֵּחַ מָה דְּלֵית רֵשׁוּ לִגְבַר אַחֲרָא לְקָרְבָא. וְנַכְסִין נִכְסָת קוּדְשִׁין בִּצְפוֹנָא דְמִזְבֵּחַ, בְּגִין דְבִּסְטָר צְפוֹנָא דְּאִית בָּהּ, כַּד קָרִיב גְבוּרָה לְגַבָּהּ עַבְדָּא אִינוּן נוּקְמִין, בְּגִין כָּךְ עַבְדִין כְּהָנֵי שְׁלָמָא בְּעַלְמָא דְלָא יִתוֹקַד עַלְמָא בְּשַׁלְהוֹבוֹי דְמִזְבֵּחַ. וּכְדֵין חַיִּים נַחְתִּין לְעָלְמָא הֲדָא הוּא דִכְתִיב (מלאכי ב׳:ה׳) בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָׁלוֹם. מַאי טַעְמָא חַיִּים בְּגִין דְהוּא עֲבָד שָׁלוֹם.","וְכַהֲנֵי עַבְדִין שָׁלוֹם בְּקָרְבָּנָא מַאי קָרְבָּנָא לָבָן וְאָדוֹם. חֵלֶב וְדָם. חֵלֶב לְקֳבֵל הַהוּא דַּרְגָא שׁוּפְרָא דְכוֹלָא. חֵלֶב הָאָרֶץ מְתַרְגֶּמִינָן שׁוּפְרָא דְאַרְעָא. דָּם לְקֳבֵל הַהוּא דַּרְגָא דְּאִקְרֵי נֶפֶשׁ דִכְתִיב (ירמיהו נ״א:י״ד) נִשְׁבַּע יְיָ צְבָאוֹת בְּנַפְשׁוֹ (עמוס ו' נשבע יי בנפשו). וּבַר נָשׁ כַּד קָרִיב הַאי דָּמָא כְּאִילוּ מַקְרִיב נַפְשֵׁיהּ הֲדָא הוּא דִכְתִיב (ויקרא י״ז:י״א') כִּי הַדָּם הוּא בַּנֶפֶשׁ יְכַפֵּר.","וּבְגִין כָּךְ אַזְהַר לוֹן אוֹרַיְיתָא, מַאן דְיֵיכוּל מֵהַהוּא חֵלֶב וְדָם דִּמְקָרְבִין מִנֵּיהּ לְמַדְבְּחָא יִשְׁתְצֵי מֵהַהוּא מַדְבְּחָא, הַאי דִכְתִיב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מְעַמֵיהָ. מַאי טַעְמָא בְּגִין דַהֲוָה לֵיהּ לְמִקְרֶבֵיהּ לְהַהוּא חֵלֶב עַל מַדְבְּחָא וְהַהוּא דָּם בַּיְסוֹד לְאַכְלָלָא מִדַּת יוֹם בַּלַּיְלָה וּמִדָּת לַיְלָה בְּיוֹם. וּבְעוֹלָת הַתָּמִיד דְאִיהִי כְּלָלָא דְכוֹלָא לְכַפָּרָא עַל כָּל יִשְׂרָאֵל עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה הַנִיתָּק לַעֲשֵׂה. מַאי טַעְמָא בְּגִין דְּהָא אֲרְבָּא (ס\"ת אתרא) דַּרְגָא דְעוֹלָה עֲשֵׂה אִיהוּ."],[],[[0,"","וּמֹשֶׁה שֶׁהוּא לֵוִי, מִצַּד זֶה הוּא קָרַב בַּתְּחִלָּה לַמִּזְבֵּחַ הַזֶּה. זֶהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. מַה זֶּה רֹאשִׁי? אֶלָּא בָּרֹאשׁ, כְּשֶׁנִּדְבֶּקֶת מִזְבֵּחַ הַזּוֹ בְּאוֹתָהּ עוֹלָה, שְׂמֹאלוֹ הִיא נִקְרֵאת בַּתְּחִלָּה. וְעִם כָּל זֶה הֵעִירוּ הַחֲבֵרִים, בְּחָלוּק לָבָן שֶׁאֵין בּוֹ אִמְרָא שִׁמֵּשׁ, זֶהוּ שֶׁכָּתוּב (בראשית ל) מַחְשּׁף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת. מִשּׁוּם שֶׁאַף עַל גַּב שֶׁהוּא מִצַּד הַדִּין, הִתְלַבֵּשׁ בְּחֶסֶד וְקָרַב אֵלֶיהָ, וְהֵעִיר חֶסֶד עֶלְיוֹן בָּעוֹלָם."],[1,"","וּמַה הִקְרִיב? פַּר בְּרֹאשׁ תָּמִיד שֶׁל שַׁחַר עוֹלָה וַדַּאי, וְאַחַר כָּךְ הִקְרִיב פַּר חַטָּאת, לָתֵת שָׁלוֹם בֵּין אוֹתוֹ פַּר חַטָּאת וְאַהֲרֹן שֶׁחָטָא לָהּ כְּשֶׁעָשָׂה עֵגֶל, וְזוֹ כְּנֶסֶת יִשְׂרָאֵל, וְהַחַטָּאת הִיא כְּנֶגְדָּהּ. וְזֶה פַּר כֹּהֵן מָשִׁיחַ כְּשֶׁהוּא חָטָא אֶל הַמִּזְבֵּחַ, מַה שֶּׁאֵין בְּאִישׁ אַחֵר, אֶלָּא נְקֵבָה לְחַטָּאת, וְאַחַר כָּךְ מַקְרִיב עוֹלָה אֵלֶיהָ. כֵּיוָן שֶׁהֻקְרְבָה עוֹלָה לַמִּזְבֵּחַ הַזֶּה, אָז מִלּוּאִים הִיא. מִלּוּאִים לְמַעְלָה מִלּוּאִים לְמַטָּה. וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה, שֶׁהֲרֵי הַגְּבִירָה הִתְחַבְּרָה עִם בַּעְלָהּ, וְאָז מַקְרִיב לְאוֹתוֹ מִזְבֵּחַ אֶת אֵיל הַמִּלֻּאִים. וְנוֹתֵן מֵאוֹתוֹ דָם עַל תְּנוּךְ אֹזֶן אַהֲרֹן כְּדֵי שֶׁתִּהְיֶה רַכָּה לִשְׁמֹעַ בְּרַכּוּת, וְלֹא בְקֹשִׁי. וִיקַבֵּל דִּבְרֵי תוֹרָה, שֶׁלֹּא לְהַפְרִיד בֵּין תּוֹרָה שֶׁבְּעַל פֶּה מִתּוֹרָה שֶׁבִּכְתָב, וּלְהַשְׁלִים כָּל הָעוֹלָמוֹת, וְכֵן לְבָנָיו."],[2,"","וְצִוָּה אוֹתָם שֶׁיֵּשְׁבוּ בְּאוֹתוֹ הַשַּׁעַר שֶׁל אוֹתוֹ הָאֹהֶל, לִשְׁמֹר אוֹתוֹ מָקוֹם שֶׁלֹּא יִקְרַב עָרֵל וְטָמֵא, וְיִשְׁתַּלְּמוּ כָּל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, וְיַעֲלוּ בְּאוֹתָהּ דַּרְגַּת הַחֶסֶד שֶׁהִיא שְׁבִיעִי מִמַּטָּה לְמַעְלָה, שֶׁהֲרֵי הֵם בַּתְּחִלָּה נִדְבְּקוּ בְּאוֹתוֹ פֶּתַח אֹהֶל מוֹעֵד, וְאַחַר כָּךְ הִתְעַלּוּ לְמַעְלָה."],[3,"","וְאַחַר כָּךְ מַה כָּתוּב? וִימִינוֹ תְּחַבְּקֵנִי. זֶהוּ שֶׁכָּתוּב (ויקרא ט) וַיְהִי בַּיּוֹם הַשְּׁמִינִי קָרָא מֹשֶׁה לְאַהֲרֹן, וְצִוָּה אוֹתוֹ לָקַחַת אוֹתוֹ עֵגֶל שֶׁחָטָא בּוֹ וְיַקְרִיבוֹ לְאוֹתוֹ מִזְבֵּחַ, וְהוּא הָיָה מִתְבַּיֵּשׁ לְהַקְרִיב אֵלֶיהָ, שֶׁפָּחַד מִשַּׁלְהֲבוֹתֶיהָ. אָמַר לוֹ מֹשֶׁה (שם), קְרַב אֶל הַמִּזְבֵּחַ וַעֲשֵׂה אֶת חַטָּאתְךְ - בַּתְּחִלָּה, וְתֵן מֵאוֹתוֹ דָם עַל אוֹתָם קְרָנוֹת, מִשּׁוּם שֶׁחָטָא בַּתְּחִלָּה אֶצְלָם וּמָנַע מֵהֶם בְּרָכוֹת, וְאַחַר כָּךְ (שם) וְאֶת הַדָּם יָצַק אֶל יְסוֹד הַמִּזְבֵּחַ, לָצֶקֶת בָּהּ אוֹתוֹ יְסוֹד. מַה זֶּה יָצַק? כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ז) וַיַּעַשׂ אֶת הַיָּם מוּצָק."],[4,"","וְאַחַר כָּךְ הִקְרִיב לְאוֹתוֹ מִזְבֵּחַ אוֹתָהּ עוֹלָה, וְעָשָׂה בַּתְּחִלָּה רֹאשׁ, וְאַחַר כָּךְ רֶגֶל, וְאַחַר הִקְרִיב עַל יִשְׂרָאֵל שְׂעִיר עִזִּים, שֶׁהֲרֵי מֵאוֹתוֹ הַצַּד שֶׁל צַד הָרָע נִדְבְּקוּ בָּעֲבוֹדָה זָרָה."],[5,"","וְאַחַר כָּךְ עֵגֶל וְכֶבֶשׁ לְעוֹלָה. בֹּא רְאֵה, בַּהַתְחָלָה עֵגֶל לְחַטָּאת. כֵּיוָן שֶׁהִקְרִיב אוֹתוֹ בִּשְׁלֵמוּת אֶל אִמּוֹ, אַחַר כָּךְ הִקְרִיב אוֹתוֹ לְאָבִיו. זֶהוּ שֶׁכָּתוּב לְעֹלָה. אַחַר כָּךְ, שׁוֹר וָאַיִל לִשְׁלָמִים, שֶׁהִנֵּה שָׁלוֹם בְּכָל הָעוֹלָמוֹת. וְשׁוֹר זֶה שֶׁל צַד הַשְּׂמֹאל. וְאֵילוֹ שֶׁל יִצְחק לֹא עוֹשִׂים דִּין אֶלָּא לִשְׁלָמִים, שָׁלוֹם לְמַעְלָה שָׁלוֹם לְמַטָּה,"],[6,"","אָז הַקָּדוֹשׁ בָּרוּךְ הוּא פָּתַח עֲלֵיהֶם, (תהלים קלג) הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. שֶׁבֶת אַחִים - יָמִין וּשְׂמֹאל, מֹשֶׁה וְאַהֲרֹן. גַּם - לְהַכְלִיל אֶת כְּנֶסֶת יִשְׂרָאֵל. יָחַד - צַדִּיק, הַכֹּל בְּיִחוּד שָׁלֵם (משלם). וְאָז מַה כָּתוּב? כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ יֹרֵד עַל הַזָּקָן. כֵּיוָן שֶׁהִתְחַבְּרוּ זָכָר וּנְקֵבָה שָׁלֵם, מִשּׁוּם כָּךְ כַּשֶּׁמֶן הַטּוֹב עַל הָרֹאשׁ, בַּהַתְחָלָה הָעַתִּיק שֶׁל הַכֹּל, רֹאשׁ כָּל הָרָאשִׁים. יֹרֵד עַל הַזָּקָן - זֶה חֶסֶד וּגְבוּרָה וְתִפְאֶרֶת, שֶׁכֻּלָּם נִקְרְאוּ זָקֵן. (בראשית כד) וְאַבְרָהָם זָקֵן. (שם כז) וַיְהִי כִּי זָקֵן יִצְחָק (גבורה). (שם מח) וְעֵינֵי יִשְׂרָאֵל (תפארת) כָּבְדוּ מִזֹּקֶן. עַל פִּי מִדּוֹתָיו - זֶה צַדִּיק, וְהוּא פִּי מִדּוֹתָיו."],[7,"","וְאַחַר כָּךְ, כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן - אֵלּוּ שִׁבְעָה הָרִים שֶׁנִּקְרְאוּ הַרְרֵי צִיּוֹן. כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה - כֵּיוָן שֶׁהִתְחַבְּרוּ. חַיִּים עַד הָעוֹלָם - זֶה עֵץ הַחַיִּים בְּאוֹתוֹ עוֹלָם. וְכָל זֶה מִשּׁוּם אוֹתָם קָרְבָּנוֹת שֶׁמְּעוֹרְרִים טוֹב לְמַעְלָה וּלְמַטָּה."],[8,"","וְאַחַר כָּךְ הַכֹּהֲנִים שֶׁמִּצַּד הַחֶסֶ\"ד קְרֵבִים לְאוֹתוֹ מִזְבֵּחַ, מַה שֶּׁאֵין רְשׁוּת לְאִישׁ אַחֵר לִקְרַב, וְנִשְׁחָטִים שְׁחִיטַת הַקְּדָשִׁים בִּצְפוֹן הַמִּזְבֵּחַ, מִשּׁוּם שֶׁבְּצַד צָפוֹן שֶׁיֵּשׁ בָּהּ כְּשֶׁקְּרֵבָה גְבוּרָה אֵלֶיהָ, עוֹשָׂה אֶת אוֹתָן נְקָמוֹת, מִשּׁוּם כָּךְ עוֹשִׂים הַכֹּהֲנִים שָׁלוֹם בָּעוֹלָם, שֶׁלֹּא יִשָּׂרֵף הָעוֹלָם בְּשַׁלְהֲבוֹת הַמִּזְבֵּחַ, וְאָז יוֹרְדִים חַיִּים לָעוֹלָם. זֶהוּ שֶׁכָּתוּב (מלאכי ב) בְּרִיתִי הָיְתָה אִתּוֹ הַחַיִּים וְהַשָּׁלוֹם. מָה הַטַּעַם חַיִּים? מִשּׁוּם שֶׁהוּא עוֹשֶׂה שָׁלוֹם."],[9,"","וְכֹהֲנִים עוֹשִׂים שָׁלוֹם בַּקָרְבָּן. מַהוּ הַקָרְבָּן? לָבָן וֶאָדם, חֵלֶב וְדָם. חֵלֶב כְּנֶגֶד אוֹתָהּ דַּרְגָּה שֶׁל יֹפִי שֶׁל הַכֹּל. חֵלֶב הָאָרֶץ תַּרְגּוּמוֹ יְפִי הָאָרֶץ. וְדָם כְּנֶגֶד אוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת נֶפֶשׁ, שֶׁכָּתוּב (ירמיה נא) נִשְׁבַּע ה' צְבָאוֹת בְּנַפְשׁוֹ ((עמוס ו) נשבע ה' בנפשו). וּבֶן אָדָם, כְּשֶׁמַּקְרִיב דָּם זֶה, כְּאִלּוּ מַקְרִיב נַפְשׁוֹ. זֶהוּ שֶׁכָּתוּב (ויקרא יז) כִּי הַדָּם הוּא בַּנֶּפֶשׁ יְכַפֵּר."],[10,"","וּמִשּׁוּם כָּךְ הִזְהִירָה אוֹתָם הַתּוֹרָה, מִי שֶׁיֹּאכַל מֵאוֹתוֹ חֵלֶב וְדָם שֶׁמִּמֶּנּוּ מַקְרִיבִים לַמִּזְבֵּחַ, יִכְלֶה מֵהַמִּזְבֵּחַ הַהוּא. זֶהוּ שֶׁכָּתוּב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁהָיָה לוֹ לְהַקְרִיב אֶת אוֹתוֹ חֵלֶב עַל הַמִּזְבֵּחַ, וְאוֹתוֹ דָם בַּיְסוֹד, לְהַכְלִיל מִדַּת יוֹם בְּלַיְלָה וּמִדַּת לַיְלָה בְּיוֹם. וּבְעוֹלַת הַתָּמִיד שֶׁהִיא כְּלָלוּת שֶׁל הַכֹּל, לְכַפֵּר עַל כָּל יִשְׂרָאֵל עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה הַנִּתָּק לַעֲשֵׂה. מָה הַטַּעַם? מִשּׁוּם שֶׁהָאֳנִיָּה (מקום) הַזּוֹ דַּרְגָּה שֶׁל עוֹלָה עֲשֵׂה הִיא, וְעוֹשִׂים לָהּ מַתָּנוֹת לְהַכְלִיל לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא כֹּל וּלְיִשְׂרָאֵל."]]],[["וְעַבְדִין לֵיהּ מָתָּנוֹת לְאַכְלָלָא לְהַהוּא אַתְרָא דְּאִקְרֵי כָּ\"ל וּלְיִשְׂרָאֵל. וּלְאָן אַתְרָא יַהֲבִין אִינוּן מָתָּנוֹת. חֲדָא בְּקֶרֶן מִזְרָחִית צְפוֹנִית לְאַתְעָרָא מִזְרָח דְּאִיהוּ רַחֲמֵי וּלְאִתְעָרָא צָפוֹן בְּחֶדְוָה לְגַבֵּיהּ דְּהַהוּא מִזְבֵּחַ. וּלְבָתָר בְּקֶרֶן מָעֲרָבִית דְּרוֹמִית לְאַכְלָלָא הַהוּא מִזְבֵּחַ דְּאִקְרֵי מַעֲרָב בַּדָּרוֹם דְּאִיהוּ חֶסֶ\"ד. וּבְגִין כָּךְ כֹּלָּא חֲדָא מַתָּנָה הֲדָא הוּא דִכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ דְּמִזְרָח דְּאִיהוּ צָפוֹן תַּחַת לְרֹאשִׁי בְּקַדְמִיתָא. וְהָדָר וִימִינוֹ תְּחַבְּקֵנִי דְּאִיהוּ חֶסֶ\"ד.","דָבָר אַחֵר מַאי טַעְמָא דְלָא יַהֲבִין מַתָּנָה בְּקֶרֶן דְּרוֹמִית מִזְרָחִית, צְפוֹנִית מַעֲרָבִית. דְּהָא הַהוּא קֶרֶן דְּרוֹמִית מִזְרָחִית אִיהוּ בְּקַדְמִיתָא כַּד סָלְקִין כַּהֲנַיָּא בְּהַהוּא כֶּבֶשׁ דְבַדָּרוֹם סִטְרָא וְחוּלָקָא דִידְהוּ דְּאִיהוּ חֶסֶ\"ד. וְאַמְרִין כָּל פְּנִיוֹת שְׁאַתָּה פוֹנֶה אִיהוּ אֶלָּא דֶּרֶךְ יָמִין לַמִּזְבֵּחַ בְּגִין לְחַבְּרָן סִטְרָא דְּמִזְרָח בְּהַהוּא מִזְבֵּחַ וַהֲוָה לֵיהּ לְכַהֲנָא לְמֵיהַב מַתָּנָה בְּקַדְמִיתָא בְּהַהוּא קֶרֶן דְּרוֹמִית מִזְרָחִית דְּהַאי אִיהוּ קַדְמָאָה לְאִינוּן דַּרְגִּין וְלֹא עוֹד אֶלָּא דְּאִתְעָר לְגַבָּהּ חֶסֶ\"ד בְּקַדְמִיתָא. הָא אִתְעָרוּ חַבְרַיָּיא וְאַמְרִין בְּגִין דִכְתִיב (ויקרא ד׳:ז׳) אֶל יְסוֹד מִזְבַּח הָעוֹלָה מִן יְסוֹד לַמִּזְבֵּחַ שֶׁל עוֹלָם (ס\"א עולה) כְּלוֹמַר קָרֵב יְסוֹד דְּאִיהוּ צַדִּיק לְגַבָּהּ, וְקֶרֶן דְּרוֹמִית מִזְרָחִית לא הָיָה לָה יְסוֹד.","תָּא חֲזֵי, כְּתִיב בֵּיהּ בִּיהוּדָה (בראשית ל״ז:כ״ז) לְכוּ וְנִמְכְּרֵנוּ לַיִשְׁמְעֱאלִים. וּבְגִין דְּאִיהוּ חָב לְגַבֵּי הַהוּא יְסוֹד וְאַפְרֵשֶׁיה מֵהַהוּא אֶרֶץ עִלָּאָה וְיָהַב עֵצָה לְמִזְבַּן יָתֵיהּ. בְּגִין כָּךְ בְּהַהוּא חוּלָקָא דִּידֵיהּ לָא הֲוָה לֵיהּ יְסוֹד.","וְהָכִי תָנֵינָן מָה הֲוָה חוּלָקֵיהּ דִיהוּדָה הַר הַבַּיִת וּלְשָׁכָיו בַּעֲזָרוֹת. וּמָה הָיָה חוּלָקֵיהּ דְבִנְיָמִן דְּאִיהוּ צַדִּיק לְתַתָּא אוּלָם וְהֵיכָל וּבֵית קֹדֶשׁ הַקֳּדָשִׁים וּרְצוּעָה נַפְקָא מֵחוּלָקֵיהּ דִיהוּדָה דְאִיהִי כְּלַפֵי מִזְרָח דְּהָא דְּגָלוּ נָמֵי מִמִּזְרָח הֲוָה וְנִכְנֵסָה בְּחוּלָקֵיהּ דְבִנְיָמִן. וְעֲלָה אִתְבְּנֵי מַדְבְּחָא דְּהָא מַדְבְּחָא חוּלָקֵיהּ דִיהוּדָה הֲוָה כְּדְּאוֹקִימְנָא (בראשית ל') וַתָעֲמֹד מִלֵדֶּת דְקַיְימָא כוֹרְסַיָּיא עַל סָמְכוֹהִי וַהֲוָא סַמְכָא רְבִיעָאָה לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל דְאִיהִי רְבִיעָאָה וּכְתִיב בָּהּ (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְדָוִד בְּרֵיהּ אֲחִיד בֵּיהּ בְּהַהוּא מִזְבֵּחַ כְּדְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא","וּבִנְיָמִן הַצַּדִּיק מִצְטָעֵר עָלֵיהּ לְקָרְבָא יָתֵהּ לְגַבֵּיהּ, הֲדָא הוּא דִכְתִיב (דברים ל״ג:י״ב) חוֹפֵף עַלָּיו כָּל הַיּוֹם. בְּגִין כָּךְ זָכָה בִנְיָמִן הַצַּדִּיק לְתַתָּא וְנַעֲשָׂה אוּשְׁפִּיזָא לִגְבוּרָ\"ה הֲדָא הוּא דִכְתִיב (דברים ל״ג:י״ב) וּבֵין כְּתֵפָיו שָׁכֵן דְּאִיהוּ חוּלָקֵיהּ בַּמָעֲרָב","וְהַשְׁתָּא שְׁכִינְתָּא בֵּין תְּרֵין צַדִּיקִים. צַדִּיק לְעֵילָא יוֹסֵף הַצַּדִּיק. לְתַתָּא בִנְיָמִן. הַאי בַּעְלָהּ דְמַטְרוֹנִיתָא וְהַאי אוּשְׁפִּיזָא. בְּגִין כָּךְ כְּתִיב (תהילים קי״ג:ט׳) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת דָא עַלְמָא דְאִתְכָּלְיָא (ס\"א דאתגלייא) דָא שְׁכִינְתָּא תַּתָּאָה דְאִיהִי עֲקֶרֶת הַבַּיִת. עִיקָרָא דְּהַאי עַלְמָא רָחֵל בֵּין תְּרֵין צַדִּיקִים לְעֵילָא וְתַתָּא.","בְּגִין כָּךְ אִתְקְרֵי בֵּי מַקְדְּשָׁא בֵּית עוֹלָמִים. מִזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הֲוָה בְּאַחֲסָנָתֵּיה דְבִנְיָמִן. אֲבָל כַּד שַׁרְיָיא שְׁכִינְתָּא בְּאַחֲסָנָתֵּיה דְיוֹסֵף בְּשִׁילֹה לֹא קָארֵי לָה בֵּית עוֹלָמִים דְּהָא עוֹלָם הוֹ\"ד לְעֵילָא וְתַתָּא אֵם הַבָּנִים שֶׂמְחָה דָא שְׁכִינְתָּא בְּגִין כָּךְ הַלְלוּיָהּ.","תָּא חֲזֵי כַּד אִזְדַּבָּן הַהוּא צַדִּיק לְמִצְרָיִם בִנְיָמִן אֲחוּהִי הֲוָה צַדִּיק לְתַתָּא וְנָטַל אַתְרֵיהּ דְלָא לְאִתְפָּגְמָא וּלְאִינוּן עֲשָׂרָה בְּנִין דַהֲווּ לֵיהּ קָרָא לוֹן עַל שְׁמֵיהּ דְּהַהוּא צַדִּיק כְּדְאוּקְמוּהַ חַבְרַיָּיא בֶּלַע עַל שֵׁם שְׁנִבְלָע בֵּין הָאוּמוֹת","בְּגִין כָּךְ תָנֵינָן הַיְסוֹד הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמָעֲרָב וְעַל פְּנֵי כָּל הַצָּפוֹן אוֹכֵל בַּמִזְרָח חֲצִי אָמָה וּבַדָרוֹם חֲצִי אָמָה בְּגִין דְּחוּלָקֵיהּ דְבִנְיָמִן הֲוָה מַעֲרָב בְּגִין כָּךְ אִית לֵיהּ יְסוֹד דְּהָא הוּא שָׁלִיט הֲוָה לְגַבֵּי הַהוּא צַדִּיק יְסוֹד עוֹלָם אֲבָל בְּחוּלָקֵיהּ דִיהוּדָה דְּאִיהוּ מִזְרָח לָא הֲוָה לֵיהּ יְסוֹ\"ד דְּהָא אִיהוּ אֲרְחִיקֵיה מִנֵּיהּ דִּיהַב עֵצָה לְמִזְבְּנֵיה לְמִצְרָיִם.","תָּא חֲזֵי סִדְרָא דְּדְגָלִּים הֲרֵי הוּא סָחְרָנֵי הַהוּא מַדְבְּחָא דְעוֹלָה דְּאִקְרֵי מַשְׁכְּנָא. יְהוּדָה וְדִּסְמִיכִין לֵיהּ בַּמִזְרָח. וּמַאן סְמִיכִין יִשָׂשׂכָר דְּאַגִין עָלֵיהּ בְּחֵילָא דְּאוֹרַיְיתָא. וּלְבָתָר זְבֻלוּן דְסָמִיךְ לְיִשָׂשׂכָר דִּיהַב לוֹן מְלָאי וְחֵילָא לְאִתְעַסְקָא בְּאוֹרַיְיתָא. אֶפְרָיִם וּמְנַשֶׁה וּבִנְיָמִן לְמַעֲרָב. רְאוּבֵן וְדִּסְמִיכִין לֵיהּ בַּדָרוֹם דָן וְדִּסְמִיכִין לֵיהּ בַּצָּפוֹן.","וְתָּא חֲזֵי כְּתִיב בֵּיהּ בְּהַהוּא צַדִּיק (בראשית ל״ז:ב׳) וְהוּא נַעַר אֶת בְּנֵי בִּלְהָה וּכְתִיב בִּבְנִי לֵאָה (שם) וַיִשְׂנֵאוּ אוֹתוֹ בְּגִין כָּךְ תָנֵינָן הַאי יְסוֹ\"ד הָיָה מְהַלֵּךְ עַל פְּנִי כָּל הַמָעֲרָב דְּהָא חוּלָקֵיהּ דְּאַחוֹי דְּנָטַר הַהוּא אַתְרָא וְדִבְנוֹי הֲוָה. וְעַל פְּנִי כָּל הַצָּפוֹן בְּגִין דְהַנְהוּ דַהֲווּ שָׁרָאָן בַּצָּפוֹן לָא הֲווּ שָׂנְאִין לֵיהּ.","אוֹכֵל בַּמִזְרָח חֲצִי אָמָה. בְּגִין דְּעָבַד יְהוּדָה פַּלְגוּ הַצָלָה וְאָמַר מָה בֶּצַע וְלֹא שָׁבָק (לון) לְמִקְטְלֵיהּ. וּבַדָרוֹם חֲצִי אָמָה בְּגִין דִרְאוּבֵן אָמַר (בראשית ל\"ז) לְהַצִיל אוֹתוֹ מִיַדָּם וְגָד נָמֵי דַהֲוָה שָׁרֵי תַמָּן לָא הֲוָה סָנֵי לֵיהּ."],[],[[0,"","וּלְאֵיזְהִ מָקוֹם נוֹתְנִים אוֹתָן מַתָּנוֹת? אַחַת בְּקֶרֶן מִזְרָחִית צְפוֹנִית לְעוֹרֵר הַמִּזְרָח, שֶׁהוּא רַחֲמִים. וּלְעוֹרֵר הַצָּפוֹן בְּשִׂמְחָה אֵלָיו שֶׁל הַמִּזְבֵּחַ הַהוּא, וְאַחַר כָּךְ בְּקֶרֶן מַעֲרָבִית דְּרוֹמִית, לְהַכְלִיל אוֹתוֹ מִזְבֵּחַ שֶׁנִּקְרָא מַעֲרָב בְּדָרוֹם שֶׁהוּא חֶסֶד, וְלָכֵן הַכֹּל מַתָּנָה אַחַת. זֶהוּ שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ - שֶׁל מִזְרָח שֶׁהוּא צָפוֹן. תַּחַת לְרֹאשִׁי - בַּתְּחִלָּה. וְאַחַר כָּךְ וִימִינוֹ תְּחַבְּקֵנִי - שֶׁהוּא חֶסֶד."],[1,"","דָּבָר אַחֵר, מָה הַטַּעַם שֶׁלֹּא נוֹתְנִים מַתָּנָה בְּקֶרֶן דְּרוֹמִית מִזְרָחִית, צְפוֹנִית מַעֲרָבִית? שֶׁהֲרֵי אוֹתָהּ קֶרֶן דְּרוֹמִית מִזְרָחִית הִיא בַּתְּחִלָּה, כְּשֶׁעוֹלִים הַכֹּהֲנִים בְּאוֹתוֹ כֶבֶשׁ, שֶׁבַּדָּרוֹם הַצַּד וְהַחֵלֶק שֶׁלָּהֶם שֶׁהוּא חֶסֶד. וְאוֹמְרִים, כָּל פִּנּוֹת שֶׁאַתָּה פּוֹנֶה, אֵינוֹ אֶלָּא דֶּרֶךְ יָמִין לַמִּזְבֵּחַ, כְּדֵי לְחַבֵּר צַד הַמִּזְרָח לְאוֹתוֹ מִזְבֵּחַ, וְהָיָה לוֹ לַכֹּהֵן לָתֵת מַתָּנָה בַּתְּחִלָּה בְּאוֹתָהּ קֶרֶן דְּרוֹמִית מִזְרָחִית, שֶׁהֲרֵי הוּא רִאשׁוֹן לְאוֹתָן דְּרָגוֹת, וְלֹא עוֹד, אֶלָּא שֶׁהִתְעוֹרֵר אֵלֶיהָ חֶסֶד בַּתְּחִלָּה. הֲרֵי הֵעִירוּ הַחֲבֵרִים וְאָמְרוּ, מִשּׁוּם שֶׁכָּתוּב (ויקרא ד) אֶל יְסוֹד מִזְבַּח הָעֹלָה - מִן יְסוֹד לְמִזְבְּחָהּ שֶׁל עוֹלָם (ס\"א עלה). כְּלוֹמַר, קָרֵב יְסוֹד שֶׁהוּא צַדִּיק אֶצְלָהּ. וְקֶרֶן דְּרוֹמִית מִזְרָחִית לֹא הָיָה לָהּ יְסוֹד."],[2,"","בֹּא רְאֵה, כָּתוּב בִּיהוּדָה (בראשית לז) לְכוּ וְנִמְכְּרֶנּוּ לַיִּשְׁמְעֵאלִים. וּבִגְלַל שֶׁהוּא חָטָא אֶל אוֹתוֹ הַיְסוֹד וְהִפְרִידוֹ מֵאוֹתָהּ אֶרֶץ עֶלְיוֹנָה וְנָתַן עֵצָה לִמְכֹּר אוֹתוֹ, מִשּׁוּם כָּךְ בְּאוֹתוֹ חֵלֶק שֶׁלּוֹ לֹא הָיָה לוֹ יְסוֹד."],[3,"","וְכָךְ שָׁנִינוּ, מֶה הָיָה חֶלְקוֹ שֶׁל יְהוּדָה? הַר הַבַּיִת וּלְשָׁכוֹת וַעֲזָרוֹת. וּמֶה הָיָה בְּחֶלְקוֹ שֶׁל בִּנְיָמִין, שֶׁהוּא צַדִּיק לְמַטָּה? אוּלָם וְהֵיכָל וּבֵית קֹדֶשׁ הַקְּדָשִׁים. וּרְצוּעָה יוֹצֵאת מֵחֶלְקוֹ שֶׁל יְהוּדָה שֶׁהִיא כְּלַפֵּי מִזְרָח, שֶׁהֲרֵי גַּם דִּגְלוֹ הָיָה מִמִּזְרָח, וְנִכְנְסָה לְחֶלְקוֹ שֶׁל בִּנְיָמִין, וְעָלֶיהָ נִבְנָה הַמִּזְבֵּחַ, שֶׁהֲרֵי הַמִּזְבֵּחַ חֶלְקוֹ שֶׁל יְהוּדָה הָיָה, כְּפִי שֶׁבֵּאַרְנוּ (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, שֶׁעָמַד הַכִּסֵּא עַל עַמּוּדָיו, וְהוּא תּוֹמֵךְ הָרְבִיעִי (מלכות), כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא רְבִיעִית, וְכָתוּב בָּהּ (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְדָוִד, בְּנוֹ אָחַז בְּאוֹתוֹ מִזְבֵּחַ, כְּמוֹ שֶׁבֵּאַרְנוּ בְּסוֹד הָאֱמוּנָה,"],[4,"","וּבִנְיָמִין הַצַּדִּיק מִצְטַעֵר עָלָיו לְקָרֵב אוֹתָהּ אֵלָיו. זֶהוּ שֶׁכָּתוּב (דברים לג) חוֹפֵף עָלָיו כָּל הַיּוֹם. מִשּׁוּם כָּךְ זָכָה בִּנְיָמִין הַצַּדִּיק לְמַטָּה, וְנַעֲשָׂה מְאָרֵחַ לַגְּבוּרָה, זֶהוּ שֶׁכָּתוּב וּבֵּין כְּתֵפָיו שָׁכֵן, שֶׁהוּא חֶלְקוֹ בַּמַּעֲרָב,"],[5,"","וְעַכְשָׁו שְׁכִינָה בֵּין שְׁנֵי צַדִּיקִים. צַדִּיק לְמַעְלָה - יוֹסֵף הַצַּדִּיק, לְמַטָּה - בִּנְיָמִין. זֶהוּ בַּעַל הַגְּבִירָה, וְזֶה הַמְאָרֵחַ. לָכֵן כָּתוּב (תהלים קיג) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת, זֶה עוֹלָם שֶׁמִּתְכַּלֶּה (ס\"א שמתגלה), זוֹ שְׁכִינָה תַּחְתּוֹנָה שֶׁהִיא עֲקֶרֶת הַבַּיִת. עִקַּר הָעוֹלָם הַזֶּה רָחֵל בֵּין שִׁנֵי צַדִּיקִים לְמַעְלָה וּלְמַטָּה."],[6,"","לָכֵןֹ נִקְרָא בֵּית הַמִּקְדָּשׁ בֵּית עוֹלָמִים. הַמִּזְבֵּחַ שֶׁל בֵּית עוֹלָמִים הָיָה בִּירֻשָּׁתוֹ שֶׁל בִּנְיָמִין, אֲבָל כְּשֶׁשָּׁרְתָה שְׁכִינָה בִּירֻשָּׁתוֹ שֶׁל יוֹסֵף בְּשִׁילֹה, לֹא קוֹרֵא לָהּ בֵּית עוֹלָמִים, שֶׁהֲרֵי עוֹלַם הוֹד הוּא לְמַעְלָה וּלְמַטָּה. אֵם הַבָּנִים שְׂמֵחָה - זוֹ שְׁכִינָה, וְלָכֵן הַלְלוּיָהּ."],[7,"","בֹּא רְאֵה, כְּשֶׁנִּמְכַּר אוֹתוֹ צַדִּיק לְמִצְרַיִם, בִּנְיָמִין אָחִיו הָיָה צַדִּיק לְמַטָּה, וְנָטַל מְקוֹמוֹ שֶׁלֹּא לְהִפָּגֵם, וּלְאוֹתָם עֲשָׂרָה בָנִים שֶׁהָיוּ לוֹ קָרָא לָהֶם עַל שְׁמוֹ שֶׁל אוֹתוֹ צַדִּיק, כְּמוֹ שֶׁפֵּרְשׁוּ הַחֲבֵרִים. בֶּלַע - עַל שֵׁם שֶׁנִּבְלַע בֵּין הָאֻמּוֹת."],[8,"","לָכֵן שָׁנִינוּ, הַיְסוֹד הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמַּעֲרָב וְעַל פְּנֵי כָּל הַצָּפוֹן, אוֹכֵל בַּמִּזְרָח חֲצִי אַמָּה וּבַדָּרוֹם חֲצִי אַמָּה, מִשּׁוּם שֶׁחֶלְקוֹ שֶׁל בִּנְיָמִין הָיָה בַּמַּעֲרָב, לָכֵן יֵשׁ לוֹ יְסוֹד, שֶׁהֲרֵי הוּא הָיָה שַׁלִּיט אֶל אוֹתוֹ צַדִּיק יְסוֹד עוֹלָם, אֲבָל בַּחֵלֶק שֶׁל יְהוּדָה שֶׁהוּא מִזְרָח, לֹא הָיָה לוֹ יְסוֹד, שֶׁהֲרֵי הוּא הִרְחִיקוֹ מִמֶּנּוּ, שֶׁנָּתַן עֵצָה לְמָכְרוֹ לַמִּצְרִים."],[9,"","בֹּא רְאֵה, סֵדֶר הַדְּגָלִים הֲרֵי הוּא סְבִיב אוֹתוֹ מִזְבַּח הָעוֹלָה שֶׁנִּקְרָא מִשְׁכָּן. יְהוּדָה וְהַסְּמוּכִים לוֹ בַּמִּזְרָח. וּמִי הַסְּמוּכִים? יִשָּׂשכָר שֶׁמֵּגֵן עָלָיו בְּכֹחַ הַתּוֹרָה. וְאַחַר כָּךְ זְבוּלוּן שֶׁסָּמוּךְ לְיִשָּׂשכָר, שֶׁנָּתַן לָהֶם מְלַאי וְכֹחַ לְהִתְעַסֵּק בַּתּוֹרָה. אֶפְרַיִם וּמְנַשֶּׁה וּבִנְיָמִין לַמַּעֲרָב. רְאוּבֵן וְהַסְּמוּכִים לוֹ בַּדָּרוֹם. דָּן וְשֶׁסְּמוּכִים לוֹ בַּצָּפוֹן."],[10,"","וּבֹא וּרְאֵה, כָּתוּב בְּאוֹתוֹ צַדִּיק (בראשית לז) וְהוּא נַעַר אֶת בְּנֵי בִלְהָה, וְכָתוּב בִּבְנֵי לֵאָה וַיִּשְׂנְאוּ אֹתוֹ. לָכֵן שָׁנִינוּ, הַיְסוֹד הַזֶּה הָיָה מְהַלֵּךְ עַל פְּנֵי כָּל הַמַּעֲרָב, שֶׁהֲרֵי חֵלֶק אָחִיו שֶׁשָּׁמַר אוֹתוֹ מָקוֹם וְשֶׁל בָּנָיו הָיָה. וְעַל פְּנֵי כָל הַצָּפוֹן, מִשּׁוּם שֶׁאֵלּוּ שֶׁהָיוּ שְׁרוּיִים בַּצָּפוֹן לֹא הָיוּ שׂוֹנְאִים אוֹתוֹ."],[11,"","אוֹכֵל בַּמִּזְרָח חֲצִי אַמָּה, מִשּׁוּם שֶׁיְּהוּדָה עָשָׂה חֲצִי הַצָּלָה. אָמַר (שם) מַה בֶּצַע, וְלֹא הִשְׁאִיר (אותם) לַהֲרֹג אוֹתוֹ. וּבַדָּרוֹם חֲצִי אַמָּה, מִשּׁוּם שֶׁרְאוּבֵן אָמַר לְהַצִּיל אוֹתוֹ מִיָּדָם. וְגַם גָּד שֶׁהָיָה חוֹנֶה שָׁם, לֹא הָיָה שׂוֹנֵא אוֹתוֹ."]]],[["תָּא חֲזֵי כַּמָה עֲקִימִין אִינוּן בְּנֵי נָשָׁא דְלָא בָעָאן לְאִשְׁתָּדְלֵי בְּאָרְחָא דְחַיֵי דְאוֹרִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִבְנוֹי וְאַזְהָר לוֹן עֲלָהּ וְאָמַר (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה דְּלֵית לָךְ רֵשׁוּ לְאַפְרָשָׁא יוֹם מִּלַּיְלָה. וּבְגִין כָּךְ יְהוּדָה אַף עַל גַּב דְּחוּלָקֵיהּ וְעַדְבֵיהּ הֲוָה מַעֲרָב דְּאִיהוּ לַיְלָה כַּד הֲוָה שָׁארֵי סַחֲרָנֵיהּ הַהוּא מַשְׁכְּנָא אִתְדַבַּק בַּמִזְרָח דְּאִיהוּ יוֹם וְקוּדְשָׁא בְּרִיךְ הוּא רָמַז לֵיהּ וְאָמַר לֵיהּ (דברים ל׳:י״ט) וּבָחַרְתָּ בַּחַיִּים דְלָא לְאַפְרָשָׁא יוֹם מִּלַּיְלָה וּמַאן דְפַרִישׁ לוֹן גָרִים מוֹתָא.","וּבְהַהוּא חוֹבָה מִיתוּ בְּנוֹי בְּגִין דְחַבִילוּ אוֹרְחֵיהוֹן וְלָא דַבִּיּקוּ יוֹם בַּלַּיְלָה בְּגִין דְלָא אִשְׁתָדְלוּ כְּדְקָא חָזֵי לְחַבְּרָא חִוְורָא בְסֻמָּקָא בְּגִין לְכַפָּרָא הַהוּא חוֹבָה דִילֵיהּ דְאַפְרִישׁ לוֹן בְּקַדְמִיתָא. כַּד זַבִּין לְהַהוּא צַדִּיק דְּאִקְרֵי יוֹם דְאַפְרֵשֶׁיה מכְּנְסֶת יִשְׂרָאֵל דְּאִקְרֵי לַיְלָה. וְרָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְקָרְבָא מִזְרָח בַּמָעֲרָב וְאָמַר לֵיהּ (במדבר ב׳:ג׳) וְהַחוֹנִים קְדְמָה מִזְרָחָה דֶגֶל מַחֲנֶה יְהוּדָה לְקָרְבָא מִזְרָח לְמַעֲרָב לְמֵיהַב לֵיהּ שֶׁפַע בִּרְכָאָן מִלְּעֵילָא.","וּבְנֵי יוֹסֵף וּבִנְיָמִן אַף עַל גַּב דְבִנְיָמִן הֲוָה מִתְדַּבָּק בַּמִזְרָח, רָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמִשְׁרֵי בַּמָעֲרָב לְקָרְבָא כְּנֶסֶת יִשְׂרָאֵל לְגַבֵּי צַדִּיק כֹּלָּא בְּאֹרַח מֵישַׁר הֲדָא הוּא דִכְתִיב (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָּם. וּרְאוּבֵן דְאִתְדַבָּק בְּסִטְרָא דְחֶסֶ\"ד יִשְׁרֵי בִּדְרוֹמָא. וְדָן בְּגִין לְכַפָּרָא הַהוּא חוֹבָא דְעֶגְלָא דִיקַבְּלוּן בְּנוֹי וְאִיהוּ מִסִּטְרָא דִּצְפוֹנָא יִשְׁרֵי לִצְפוֹנָא לְכַפָּרָא הַהוּא חוֹבָה.","בְּגִין כָּךְ כְּתִיב בַּיָם שֶׁעָשָׂה שְׁלֹמֹה עֲשָׂרָה עַל עֲשָׂרָה (מלכים א ז׳:כ״ג) וְקַו שְׁלֹשִׁים בַּאָמָה יִסוֹב. כֻלָּא בְּרָזָא דְחָכְמְתָא. כְּתִיב בֵּיהּ עוֹמֵד עַל שְׁנֵים עֲשָׂר בָּקָר שְׁלשָׁה פּוֹנִים צָפוֹנָה וּשְׁלשָׁה פּוֹנִים יָמָּה וּשְׁלשָׁה פּוֹנִים נֶגְבָּה וּשְׁלשָׁה פּוֹנִים מִזְרָחָה וְהַיָּם עֲלֵיהֶם מִלְמַעְלָה הַהוּא יַמָּא דְחָכְמְתָא אִתְתְּקַן בְּהוּ.","תָּא חֲזֵי כַּד הֲווּ עַבְדִין כַּהֲנַיָּא הַהוּא חַטָּאת לְכַפָּרָה חוֹבִין דְלא תַעֲשֶׂה הֲוָה דְּאִית בְּהוּ כָּרֵת. וְעוֹלֶה לְכַפָּרָה עַל מַאן דְלָא עֲבִיד מִצְוֹת עֲשֵׂה אָתֵי וּמֵהַהוּא סִטְרָא אָתֵי עוֹלָה דְּאִיהוּ זָכָר. וּכְתִיב (שמות כ׳:ח׳) זָכוֹר אֶת יוֹם הַשַׁבָּת מִצְוַת עֲשֵׂה וּבְגִין כָּךְ אָנוּ מַקְרִיבִין בְּשַׁבָּת תְּרֵין אִמְרִין דְּמוּסָף עוֹלָה בְּגִין דְּבְהַהוּא דִיְמִינָא אִתּוֹסַף לְהַהוּא צַדִּיק נְהִירוּ דְעַתִּיקָא קַדִּישָׁא. כַּד אִתְדַבַּק בִּכְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי שָׁמוֹר לֹא תַעֲשֶׂה","בְּגִין כָּךְ אִית בֵּיהּ בְּשַׁבָּת עֲשֵׂה וְלֹא תַעֲשֶׂה דְּאִית בֵּיהּ כָּרֵת דְּהָא מַאן דְּעָבַד פְּגִימוּ בְּהַהוּא אַתְרָא דְּאִקְרֵי לא תַעֲשֶׂה וְאַפְרֵישׁ זִווּגָא דִילְהוֹן אִשְׁתָצֵי מִתַּמָּן נַפְשָׁא דִילֵיהּ. וּמַאן אִיהוּ, מַאן דְּעָבִיד עוֹבָדִין דְּחוֹל בְשַׁבְּתָא בַּקֹּדֶשׁ דְאִתְדַבָּק בְּשַׁבָּת בְּשַׁבָּתוֹן וְכֻלְּהוּ עָלְמִין בְּחֶדְוָה בִּנְהִירוּ אֲבָל מַאן דְלָא עֲבִיד אֶלָּא בִּשְׁגָגָה מַקְרִיב חַטָּאת לְקֳבֵל הַהוּא דַּרְגָא דְמִזְבֵּחַ.","וּבְרֹאשׁ חוֹדֶשׁ דְּאִיהוּ חַדְּתוּתָא דְסִיהֲרָא אֲנָן מַקְרִיבִין (במדבר כ״ח:י״א) פָּרִים בְּנֵי בָּקָר שְׁנַיִם דְּהָא מִסִּטְרָא דְפָרָה אֲדוּמָה תְמִימָה אָתוּ וְאִינוּן לְעֵילָא לְאַשְׁלָמָא פְּגִימוּ דִּילָה וּלְמֵיהַב לָהּ שֶׁפַע עַל חַד תְרֵין מֵהַהוּא אֲתַר דְּאִקְרֵי עוֹלָה וְאִתוֹסָף בְּהַהוּא זִמְנָא נְהִירוּ לְסִיהֲרָא אַיִל אֶחָד לְקָרְבָא לָהּ אֵילוֹ דְּיִצְחָק (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי","כְּבָשִׂים בְּנֵי שָׁנָה שִׁבְעָה לְחַבְּקָא לָהּ יְמִינָא וְשַׁבְעָא דַּכְרִין אִתְקַרְבִין בָּהּ תְמִימִים שְׁלֵמִין בְּכוֹלָא וַאֲנָן מְקָרְבִין שֵׂעִיר עִזִים אֶחָד לְחַטָּאת דְּהַאי חַטָּאת מֵהָאי סִטְרָא דְפָּר חַטָּאת אָתֵי דִכְתִיב שָׁמוֹר. וְשָׁמוֹר לֹא תַעֲשֶׂה אִיהוּ וַאֲנָן מְקָרְבִין שֵׂעִיר חַטָּאת דְאָתֵי עַל לֹא תַעֲשֶׂה. בְּמוּסָף דִּידָהּ בְּרֹאשׁ חוֹדֶשׁ דְאָתֵי לְכַפָּרָה עַל טוּמְאַת מִקְדָּשׁ וְקֹדָשָׁיו דִכְתִיב (יחזקאלמ\"ג) וְלָא יְטָמְאוּ עוֹד בֵּית יִשְׂרָאֵל שֵׁם קָדְשִׁי דְלָא יִתְקַרָב בִּכְנֶסֶת יִשְׂרָאֵל עָרֵל וְטָמֵא.","אֲבָל מוּסָף דְּשַׁבָּת לֵיכָּא לְקָרְבָא בְּגִין דְּהָא אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא וְנָהִיר בְּהַהוּא רָצוֹן לְכֻלְּהוּ עָלְמִין וְכֹלָּא אִשְׁתְּכַח בִּנְהִירוּ, דְּהָא שַׁבָּת בְלָא דִינָא כְּלָל אִיהוּ וְלָא שָׁלִיט חִוְיָּיא עֲקִימָא וְכַהֲנֵי מִסִּטְרָא דְחֶסֶ\"ד נַכְסִין יָתֵיהּ בִּצְפוֹנָא דְמִזְבֵּחַ וְאֲפִילּוּ יִשְׂרָאֵל יַכְלִין לְמֶעְבָּד, בָּר דְּלֵית לוֹן רֵשׁוּ לְמִקְרַב לְהַהוּא לַמִּזְבֵּחַ לְקָרְבָא אֲבָל לְמֵיכַס שָׁרֵי.","וּבִצְפוֹנָא אִיהוּ אַתְרֵיהּ דְּהַהוּא שָׂעִיר דְּהָא שָׂעִיר מִצְפוֹנָא יָנִיק וַאֲנָן מְקָרְבִין דָּמָא לְמַדְבְּחָא וְעַבְדִּין ד' מָתָּנוֹת עַל ד' קְרָנוֹת בְּגִין לְאַקַפָא לָהּ מִכָּל סִטְרִין דְלָא יִתְקַרָב מַאן דְלָא חֲזֵי לְקָרְבָא לְקֹדֶשׁ הַקֳּדָשִׁים וְהַאי חַטָּאת דְעֲבְדִינָן מִנֵּיהּ קֹדֶשׁ הַקֳּדָשִׁים, אִיהוּ דְלָא יִתְעֲר סִטְרָא דִמְסָאֲבָא מִנֵּיהּ בְּעַלְמָא.","וְתָּא חֲזֵי בְּעוֹלָה ב' מָתָּנוֹת שְׁהֵן אַרְבַּע רָזָא דְּיִחוּדָא דְּמִתְיַחֵד עוֹלָה בַּמִזְבֵּחַ. אֲבָל חַטָּאת אַרְבַּע מָתָּנוֹת דְלָאו אִינוּן אֶלָּא לְנַטְרָא וּלְאַקַפָא אִינוּן גִבּוֹרִין דְּאִינוּן מִסִּטְרָא דִגְבוּרָה לְהַהוּא מִטָּה כּוּרְסַיָּיא קַדִּישָׁא וּלְאַשְׁלָמָא הַהוּא פְּגִימוּ דְּעָבְדוּ בָּהּ. וּמַאן דְּגָרִים לוֹן לִבְנִי נָשָׁא לְמֶעְבָּד הַהוּא חוֹבָה מִסִּטְרָא דְּשָׂעִיר אָתֵי, בְּגִין כָּךְ חַטָּאת יָחִיד שְׂעִירָה וְחַטָאת נָשִׂיא שָׂעִיר, וְחַטָאת כֹּהֵן מָשִׁיחַ פָּר, כּוּלְהוּ מִסִּטְרָא דִשְׂמָאלָא."],[],[[0,"","בֹּא רְאֵה בַּמָּה עֲקֻמִּים הֵם בְּנֵי אָדָם שֶׁלֹּא רוֹצִים לְהִשְׁתַּדֵּל בְּדֶרֶךְ הַחַיִּים שֶׁהוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא לְבָנָיו, וְהִזְהִיר אוֹתָם עָלֶיהָ וְאָמַר (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה, שֶׁאֵין לְךְ רְשׁוּת לְהַפְרִיד יוֹם מִלַּיְלָה. וְלָכֵן יְהוּדָה, אַף עַל פִּי שֶׁחֶלְקוֹ וְגוֹרָלוֹ הָיָה מַעֲרָב, שֶׁהוּא לַיְלָה, כְּשֶׁהָיָה שׁוֹרֶה סְבִיב אוֹתוֹ הַמִּשְׁכָּן, נִדְבַּק בַּמִּזְרָח שֶׁהוּא יוֹם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָמַז לוֹ וְאָמַר לוֹ (דברים ל) וּבָחַרְתָּ בַּחַיִּים. שֶׁלֹּא לְהַפְרִיד יוֹם מִלַּיְלָה. וּמִי שֶׁמַּפְרִיד אוֹתָם גּוֹרֵם לְמָוֶת,"],[1,"","וּבְאוֹתוֹ חֵטְא מֵתוּ בָנָיו, מִשּׁוּם שֶׁהִשְׁחִיתוּ דַרְכָּם וְלֹא חִבְּרוּ יוֹם עִם לַיְלָה, מִשּׁוּם שֶׁלֹּא הִשְׁתַּדְּלוּ כָּרָאוּי לְחַבֵּר לָבָן עִם אָדם כְּדֵי לְכַפֵּר אוֹתוֹ חֵטְא שֶׁלּוֹ, שֶׁהִפְרִידָם בַּתְּחִלָּה. כְּשֶׁמָּכַר אֶת אוֹתוֹ צַדִּיק שֶׁנִּקְרָא יוֹם, שֶׁהִפְרִידוֹ מִכְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת לַיְלָה. רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְקָרֵב מִזְרָח בְּמַעֲרָב, וְאָמַר לוֹ, (במדבר ב) וְהַחֹנִים קֵדְמָה מִזְרָחָה דֶּגֶל מַחֲנֵה יְהוּדָה, לְקָרֵב מִזְרָח לַמַּעֲרָב לָתֵת לוֹ שֶׁפַע בְּרָכוֹת מִלְמַעְלָה."],[2,"","וּבְנֵי יוֹסֵף וּבִנְיָמִין, אַף עַל גַּב שֶׁבִּנְיָמִין הָיָה נִדְבָּק בַּמִּזְרָח, רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לַחֲנוֹת בַּמַּעֲרָב לְקָרֵב כְּנֶסֶת יִשְׂרָאֵל לַצַּדִּיק הַכֹּל בְּדֶרֶךְ יָשָׁר. זֶהוּ שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּקִים יֵלְכוּ בָם. וּרְאוּבֵן שֶׁנִּדְבַּק בְּצַד הַחֶסֶד, יַחֲנֶה בַדָּרוֹם. וְדָן, כְּדֵי לְכַפֵּר עַל אוֹתוֹ חֵטְא הָעֵגֶל שֶׁיְּקַבְּלוּ בָנָיו, וְהוּא מִצַּד הַצָּפוֹן, יַחֲנֶה בַצָּפוֹן לְכַפֵּר עַל אוֹתוֹ חֵטְא."],[3,"","מִשּׁוּם כָּךְ כָּתוּב בַּיָּם שֶׁעָשָׂה שְׁלֹמֹה עֲשָׂרָה עַל עֲשָׂרָה, (מלכים א ז) וְחוּט שְׁלֹשִׁים בָּאַמָּה יִסּוֹב. הַכֹּל בְּסוֹד הַחָכְמָה. כָּתוּב בּוֹ (שם) עֹמֵד עַל שְׁנֵי עָשָׂר בָּקָר שְׁלֹשָׁה פֹנִים צָפוֹנָה וּשְׁלֹשָׁה פֹנִים יָמָּה וּשְׁלֹשָׁה פֹּנִים נֶגְבָּה וּשְׁלֹשָׁה פֹּנִים מִזְרָחָה וְהַיָּם עֲלֵיהֶם מִלְמָעְלָה. אוֹתוֹ יָם שֶׁל חָכְמָה נִתְקַן בָּהֶם."],[4,"","בֹּא רְאֵה, כְּשֶׁהָיוּ עוֹשִׂים הַכֹּהֲנִים אֶת אוֹתָהּ חַטָּאת, לְכַפֵּר עַל עֲבֵרוֹת שֶׁל לֹא תַעֲשֶׂה זֶה הָיָה, שֶׁיֵּשׁ בָּהֶם כָּרֵת. וְעוֹלָה בָּאָה עַל מִי שֶׁלֹּא עוֹשֶׂה מִצְווֹת עֲשֵׂה, וּמֵאוֹתוֹ צַד בָּאָה הָעוֹלָה שֶׁהִיא זָכָר, וְכָתוּב (שמות כ) זָכוֹר אֶת יוֹם הַשַּׁבָּת - מִצְוַת עֲשֵׂה, וְלָכֵן אָנוּ מַקְרִיבִים בְּשַׁבָּת שְׁנֵי כְבָשִׂים, שֶׁל מוּסַף עוֹלָה, מִשּׁוּם שֶׁבְּאוֹתוֹ שֶׁל הַיָּמִין נִתּוֹסֵף לְאוֹתוֹ צַדִּיק אוֹר מֵהָעַתִּיק הַקָּדוֹשׁ. כְּשֶׁנִּדְבָּק עִם כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא שָׁמוֹר, לֹא תַעֲשֶׂה."],[5,"","מִשּׁוּם כָּךְ יֵשׁ בְּשַׁבָּת עֲשֵׂה וְלֹא תַעֲשֶׂה שֶׁיֵּשׁ בּוֹ כָּרֵת, שֶׁהֲרֵי מִי שֶׁעוֹשֶׂה פְגָם בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא לֹא תַעֲשֶׂה, וּמַפְרִיד אֶת הַזִּוּוּג שֶׁלָּהֶם, נִכְרֶתֶת מִשָּׁם נַפְשׁוֹ, וּמִיהוּ? מִי שֶׁעוֹשֶׂה מַעֲשִׂים שֶׁל חֹל בְּשַׁבָּת, בַּקֹּדֶשׁ שֶׁנִּדְבָּק בְּשַׁבָּת בְּשַׁבָּתוֹן, וְכָל הָעוֹלָמוֹת בְּחֶדְוָה בְּאוֹרָה. אֲבָל מִי שֶׁלֹּא עוֹשֶׂה אֶלָּא בִּשְׁגָגָה, מַקְרִיב חַטָּאת כְּנֶגֶד אוֹתָהּ דַּרְגַּת מִזְבֵּחַ."],[6,"","וּבְרֹאשׁ חֹדֶשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה אָנוּ מַקְרִיבִים (במדבר כח) פָּרִים בְּנֵי בָקָר שְׁנַיִם, שֶׁהֲרֵי מִצַּד שֶׁל פָּרָה אֲדֻמָּה תְּמִימָה בָּאוּ, וְהֵם לְמַעְלָה לְהַשְׁלִים אֶת הַפְּגָם שֶׁלָּהּ וְלָתֵת לָהּ שֶׁפַע אֶחָד עַל שְׁנַיִם מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עוֹלָה, וְנוֹסָף בְּאוֹתוֹ זְמַן אוֹר לַלְּבָנָה. וְאַיִל אֶחָד - לְהַקְרִיב לָהּ אֵילוֹ שֶׁל יִצְחָק, (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי,"],[7,"","כְּבָשִׂים בְּנֵי שָׁנָה שִׁבְעָה, לְחַבֵּק אוֹתָהּ בְּיָמִין, וְשִׁבְעָה זְכָרִים נִקְרָבִים עִמָּהּ, תְּמִימִים שְׁלֵמִים בַּכֹּל, וְאָנוּ מַקְרִיבִים שְׂעִיר עִזִּים אֶחָד לְחַטָּאת. שֶׁחַטָּאת הַזּוֹ בָּאָה מִצַּד זֶה שֶׁל פַּר הַחַטָּאת, שֶׁכָּתוּב שָׁמוֹר, וְשָׁמוֹר לֹא תַעֲשֶׂה הוּא, וְאָנוּ מַקְרִיבִים שְּׂעִיר חַטָּאת שֶׁבָּא עַל לֹא תַעֲשֶּׂה. בַּמּוּסָף שֶׁלָּהּ בְּרֹאשׁ חֹדֶשׁ, שֶׁבָּא לְכַפָּרָה עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, שֶׁכָּתוּב (יחזקאל מג) וְלֹא יְטַמְּאוּ עוֹד בֵּית יִשְׂרָאֵל שֵׁם קָדְשִׁי, שֶׁלֹּא יִתְקָרֵב לִכְנֶסֶת יִשְׂרָאֵל עָרֵל וְטָמֵא."],[8,"","אֲבָל מוּסָף שֶׁל שַׁבָּת אֵין לְהַקְרִיב, מִשּׁוּם שֶׁהֲרֵי הִתְגַּלָּה הָעַתִּיק הַקָּדוֹשׁ, וּמֵאִיר בְּאוֹתוֹ רָצוֹן לְכָל הָעוֹלָמוֹת, וְהַכֹּל נִמְצָא בְּהֶאָרָה, שֶׁהֲרֵי שַׁבָּת הִיא בְּלִי דִין כְּלָל, וְלֹא שׁוֹלֵט הַנָּחָשׁ הֶעָקֹם. וְכֹהֲנִים מִצַּד הַחֶסֶ\"ד שׁוֹחֲטִים אוֹתוֹ בִּצְפוֹן הַמִּזְבֵּחַ, וַאֲפִלּוּ יִשְׂרָאֵל יְכוֹלִים לַעֲשׂוֹת, פְּרָט לָזֶה שֶׁאֵין לָהֶם רְשׁוּת לִקְרַב לְאוֹתוֹ מִזְבֵּחַ לְהַקְרִיב, אֲבָל לִשְׁחֹט מֻתָּר."],[9,"","וּבַצָפוֹן הוּא מְקוֹמוֹ שֶׁל אוֹתוֹ שָׂעִיר, שֶׁהֲרֵי שָׂעִיר יוֹנֵק מִצָּפוֹן, וְאָנוּ מַקְרִיבִים דָּם לַמִּזְבֵּחַ, וְעוֹשִׂים אַרְבַּע מַתָּנוֹת עַל אַרְבַּע קְרָנוֹת כְּדֵי לְהַקִּיפוֹ מִכָּל הַצְּדָדִים, שֶׁלֹּא יִתְקָרֵב מִי שֶׁלֹּא רָאוּי לִקְרַב לְקֹדֶשׁ הַקְּדָשִׁים. וְחַטָּאת זוֹ שֶׁעוֹשֶׂה מִמֶּנָּה הִיא קֹדֶשׁ הַקְּדָשִׁים, שֶׁלֹּא יִתְעוֹרֵר צַד הַטֻּמְאָה מִמֶּנּוּ בָּעוֹלָם."],[10,"","וּבֹא וּרְאֵה, בָּעוֹלָה שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע, סוֹד הַיִּחוּד שֶׁמִּתְיַחֵד עוֹלָה בַּמִּזְבֵּחַ. אֲבָל חַטָּאת אַרְבַּע מַתָּנוֹת, שֶׁאֵינָם אֶלָּא לִשְׁמֹר וּלְהַקִּיף אוֹתָם גִּבּוֹרִים שֶׁהֵם מִצַּד הַגְּבוּרָה, לְאוֹתוֹ מַטָּה כִּסֵּא קָדוֹשׁ, וּלְהַשְׁלִים אוֹתוֹ פְגָם שֶׁעָשׂוּ בָהּ. וּמִי שֶׁגָּרַם לִבְנֵי אָדָם לַעֲשׂוֹת אוֹתוֹ חֵטְא, בָּא מִצַּד הַשָּׂעִיר, לָכֵן חַטָּאת יָחִיד שְׂעִירָה, וְחַטָּאת נָשִׂיא שָׂעִיר, וְחַטָּאת כֹּהֵן מָשִׁיחַ פַּר. הַכֹּל מִצַּד שְׂמֹאל."]]],[["וּלְזִמְנִין קַרִיב יָחִיד כִּשְׂבָּה לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל וְכֻלְהוּ שְׁאָר מִצְוֹת. אֶלָּא בַּעֲבוֹדָה זָרָה דְּצִבּוּר מְקָרְבִין פָּר לְעוֹלָה וְשָׂעִיר לְחַטָּאת וְהַהוּא חַטָּאת חֲסֵר אִיהוּ בְלֹא אַלֶף. בְּגִין דְּאִיהוּ גְרִיעוּת סַגִּיאָה דְּהָא חַטָּאת לִישָׁנָא דִגְרִיעָא הוּא דִכְתִיב (מלכים א א׳:כ״א) וְהֲיִיתִּי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים. וְכָל חַד עֵז בַּת שְׁנָתוֹ מִסִּטְרָא דִשְׂמָאלָא. וְהַהוּא פָּר דוֹרוֹן לְעֵילָא אִיהוּ לְצַדִּיק דְּאַפְרִידוּ הַהוּא אֲרוֹן מֵהַהוּא בְּרִית. וְשָׂעִיר לְחַטָּאת לְקֳבֵל כְּנֶסֶת יִשְׂרָאֵל דְּמָנְעוּ מִינָהּ בִּרְכָאָן. וְעִם כָּל דָּא יָחִיד כַּד חָב בְּכֻלְּהוּ מִצְוֹת לא תַעֲשֶׂה דְּאִית בְּהוּ כָּרֵת. שְׂעִירָת עִזִים בָּעֵי לְקָרְבָא לְכַתְּחִלָּה, אֶלָּא כַּד לֵית לֵיהּ דְּיַקְרִיב כִּשְׂבָּה.","וְתָּא חֲזֵי כְּנֶסֶת יִשְׂרָאֵל רְבִיעִית הִיא לְיוֹמֵי וּבְגִין כָּךְ ד' מָתָּנוֹת בַּעְיָא, וְסַלִּיק הַהוּא רֵיחַ נִיחֹחַ מֵאִינוּן אִמְרִין. וּכְדֵין נְיָיחָא לכְּנֶסֶת יִשְׂרָאֵל וְלָא עֲבְדַת נוּקְמִין דְּהָא בְּשׁוֹגֵּג הֲוָה.","(במדבר כ״ח:ט״ז) וּבַחוֹדֶשׁ הָרִאשׁוֹן דְּאִיהוּ אַרְבָּעָה עַל עֲשַׂר עַבְדִינָן פֶּסַח בְּגִין דְּיֶהוֶי דְכִיר לָן לְעֲלָם הוּא פֶּסַח דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל, דְּקָטַל הַהוּא טָלֶה וְאַפִּיק שְׁכִינְתָּא וְיִשְׂרָאֵל מֵאַתְרָא מְסָאָבָא וְאִתְחַבָּר אַרְבָּעָה בְּעֲשוֹר כְּנֶסֶת יִשְׂרָאֵל אִתְחַבְּרָא בְּעֲשוֹר דְּאִיהוּ צַדִּיק וְרָמִיז אַתְרֵיהּ בְּעֶשֶׂר. וּכְדֵין פֶּסַח לַיְיָ,","וּבְגִין כָּךְ מַאן דְּאִיהוּ טָהוֹר וְיִסְתַּלַּק מִנֵּיהּ הַהוּא עָרְלָה וְיִתְחָזֵי רְשִׁימָא קַדִּישָׁא דְצָדִי\"ק דְּאִיהוּ י' בֵּיהּ וְלָא קָרִיב פֶּסַח לַיְיָ (דאיהו) כְּנֶסֶת יִשְׂרָאֵל לְצַדִּיק דְהוּא חֲזֵי לְקָרְבָא לְמַקְדְּשָׁא וְלֹא עָרֵל וְטָמֵא, דְּאִי לָא קַרִיב אִית בֵּיהּ כָּרֵת.","וּמַאי טַעְמָא דְּהָא כָּל אוֹרַיְיתָא לָא אִית בָּהּ כָּרֵת אֶלָּא עַל מִצְוֹת לא תַעֲשֶׂה. מַאי (ומאי) טַעְמָא בְּפֶּסַח וּמִילָּה דְּאִינוּן מִצְוֹת עֲשֵׂה כָּרֵת. אֶלָּא בְּגִין דְדַרְגָא קַא גָרִים דְּאִיהִי כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי פֶּסַח, וְאִקְרֵי (אקרי) מִצְוֹת לא תַעֲשֶׂה, בַּעְיָא לְאִתְחַבְּרָא בַּעֲשֵׂה וּלְאִתְכַּלְלָא בֵּיהּ מִדַּת לַיְלָה בְּיוֹם. וּמַאן אִיהוּ דָא צַדִּי\"ק, דְּאִיהוּ מִילָה וּמִצְוֹת עֲשֵׂה וְאִתְכְּלִיל בְּמִצְוֹת לא תַעֲשֶׂה מִדַּת יוֹם בַּלַּיְלָה. וְאִי לָא אִתְגְּזַר בָּר נָשׁ לָא אִתְחֲזֵי לְקָרְבָא לוֹן,","בְּגִין כָּךְ קַיָימָא מִצְוַת לֹא תַעֲשֶׂה עָלֵיהּ וְדַיְינָת לֵיהּ בְּכָּרֵת, דְּלָא יֵיעוּל נַפְשֵׁיהּ לְמַקְדְּשָׁא. וְכֵן בְּפֶּסַח בַּעְיָא כְּנֶסֶת יִשְׂרָאֵל לְאִתְחַבְּרָא בְּבַעְלָהּ וְאִי לָא עֲבִיד בָּר נָשׁ וְלָא קַרִיב פֶּסַח לַיְיָ, קַיָימָא עָלֵיהּ וְדַיְינָת לֵיהּ וְלָא אַפִּיקַת יָתֵיהּ מִתְּחוֹת יְדָא דְפַרְעֹה וְאִשְׁתַּצִיאַת נַפְשֵׁיהּ מֵאַתְרָא קַדִּישָׁא, וְאִשְׁתָּאַרַת בְּאַתְרָא מְסָאָבָא בְּמִצְרָיִם. דְּהָא יִשְׂרָאֵל אִי לָא עֲבִידוּ הֲנֵי תְּרֵין פִּקּוּדִין לָא נַפְקוּ מִתַּמָּן.","וּבְגִין כָּךְ כְּתִיב (דבהם י\"ז) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַיְיָ אֱלֹהֶיךָ. שָׁמוֹר, כְּלָלָא דְנוּקְבָא לא תַעֲשֶׂה. אֶת, כְּלָלָא דְכוֹלָא. חֹדֶשׁ הָאָבִיב דְּהָא בְּהַהוּא שַׁעְתָּא שְׂעוֹרָה אֲבִיב וּמְקָרְבִין מִנֵּיהּ עוֹמֶר עֲשִׂירִית הָאֵיפָה מִמָחֳרָת הַשַּׁבָּת אִיהוּ, וְסַפְרִין שֶׁבַע שְׁבוּעִין שְׁלֵמִין לְאִסְתַּלְקָא לְעֵילָא וּלְקַבְּלָא מֵאִינוּן חַמְשִׁין יוֹמִין עִלָּאִין דְּאִימָא עִלָּאָה אוֹרַיְיתָא. דְּאִקְרֵי לֶחֶם דִכְתִיב (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְּלַחְמִי.","וַאֲנָן מְקָרְבִין בְּיוֹמָא דְּחַמְשִׁין דְאִתְיְיהִיב בֵּיהּ אוֹרַיְיתָא שְׁתֵּי הַלֶּחֶם, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וְנָחִית טִיבוּ דְּעַתִּיקָא קַדִּישָׁא דְּאִימָא עִלָּאָה בְּאִינוּן שֶׁבַע שְׁבוּעִין שְׁלִימָן בְּכוֹלָא. וְכָל חַד מֵאִינוּן שֶׁבַע דַּרְגִּין כַּלִיל בְּשִׁבְעָה כְּדְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא.","בְּגִין כָּךְ (דברים ט״ז:א׳) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַיְיָ, קַרִיב לוֹן בְּיִחוּדָא. דְּהָא בֵּיהּ אֲפְּקַךְ מִמִּצְרָיִם לַיְלָה, וְתַשְׁלִים לְהַאי דַּרְגָא דְּאִקְרֵי לֵיל שִׁמּוּרִים, וְתַּקְרִיב דְכוּרָא לְגַבָּהּ וְתִתְקְרֵי לַיְלָה שְׁלֵימָא. וְתָּא חֲזֵי נַעֲרָה בְּתוּלָה עַד לָא אִתְקַרִיב דְכוּרָא לְגַבָּהּ אִקְרֵי נַעַר, לְבָתָר אִקְרֵי נַעֲרָה. הֲדָא הוּא דִכְתִיב (דברים כ״ב:י״ט) וְנָתְנוּ לַאֲבִי הַנַּעֲרָה, שְׁלֵימָא דַּיְיקָא. וְדָא אִיהוּ כַּד אִשְׁתַּכְּחַת שְׁלֵימָא וְלָא אִתְקַרִיב מַאן (ס\"א למאן) דְלָא אִתְחֲזֵי. אוּף הָכָא בְּקַדְמִיתָא לֵיל שִׁמּוּרִים לְבָתָר, הַלַּיְלָה הַזֶּה לַיְיָ, כַּד אִתְקַרִיב זֶה לְזֹאת.","בְּגִין כָּךְ לָא אִתְחֲזֵי לְאִתְקָרְבָא בְּהַהוּא פֶּסַח עָרֵל וְטָמֵא. וְדָמָהּ טָעוּן מַתָּנָה אַחַת דַּיְיקָא, כְּמָה דָּא אָמֵר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. הִיא נָטְרָת בְּנָהָא דְלָא יִסְתַּאֲבוּן בְּנִמוּסָיְיהוּ יִשְׂרָאֵל, בְּגִין כָּךְ שִׁבְטֵי יָהּ נַפְקוּ מִתַּמָּן וְאִתְחַבְּרַת יוֹ\"ד בָּה\"א וְלָא בַּאֲתַר אַחֲרָא כְּמָה דְּעָבְדוּ אִינוּן.","אֲבָל כַּד נַפְקוּ מִבָּבֵל דְּאִסְתָאֲבוּ תַמָּן, סָאִיבוּ מַקְדְּשָׁא. בְּגִין כָּךְ חִוְיָּיא שָׁלִיט בְּהוּ וְלָא אִשְׁתְּכַח שׁוּלְטָנוּתָא לְיִשְׂרָאֵל בְּהַהוּא זִמְנָא, בְּגִין דְּסָאִיבוּ מַקְדְּשָׁא בַּנָּשִׁים נָכְרִיּוֹת. מִכָּאן מַאן דִּמְסָאֵב גַּרְמֵיהּ לְתַתָּא, מְסָאֵב לְעֵילָא. וּמַאן דְּקַדִּישׁ גַּרְמֵיהּ לְתַתָּא מְקַדֵּשׁ לְעֵילָא. וְעַל דָא רְאוּיִּין הֲווּ דְּיִתָעֲבַד לְהוּ נִיסָא בְּהַהִיא שַׁעְתָּא דְּנַפְקוּ מִבָּבֶל כְּשָׁעְתָּא דְּנַפְקוּ מִמִּצְרָיִם. אֶלָּא דְּגָרִים חוֹבָא.","וּבַחֲמִשָׁה עֲשָׂר לְיָרְחַא קַדְמָאָה חוּלָקָא דְאַבְרָהָם דְּאִיהוּ קַדְמָאָה וְאַחִיד בְּדַרְגָּא דְחֶסֶ\"ד. אֲנָן מַקְרִיבִין לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין פָּרִים לְאוֹסָפָא תְּרֵין חוּלָקִין לְדַרְגָּא דְחֶסֶד מֵעַתִּיקָא קַדִּישָׁא. אַיִל אֶחָד לְקֳבֵל דַּרְגָא דְיִצְחָק וּבָעֵינָן אַיִל לִישָׁנָא דְּתַקִיפוּ, בְּגִין דְּחוּלָקַא דִּידֵיהּ תַּקִּיפוּ מַיָא. וּבָעֵינָן דְּיִסְתָּכַּם הַהוּא דַּרְגָא דִּגְבוּרָ\"ה בְּחֶסֶד עִלָּאָה לְמֶעְבַּד טִיבוּ עִם כָּל יִשְׂרָאֵל. וּלְאִתְפָּרְעָא מֵאִינוּן דְּעֲאקִין לוֹן וּלְאַסְחֲרָא לֵיהּ סִטְרָא דְּמַיִּין, הַאי דִכְתִיב (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן."],[],[[0,"","וְלִפְעָמִים מַקְרִיב יָחִיד כִּשְׂבָּה כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל וְכָל שְׁאָר הַמִּצְווֹת. אֶלָּא בַּעֲבוֹדָה זָרָה שֶׁל צִבּוּר מַקְרִיבִים פַּר לְעוֹלָה וְשָׂעִיר לְחַטָּאת, וְאוֹתוֹ חַטָּאת הוּא חָסֵר בְּלִי אָלֶ\"ף, מִשּׁוּם שֶׁהוּא חִסָּרוֹן גָּדוֹל, שֶׁהֲרֵי חַטָּאת הוּא לָשׁוֹן שֶׁל חִסָּרוֹן, שֶׁכָּתוּב (מלכים א כא) וְהָיִיתִי אֲנִי וּבְנִי שְׁלֹמֹה חַטָּאִים. וְכָל אֶחָד עֵז בַּת שְׁנָתוֹ, מִצַּד הַשְּׂמֹאל. וְאוֹתוֹ הַפָּר דּוֹרוֹן הוּא לְמַעְלָה לַצַּדִּיק, שֶׁהִפְרִידוּ אוֹתוֹ אָרוֹן מֵאוֹתָהּ בְּרִית, וְשָׂעִיר לְחַטָּאת כְּנֶגֶד כְּנֶסֶת יִשְׂרָאֵל שֶׁמָּנְעוּ מִמֶּנָּה בְּרָכוֹת. וְעִם כָּל זֶה, כְּשֶׁיָּחִיד חָטָא בְּכָל מִצְווֹת שֶׁל לֹא תַעֲשֶׂה שֶׁיֵּשׁ בָּהֶם כָּרֵת, צָרִיךְ לְהַקְרִיב שְׂעִירַת עִזִּים לְכַתְּחִלָּה, אֶלָּא כְּשֶׁאֵין לוֹ שֶׁיַּקְרִיב כִּשְׂבָּה."],[1,"","וּבֹא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל הִיא רְבִיעִית לַיָּמִים, וְלָכֵן צְרִיכָה אַרְבַּע מַתָּנוֹת, וְעוֹלֶה אוֹתוֹ רֵיחַ נִיחוֹחַ מֵאוֹתָם כְּבָשִׂים, וְאָז יֵשׁ נַחַת רוּחַ לִכְנֶסֶת יִשְׂרָאֵל וְלֹא עוֹשָׂה נְקָמוֹת, שֶׁהֲרֵי זֶה הָיָה בְּשׁוֹגֵג."],[2,"","(במדבר כח) וּבַחֹדֶשׁ הָרִאשׁוֹן - שֶׁהוּא אַרְבָּעָה עַל עֶשֶׂר עוֹשִׂים פֶּסַח, כְּדֵי שֶׁיִּהְיֶה זוֹכֵר לָנוּ לְעוֹלָם אוֹתוֹ פֶּסַח שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל. שֶׁהִכָּה אֶת אוֹתוֹ טָלֶה, וְהוֹצִיא הַשְּׁכִינָה וְיִשְׂרָאֵל מִמָּקוֹם טָמֵא, וְהִתְחַבֵּר אַרְבָּעָה עִם עָשׂוֹר, כְּנֶסֶת יִשְׂרָאֵל הִתְחַבְּרָה בֶּעָשׂוֹר שֶׁהוּא צַדִּיק, וְרָמוּז מְקוֹמוֹ בְּעֶשֶׂר, וְאָז פֶּסַח לַה'."],[3,"","וְלָכֵן מִי שֶׁהוּא טָהוֹר וְסֻלְּקָה מִמֶּנּוּ אוֹתָהּ עָרְלָה, וְיֵרָאֶה רֹשֶׁם קָדוֹשׁ שֶׁל צַדִּיק, שֶׁהוּא י' בּוֹ, וְלֹא הִקְרִיב פֶּסַח לַה', כְּנֶסֶת יִשְׂרָאֵל לַצַּדִּיק, שֶׁהוּא רָאוּי לִקְרַב לַמִּקְדָּשׁ וְלֹא עָרֵל וְטָמֵא. שֶׁאִם לֹא הִקְרִיב, יֵשׁ בּוֹ כָּרֵת."],[4,"","וּמָה הַטַּעַם? שֶׁהֲרֵי בְּכָל הַתּוֹרָה אֵין כָּרֵת אֶלָּא עַל מִצְווֹת לֹא תַעֲשֶׂה, מָה (ומה) הַטַּעַם בְּפֶסַח וּמִילָה, שֶׁהֵם מִצְווֹת עֲשֵׂה, יֵשׁ כָּרֵת? אֶלָּא מִשּׁוּם שֶׁהַדַּרְגָּה גּוֹרֶמֶת שֶׁהִיא כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא פֶּסַח, וְנִקְרֵאת (נקראת) מִצְווֹת לֹא תַעֲשֶׂה, צְרִיכָה לְהִתְחַבֵּר עִם עֲשֵׂה וּלְהַכְלִיל בּוֹ מִדַּת לַיְלָה עִם יוֹם. וּמִיהוּ,? זֶה צַדִּיק, שֶׁהִיא מִילָה וּמִצְוַת עֲשֵׂה, וְנִכְלָל בְּמִצְוַת לֹא תַעֲשֶׂה מִדַּת יוֹם בְּלַיְלָה. וְאִם לֹא נִמּוֹל בֶּן אָדָם, לֹא רָאוּי לְהַקְרִיב אוֹתָם,"],[5,"","לָכֵן עוֹמֶדֶת מִצְוַת לֹא תַעֲשֶׂה עָלָיו, וְדָנָה אוֹתוֹ בְּכָרֵת, שֶׁלֹּא תִכָּנֵס נַפְשׁוֹ לַמִּקְדָּשׁ. וְכֵן בְּפֶסַח צְרִיכָה כְּנֶסֶת יִשְׂרָאֵל לְהִתְחַבֵּר עִם בַּעְלָהּ. וְאִם בֶּן אָדָם לֹא עוֹשֶׂה וְלֹא מַקְרִיב פֶּסַח לַה', הִיא עוֹמֶדֶת עָלָיו וְדָנָה אוֹתוֹ, וְלֹא מוֹצִיאָה אוֹתוֹ מִתַּחַת יַד פַּרְעֹה, וְנִכְרֶתֶת נַפְשׁוֹ מִמָּקוֹם קָדוֹשׁ, וְנִשְׁאֶרֶת בִּמְקוֹם טֻמְאָה בְּמִצְרַיִם, שֶׁהֲרֵי אִם לֹא עָשׂוּ יִשְׂרָאֵל שְׁתֵּי מִצְווֹת אֵלּוּ, לֹא יָצְאוּ מִשָּׁם."],[6,"","וְלָכֵן כָּתוּב (דברים טז) שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַה' אֱלֹהֶיךְ. שָׁמוֹר - כְּלָלוּת שֶׁל נְקֵבָה, לֹא תַעֲשֶׂה. אֶת - כְּלָלוּת שֶׁל הַכֹּל. חֹדֶשׁ הָאָבִיב - שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה שְׂעוֹרָה אָבִיב, וּמַקְרִיבִים מִמֶּנּוּ עֹמֶר עֲשִׂירִית הָאֵיפָה מִמָּחֳרַת הַשַּׁבָּת הִיא, וְסוֹפְרִים שִׁבְעָה שָׁבוּעוֹת שְׁלֵמִים לַעֲלוֹת לְמַעְלָה, וּלְקַבֵּל מֵאוֹתָם חֲמִשִּׁים יָמִים עֶלְיוֹנִים שֶׁל הָאֵם הָעֶלְיוֹנָה תּוֹרָה שֶׁנִּקְרֵאת לֶחֶם, שֶׁכָּתוּב (משלי ט) לְכוּ לַחֲמוּ בְלַחְמִי."],[7,"","וְאָנוּ מַקְרִיבִים בְּיוֹם הַחֲמִשִּׁים שֶׁנִּתְּנָה בּוֹ תּוֹרָה שְׁתֵּי הַלֶּחֶם, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, וְיוֹרֵד חֶסֶד שֶׁל הָעַתִּיק הַקָּדוֹשׁ שֶׁל הָאֵם הָעֶלְיוֹנָה (בינה) בְּאוֹתָם שִׁבְעָה שָׁבוּעוֹת שְׁלֵמִים בַּכֹּל, וְכָל אַחַת מֵאוֹתָן שֶׁבַע דְּרָגוֹת כְּלוּלָה בְּשִׁבְעָה, כְּפִי שֶׁבֵּאַרְנוּ בְּסוֹד הָאֱמוּנָה."],[8,"","לָכֵן שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב וְעָשִׂיתָ פֶּסַח לַה'. הַקְרֵב אוֹתָם בְּיִחוּד, שֶׁהֲרֵי בּוֹ הוֹצִיאֲךְ מִמִּצְרַיִם לַיְלָה, וְתַשְׁלִים אֶת הַדַּרְגָּה הַזּוֹ שֶׁנִּקְרֵאת לֵיל שִׁמּוּרִים, וְתַקְרִיב זָכָר אֵלֶיהָ וְתִקָּרֵא לַיְלָה שָׁלֵם. וּבֹא תִרְאֶה, נַעֲרָה בְתוּלָה, עַד שֶׁלֹּא קָרַב אֵלֶיהָ זָכָר, נִקְרֵאת נַעַר. אַחַר כָּךְ נִקְרֵאת נַעֲרָה. זֶהוּ שֶׁכָּתוּב (דברים כב) וְנָתְנוּ לַאֲבִי הַנַּעֲרָה, שְׁלֵמָה דַּוְקָא. וְזֶהוּ כְּשֶׁנִּמְצֵאת שְׁלֵמָה, וְלֹא הִתְקָרֵב מִי (למי) שֶׁלֹּא רָאוּי. אַף כָּאן, בַּתְּחִלָּה לֵיל שִׁמּוּרִים, אַחַר כָּךְ הַלַּיְלָה הַזֶּה לַה', כְּשֶׁמִּתְקָרֵב זֶה לְזֹאת,"],[9,"","וְלָכֵן לֹא רָאוּי לְהִתְקָרֵב לְאוֹתוֹ פֶּסַח עָרֵל וְטָמֵא. וְדָמָהּ טָעוּן מַתָּנָה אַחַת דַּוְקָא, כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. הִיא שׁוֹמֶרֶת אֶת בָּנֶיהָ יִשְׂרָאֵל שֶׁלֹּא יִתְטַמְּאוּ בְּמִנְהֲגֵיהֶם, מִשּׁוּם כָּךְ שִׁבְטֵי יָהּ יָצְאוּ מִשָּׁם, וְהִתְחַבְּרָה יוֹ\"ד בְּהֵ\"א, וְלֹא בְּמָקוֹם אַחֵר, כְּמוֹ שֶׁעָשׂוּ הֵם."],[10,"","אֲבָל כְּשֶׁיָּצְאוּ מִבָּבֶל, נִטְמְאוּ שָׁם וְטִמְּאוּ הַמִּקְדָּשׁ, מִשּׁוּם כָּךְ הַנָּחָשׁ שָׁלַט בָּהֶם, וְלֹא נִמְצָא שִׁלְטוֹן לְיִשְׂרָאֵל בְּאוֹתוֹ זְמַן, מִשּׁוּם שֶׁטִּמְּאוּ אֶת הַמִּקְדָּשׁ בְּנָשִׁים נָכְרִיּוֹת. מִכָּאן, מִי שֶׁמְּטַמֵּא אֶת עַצְמוֹ לְמַטָּה, הוּא טָמֵא לְמַעְלָה. וּמִי שֶׁמְּקַדֵּשׁ עַצְמוֹ לְמַטָּה, מְקֻדָּשׁ לְמַעְלָה. וְעַל כָּךְ הָיוּ רְאוּיִים שֶׁיֵּעָשֶׂה לָהֶם נֵס בְּאוֹתָהּ שָׁעָה שֶׁיָּצְאוּ מִבָּבֶל כְּאוֹתָהּ שָׁעָה שֶׁיָּצְאוּ מִמִּצְרַיִם, אֶלָּא שֶׁגָּרַם הַחֵטְא."],[11,"","וּבַחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ הָרִאשׁוֹן הַחֵלֶק שֶׁל אַבְרָהָם, שֶׁהוּא רִאשׁוֹן וְאָחוּז בְּדַרְגַּת חֶסֶד, אָנוּ מַקְרִיבִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא שְׁנֵי פָרִים, לְהוֹסִיף שְׁנֵי חֲלָקִים לְדַרְגַּת חֶסֶד מֵהָעַתִּיק הַקָּדוֹשׁ. אַיִל אֶחָד כְּנֶגֶד דַּרְגַּת יִצְחָק, וְצָרִיךְ אַיִל, לָשׁוֹן שֶׁל תַּקִּיפוּת, מִשּׁוּם שֶׁחֶלְקוֹ חֹזֶק הַמַּיִם. וְצָרִיךְ שֶׁתַּסְכִּים אוֹתָהּ דַּרְגַּת הַגְּבוּרָה עִם חֶסֶד עֶלְיוֹן לַעֲשׂוֹת חֶסֶד עִם כָּל יִשְׂרָאֵל, וּלְהִפָּרַע מֵאוֹתָם שֶׁמְּצִיקִים לָהֶם, וּלְהַקִּיפוֹ צַד הַמַּיִם. זֶהוּ שֶׁכָּתוּב (בראשית ל) מַחְשּף הַלָּבָן."]]],[["שִׁבְעָה כְּבָשִׂים תְמִימִים. לְקֳבֵל כֻּלְּהוּ דַּרְגִּין דְּיִשְׁתַּלְּמוּן בֵּיהּ. וְכֵן בְּכָל יוֹמָא וְיוֹמָא שִׁבְעָה אִמְרִין בְּיוֹמָא קַדְמָאָה דְּכוּלְהוּ שִׁבְעָה יוֹמִין עִלָּאִין כָּל חַד אִשְׁתְּלִים בְּרָזָא דְשֶׁבַע וִיהוֹן שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת לְקֳבְּלָא נְהִירוּ עִלָּאָה דְּאוֹרַיְיתָא. שֵׂעִיר חַטָּאת לְכַפָּרָה עַל סָאִיבוּ דְּמָקְדְּשָׁא וְלָא יְהֵא לֵיהּ רֵשׁוּ לְהַהוּא שָׂעִיר לְעֲרְבְּבָא וְלָא לְאַסְטָנָא עַל יִשְׂרָאֵל.","(במדבר כ״ח:כ״ו) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה. לְקֳבֵל דַּרְגָא דְיַעֲקֹב דְּהָא כְּדֵין אִשְׁתְּלִים עַלְמָא וְאִתְחַדַּשׁ. וַאֲנָן מָנִינָן שֶׁבַע שְׁבוּעִין בְּגִין לְחַבְּרָא כֹּלָּא בְּיוֹבְלָא עִלָּאָה דְּיַהֲבָא לְהַאי בְּרָא בּוּכְרָא עֲטָרָה דְּאוֹרַיְיתָא דְּאִתְכַּלִילָת בְּמ\"ט אַנְפִּין וְנַפְקָא מֵחָכְמָה עִלָּאָה בְּאִינוּן חַמְשִׁין שַׁעֲרֵי בִּינָה. וְאִתְיְּיהִיבַת לְהַאי בְּרָא בּוּכְרָא עַל יְדֵי דְמֹשֶׁה דְאֲחִיד נָמֵי בְּהַאי דַּרְגָא הֲדָא הוּא דִכְתִיב (שיר השירים ג׳:י״א) צְאֵינָה וּרְאֵינָה בְּנוֹת צִיּוֹן בַּמֶלֶךְ שְׁלֹמֹה, בְּמַלְכָּא דִּשְׁלָמָא כֹּלָּא דִילֵיהּ. (והא) דְּהָא אוֹקִימְנָא דְּהַאי דַּרְגָא שְׁלִים מִכָּל סִטְרִין וּשְׁלִים אִקְרֵי בְּרָזָא דִמְהֵימְנוּתָא דִכְתִיב (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. בְּיוֹם חֲתוּנָתוֹ. דָא כַּד אִתְיְיהִיבַת (אורייתא). וּבְיוֹם שִׂמְחַת לִבּוֹ. כַּד אִתְבַּנֵי בֵּי מַקְדְּשָׁא:","תָּא חֲזֵי כְּתִיב בַּחֹדֶשׁ הַשְׁלִישִׁי דְאִתְחַבַּר הַאי דַּרְגָא דְּאִקְרֵי שְׁלִישִׁי בַּחֹדֶשׁ וְהִיא חֲתוּנָתוֹ, עַל דָא כְּתִיב (שמות י״ט:ב׳) וַיִּחַן שָׁם יִשְׂרָאֵל נֶגֶד הָהָר. הַאי דַּרְגָא בְּרָא בּוּכְרָא. נֶגֶד הָהָר לְקֳבֵל הַהוּא הַר דְּאִתְיָּידַע דְּאִיהוּ זְעֵיר מִכָּל טוּרַיָּא דִּלְעֵילָא דְּאִיהוּ רָם וְנָשָׂא כַּד אִתְחַבָּר לְעֵילָא וְאִקְרֵי הַר סִינַי דְּהָא ז' טוּרִין וְז' יוֹמִין וְז' אַרְצוֹת בָּרָא קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא דְּאִינוּן לְקֳבֵל שִׁבְעָה יוֹמִין עִלָּאִין וְלָא בָּחָר מִכֻּלְּהוּ לְמֵיהַב אוֹרַיְיתָא אֶלָּא בְּהַר סִינַי דְּאִיהוּ רָזָא דְּכְּנְסֶת יִשְׂרָאֵל,","וּבְיָם כִּנֶרֶת נָמֵי דְאָתֵי מִתַּמָּן תְּכֵלֶת דְּדָמֵי לְכִּסֵא הַכָּבוֹד. כְּנֶסֶת יִשְׂרָאֵל. כִּנֶרֶת דָא צַדִּי\"ק וְהַאי יָם דְּכִּנֶרֶת הוּא כְּדְאוּקְמוּהַ חַבְרַיָּיא. כִּנּוֹר הָיָה תָּלוּי לְמָעְלָה מִמִּטָתוֹ שֶׁל דָוִד, וּבְשָׁעָה שְׁרוּחַ צְפוֹנִית מְנַשֶׁבֶת בּוֹ מְנַגֵּן מֵאֵלָיו. וְדָוִד קָם לְמִלְעֵי בְּאוֹרַיְיתָא חֲצוֹת לַיְלָה לְאִתְחַבְּרָא בְּכְּנְסֶת יִשְׂרָאֵל. וּבְאֶרֶץ יִשְׂרָאֵל שְׁבִיעָאָה דְכוֹלָא נְקוּדָה אֶמְצָעִיתָּא דְּאַרְעָא תַּתָּאָה, בָּחַר קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהִי לְקֳבֵל נְקוּדָה עִלָּאָה.","מָאי טַעְמָא בֵּיהּ בְּהַר סִינַי דִּלְעֵילָא לְמֵיהַב בֵּיהּ אוֹרַיְיתָא שֶׁבִּכְתָב וְסִימָנִיךְ בְּהַאי אֲרוֹן לְמֵיהַב בֵּיהּ בְּרִית, בְּגִין דִּבְּהָאי אֲרוֹן מוּנָחִין כָּל גְנִיזִין טָבִין, וְתוֹרָה שֶׁבִּכְתָב דְּאִקְרֵי בְּרִית בֵּיהּ מוּנָחָא. וְכָל מָאנֵי קְרָבָא דְּמַלְכָּא בִּידֵיהּ אִתְמְסָרוּ, וְכֻלְּהוּ עָלְמִין דִּלְתַתָּא מִינָהּ יַנְקִין. זָכוּ יִשְׂרָאֵל לְמֵיטַר אוֹרַיְיתָא כְּדֵין יַהֲבַת לוֹן כָּל טִיבוּ דְּעָלְמָא. וְאִי לָא כְּדֵין יַסְרָת לוֹן, הֲדָא הוּא דִכְתִיב (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְכַד תְּחַבֵּר בְּאֲנִ\"י דָּלֶ\"ת דִּילָה אִקְרֵי אֲדֹנָ\"י וְדַּיְינָא לְעָלְמָא.","בְּגִין כָּךְ כְּתִיב (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. בְּזֹאת אִתְיְיהִיבַת אוֹרַיְיתָא. תָּא חֲזֵי אוֹרַיְיתָא שֶׁבִּכְתָב צַדִּי\"ק אִקְרֵי, וּמוּנָח בְּזֹאת דְּהַאי בְּרִית מָנְחַא בֵּיהּ, דִכְתִיב אֲרוֹן הַבְּרִית בְּגִין דְּמוּנָח בֵּיהּ בְּרִית דְּאִיהוּ צַדִּי\"ק בְּגִין כָּךְ וְזֹאת הַתּוֹרָה אִתְחַבָּר וא\"ו בְּזֹאת וּכְדֵין אֲשֶׁר שָׂם מֹשֶׁה סַם חַיִּין לְעָלְמָא. דְּהָא אִילָנָא דְחַיֵּי אִתְדַבַּק בָּהּ.","וְכַד לָא מָכְשְׁרִין בְּנֵי נָשָׁא עוֹבַדָיְיהוּ, אִסְתְּלַק וא\"ו מִזֹאת. וּכְדֵין כְּתִיב (ויקרא י״ד:ב׳) זֹאת תִּהְיֶה תּוֹרַת הַמְצוֹרָע, וְזֶהוּ חָשׁוּב כַּמֵּת. וּכְתִיב (במדבר י״ט:י״ד) זֹאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל אִסְתָּלָק ו' מִזֹאת וְעָבִיד הַאי אֹהֶל נוּקְמִין, הַיְינוּ דִכְתִיב (שם) זֹאת חֻקַת הַתּוֹרָה אֲשֶׁר צִוָּה יְיָ. וּבְגִין דְּלָא אִתְחַבָּר ו' בְּה', גָּרְמוּ דְּסָאִיבוּ מַקְדְּשָׁא וְגָּרִימוּ לוֹן מוֹתָא. דְּהָא מַאן דְאַפְרִישׁ לוֹן, גָרִים מוֹתָא לְנַפְשֵׁיהּ,","עַד דְּאָתַת פָּרָה וְכִפְּרָה עַל בְּנָהּ. וְעַבְדִין מִינָהּ הַזָּאָה עַל טְמֵאֵי מֵתִים. זֹאת הַתּוֹרָה דְלָא אִתְחַבָּר בָּהּ וא\"ו עַד דְּעָבְדוּ הַזָּאַה לְאִינוּן כְּלֵי מִדְיָן. וּלְבָתָר (דברים ד') וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹ' חַיִּים אִתְדַבַּק בָּהּ.","(דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה, בְּרָכָה אִתְדַבַּק בָּהּ בְּהַאי זֹאת. אֲבָל כָּל אֲתַר דְּתִשְׁכַּח בְּאוֹרַיְיתָא זֹאת הַתּוֹרָה בְלא וא\"ו, בְּגִין חוֹבָה (ויקרא י״ג:נ״ט) זֹאת תּוֹרַת נְגַע צָרַעַת. (ויקרא י״ד:נ״ד) זֹאת הַתּוֹרָה לְכָל נְגַע הַצָרַעַת (במדבר ה׳:כ״ט) זֹאת תּוֹרַת הַקְנָאוֹת. בְּגִין דְּסָאִיבוּ גָּרְמֵיהוֹן וְסָאִיבוּ מַקְדְּשָׁא. (ויקרא ו׳:ב׳) זֹאת תּוֹרַת הָעוֹלָה, לָא כְּתִיב בֵּיהּ וא\"ו עַד דְּיַעֲבְדוּ לָהּ שְׁלִימוּ בְּנֵי אַהֲרֹן לְחַבְּרָא לְזֹאת בְּבַעְלָהּ.","(ויקרא ו׳:ז׳) וְזֹאת תּוֹרַת הַמִּנְחָה, לא אַתְיָיא עַל חֵטְא, דְּהָא נְדָבָה הִיא. אוֹ דְּאַתְיָיא עִם עוֹלָה וְהָא עַבְדָּא עוֹלָה שְׁלִימוּ. (ויקרא ו׳:ז׳) זֹאת תּוֹרַת הַחַטָּאת אַתְיָיא עַל חֵטְא דְּסָאִיבוּ לְהַאי זֹאת. וְזֹאת תּוֹרַת הַאֲשָׁם בְּגִין דְלָא עָבְדוּ כָּל כָּךְ פְּגִימוּ, וּבְגִין כָּךְ אַתְיָיא דְכוּרָא וְלָא נוּקְבָא (ויקרא ז׳:י״א) וְזֹאת תּוֹרַת זֶבַח הַשְּׁלָמִים בְּגִין דְאַתְיָין לִשְׁלָמָא אִתְחַבָּר בָּהּ וא\"ו. (שם) זֹאת הַתּוֹרָה לְעוֹלָה לַמִנְחָה וְלַחַטָאת, בְּגִין חַטָּאת דְּאִית בִּקְרָא, וְחוֹטֵּא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה."],[],[[0,"","שִׁבְעָה כְּבָשִׂים תְּמִימִים - כְּנֶגֶד כָּל הַדְּרָגוֹת שֶׁיִּשְׁתַּלְּמוּ בוֹ. וְכֵן בְּכָל יוֹם וָיוֹם שִׁבְעָה כְבָשִׂים, בַּיּוֹם הָרִאשׁוֹן שֶׁל כָּל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים, כָּל אֶחָד נִתְקָן בְּסוֹד שֶׁל שֶׁבַע, וְיִהְיוּ שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת לְקַבֵּל אֶת הָאוֹר הָעֶלְיוֹן שֶׁל הַתּוֹרָה. שְׂעִיר חַטָּאת לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ, וְלֹא תִהְיֶה רְשׁוּת לְאוֹתוֹ שָׂעִיר לְעַרְבֵּב וְלֹא לְהַסְטִין עַל יִשְׂרָאֵל."],[1,"","(במדבר כח) וּבְיוֹם הַבִּכּוּרִים בְּהַקְרִיבְכֶם מִנְחָה חֲדָשָׁה - כְּנֶגֶד דַּרְגַּת יַעֲקֹב, שֶׁהֲרֵי אָז נִתְקַן הָעוֹלָם וְהִתְחַדֵּשׁ, וְאָנוּ מוֹנִים שִׁבְעָה שָׁבוּעוֹת כְּדֵי לְחַבֵּר הַכֹּל בַּיּוֹבֵל הָעֶלְיוֹן, שֶׁנּוֹתֶנֶת לַבֵּן הַבְּכוֹר הַזֶּה עֲטָרָה שֶׁל תּוֹרָה שֶׁנִּכְלֶלֶת בְּאַרְבָּעִים וְתִשְׁעָה פָנִים, וְיָצְאָה מֵחָכְמָה הָעֶלְיוֹנָה בְּאוֹתָם חֲמִשִּׁים שַׁעֲרֵי בִינָה, וְנִתְּנָה לַבֵּן הַבְּכוֹר הַזֶּה עַל יְדֵי מֹשֶׁה שֶׁאָחוּז גַּם בְּדַרְגָּה זוֹ. זֶהוּ שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה, בַּמֶּלֶךְ שֶׁהַשָּׁלוֹם כֻּלּוֹ שֶׁלּוֹ. (והרי) שֶׁהֲרֵי בֵּאַרְנוּ שֶׁדַּרְגָּה זוֹ שְׁלֵמָה מִכָּל הַצְּדָדִים, וְשָׁלֵם נִקְרָא בְּסוֹד הָאֱמוּנָה, שֶׁכָּתוּב (בראשית כה) וְיַעֲקֹב אִישׁ תָּם. בְּיוֹם חֲתֻנָּתוֹ - זֶה כְּשֶׁנִּתְּנָה (תורה). וּבְיוֹם שִׂמְחַת לִבּוֹ - כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ."],[2,"","בֹּא רְאֵה, כָּתוּב (שמות יט) בַּחֹדֶשׁ הַשְּׁלִישִׁי, שֶׁהִתְחַבְּרָה דַרְגָּה זוֹ שֶׁנִּקְרֵאת שְׁלִישִׁי בַּחֹדֶשׁ, וְהִיא חֲתֻנָּתוֹ, עַל זֶה כָּתוּב (שם) וַיִּחַן שָׁם יִשְׂרָאֵל נֶגֶד הָהָר. דַּרְגָּה זוֹ הַבֵּן הַבְּכוֹר. נֶגֶד הָהָר - כְּנֶגֶד אוֹתוֹ הַר שֶׁנּוֹדַע שֶׁהוּא קָטָן מִכָּל הֶהָרִים שֶׁלְּמַעְלָה, שֶׁהוּא רָם וְנִשָּׂא כְּשֶׁמִּתְחַבֵּר לְמַעְלָה, וְנִקְרָא הַר סִינַי. שֶׁהֲרֵי שִׁבְעָה הָרִים וְשִׁבְעָה יָמִים וְשֶׁבַע אֲרָצוֹת בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָם, שֶׁהֵם כְּנֶגֶד שִׁבְעָה יָמִים עֶלְיוֹנִים, וְלֹא בָחַר מִכֻּלָּם לָתֵת תּוֹרָה אֶלָּא בְּהַר סִינַי, שֶׁהוּא הַסּוֹד שֶׁל כְּנֶסֶת יִשְׂרָאֵל, וְגַם בְּיָם כִּנֶּרֶת, שֶׁבָּא מִשָּׁם תְּכֵלֶת, שֶׁדּוֹמֶה לְכִסֵּא הַכָּבוֹד."],[3,"","כְּנֶסֶת יִשְׂרָאֵל כִּנֶּרֶת זֶה הַצַּדִּיק, וְזֶהוּ יָם כִּנֶּרֶת, כְּפִי שֶׁפֵּרְשׁוּ הַחֲבֵרִים. כִּנּוֹר הָיָה תָלוּי לְמַעְלָה מִמִּטָּתוֹ שֶׁל דָּוִד, וּבְשָׁעָה שֶׁרוּחַ צְפוֹנִית מְנַשֶּׁבֶת בּוֹ, מְנַגֵּן מֵאֵלָיו, וְדָוִד קָם לַעֲסֹק בַּתּוֹרָה בַּחֲצוֹת הַלַּיְלָה לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. וּבְאֶרֶץ יִשְׂרָאֵל הַשְּׁבִיעִית שֶׁל הַכֹּל, הַנְּקֻדָּה הָאֶמְצָעִית שֶׁל אֶרֶץ הַתַּחְתּוֹנָה בָּחַר הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא כְּנֶגֶד הַנְּקֻדָּה הָעֶלְיוֹנָה."],[4,"","מָה הַטַּעַם בּוֹ בְּהַר סִינַי שֶׁלְּמַעְלָה לָתֵת בּוֹ תּוֹרָה שֶׁבִּכְתָב, וְסִימָנִיךְ בְּאָרוֹן זֶה לָתֵת בּוֹ בְּרִית? מִשּׁוּם שֶׁבְּאָרוֹן זֶה מֻנָּחִים כָּל הַגְּנָזִים הַטּוֹבִים, וְתוֹרָה שֶׁבִּכְתָב, שֶׁנִּקְרֵאת בְּרִית, מֻנַּחַת בּוֹ, וְכָל כְּלֵי הַקְּרָב שֶׁל הַמֶּלֶךְ נִמְסְרוּ בְיָדֶיהָ, וְכָל הָעוֹלָמוֹת שֶׁלְּמַטָּה יוֹנְקִים מִמֶּנָּה. אִם זָכוּ יִשְׂרָאֵל לִשְׁמֹר הַתּוֹרָה, אָז נוֹתֶנֶת לָהֶם כָּל טוּב הָעוֹלָם, וְאִם לֹא, אָז מְיַסֶּרֶת אוֹתָם. זֶהוּ שֶׁכָּתוּב (ויקרא כו) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי. זוֹ כְּנֶסֶת יִשְׂרָאֵל. וּכְשֶׁתְּחַבֵּר בְּ\"אָנִי\" דָּלֶ\"ת שֶׁלָּהּ, נִקְרֵאת אֲדנָ\"י, וְדָן אֶת הָעוֹלָם."],[5,"","לָכֵן כָּתוּב (דברים ד) וְזאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. בְּ\"זֹאת\" נִתְּנָה תּוֹרָה. בֹּא רְאֵה, תּוֹרָה שֶׁבִּכְתָב נִקְרֵאת צַדִּיק, וּמֻנַּחַת בְּזאת, שֶׁבְּרִית זוֹ מֻנַּחַת בּוֹ, שֶׁכָּתוּב אֲרוֹן הַבְּרִית, מִשּׁוּם שֶׁמֻּנַּחַת בּוֹ בְּרִית שֶׁהוּא צַדִּיק. וְלָכֵן וְזֹאת הַתּוֹרָה, הִתְחַבֵּר וָא\"ו עִם זֹאת, וְאָז - אֲשֶׁר שָׂם מֹשֶׁה, סַם הַחַיִּים לָעוֹלָם, שֶׁהֲרֵי עֵץ הַחַיִּים נִדְבַּק בָּהּ. וּכְשֶׁמַּעֲשֵׂי בְּנֵי אָדָם אֵינָם כְּשֵׁרִים, מִסְתַּלֵּק וָא\"ו מִ\"זֹּאת\", וְאָז כָּתוּב (ויקרא יד) זֹאת תִּהְיֶה תּוֹרַת הַמְּצֹרָע, וְזֶהוּ חָשׁוּב כַּמֵּת."],[6,"","וְכָתוּב (במדבר יט) זאת הַתּוֹרָה אָדָם כִּי יָמוּת בְּאֹהֶל. הִסְתַּלְּקָה ו' מִזֹּאת, וְעוֹשֶׂה הָאֹהֶל הַזֶּה נְקָמוֹת. הַיְנוּ מַה שֶּׁכָּתוּב (שם) זֹאת חֻקַּת הַתּוֹרָה אֲשֶׁר צִוָּה ה'. מִשּׁוּם שֶׁלֹּא הִתְחַבְּרָה ו' עִם ה', גָּרְמוּ שֶׁטִּמְּאוּ הַמִּקְדָּשׁ וְגָרְמוּ לָהֶם מִיתָה, שֶׁהֲרֵי מִי שֶׁמַּפְרִידָם גּוֹרֵם מִיתָה לְנַפְשׁוֹ,"],[7,"","עַד שֶׁבָּאָה פָּרָה וְכִפְּרָה עַל בְּנָהּ, וְעוֹשִׂים מִמֶּנָּה הַזָּאָה עַל טְמֵאֵי מֵתִים. זֹאת הַתּוֹרָה, שֶׁלֹּא הִתְחַבֵּר לָהּ וָא\"ו עַד שֶׁעָשׂוּ הַזָּאָה לְאוֹתָם כְּלֵי מִדְיָן, וְאַחַר כָּךְ (דברים ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹמֵר. חַיִּים נִדְבְּקוּ בָהּ,"],[8,"","(שם לג) וְזאת הַבְּרָכָה. בְּרָכָה נִדְבְּקָה בָּ\"זֹּאת\" הַזּוֹ. אֲבָל כָּל מָקוֹם שֶׁתִּמְצָא בַתּוֹרָה \"זֹאת הַתּוֹרָה\" בְּלִי וָא\"ו, זֶה בִּגְלַל חֵטְא. (ויקרא יג) זֹאת תּוֹרַת נֶגַע צָרַעַת. (שם יד) זאת התורה לכל נגע הצרעת. (במדבר ה) זאת תּוֹרַת הַקְּנָאֹת. מִשּׁוּם שֶׁטִּמְּאוּ אֶת עַצְמָם וְטִמְּאוּ הַמִּקְדָּשׁ. (ויקרא ו) זֹאת תּוֹרַת הָעֹלָה, לֹא כָתוּב בּוֹ וָא\"ו, עַד שֶׁיַּעֲשׂוּ לָהּ בְּנֵי אַהֲרֹן שְׁלֵמוּת לְחַבֵּר אֶת זאת לְבַעְלָהּ."],[9,"","(שם ו) וְזאת תּוֹרַת הַמִּנְחָה - לֹא בָא עַל חֵטְא, שֶׁהֲרֵי הִיא נְדָבָה, אוֹ שֶׁבָּאָה עִם עוֹלָה, וְהָעוֹלָה הֲרֵי עוֹשָׂה שְׁלֵמוּת. (שם) זֹאת תּוֹרַת הַחַטָּאת - בָּא עַל חֵטְא שֶׁטִּמְּאוּ אֶת \"זאת\". (ויקרא ז) וְזֹאת תּוֹרַת הָאָשָׁם - מִשּׁוּם שֶׁלֹּא עָשׂוּ כָּל כָּךְ פְּגָם, וְלָכֵן בָּאָה זָכָר וְלֹא נְקֵבָה. (שם) וְזאת תּוֹרַת זֶבַח הַשְּׁלָמִים, מִשּׁוּם שֶׁבָּאָה לְשָׁלוֹם, מִתְחַבֵּר עִמָּהּ וָא\"ו. (שם) זֹאת הַתּוֹרָה לָעֹלָה (ו) לַמִּנְחָה וְלַחַטָּאת - בִּגְלַל חַטָּאת שֶׁיֵּשׁ בַּפָּסוּק, וְחוֹטֵא אֶחָד יְאַבֵּד טוֹבָה הַרְבֵּה,"]]],[["דָא אוֹקִימְנָא בְּכָל אַתְרָא וא\"ו מוֹסִיף עַל עִנְיָּן רִאשׁוֹן. וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹ' מַאי טַעְמָא וא\"ו, הָא לא אָמַר זֹאת בְּקַדְמִיתָא, אַמָּאי כְּתִיב וְזֹאת, בְּגִין סַם חַיִּים דְאִתְדַבָּק בָּהּ.","(דברים ל״ג:א׳) וְזֹאת הַבְּרָכָה, בְּגִין בְּרָכָה אַף עַל גַּב דְלָא כְּתִיב זֹאת בְּקַדְמִיתָא, אוֹ מִלָּה עַל מָה דְּיֵיתֵי. אֲבָל בְּכוּלְהוּ מַאי טַעְמָא לָא כְּתִיב וְזֹאת. בְּגִין דְלָא אִתְדַבַּק וא\"ו. וְהַאי דִכְתִיב וְזֹאת תּוֹרַת הַאֲשָׁם בְּגִין דִכְתִיב לְעֵיל זֹאת תּוֹרַת הַחַטָּאת, וא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן.","בְּגִין כָּךְ אִתְיְיהִיבַת אוֹרַיְיתָא בְּהַאי זֹאת. וּבְגִין כָּךְ כְּתִיב (ויקרא כ״ו:ט״ז) אַף אֲנִי אֶעֱשֶׂה זֹאת, אֲסָלֵק מִינָהּ וא\"ו וְתַּעֲבִיד בְּהוּ נוּקְמִין וְכוּלְהוּ קָרְבָּנִין אַתְיָין לְקָרְבָא לְהַאי זֹאת לְעֵילָא בְּהַאי שְׁלִישִׁי. וַאֲנָן מְקָרְבִין בְּהַאי יוֹמָא תְּרֵין פָּרִים בְּמוּסָף, לְאוֹסָפָא לֵיהּ תְּרֵין חוּלָקִין. אַיִל אֶחָד, לְאִתְחַבְּרָא לֵיהּ אֵילָא דִּגְבוּרָ\"ה. שִׁבְעָה אִמְרִין לְקֳבֵל כּוּלְהוּ דַּרְגִּין דְּיֵּחְדוּן בְּהַאי הִלּוּלָא. שֵׂעִיר עִזִים, לְכַפָּרָא עַל דְּסָאִיבוּ מַקְדְּשָׁא חַיָּיבִין דִּלְתַתָּא.","(במדבר כ״ט:א׳) בַּחֹדֶשׁ הַשְׁבִיעִי, לְקֳבֵל דַּרְגָא דְּיִצְחָק דְּיִתְחַבָּר בֵּיהּ כְּנֶסֶת יִשְׂרָאֵל בִתְּרֵין פָּרִים. הַאי דִכְתִיב (בראשית ח׳:ד׳) וַתָּנַח הַתֵּיבָה בַּחֹדֶשׁ הַשְׁבִיעִי בְּשִׁבְעָה עֲשָׂר, דְּאִתּוֹסְפָא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי שְׁבִיעִית עַל עֶשֶׂר סְמִיכָא לַעֲשָׂרָה. בְּגִין כָּךְ פָּר אֶחָד לְאוֹסָפָא לֵיהּ חֵילָא דְּאִימָא עִלָּאָה לְמֵידָן עַלְמָא. אֲבָל תְּרֵין לָא, בְּגִין דְלָא יָכִיל עַלְמָא לְמִסְבַּל דִּינָא תַּקִּיפָא. אַיִל אֶחָד, גְּבוּרָה דִילֵיהּ לִישָׁנָא דְּתַקִיפוּ, (תהלים כ\"א) אֱיַּלוּתִי לְעֶזְרָתִי חוּשָׁה. וְהַאי אַיִל תַשְׁכַּח בְּכוּלְהוּ מוּסָפִין, דְּמוֹסִיפִין חֵילָא דִּגְבוּרָה עָלַיְיהוּ. בָּר מְשָׁבְּתָא דְּאִית בֵּיהּ נִיחָא, וְלֵית בֵּיהּ דִּינָא כְּלָל. דְאִתְגַלְיָיא עַתִּיקָא קַדִּישָׁא חֵידוּ וְטָבָאן לְכוּלְהוּ עִלָּאִין (ס\"א עלמין).","(במדבר כ״ח:ג׳) כְּבָשִׂים בְּנֵי שָׁנָה, לְמֵיהַב חֵילָא לְכוּלְהוּ דַּרְגִּין. שֵׂעִיר עִזִים דְלָא יִתְחָזֵי סָאִיבוּ בְּמַקְדְּשָׁא בְּיוֹמָא דְּדִינָא וּבְהָאי יוֹמָא אִתְחַבָּר גְּבוּרָה עִלָּאָה בְּדִינָא תַּתָּאָה דְּרֹאשׁ חוֹדֶשׁ לְמֵידָן עַלְמָא. תָּא חֲזֵי גְּבוּרָה דִּינָא קַשְׁיָא, כְּנֶסֶת יִשְׂרָאֵל דִּינָא רַפְיָא. אַךְ חוֹבַת הַיּוֹם פָּר אֶחָד, בְּגִין דְּיָכִיל עַלְמָא לְמִסְבַּל.","וּבְגִין כָּךְ בְּרֵישׁ יַרְחָא תְּרֵין פָּרִים דְהִיא כַּפָרָה. בַּעֲשָׂרָה לְיַרְחָא לְקֳבֵל דַּרְגָא דְמֹשֶׁה, בְּמוּסָף דִילֵיהּ פָּר בֶּן בָּקָר אֶחָד, דְלָא אִתּוֹסַף בֵּיהּ דִּינָא כָּל כַּךְ בְּגִין דְהוּא יוֹמָא דְּכַפָּרָה. אַיִל אֶחָד תַקִיף, לְתַבְרָא רְשִׁיעֵי עַלְמָא, וּבַעֵינָן לְמֶעְבָּד נַיְיחַא לְשָׁכְּכָא רָגְזָא.","כְּבָשִׂים שִׁבְעָה, לְאוֹסָפָא לְכוּלְהוּ דַּרְגִּין. שֵׂעִיר עִזִים אֶחָד, אִתּוֹסַף הַכָא בְּחוֹבָת הַיּוֹם לְכַפָּרָא עַל סוֹאֲבָת מַקְדְּשָׁא, בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא מְכַפֵּר כֹּלָּא. וְלָא יִשְׁתָּאַר סָאִיבוּ בְּעָלְמָא. בְּגִין כָּךְ, חַד בְּיוֹמָא, לְכַפָּרָא קֹדֶשׁ הַקֳּדָשִׁים חַד זִמְנָא בְּשַׁתָּא, בְּגִין דְלָא אִשְׁתְּכַח כָּל כַּךְ סָאִיבוּ תַמָּן. וְחַד לְבָרָא, לַמִּזְבֵּחַ הַחִיצוֹן, דְלָא יִשְׁתַּכַּח סָאִיבוּ בְּעָלְמָא.","בַּחֲמִשָׁה עֲשָׂר לְיַרְחָא לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּהוֹ\"ד וְאִסְתַּלַק נָמֵי בְּחֶסֶ\"ד. וּבְגִין כָּךְ בְּהַאי זִמְנָא אֲפִילוּ עִם כָּל אוּמִין דְּעָלְמָא עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא טִיבוּ. בְּגִין דְּאִתּוֹסַף חֶסֶ\"ד דְאֲהַרֹן עִם חֶסֶ\"ד דְּאַבְרָהָם וְאִינוּן מְקָרְבִין בֵּיהּ בְּשִׁבְעָה יוֹמִין קָרְבָּנִין עֲלָוָון, בְּגִין דְּיְחְדוּ כּוּלֵיהּ עַלְמָא בְּחֶדְוָותָא דְּיִשְׂרָאֵל.","ע' פָּרִים לְקֳבֵל ע' אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, וּבְיוֹמָא קַדְמָאָה פָּרִים שְׁלשָׁה עֲשָׂר. לְאַחְזָאָה דְלָאו אִינוּן כְּדָאי לְאִתְקַיְימָא בְּעָלְמָא, אֶלָּא בְּטִיבוּ דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִית בֵּיהּ תְּלֵיסַר מְכִילָן דְּרַחֲמֵי.","אֵלִים שְׁנַיִם לְמֶהֱוֵי תַּקִּיפוּ לְהַהוּא דַּרְגָא דְחֶסֶ\"ד עִלָּאָה עַל חַד תְּרֵין מִמַּה דִּמְקָרְבִין בְּכוּלְהוּ מוּסָפִין בְּגִין דְּהַאי חַגָא אִיהוּ לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּדַרְגָּא שְׁתִיתָאִי. וְאִקְרֵי יוֹם שְׁתִיתָאִי. יוֹמָא דְקוּדְשָׁא בְּרִיךְ הוּא אֶלֶף שְׁנִין.","וּבְהַהוּא יוֹמָא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאוֹסָפָא עַל חַד תְּרֵין טִיבוּ לְעַמֵּיהּ. הֲדָא הוּא דִכְתִיב (שמות ט״ז:ה׳) וְהָיָה בְּיוֹם הַשִׁשִׁי וְהֵכִינוּ אֶת אֲשֶׁר יָבִיאוּ, אָז וְהָיָה מִשְׁנֶה עַל אֲשֶׁר יִלְקְטוּ יוֹם יוֹם, וּבְכֻלְּהוּ דַּרְגִּין דִּלְעֵילָא אִתּוֹסַף בִּרְכָאָן.","וּבְהַהוּא יוֹמָא יֵיתֵי מַלְכָּא מְשִׁיחָא וְיִתְקְרֵי חַג הַאָסִיף דְּיַכְנִישׁ קוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ גָּלוּתָא דְּעַמֵּיהּ, הֲדָא הוּא דִכְתִיב (ישעיהו י״א:י״א) וְהָיָה בְּיוֹם הַהוּא יוֹסִיף יְיָ שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. וְיִתְקְרֵי חַג הַסֻּכּוֹת, דְּכֻלְּהוּ שִׁבְעָה דַּרְגִּין חַפְיָין עַל יִשְׂרָאֵל כְּסוּכָּה וּבְגִין כָּךְ כּוּלְהוּ עֲנָנֵי כָּבוֹד אַזְלִין עִם יִשְׂרָאֵל בְּמַדְבְּרָא בִּזְכוּתָא דְאֲהַרֹן","בְּגִין כָּךְ י\"ד אִמְרִין בְּכָל יוֹמָא. וּבְשִׁבְעָה יוֹמִין הָא שִׁבְעָתַיִם וְיַנְהִיר שִׁבְעָתַיִם נְהִירוּ דְשִׁמְשָׁא. וְקוּדְשָׁא בְּרִיךְ הוּא יְרָחֶם עַל עַלְמָא וְשָׂעִיר עִזִים אֶחָד חַטָּאת לְכַפָּרָא עַל סָאִיבוּ מַקְדְּשָׁא דְּסָאִיבוּ אוֹמֵי עַלְמָא עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת בְּיוֹמָא תִּנְיַנָא לְקֳבֵל דַּרְגָא דְּיִצְחָק. בְּיוֹמָא תְּלִיתָאָה לְקֳבֵל דַּרְגָא דְיַעֲקֹב. בְּיוֹמָא רְבִיעָאָה לְקֳבֵל דַּרְגָא דְּיוֹסֵף. בְּיוֹמָא חֲמִישָׁאָה לְקֳבֵל דַּרְגָא דְמֹשֶׁה. בְּיוֹמָא שְׁתִיתָאָה לְקֳבֵל דַּרְגָא דְאֲהַרֹן:","וְתָא חֲזֵי בְּהַאי חַגָא וּבְחַגָא דִּפְּטִירוּ, שִׁבְעָה יוֹמֵי דִכְלִילָן כּוּלְהוּ יוֹמִין דִּלְעֵילָא בְּהוּ. מָה דְּלֵית כֵּן בִּשְׁאָר חַגִּין דִּמְקָרְבִין בְּהוּ מוּסָף, אֶלָּא הַיְינוּ דְּאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא (בראשית ל׳:ל״ז) מָחְשׂוֹף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת, דִּי לְכָל אִינוּן שִׁבְעָה שִׁבְעָה דַּרְגִּין אַסְחַר לוֹן בִּסְטָר דְחֶסֶ\"ד חַגָא דִּפְּטִירָא, לְקֳבֵל אַבְרָהָם דְאָתֵי מִחֶסֶ\"ד בְּגִין כָּךְ כּוּלְהוּ דַּרְגִּין תַמָּן. דְּהָא לְכוּלְהוּ דַּרְגִּין אֶסְחַר יַעֲקֹב שְׁלֵימָא לְסִטְרָא דְחֶסֶ\"ד. הַאי חַגָא לְקֳבֵל דַּרְגָא דְאֲהַרֹן דְאֲחִיד בְּחֶסֶד, כּוּלְהוּ עִמֵּיהּ."],[],[[0,"","זֶה פֵּרַשְׁנוּ בְּכָל מָקוֹם - וָא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן. וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם וְגוֹמֵר, מָה הַטַּעַם וָא\"ו, הֲרֵי לֹא אָמַר זאת בַּתְּחִלָּה? לָמָּה כָּתוּב וְזאת? מִשּׁוּם סַם הַחַיִּים שֶׁנִּדְבַּק בָּהּ."],[1,"","(דברים לג) וְזֹאת הַבְּרָכָה - בִּשְׁבִיל בְּרָכָה, אַף עַל גַּב שֶׁלֹּא כָתוּב זֹאת בַּתְּחִלָּה, אוֹ דִּבֵּר עַל מַה שֶּׁיָּבֹא, אֲבָל בְּכֻלָּם מָה הַטַּעַם לֹא כָתוּב וְזאת? מִשּׁוּם שֶׁלֹּא נִדְבָּק וָא\"ו. וְזֶהוּ שֶׁכָּתוּב (ויקרא ז) וְזֹאת תּוֹרַת הָאָשָׁם, מִשּׁוּם שֶׁכָּתוּב לְמַעְלָה (שם ו) וְזֹאת תּוֹרַת הַחַטָּאת, וָא\"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן,"],[2,"","מִשּׁוּם כָּךְ נִתְּנָה תּוֹרָה בְּ\"זאת\". וּמִשּׁוּם כָּךְ כָּתוּב (שם כו) אַף אֲנִי אֶעֱשֶׂה זֹאת, אֲסַלֵּק מִמֶּנָה וָא\"ו וְתַעֲשֶׂה בָהֶם נְקָמוֹת, וְכָל הַקָּרְבָּנוֹת בָּאִים לְקָרֵב אֶת הַ\" את\" לְמַעְלָה בַּשְּׁלִישִׁי הַזֶּה, וְאָנוּ מַקְרִיבִים בְּיוֹם זֶה שְׁנֵי פָרִים בְּמוּסָף, לְהוֹסִיף לָהּ שְׁנֵי חֲלָקִים. אַיִל אֶחָד לְחַבֵּר לָהּ הַכֹּחַ שֶׁל גְּבוּרָה, שִׁבְעָה כְבָשִׂים כְּנֶגֶד כָּל הַדְּרָגוֹת שֶׁיִּשְׂמְחוּ בַּהִלּוּלָא הַזּוֹ, שְׂעִיר עִזִּים לְכַפֵּר עַל שֶׁטִּמְּאוּ הַמִּקְדָּשׁ הָרְשָׁעִים שֶׁלְּמַטָּה."],[3,"","(במדבר כט) וּבַחֹדֶשׁ הַשְּׁבִיעִי - כְּנֶגֶד דַּרְגַּת יִצְחָק שֶׁיִּתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל בִּשְׁנֵי פָרִים. זֶהוּ שֶׁכָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר, שֶׁהִתּוֹסְפָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא שְׁבִיעִית עַל עֶשֶׂר סְמוּכָה לַעֲשָׂרָה. מִשּׁוּם כָּךְ פַּר אֶחָד, לְהוֹסִיף לוֹ כֹּחַ הָאִמָּא הָעֶלְיוֹנָה לָדוּן אֶת הָעוֹלָם. אֲבָל שְׁנַיִם לֹא, מִשּׁוּם שֶׁהָעוֹלָם לֹא יָכוֹל לִסְבֹּל אֶת הַדִּין הַקָּשֶׁה. אַיִל אֶחָד - הַגְּבוּרָה שֶׁלּוֹ, לָשׁוֹן שֶׁל תַּקִּיפוּת, (תהלים כב) אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה, וְהָאַיִל הַזֶּה תִּמְצָא בְּכָל הַמּוּסָפִים, שֶׁמּוֹסִיפִים כֹּחַ וּגְבוּרָה עֲלֵיהֶם, פְּרָט לְשַׁבָּת שֶׁיֵּשׁ בָּהּ מְנוּחָה וְאֵין בָּהּ דִּין כְּלָל, שֶׁמִּתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ שִׂמְחָה וְטוֹבוֹת לְכָל הָעֶלְיוֹנִים (עולמים)."],[4,"","(במדבר כח) כְּבָשִׂים בְּנֵי שָׁנָה - לָתֵת כֹּחַ לְכָל הַדְּרָגוֹת. שְׂעִיר עִזִּים - שֶׁלֹּא תֵרָאֶה טֻמְאָה בַּמִּקְדָּשׁ בְּיוֹם הַדִּין, וּבְיוֹם זֶה מִתְחַבֶּרֶת הַגְּבוּרָה הָעֶלְיוֹנָה בַּדִּין הַתַּחְתּוֹן שֶׁל רֹאשׁ חֹדֶשׁ לָדוּן אֶת הָעוֹלָם. בֹּא רְאֵה, גְּבוּרָה דִּין הַקָּשֶׁה, כְּנֶסֶת יִשְׂרָאֵל דִּין הָרָפֶה, אַךְ חוֹבַת הַיּוֹם פַּר אֶחָד כְּדֵי שֶׁהָעוֹלָם יוּכַל לִסְבֹּל,"],[5,"","וְלָכֵן בְּרֹאשׁ חֹדֶשׁ שְׁנֵי פָרִים, שֶׁהִיא כַּפָּרָה. בַּעֲשָׂרָה לַחֹדֶשׁ כְּנֶגֶד דַּרְגַּת מֹשֶׁה. בַּמּוּסָף שֶׁלּוֹ פַּר בֶּן בָּקָר אֶחָד, שֶׁלֹּא נוֹסָף בּוֹ דִּין כָּל כָּךְ, הֱיוֹת שֶׁאוֹתוֹ יוֹם הוּא שֶׁל כַּפָּרָה. אַיִל אֶחָד תַּקִּיף לִשְׁבֹּר אֶת הָרְשָׁעִים שֶׁל הָעוֹלָם, וְצָרִיךְ לַעֲשׂוֹת נַחַת לְשַׁכֵּךְ הָרֹגֶז. כְּבָשִׂים שִׁבְעָה לְהוֹסִיף לְכָל הַדְּרָגוֹת. שְׂעִיר עִזִּים אֶחָד הִתּוֹסֵף כָּאן בְּחוֹבַת הַיּוֹם לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה יְכַפֵּר עַל הַכֹּל וְלֹא תִשָּׁאֵר טֻמְאָה בָּעוֹלָם."],[6,"","מִשּׁוּם כָּךְ אֶחָד בַּיּוֹם, לְכַפֵּר קֹדֶשׁ הַקְּדָשִׁים פַּעַם אַחַת בְּשָׁנָה, כְּדֵי שֶׁלֹּא תִמָּצֵא שָׁם טֻמְאָה כָּל כָּךְ, וְאֶחָד בַּחוּץ לַמִּזְבֵּחַ הַחִיצוֹן שֶׁלֹּא תִמָּצֵא טֻמְאָה בָּעוֹלָם."],[7,"","בַּחֲמִשָּׁה עָשָׂר לַחֹדֶשׁ כְּנֶגֶד דַּרְגַּת אַהֲרֹן שֶׁאָחוּז בְּהוֹד, וְהִתְעַלָּה גַּם בְּחֶסֶד. וְלָכֵן בִּזְמַן זֶה אֲפִלּוּ עִם כָּל אֻמּוֹת הָעוֹלָם עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא חֶסֶד, מִשּׁוּם שֶׁמִּתּוֹסֵף חֶסֶד שֶׁל אַהֲרֹן עִם חֶסֶד שֶׁל אַבְרָהָם, וְהֵם מַקְרִיבִים בּוֹ בְּשִׁבְעָה יָמִים קָרְבְּנוֹת עוֹלוֹת, כְּדֵי שֶׁיִּשְׂמְחוּ כָּל הָעוֹלָם בְּשִׂמְחַת יִשְׂרָאֵל."],[8,"","שִׁבְעִים פָּרִים כְּנֶגֶד שִׁבְעִים אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזְּלוֹת הָעוֹלָם, וּבַיּוֹם הָרִאשׁוֹן פָּרִים שְׁלֹשָׁה עָשָׂר, לְהַרְאוֹת שֶׁאֵינָם כְּדָאִים לְהִתְקַיֵּם בָּעוֹלָם אֶלָּא בְּטוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיֵּשׁ בּוֹ שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל רַחֲמִים."],[9,"","אֵילִים שְׁנַיִם, שֶׁתִּהְיֶה תַקִּיפוּת לְאוֹתָהּ דַּרְגָּה שֶׁל חֶסֶד עֶלְיוֹן עַל אֶחָד שְׁנַיִם מִמַּה שֶּׁמַּקְרִיבִים בְּכָל הַמּוּסָפִים, מִשּׁוּם שֶׁחַג זֶה הוּא כְּנֶגֶד דַּרְגַּת אַהֲרֹן, שֶׁאָחוּז בְּדַרְגָּה שִׁשִּׁית. וְנִקְרָא יוֹם הַשִּׁשִּׁי. יוֹמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלֶף שָׁנִים."],[10,"","וּבְאוֹתוֹ יוֹם עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹסִיף עַל כָּל אֶחָד שְׁנַיִם חֶסֶד לְעַמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות טז) וְהָיָה בַּיּוֹם הַשִּׁשִּׁי וְהֵכִינוּ אֵת אֲשֶׁר יָבִיאוּ, אָז - וְהָיָה מִשְׁנֶה עַל אֲשֶׁר יִלְקְטוּ יוֹם יוֹם, וּבְכָל הַדְּרָגוֹת שֶׁלְּמַעְלָה נוֹסָפוֹת בְּרָכוֹת."],[11,"","וּבְאוֹתוֹ יוֹם יָבֹא מֶלֶךְ הַמָּשִׁיחַ וְיִקָּרֵא חַג הָאָסִיף, שֶׁיְּכַנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹ הַגָּלוּת שֶׁל עַמּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה יא) וְהָיָה בַּיּוֹם הַהוּא יוֹסִיף ה' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. וְיִקָּרֵא חַג הַסֻּכּוֹת, שֶׁכָּל שֶׁבַע הַדְּרָגוֹת מְכַסּוֹת עַל יִשְׂרָאֵל כְּמוֹ סֻכָּה, וְלָכֵן כָּל עַנְנֵי הַכָּבוֹד הוֹלְכִים עִם יִשְׂרָאֵל בַּמִּדְבָּר בִּזְכוּת אַהֲרֹן,"],[12,"","וְלָכֵן אַרְבָּעָה עָשָׂר כְּבָשִׂים שֶׁבְּכָל יוֹם. וּבְשִׁבְעָה יָמִים - הֲרֵי שִׁבְעָתַיִם, וְיָאִיר שִׁבְעָתַיִם אוֹר הַשֶּׁמֶשׁ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְרַחֵם עַל הָעוֹלָם. וּשְׂעִיר עִזִּים אֶחָד לְחַטָּאת - לְכַפֵּר עַל טֻמְאַת הַמִּקְדָּשׁ שֶׁטִּמְּאוּ אֻמּוֹת הָעוֹלָם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. בַּיּוֹם הַשֵּׁנִי כְּנֶגֶד דַּרְגַּת יִצְחָק. בַּיּוֹם הַשְּׁלִישִׁי כְּנֶגֶד דַּרְגַּת יַעֲקֹב. בַּיּוֹם הָרְבִיעִי כְּנֶגֶד דַּרְגַּת יוֹסֵף. בַּיּוֹם הַחֲמִישִׁי כְּנֶגֶד דַּרְגַּת מֹשֶׁה. בַּיּוֹם הַשִּׁשִּׁי כְּנֶגֶד דַּרְגַּת אַהֲרֹן."],[13,"","וּבֹא וּרְאֵה, בְּחַג זֶה וּבְחַג הַמַּצּוֹת שִׁבְעָה יָמִים שֶׁכְּלוּלִים בָּהֶם כָּל הַיָּמִים שֶׁלְּמַעְלָה, מַה שֶּׁאֵין כֵּן בִּשְׁאָר חַגִּים שֶׁמַּקְרִיבִים בָּהֶם מוּסָף, אֶלָּא הַיְנוּ מַה שֶּׁפֵּרַשְׁנוּ בְּסוֹד הָאֱמוּנָה, (בראשית ל) מַחְשּף הַלָּבָן אֲשֶׁר עַל הַמַּקְלוֹת, שֶׁלְּכָל אוֹתָם שִׁבְעָה שֶׁבַע דְּרָגוֹת מַקִּיפוֹת אוֹתָם בְּצַד הַחֶסֶד, הֶחָג שֶׁל הַמַּצּוֹת כְּנֶגֶד אַבְרָהָם שֶׁבָּא מֵחֶסֶד, לָכֵן כָּל הַדְּרָגוֹת שָׁם, שֶׁהֲרֵי אֶת כָּל הַדְּרָגוֹת מַקִּיף יַעֲקֹב הַשָּׁלֵם לַצַּד שֶׁל חֶסֶד. הֶחָג הַזֶּה כְּנֶגֶד דַּרְגָּתוֹ שֶׁל אַהֲרֹן שֶׁאָחוּז בְּחֶסֶד, כֻּלָּם עִמּוֹ."]]],[["דָבָר אֲחֵר, בְּגִין דְּכוּלְהוּ דַּרְגִּין וְכוּלְהוּ זַכָּאִין, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם קוּדְשָׁא בְּרִיךְ הוּא אִתְגְּלֵי תַמָּן בְּכִתְרוֹי וְזַמִּין לְמֶעְבַּד כֵּן בְּיוֹמֵי דְּיֵיתֵי מְשִׁיחָא. בְּגִין כָּךְ כּוּלְהוּ כִּתְרִין רְמִיזִין הַכָא וְהָכָא וְנַטְלִין עַל חַד תְּרֵין שֶׁבַע בִּרְכָאָן הַכָא מֵהַתָּם.","וְהָתָם עַל חַד שִׁבְעָה מִשְׁאָר מוּסָפִין, הֲדָא הוּא דִכְתִיב (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כְּיוֹם צֵאתְךָ הֲוָה לֵיהּ לְמֵימָר. מַאי כִּימֵי. דְּכוּלְהוּ יוֹמִין עִלָּאִין אִזְדְּמָנוּ הֲתָם וְאִזְדָּמְנוּ הַכָא. בְּגִין כָּךְ נִפְלָאוֹת נ' פְּלָאוֹת, חַמְשִׁין פְּלָאוֹת. דְּהָא נ' תַרְעִין דְבִּינָ\"ה פָּתַח קוּדְשָׁא בְּרִיךְ הוּא לְאַפָּקָא לוֹן מִתַּמָּן. וּבְּגִינֵי כַּךְ בְּאוֹרַיְיתָא אִדְכַּר יְצִיאַת מִצְרָיִם נ' זִמְנִין לְקֳבֵל נ' תַרְעִין כְּדֵין יַעֲבִיד לְיוֹמֵי מְשִׁיחָא.","וּמַאי אַרְאֶנּוּ. אֶלָּא אַרְאֶנּוּ לְהַהוּא סָבָא דְחָזָא בְּקַדְמִיתָא דִכְתִיב (שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה. כְּדֵין זַמִּין לְמֶחְזֵי פּוּרְעַנוּתָא דֶאֱדוֹם.","דָבָר אַחֵר, דִּבְּגִינְהוֹן דְּשִׁבְעָה צַדִּיקַיָּיא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לְכָל אוּמִין דְּעָלְמָא וְלָא יִשְׁתָּאַר בְּעָלְמָא אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי וְיִשְׂרָאֵל גּוֹי אֶחָד בְּגִין כָּךְ הַכָא שִׁבְעָה יוֹמִין. תָּא חֲזֵי, דִּבְגִין כַּךְ מִתְמָעֲטִין וְהוֹלְכִין. וּבְיוֹמָא תְמִינָאָה שַׁלְטִין יִשְׂרָאֵל לְחוֹדָּיְיהוּ בְּעָלְמָא וּמָקְרִיבִין פָּר אֶחָד אַיִל אֶחָד, רָזָא דְּיִחוּדָא.","שִׁבְעָה כְּבָשִׂים לְקֳבֵל שִׁבְעָה דַּרְגִּין. שְׂעִיר עִזִים, אַף עַל גַּב דְּבְהַהוּא זִמְנָא יַעֲבְרִינֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵעָלְמָא, עִם כָּל דָּא יִשְׁתָּאַר מִנֵּיהּ דְלָא יִתְבָּטְלוּן מִפִּרְיָה וְרִבְיָה. וּבְהַהוּא זִמְנָא יִפְקוּן מַיִם חַיִּים מֵחָכְמָה עִלָּאָה (זכריה י״ד:ח׳) חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי דָא חֶסֶד עִלָּאָה וְחֶצְיָּם אֶל הַיָּם הָאַחֲרוֹן דָא גְּבוּרָ\"ה תַּתָּאָה וּגְבוּרָ\"ה עִלָּאָה. בַּקַיִץ וּבַחוֹרֵף בְּסִטְרָא דְאֶשָא וּבְּסִטְרָא דְמַיָּא. דְלָא יִשְׁתָּאַר דִינָא בְּעַלְמָא אֶלָּא כֹּלָּא רַחֲמֵי וְחַיִּים וְחֵירוּ בְּעַלְמָא:","וְתָא חֲזֵי בְּהַאי חַגָא עַבְדִין נִסוּךְ הַמָּיִם. נְבִיעַ דְּחֶסֶד בְּאִינוּן שִׁתִּין מִשֵׁשֶׁת יְמֵי בְּרֵאשִׁית, וְכוּלְהוּ שִׁבְעָה יוֹמִין עִלָּאִין מְקַבְּלִין מֵאִינוּן מָיִם חַיִּים דְּנָפְקִין מִיְרוּשָׁלַיִם עִלָּאָה טְמִירָא. וּבֵאַן אֲתַר רָמִיז לְאִינוּן מָיִם חַיִּים, בְּאִינוּן שִׁיתִּין.","וְחֲסִידֵי וְצַדִּיקֵי חַדָּאן בְּהַאי הִלּוּלָא, בְּגִין דִּרְמִיזָא לְהַהוּא טִיבוּ דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד כַּד יַעְבֵּר קוּדְשָׁא בְּרִיךְ הוּא סָאִיבוּ מֵאַרְעָא דְּיֶחְתוּן אִינוּן מָיִם חַיִּים טְהוֹרִים בְּאִינוּן שִׁיתִּין, בְּהַהוּא מִזְבֵּחַ עִלָּאָה הַהוּא יָם הָאַחֲרוֹן. וְאִינוּן תְלָתָא לוֹגִין מָיִם י\"ח בֵּצִים לְקֳבֵל צַדִּיק דְּאִקְרֵי ח\"י הָעוֹלָמִים, וְעַל יְדֵיהּ מָיִם נַחְתִּין בְּאִינוּן שִׁיתִּין.","וְתָּא חֲזֵי הִלֵּל הַזָּקָן כַּד הֲוָה חַדֵּי בְּהַאי הִלּוּלָא אָמַר אִם אֲנִי כָּאן הַכֹּל כָּאן. וְאִם אֵין אֲנִי כָּאן מִי כָּאן. הוּא רָמִיז וְאָמַר אִי שְׁכִינְתָּא דְּאִקְרֵי אֲנִי שַׁרְיָיא כַּאן. הַכֹּל כָּאן הַהוּא אַתְרָא דְּאִקְרֵי כָּל דְאָתֵי לְאִזְדַּוְּוגָא בָּהּ. וְאִם אֵין אֲנִי כָּאן מִי כָּאן. דְּהָא לָא חַשִׁיבָא טִיבוּ שְׁלֵימָא בְּגִין דִשְׁכִינְתָּא לָא שַׁרְיָיא בְּאַרְעָא קַדִּישָׁא.","אֲבָל כַּד יִשְׁתְּלָמוּ אִינוּן פָּרִים כְּדֵין כְּתִיב (ישעיהו י״ב:ג׳) וּשְׁאַבְתֶּם מָיִם בְּשָׂשׂוֹן מִמָעֲיְינֵי הַיְשׁוּעָה. מַאן אִינוּן. שִׁית מָעֲיַינֵי דְּאִינוּן מְרִיקִין בְּהַאי יְשׁוּעָה וּכְדֵין עַלְמָא כּוּלֵיהּ בְּחֶדְוָה בְּגִין דְּנָפְקַא שְׁכִינְתָּא מִבֵּין הַהוּא סָאִיבוּ דִּשְׁאָר עַמִּין, בְּגִין כָּךְ (במדבר כ״ט:ל״ה) בְּיוֹם הַשְׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם.","תָּא חֲזֵי עֶשֶׂר נְטִיעוֹת עֲרָבָה וְנִסוּךְ הַמָּיִם הֲלָכָה לְמֹשֶׁה מִסִּינַי. שְׁאָר מִלֵּי דְּאוֹרַיְיתָא תּוֹרָה. וְהָכָא הֲלָכָה. מַאי טַעְמָא, אֶלָּא בְּגִין דְּהַאי אַתְרָא דְּאִקְרֵי הַר סִינַי, תּוֹרָה שֶׁבְּעַל פֶּה אוֹלִיפַת לֵיהּ לְמֹשֶׁה לְקַשְׁרָא קִשְׁרִין דִמְהֵימְנוּתָא.","אִינוּן עֶשֶׂר נְטִיעִין דְּנָצָב קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא אֲחִיד לוֹן בְּהַהוּא אַתְרָא דְּאִקְרֵי עֶרֶב שְׁבִיעִית וְיַעְבְּדוּן פְּרִי בְּהַהוּא בֵּית סְאָה, בְּגִין דְאַיְיתֵי מְזוֹנָא לְעָלְמָא בְּהַאי שְׁבִיעִית. דְּלֵית לוֹן מְזוֹנָא אֶלָּא מֵהַהוּא שַׁתָּא שְׁתִיתָאָה דְּזַרְעִין בָּהּ זַרְעִין, הֲדָא הוּא דִכְתִיב (הושע י׳:י״ב) זִרְעוּ לָכֶם לִצְדָקָה קִצְרוּ לְפִי חֶסֶד, מָה דְּזַרְעִין יְהֵא לְהַהוּא אַחֲרָא דְּאִקְרֵי צְדָקָה שְׁלֵימָה, וּכְדֵין וְקִצְרוּ לְפִי חֶסֶד כְּדֵין יְהֵא טִיבוּ עִלָּאָה. וּמַאן אִיהוּ לְפִי (פי) חֶסֶד דָא אַבְרָהָם.","וְתָא חֲזֵי לְתַתָּא שִׁבְעָה עֲבִידָן אִית בֵּינֵיהוֹן. זְרִיעָ\"ה לְקֳבֵל אִימָא עִלָּאָה, הֲדָא הוּא דִכְתִיב (בראשיתמ\"ז) הֵא לָכֶם זֶרַע. קְצִירָ\"ה לְקֳבֵל דַּרְגָא דְאַבְרָהָם הֲדָא הוּא דִכְתִיב וְקִצְרוּ לְפִי חֶסֶד. דִישָׁ\"ה בַּחָרוּץ לְקֳבֵל דַּרְגֵּיהּ דְיִצְחָק דְּעָבִיד דִּינָא וְאַפְרִישׁ תֹּכֵן מֵהַהוּא בָּר. דִּינָא אַפְרִישׁ מִנֵּיהּ וְעֲבַד דִּינָא בִּרְשִׁיעֵי עַלְמָא וּכְדֵין אִינְהוּ כְּמוֹץ לִפְנִי רוּחַ.","וְהַאי רוּחַ דָא דַּרְגָא דְיַעֲקֹב דִכְתִיב (בראשית מ״ה:כ״ז) וַתְּחִי רוּחַ יַעֲקֹב, וּלְקִבְלֵיהּ זוֹרֶ\"ה וְהוּא מוֹץ לְאֶשָּׁא אִתְיְיהִיב לְמֵיכָל. טוֹחֵ\"ן לְקֳבֵל דַּרְגָא דְמֹשֶׁה. לָּ\"שׁ לְקֳבֵל דַּרְגָא דְאֲהַרֹן. אוֹפֵ\"ה לְקֳבֵל דַּרְגָא דְצָדִי\"ק וְאִתְעֲבִיד לֶחֶ\"ם בְּיָדוֹ דְצָדִי\"ק בְּהַהוּא אוֹר דְּאִית בְּצִיּוֹן, הֲדָא הוּא דִכְתִיב (תהילים קל״ו:כ״ה) נוֹתֵן לֶחֶם לְכָל בָּשָׂר. בְּקַדְמִיתָא לְכָ\"ל וּלְבָתָר לְהַהוּא אֲתַר דְּאִקְרֵי בָּשָׂר וּמָאי לֶחֶם דָא קִיוּמָא."],[],[[0,"","דָּבָר אַחֵר - מִשּׁוּם שֶׁכָּל הַדְּרָגוֹת וְכָל הַצַּדִּיקִים, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְגַּלָּה שָׁם בַּכְּתָרִים שֶׁלּוֹ, וְעָתִיד לַעֲשׂוֹת כֵּן בִּזְמַן בִּיאַת הַמָּשִׁיחַ. מִשּׁוּם כָּךְ כָּל הַכְּתָרִים רְמוּזִים כָּאן וְכָאן, וְנוֹטְלִים עַל אֶחָד שְׁנַיִם שֶׁבַע בְּרָכוֹת כָּאן מִשָּׁם."],[1,"","וְשָׁם עַל אֶחָד שִׁבְעָה מִשְּׁאָר הַמּוּסָפִים, זֶהוּ שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת. כְּיוֹם צֵאתְךְ הָיָה לוֹ לוֹמַר! מַה זֶּה כִּימֵי? שֶׁכָּל הַיָּמִים הָעֶלְיוֹנִים הִזְדַּמְּנוּ לְשָׁם וְהִזְדַּמְּנוּ לְכָאן, מִשּׁוּם כָּךְ נִפְלָאוֹת, נ' פְּלָאוֹת, חֲמִשִּׁים פְּלָאוֹת, שֶׁהֲרֵי חֲמִשִּׁים שַׁעֲרֵי בִינָה פָּתַח הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹצִיא אוֹתָם מִשָּׁם, וְלָכֵן מֻזְכֶּרֶת בַּתּוֹרָה חֲמִשִּׁים פְּעָמִים יְצִיאַת מִצְרַיִם, כְּנֶגֶד חֲמִשִּׁים שְׁעָרִים, כָּךְ יַעֲשֶׂה לִימוֹת הַמָּשִׁיחַ."],[2,"","וּמַה זֶּה אַרְאֶנּוּ? אֶלָּא אַרְאֶנּוּ אֶת אוֹתוֹ הַזָּקֵן שֶׁרָאָה בָּרִאשׁוֹנָה, שֶׁכָּתוּב (שמות יד) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה, וְאָז עֲתִיד לִרְאוֹת אֶת הַפֻּרְעָנוּת שֶׁל אֱדוֹם"],[3,"","דָּבָר אַחֵר - שֶׁבִּשְׁבִיל שִׁבְעַת הַצַּדִּיקִים עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר אֶת כָּל אֻמּוֹת הָעוֹלָם, וְלֹא יִשָּׁאֵר בָּעוֹלָם אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ וְיִשְׂרָאֵל גּוֹי אֶחָד. מִשּׁוּם כָּךְ כָּאן שִׁבְעָה יָמִים. בֹּא רְאֵה שֶׁמִּשּׁוּם כָּךְ מִתְמַעֲטִים וְהוֹלְכִים, וּבַיּוֹם הַשְּׁמִינִי שׁוֹלְטִים יִשְׂרָאֵל לְבַדָּם בָּעוֹלָם וּמַקְרִיבִים פַּר אֶחָד, אַיִל אֶחָד, סוֹד הַיִּחוּד."],[4,"","שִׁבְעָה כְבָשִׂים - כְּנֶגֶד שֶׁבַע דְּרָגוֹת. שְׂעִיר עִזִּים - אַף עַל גַּב שֶׁבְּאוֹתוֹ זְמַן יַעֲבִירֶנּוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם, עִם כָּל זֶה יִשָּׁאֵר מִמֶּנּוּ שֶׁלֹּא יִתְבַּטְּלוּ מִפְּרִיָּה וּרְבִיָּה. וּבְאוֹתוֹ זְמַן יֵצְאוּ מַיִם חַיִּים מֵחָכְמָה הָעֶלְיוֹנָה, (זכריה יד) חֶצְיָם אֶל הַיָּם הַקַּדְמוֹנִי - זֶה חֶסֶד עֶלְיוֹן, וְחֶצְיָם אֶל הַיָּם הָאַחֲרוֹן - זוֹ גְבוּרָה תַּחְתּוֹנָה וּגְבוּרָה עֶלְיוֹנָה. בַּקַּיִץ וּבַחֹרֶף - בְּצַד הָאֵשׁ וּבְצַד הַמַּיִם. שֶׁלֹּא יִשָּׁאֵר דִּין בָּעוֹלָם, אֶלָּא הַכֹּל רַחֲמִים וְחַיִּים וְחֵרוּת בָּעוֹלָם."],[5,"","וּבֹא רְאֵה, בֶּחָג הַזֶּה עוֹשִׂים נִסּוּךְ הַמַּיִם, שֶׁפַע שֶׁל חֶסֶד בְּאוֹתָם שִׁיתִים מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית, וְכָל שִׁבְעַת הַיָּמִים הָעֶלְיוֹנִים מְקַבְּלִים מֵאוֹתָם מַיִם חַיִּים שֶׁיּוֹצְאִים מִירוּשָׁלַיִם הָעֶלְיוֹנָה הַטְּמִירָה. וּבְאֵיזֶה מָקוֹם רָמוּז עַל אוֹתָם מַיִם חַיִּים? בְּאוֹתָם שִׁיתִים,"],[6,"","וַחֲסִידִים וְצַדִּיקִים שְׂמֵחִים בַּהִלּוּלָא הַזּוֹ, מִשּׁוּם שֶׁרוֹמֵז לְאוֹתוֹ הַטּוֹב שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת כְּשֶׁיַּעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַטֻּמְאָה מִן הָאָרֶץ, שֶׁיֵּרְדוּ אוֹתָם מַיִם טְהוֹרִים בְּאוֹתָם הַשִּׁיתִים בְּאוֹתוֹ מִזְבֵּחַ עֶלְיוֹן, יָם הָאַחֲרוֹן, וְהֵם שְׁלֹשָׁה לֻגִּים מַיִם, שְׁמוֹנֶה עֶשְׂרֵה בֵּיצִים, כְּנֶגֶד צַדִּיק שֶׁנִּקְרָא חַי הָעוֹלָמִים, וְעַל יָדוֹ הַמַּיִם יוֹרְדִים בְּאוֹתָם שִׁיתִים."],[7,"","וּבֹא וּרְאֵה, כְּשֶׁהִלֵּל הַזָּקֵן הָיָה שָׂמֵחַ בַּהִלּוּלָא הַזּוֹ, אָמַר, אִם אֲנִי כָּאן - הַכֹּל כָּאן, וְאִם אֵין אֲנִי כָּאן - מִי כָּאן? הָיָה רוֹמֵז וְאוֹמֵר, אִם שְׁכִינָה שֶׁנִּקְרֵאת אֲנִי שׁוֹרָה כָּאן - הַכֹּל כָּאן, אוֹתוֹ מָקוֹם שֶׁנִּקְרָא כֹּל שֶׁבָּהּ לְהִזְדַּוֵּג בָּהּ. וְאִם אֵין אֲנִי כָּאן - מִי כָּאן? שֶׁהֲרֵי לֹא חָשׁוּב טוֹב שָׁלֵם, מִשּׁוּם שֶׁשְּׁכִינָה לֹא שׁוֹרָה בָּאָרֶץ הַקְּדוֹשָׁה."],[8,"","אֲבָל כְּשֶׁיִּשְׁתַּלְּמוּ אוֹתָם פָּרִים, אָז כָּתוּב (ישעיה יב) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן מִמַּעַיְנֵי הַיְשׁוּעָה. מִי הֵם? שִׁשָּׁה מַעְיָנוֹת שֶׁמְּרִיקִים בַּיְשׁוּעָה הַזֹּאת, וְאָז הָעוֹלָם כֻּלּוֹ בְּחֶדְוָה, מִשּׁוּם שֶׁשְּׁכִינָה יוֹצֵאת מִתּוֹךְ אוֹתָהּ טֻמְאַת שְׁאָר הָעַמִּים, מִשּׁוּם כָּךְ (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם."],[9,"","בֹּא רְאֵה, עֶשֶׂר נְטִיעוֹת, עֲרָבָה וְנִסּוּךְ הַמַּיִם - הֲלָכָה לְמֹשֶׁה מִסִּינַי, שְׁאָר הַדְּבָרִים שֶׁל הַתּוֹרָה - תּוֹרָה, וְכָאן הֲלָכָה. מָה הַטַּעַם? אֶלָּא מִשּׁוּם שֶׁמָּקוֹם זֶה שֶׁנִּקְרָא הַר סִינַי, תּוֹרָה שֶׁבְּעַל פֶּה לִמְּדָה אֶת מֹשֶׁה לִקְשֹׁר קִשְׁרֵי הָאֱמוּנָה."],[10,"","אוֹתָן עֶשֶׂר נְטִיעוֹת שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאָחַז אוֹתָן בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא עֶרֶב שְׁבִיעִית, וְיַעֲשׂוּ פְרִי בְּאוֹתוֹ בֵּית סֵאָה, כְּדֵי שֶׁיָּבא מָזוֹן לָעוֹלָם בַּשְּׁבִיעִית הַזּוֹ, שֶׁאֵין לָהֶם מָזוֹן אֶלָּא מֵאוֹתָהּ שָׁנָה שִׁשִּׁית שֶׁזּוֹרְעִים בָּהּ זְרָעִים. זֶהוּ שֶׁכָּתוּב (הושע י) זִרְעוּ לָכֶם לִצְדָקָה וְקִצְרוּ לְפִי חֶסֶד. מַה שֶּׁזּוֹרְעִים יִהְיֶה לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא צְדָקָה שְׁלֵמָה, וְאָז וְקִצְרוּ לְפִי חֶסֶד, אָז יִהְיֶה טוֹב הָעֶלְיוֹן. וּמִי הוּא לְפִי חֶסֶד? זֶה אַבְרָהָם."],[11,"","בֹּא רְאֵה, לְמַטָּה שִׁבְעָה מַעֲשִׂים יֵשׁ בֵּינֵיהֶם. זְרִיעָה - כְּנֶגֶד הָאֵם הָעֶלְיוֹנָה, זֶהוּ שֶׁכָּתוּב (בראשית מו) הֵא לֶם זֶרַע. קְצִירָה - כְּנֶגֶד דַּרְגַּת אַבְרָהָם, זֶהוּ שֶׁכָּתוּב (ו) קִצְרוּ לְפִי חֶסֶד. דִּישָׁה בְּחָרוּץ - כְּנֶגֶד דַּרְגַּת יִצְחָק, שֶׁעוֹשֶׂה דִּין וּמַפְרִיד תֶּבֶן מֵאוֹתוֹ בָּר. דִּין מַפְרִיד מִמֶּנּוּ, וְעוֹשֶׂה דִּין בְּרִשְׁעֵי הָעוֹלָם, וְאָז הוּא (תהלים לה) כְּמֹץ לִפְנֵי רוּחַ."],[12,"","וְרוּחַ הַזּוֹ זוֹ הַדַּרְגָּה שֶׁל יַעֲקֹב, שֶׁכָּתוּב (בראשית מה) וַתְּחִי רוּחַ יַעֲקֹב, וּכְנֶגְדוֹ זוֹרֶה. וְאוֹתוֹ הַמֹּץ נִתָּן לָאֵשׁ לְמַאֲכָל. טוֹחֵן - כְּנֶגֶד דַּרְגַּת מֹשֶׁה. לָשׁ - כְּנֶגֶד דַּרְגַּת אַהֲרֹן. אוֹפֶה - כְּנֶגֶד דַּרְגַּת צַדִּיק, וְנַעֲשֶׂה לֶחֶם בְּיָדוֹ שֶׁל צַדִּיק בְּאוֹתוֹ אוֹר שֶׁיֵּשׁ בְּצִיּוֹן. זֶהוּ שֶׁכָּתוּב (תהלים קלו) נֹתֵן לֶחֶם לְכָל בָּשָׂר. בַּתְּחִלָּה לְ\"כָל\", וְאַחַר כָּךְ לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא בָּשָׂר. וּמַה זֶּה לֶחֶם? זֶה הַקִּיּוּם."]]],[["וּבְהַאי שַׁתָּא שְׁבִיעַתָּא לָא עָבְדִין עֲבִידְתָּא, אֶלָּא אַכְלִין הַהוּא לֶחֶם דְאִתְיְיהִיב לְהוּ מִשָׁתָּא שְׁתִיתָאָה. וְכוּלְהוּ עָלְמִין בְּחֶדְוָה נָיְיחִין וְכוּלְהוּ מִסְכְּנִי וְעֲתִּירֵי כּוּלְהוּ שָׁוִין בְּהַאי אֲתַר, דְּהָא כּוּלְהוּ תַתָּאֵי מֵהָאי שַׁתָּא שְׁבִיעַתָּא מִתְזָּנִין.","וְאִי בַּר נָשׁ עֲבִיד בְּאִינוּן פֵּירִין סְחוֹרָתָא. הַאי דְאַתְרָא דְעַנִּיּוּתָא מָנַע מִנֵּיהּ בִּרְכָאָן, בְּגִין כָּךְ מָנַע מִנֵּיהּ בִּרְכָאָן. וּבָעֵי בַּר נָשׁ לְאַחֲזָאָה דְּהַאי אַרְעָא קַדִּישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא אִית לָה נַיְיחָא בְּבַעְלָהּ וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לֶחֶם לְהַאי כָּ\"ל. וְכָ\"ל לְהַהוּא אַתְרָא דְּאִקְרֵי בָּשָׂ\"ר מִבְּשָׂרִי, וְלֵית לָהּ נְהוֹרָא מִדִילָה אֶלָּא הַנְהוּ סְפִיחֵי דִּשְׁתִּיתַאָה דְּאִזְדְּרָעוּ בָּהּ מִמֵילָא.","וּבָעֵי בַּר נָשׁ בְּהַהוּא עֶרֶב שְׁבִיעִית לְמֶעְבָּד עֲבִידְתָּא דְּאַרְעָא בְּאִינוּן עֶשֶׂר נְטִיעָן אִשְׁתְּלִימוּ בָּהּ דְּתִתְיַחֵד הַאי אַרְעָא בְּהוּ, וְלָא תִתְפָּרָשׁ מִנַּיְיהוּ וְתִתִקְרֵי אַף הִיא נְטִיעָה, נְצִיבוּ דְּנָצָב קוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְלָא יִתִּמְנַע מִינָהּ הַהוּא טִיבוּ דְּאִית לָהּ עִם בַּעְלָהּ, נַיְיחָא בַּשְׁבִיעִית.","בְּגִין כָּךְ אָדָם בְּיוֹמָא שְׁתִיתָאָה אִתְבְּרֵי וְאִזְדַּוְּוגַת עִמֵּיהּ בַּת זוּגֵיהּ לְאִתְעֲנְגָא בְּשַׁבְּתָא, וְהַשְׁתָּא אִזְדַּוְּוגַת צֶדֶ\"ק בִּשְׁתִיתָאָה לְמֵיהַב נְהִירוּ לְהַאי הַר סִינַי.","וְתָּא חֲזֵי, הַר חוֹרֵב אִתְקְרֵי כַּד אִזְדְּוַוג עִמֵּיהּ וא\"ו. וְאִי בְּנִי נָשָׁא מַפְרִישִׁין וא\"ו מִינָהּ, אִקְרֵי חֶרֶב לַיְיָ, דְּהָא חֶרֶב כְּתִיב, וְעַבְדָּא נוּקְמִין. בְּגִין כָּךְ הֲלָכָה לְמֹשֶׁה מִסִּינַי תּוֹרָה שֶׁבְּעַל פֶּה דְּיִכְלְלוּן יָתָהּ בְּאִינוּן עֶשֶׂר נְטִיעָן עֶרֶב שְׁבִיעִית, וְיֵיתֵי מְזוֹנָא לְעָלְמָא בַּשְׁבִיעִית. דְהוּא אַתְרָא דְּלֵית לָהּ נְהוֹרָא אֶלָּא מָה דְאִתְיְיהִיב לָהּ מֵהַהוּא וא\"ו.","וְתָּא חֲזֵי יִשְׂרָאֵל כַּד עֲבַדוּ עֶגְלָא וְאַפְרִישׁוּ בִּרְכָאָן מֵהַאי הַר חוֹרֵב דְּאַפְרִישׁוּ מִנֵּיהּ וא\"ו וְקַצִּיצוּ בִּנְטִיעוֹת בְּאִינוּן נְטִיעָן, מָה כְּתִיב (שמותל\"ג) וַיִתְנַצְּלוּ בְּנִי יִשְׂרָאֵל אֶת עֵדְיָם מֵהַר חוֹרֵב. הַהוּא עֲדִי עִלָּאָה, תְפִלִּין דְּרֵישָׁא וּדְרוֹעָא דְּשָׁוְויָין בְּיָד כֵּהָה אַעְדִּיאוּ מִנְּהוֹן. וּמֵאַן אֲתַר אִתְיְיהִיב לוֹן, מֵהַר חוֹרֵב כַּד אִזְדְּוַוג בָּהּ וא\"ו. וְהַשְׁתָּא (משלי ט״ז:כ״ח) וְנִרְגָּן מַפְרִיד אַלּוּף וְאִתְעָרוּ עֲלֵיהוֹן חֶרֶב.","בְּגִין כָּךְ בְּנֵי לֵוִי דְּעָבְדוּ לְוָיָה לְהַאי אַתְרָא, אִתְפְּרָעוּ מִנְּהוֹן. הֲדָא הוּא דִכְתִיב (שמות ל״ב:כ״ו) וַיַעֲמֹד מֹשֶׁה בְּשַׁעַר הַמַּחֲנְה וַיֹּאמֶר מִי לַיְיָ אֵלָי וַיֵאָסְפוּ אֵלָיו כָּל בְּנִי לֵוִי, דְּהָא לָא עֲבָדוּ פִּרוּדָא אֶלָּא לְוָיָה.","וְאָמַר לוֹן מֹשֶׁה (שמות ל״ב:כ״ז) כֹּה אָמַר יְיָ עִבְרוּ וָשׁוּבוּ מִשַׁעַר לְשַׁעַר בַּמַּחֲנֶה, בְּגִין דְּהַאי כֹּ\"ה יָהֲבַת לוֹן רְשׁוּתָא לְמֶעְבָּד דִּינִין וּמַאן אִיהוּ כֹּ\"ה, דָא הַר חוֹרֵב וּבְגִין כָּךְ קַטְלוּ מִנְּהוֹן כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ, שְׁלֹשֶׁת לָא אִתְּמָר, אֶלָּא כִּשְׁלֹשֶׁת לְקֳבֵל הַנְהוּ תְלָתָא דַּרְגִּין דְהֲווּ מַלְיָין לְהַאי בְּאֵר. הֲדָא הוּא דִכְתִיב (בראשית כ״ט:ב׳) וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רוֹבְצִים עָלֵיהּ. בְּגִין דְּאִינוּן גָּרְמוּ דְּיִסְתַּלְקוּן מִינָהּ וְהָא אוּקְמוּהָ.","בְּגִין כָּךְ פְּקִידָּת לֵיהּ הַאי תּוֹרָה שֶׁבְּעַל פֶּה לְמֹשֶׁה עַל אִינוּן עֶשֶׂר נְטִיעָן וַעֲרָבָה דְּיָקִיפוּן לְהַאי מִזְבֵּחַ בְּאִינוּן עַרְבֵי נַחַל לְקֳבֵל תְּרֵין דַּרְגִּין דְּמָקִיפִין לְעֵילָא דְּאִינוּן נְצַ\"ח הוֹ\"ד. וּכְדֵין יַעַבְדוּן נִסוּךְ הַמָּיִם מֵאִינוּן מָיִם חַיִּים דְאַתְיָין עַל יְדֵי דְּצַדִּיק וְלָא יִמְנֵעוּן מֵהָאי מִזְבֵּחַ טִיבוּ עִלָּאָה.","וְתָא חֲזֵי כָּל שְׁאָר יוֹמֵי דְּשָׁתָא בְּהַאי מִזְבֵּחַ עַבְדִין נִסוּךְ הַיָּיִן, רָמִיז לְדִינָא דְעָיִיל בָּהּ לְמֵידָן עַלְמָא. אֲבָל בְּחָג עַבְדִין אוּף בְּמַיִם חַיִּים. דְּהָא חַיִּים וּנְהִירוּ אִתּוֹסַף בְּהַהוּא זִמְנָא (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ כַּמַּיִם לַיָּם מְכַסִּים.","עֲשָׂרָה פַּעֲמָיִם נִמְנוּ יִשְׂרָאֵל, אַחַת בִּיְרִידַתָן לְמִצְרָיִם דִכְתִיב (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה וכו' (וגו'). וְאַחַת בַּעֲלִיָיתָן דִכְתִיב (שמות י״ב:ל״ז) כְּשֵׁשׁ מֵאוֹת אֶלֶף. וּשְׁנַיִם בְּחוּמָשׁ הַפְּקוּדִים וּשְׁנַיִם בִּימֵי שָׁאוּל, א' בְּבֶּזֶק וְא' בַּטְלָאִים, וְא' בִּימֵי דָוִד (שמואל ב' כ\"ג) וַיִּתֵּן יוֹאָב אֶת מִסְפָּר הֲעָם אֶל הַמֶּלֶךְ. וְא' בִּימֵי עֶזְרָא (עזרא ב׳:ס״ד) כָּל הַקָּהָל כְּאֶחָד. וְא' לְעָתִיד לָבֹא (ירמיהו ל״ג:י״ג) עוֹד תַּעֲבוֹרְנָה הַצֹּאן עַל יְדֵי מוֹנֵה.","אַשְׁרֵי אָדָם מָצָא חָכְמָה, דָא אָדָם עִלָּאָה דְּאַשְׁרֵי עֲלוֹי טִיבוּ דְּעַתִּיקָא. אֵימָתַי, כַּד מָטָא חָכְמָה כְּמָה דְאַתְּ אָמֵר (משלי י״ח:כ״ב) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֵק רָצוֹן מֵיְיָ. דָא רַעֲוָא דְּעַתִּיקָא וּמָאי אִיהוּ הַאי חָכְמָה, דָא חָכְמָה זְעִירָא דְהִיא רַבְרְבָא בְּאִתְחַבְּרוּתָא לְעֵילָא.","מָצָא, מַאי מָצָא כְּגוֹן דְאִשְׁתַּכְּחַת בְּכֹלָּא. וְאָדָם יָפִיק תְבוּנָה דְּבָעֵי לְעַיְינָא וּלְאִסְתַּכְּלָא וּלְאַפָּקָא מֵעוֹמָקַא עִלָּאָה תְבוּנָה, לְאַנְהֲרָא לְהַאי חָכְמָה. וְעַל יְדֵי דְּמַאן אִתְנָהִירָת עַל יְדֵי עִלָּאָה דְּמָפִּיק רָצוֹן מִלְּעֵילָא לְאַנְהֲרָא לָהּ: רִבִּי בִנְיָמִן לֵוִי, מַצָאתִי כָּתוּב שֵׁם בֵּן י\"ב אוֹתִיּוֹת יְהַ יְהַ וְהַ וְהַ וָה יִה: תֹּה\"וּ בְּמִסְפָּר קָטָן עִם ג' אוֹתִיּוֹת גִימַטְרִיָּא ש' ש\"ד שד\"י. בֹּהוּ בְּמִסְפָּר קָטָן גִימַטְרִיָּא צְבָאוֹת כָּזֶה ב' ב\"ה בֹּהוּ. חֹשֶׁךְ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא אֱלֹהִים. רוּחַ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל בְּגִימַטְרִיָּא יהו\"ה בְּמִסְפָּר קָטָן. רַעַשׁ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא בֹּהוּ. קוֹל דְּמָמָה דַקָּה בְּמִסְפָּר קַטָן עִם הַכּוֹלֵל יהו\"ה וְי\"ב יוֹתֵר כְּנֶגֶד שֵׁם י\"ב הַנִמְסָר לְאֵלִיָּהוּ בַּמֵעַרָה. וְכֵן דַקָּה בְּמִסְפָּר קָטָן עִם הַשְׁלֹשָׁה אוֹתִיּוֹת גִימַטְרִיָּא יב\"ק נלעד\"ן:"],[],[[0,"","וּבַשָּׁנָה הַשְּׁבִיעִית הַזּוֹ לֹא עוֹשִׂים מְלָאכָה, אֶלָּא אוֹכְלִים אוֹתוֹ לֶחֶם שֶׁנִּתַּן לָהֶם בַּשָּׁנָה הַשִּׁשִּׁית, וְכָל הָעוֹלָמוֹת נָחִים בְּחֶדְוָה. וְכָל הָעֲנִיִּים וְהָעֲשִׁירִים, כֻּלָּם שָׁוִים בְּמָקוֹם זֶה, שֶׁהֲרֵי כָּל הַתַּחְתּוֹנִים נִזּוֹנִים מִשָּׁנָה הַשְּׁבִיעִית הַזּוֹ."],[1,"","וְאִם אָדָם עוֹשֶׂה סְחוֹרָה בְּאוֹתָם פֵּרוֹת, הַמָּקוֹם הַזֶּה שֶׁל עֲנִיּוּת מוֹנֵעַ מִמֶּנּוּ בְּרָכוֹת, וְלָכֵן מוֹנֵעַ מִמֶּנּוּ בְּרָכוֹת. וְצָרִיךְ אָדָם לְהַרְאוֹת שֶׁלָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא יֵשׁ נַחַת עִם בַּעְלָהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לֶחֶם לַכֹּל הַזֶּה, וְ\"כֹל\" לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא (בראשית ב) בָּשָׂר מִבְּשָׂרִי, וְאֵין לָהּ אוֹר מִשֶּׁלָּהּ, אֶלָּא אוֹתָם סְפִיחֵי הַשִּׁשִּׁית שֶׁנִּזְרְעוּ בָהּ מִמֵּילָא."],[2,"","וְצָרִיךָ אָדָם בְּאוֹתוֹ עֶרֶב שְׁבִיעִית לַעֲשׂוֹת מְלֶאכֶת הָאָרֶץ בְּאוֹתָן עֶשֶׂר נְטִיעוֹת שֶׁהִשְׁתַּלְּמוּ בָהּ, שֶׁתִּתְיַחֵד הָאָרֶץ הַזּוֹ עִמָּהֶם וְלֹא תִפָּרֵד מֵהֶם, וְאַף הִיא תִּקָּרֵא נְטִיעָה, נְטִיעָה שֶׁנָּטַע הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי שֶׁלֹּא יִמָּנַע מִמֶּנָּה אוֹתוֹ טוּב שֶׁיֵּשׁ לָהּ עִם בַּעְלָהּ מְנוּחָה בַּשְּׁבִיעִית."],[3,"","וְלָכֵן נִבְרָא אָדָם בַּיּוֹם הַשִּׁשִּׁי, וְהִזְדַּוְּגָה עִמּוֹ בַּת זוּגוֹ לְהִתְעַנֵּג בְּשַׁבָּת, וְעַכְשָׁו הִזְדַּוְּגָה צֶדֶק עִם שִׁשִּׁי לָתֵת אוֹר לְהַר סִינַי הַזֶּה."],[4,"","וּבֹא וּרְאֵה, הַר חוֹרֵב נִקְרָא כְּשֶׁמִּזְדַּוֵּג עִמּוֹ וָא\"ו, וְאִם בְּנֵי אָדָם מַפְרִידִים וָא\"ו מִמֶּנָּה, נִקְרָא חֶרֶב לַה', שֶׁהֲרֵי כָּתוּב חֶרֶב, וְעוֹשָׂה נְקָמוֹת, לָכֵן הֲלָכָה לְמֹשֶׁה מִסִּינַי תּוֹרָה שֶׁבְּעַל פֶּה, שֶׁיִּכְלְלוּ אוֹתָהּ עִם אוֹתָם עֶשֶׂר נְטִיעוֹת עֶרֶב שְׁבִיעִית, וְיָבֹא מָזוֹן לָעוֹלָם בַּשְּׁבִיעִית, שֶׁהוּא מָקוֹם שֶׁאֵין לוֹ אוֹר אֶלָּא מַה שֶּׁנִּתָּן לוֹ מֵאוֹתוֹ וָא\"ו."],[5,"","וּבֹא וּרְאֵה, כְּשֶׁעָשׂוּ יִשְׂרָאֵל אֶת הָעֵגֶל, וְהִפְרִידוּ הַבְּרָכוֹת מֵהַר חוֹרֵב הַזֶּה, שֶׁהִפְרִידוּ מִמֶּנּוּ וָא\"ו וְקִצְּצוּ בַּנְּטִיעוֹת, בְּאוֹתָן נְטִיעוֹת מַה כָּתוּב? (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב. אוֹתוֹ תַכְשִׁיט עֶלְיוֹן, תְּפִלִּין שֶׁל רֹאשׁ וּזְרוֹעַ שֶׁשָּׂמִים בְּיָד כֵּהָה הֵסִירוּ מֵהֶם, וּמֵאֵיזֶה מָקוֹם נִתַּן לָהֶם? מֵהַר חוֹרֵב, כְּשֶׁהִזְדַּוֵּג עִמָּהּ וָא\"ו. וְכָעֵת (משלי טז) (ו) נִרְגָּן מַפְרִיד אַלּוּף, וְעוֹרְרוּ עֲלֵיהֶם אֶת הַחֶרֶב."],[6,"","מִשּׁוּם כָּךְ, בְּנֵי לֵוִי שֶׁעָשׂוּ לְוָיָה לְמָקוֹם זֶה, נִפְרְעוּ מֵהֶם, זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּעֲמֹד מֹשֶׁה בְּשַׁעַר הַמַּחֲנֶה וַיֹּאמֶר מִי לַה' אֵלָי, וַיֵּאָסְפוּ אֵלָיו כָּל בְּנֵי לֵוִי. שֶׁהֲרֵי לֹא עָשׂוּ פֵרוּד, אֶלָּא לְוָיָה."],[7,"","וְאָמַר לָהֶם מֹשֶׁה, כֹּה אָמַר ה' עִבְרוּ וָשׁוּבוּ מִשַּׁעַר לָשַׁעַר בַּמַּחֲנֶה. מִשּׁוּם שֶׁהַ\"כֹּה\" הַזֹּאת נָתְנָה לָהֶם רְשׁוּת לַעֲשׂוֹת דִּינִים. וּמִיהוּ כֹּה? זֶה הַר חוֹרֵב, וְלָכֵן הָרְגוּ מֵהֶם כִּשְׁלֹשֶׁת אַלְפֵי אִישׁ. שְׁלֹשֶׁת לֹא נֶאֱמַר, אֶלָּא כִּשְׁלֹשֶׁת, כְּנֶגֶד אוֹתָן שָׁלֹשׁ דְּרָגוֹת שֶׁהָיוּ מְמַלְּאוֹת אֶת הַבְּאֵר הַזּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית כט) וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ, מִשּׁוּם שֶׁהֵם גָּרְמוּ שֶׁיִּסְתַּלְּקוּ מִמֶּנָּה, וַהֲרֵי בֵּאֲרוּהָ."],[8,"","מִשּׁוּם כָּךְ צִוְּתָה תּוֹרָה שֶׁבְּעַל פֶּה הַ את אֶת מֹשֶׁה עַל אוֹתָן עֶשֶׂר נְטִיעוֹת וַעֲרָבָה, שֶׁיַּקִּיפוּ אֶת הַמִּזְבֵּחַ הַזֶּה עִם אוֹתָם עַרְבֵי נַחַל, כְּנֶגֶד שְׁתֵּי דְרָגוֹת שֶׁמַּקִּיפִים לְמַעְלָה, שֶׁהֵם נֵצַח וְהוֹד, וְאָז יַעֲשׂוּ נִסּוּךְ הַמַּיִם אוֹתָם מַים חַיִּים שֶׁבָּאִים עַל יְדֵי צַדִּיק, וְלֹא יִמְנְעוּ מִמִּזְבֵּחַ הַזֶּה הַטּוֹב הָעֶלְיוֹן."],[9,"","וּבֹא וּרְאֵה, כָּל שְׁאָר יְמוֹת הַשָּׁנָה עוֹשִׂים בַּמִּזְבֵּחַ הַזֶּה נִסּוּךְ הַיַּיִן, רוֹמֵז לַדִּין שֶׁנִּכְנָס בָּהּ לָדוּן אֶת הָעוֹלָם. אֲבָל בֶּחָג עוֹשִׂים אַף בְּמַיִם חַיִּים, שֶׁהֲרֵי חַיִּים וְאוֹר נוֹסָף בְּאוֹתוֹ זְמַן, (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה' כַּמַּיִם לַיָּם מְכַסִּים."],[10,"","עָשֶׂר פְּעָמִים נִמְנוּ יִשְׂרָאֵל: אַחַת בִּירִידָתָם לְמִצְרַיִם, שֶׁכָּתוּב (בראשית מו) כָּל הַנֶּפֶשׁ לְבֵית יַעֲקֹב הַבָּאָה מִצְרַיְמָה וְגוֹמֵר. וְאַחַת בַּעֲלִיָּתָם, שֶׁכָּתוּב (שמות יב) כְּשֵׁשׁ מֵאוֹת אֶלֶף. וּשְׁתַּיִם בְּחֻמַּשׁ הַפְּקוּדִים. וּשְׁתַּיִם בִּימֵי שָׁאוּל, אַחַת בְּבֶזֶק וְאַחַת בַּטְּלָאִים. וְאַחַת בִּימֵי דָוִד, (שמואל ב כד) וַיִּתֵּן יוֹאָב אֶת מִסְפַּר מִפְקַד הָעָם אֶל הַמֶּלֶךְ. וְאַחַת בִּימֵי עֶזְרָא, (עזרא ב) כָּל הַקָּהָל כְּאֶחָד. וְאַחַת לֶעָתִיד לָבא, (ירמיה לג) עֹד תַּעֲברְנָה הַצּאן עַל יְדֵי מוֹנֶה."],[11,"","אַשְׁרֵי אָדָם מָצָא חָכְמָה - זֶה אָדָם הָעֶלְיוֹן שֶׁהִשְׁרָה עָלָיו הַטּוֹב שֶׁל הָעַתִּיק (כתר), אֵימָתַי. כְּשֶׁמַּגִּיעָה הַחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) מָצָא אִשָּׁה מָצָא טוֹב וַיָּפֶק רָצוֹן מֵה'. זֶה הָרָצוֹן שֶׁל הָעַתִּיק. וּמַהִי הַחָכְמָה הַזּוֹ? זוֹ חָכְמָה זְעִירָה שֶׁהִיא גְדוֹלָה בְּהִתְחַבְּרוּת לְמַעְלָה."],[12,"","מָצָא, מַה זֶּה מָצָא? כְּמוֹ שֶׁנִּמְצֵאת בַּכֹּל. וְאָדָם יָפִיק תְּבוּנָה - שֶׁצָּרִיךְ לְעַיֵּן וּלְהִסְתַּכֵּל וּלְהוֹצִיא מֵהָעֹמֶק הָעֶלְיוֹן תְּבוּנָה לְהָאִיר לַחָכְמָה הַזּוֹ, וְעַל יְדֵי מִי הִיא נְאוֹרָה? עַל יְדֵי הָאָדָם הָעֶלְיוֹן שֶׁמֵּפִיק רָצוֹן מִלְמַעְלָה לְהָאִיר לָהּ: רִבִּי בִנְיָמִן לֵוִי, מַצָאתִי כָתוּב שֵׁם בֵּן י\"ב אוֹתִיּוֹת יְהַ יְהַ וְהַ וְהַ וָה יִה: תֹּה\"וּ בְמִסְפָּר קָטָן עִם ג' אוֹתִיּוֹת גִימַטְרִיָּא ש' ש\"ד שד\"י. בּהוּ בְמִסְפָּר קָטָן גִימַטְרִיָּא צְבָאוֹת כָּזֶה ב' ב\"ה בֹהוּ. חֹשֶׁךְ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא אֱלֹהִים. רוּחַ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל בְּגִימַטְרִיָּא יהו\"ה בְמִסְפָּר קָטָן. רַעַשׁ בְּמִסְפָּר קָטָן עִם הַכּוֹלֵל גִימַטְרִיָּא בהוּ. קוֹל דְּמָמָה דַקָּה בְמִסְפָּר קַטָן עִם הַכּוֹלֵל יהו\"ה וְי\"ב יוֹתֵר כְּנֶגֶד שֵׁם י\"ב הַנִמְסָר לְאֵלִיָּהוּ בַמֵעַרָה. וְכֵן דַקָּה בְמִסְפָּר קָטָן עִם הַשְׁלֹשָׁה אוֹתִיּוֹת גִימַטְרִיָּא יב\"ק. גלעד\"ן"]]],[["לָּמָה בֵּי\"ת דּוֹמֶה לְאָדָם שֶׁנוֹצָר בְּחָכְמָה שֶׁסָתוּם מִכָּל צָד וּפַּתוּחַ מִלְפָנָיו וְהָאָלֶף פְתוּחָה מֵאַחֲרָיו רוֹצֶה לוֹמַר כִּי הִיא פְתוּחָה לְקַבֵּל מִן הַכֶּתֶר וְיֵשׁ לָהּ פְּתַח לְהַשְׁפִּיעַ לְאֲחֵרִים.","וּמְנָא לָן דְּשָׁמַיִם הֲוֵי קוּדְשָׁא בְּרִיךְ הוּא, דִכְתִיב (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. אֲטוּ שְׁלמֹה מִתְפָּלֵל אֶל הַשָּׁמַיִם שְׁיִשְׁמְעוּ תְּפִלָּתוֹ, אֶלָּא שְׁנִקְרָא שְׁמָן עַל שְׁמוֹ. וְלָמָּה נִקְרָא שָׁמַיִם אֶלָּא שֶׁהוּא עֲגוֹל כְּמוֹ רֹאשׁ וּמְלַמֵּד שֶׁמָּיִם מִימִינוֹ וְאֵשׁ מִשְׂמֹאלוֹ וְהוּא בְּאֶמְצַע שָׂא מָיִם, מֵאֶשׁ וּמִמָיִם וּמָכְנִיס בֵּינֵיהֶם שָׁלוֹם, בָּא הָאֵשׁ וּמָצָא מִצִדוֹ מִדַּת הָאֵשׁ. בָּא מָיִם וּמָצָא מִצִדוֹ מִדַּת הַמָּיִם וְהַיְינוּ (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו, מַאי שָׁמַיִם מְלַמֵּד שֶׁגָבַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵשׁ וּמַיִם וּטְפָחַן זֶה בָּזֶה וְעָשָׂה מֶהֵן רֹאשׁ לִדְבַרָיו שֶׁנֶּאֱמַר (תהילים קי״ט:ק״ס) רֹאשׁ דְּבָרְךָ אֱמֶת. ע\"כ.","וְהָאָרֶץ הָיְתָה תֹהוּ. בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בְּאִלֵּין קְלִיפִּין הֲוָה בּוֹנֶה עָלְמִין וּמַחֲרִיבָן וְהָא אוּקְמוּהָ דְּלֵית הַשְפָּעַה בְּכָל עָלְמִין, וְנָהָר דְּאִיהוּ צַדִּיק יֶחרַב וְיָבֵשׁ בִּתְרֵין עָלְמִין, בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי.","וְאִית מָאן דְּאָמַר דְסָלִיק בְּמַחְשַׁבְתֵּיהּ לְמִבְנִי עָלְמִין וּלְהַחָרִיבָן. וְאָמַר דֵין מְהַנְיָין לִי וְדֵין לָא מְהַנְיָין לִי. אִלֵּין דְּאִתְּמָר בְּהוֹן אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ מְהַנְיָין לִי. וְאַחֲרָנִין דְּאִתְּמָר בְּהוֹן וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ דְּאַחְזֵי עַל עָלְמִין דְסָלִיק בִּרְעוּתֵיהּ לְמִבְנִי לוֹן וְלָא עֲבִיד לוֹן עֲלַיְהוּ אִתְּמָר תֹהוּ וָבֹהוּ.","וּבְזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּאִלֵּין קְלִיפִּין אִתְּמָר בֵּיהּ (איכה ג׳:מ״ד) סַכּוֹתָה בֶּעָנָן לָךְ מֵעֲבוֹר תְפִלָּה. תֹהוּ וְחֹשֶׁךְ עֲלַיְהוּ אִתְּמָר (שמות י״ד:כ׳) וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ וְאִלֵּין קְלִיפִּין דֶּאֱגוֹזָא, מוֹחָא מִלְגַאו דְּתַלְיָא (דתלת) לד' סִטְרִין דָא יהו\"ה דְּאִיהוּ לָא קַבִּיל מֵסָאֲבוּ, כְּמָה דְאַתְּ אָמֵר (ירמיהו כ״ג:כ״ט) הֲלֹא כֹּה דְּבָרַי כָּאֵשׁ נְאֻם יְיָ. מָה אֶשָׁא לָא מְקַבֵּל טוּמְאָה הֲכִי שְׁמֵיהּ לָא מְקַבֵּל טוּמְאָה.","וּבִזְמְנָא דְּמִתְגַּבְּרִין אִלֵּין קְלִיפִּין וְאִתְבָּרוּן מֵאֱגוֹזָא, צְלוֹתָא דְּאִיהִי שְׁכִינְתָּא אדנ\"י, סַלְקָא לְגַבֵּי בַּעְלָהּ דְּאִיהוּ יהו\"ה וּסְלִיקַת כוּלַּהּ, דִּבְּזִמְנָא דְּאִיהוּ מִתְכָּסֵי מִינָהּ בְּאִלֵּין קְלִיפִּין, אִיהִי אִתְקְרִיאַת עֲנִיָּה יְבֵשָׁה וְלֵית לָהּ אֶלָּא מָה דְיַהֲבִין עֲבָדִין בַּחֲשָׁאי.","וּבְהַהוּא זִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְפְּשָׁט מֵאִלֵּין קְלִיפִּין אִתְּמָר (ישעיהו ל׳:כ׳) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ וְהָיוּ עֵינְיךָ רוֹאוֹת אֶת מוֹרֶיךָ. וּמָה דַהֲוָה יְבֵשָׁה אִתְּמָר בָּהּ, מְלא כָּל הָאָרֶץ כְּבוֹדוֹ. וְאִתְקְרִיאַת בְּרָכָה דִילֵיהּ, קָרְבָּנָא דִילֵיהּ, עוֹלָה דִילֵיהּ, דְּאוֹקִיד כָּל אִלֵּין קְלִיפִּין.","וּסְלִיקַת לְגַבֵּיהּ קְטֹרֶת. קִשׁוּרָא דִילֵיהּ, עוֹלָה דִילֵיהּ, דִכְתִיב (ויקרא ו׳:י״ח) זֹאת תּוֹרַת הָעוֹלָה, הִיא הָעוֹלָה בִּצְלוֹתָא דְשַׁחֲרִית, הִיא הָעוֹלָה לְגַבֵּיהּ בִּצְלוֹתָא דְמִנְחָה בְּכַמָּה רֵיחִין וּבוּסְמִין דְּגָן עֶדֶן דְאִיהִי גָן דְּאוֹרַיְיתָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:י״ב) גָן נָעוּל אֲחוֹתִי כַלָּה, סְתִימָא דְלָא אִתְפַּתְּחַת אֶלָּא לְגַבֵּי בַּעְלָהּ.","וְכַד יֵיתֵי בַּעְלָהּ (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח דְאִיהִי בָּבַא עִלָּאָה אִתְפַּתְּחַת לְגַבֵּיהּ כִּתְרִין (בתרין) סַמְכֵין קְשׁוֹט וְקַבִּילַת לֵיהּ בִּתְרֵין דְּרוֹעִין, הֲדָא הוּא דִכְתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי.","יהו\"ה נָחִית לְגַבָּהּ וְדָא הוּא רָזָא אָמֵ\"ן (דאמ\"ן) גִימַטְרִיָּא יאהדונה\"י דְּאִיהוּ חִבּוּרָא דִּתְּרֵין שְׁמָהָן בְּאַתְוָון. וּבְגִין דָּא גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ בְּזִמְנָא דְּאִינוּן תְרֵין בְּרֵישָׁא דְּצַדִּיקַיָּא.","אֲבָל כַּד אִינוּן בְּרֵישָׁא דְּחֲיָּיבַיָּיא כְּנֶסֶת יִשְׂרָאֵל אֲמָרַת לְגַבַּיְיהוּ (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת מֵאִלֵּין דְּשַׁרְיָין לְפַתָּאָה לִבְנִי נָשָׁא כְּמָה דַהֲווּ מְפָתִין לְיִשְׂרָאֵל בַעֲגָלָא בְּשִׁית שַׁעְתִּין, הֲדָא הוּא דִכְתִיב (שמות ל״ב:א׳) וַיַּרְא הָעָם כִּי בֹּשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר. וְאוּקְמוּהָ מַאי כִּי בֹּשֵׁשׁ, אֶלָּא בְּשִׁית שַׁעְתִּין עֲבָדוּ יָת עֶגְלָא בְּגִין לְאַפְרָשָׁא לוֹן מִשֶׁבַע. הֲדָא הוּא דִּכְתִיב (שמות י״ב:ט״ו) אַךְ בַּיוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְׁאֹר, אַךְ חִלֵק בֵּין שֵׁשׁ לְשֶׁבַע."],[],[[0,"","לְמָה בֵּי\"ת דּוֹמָה? לָאָדָם שֶׁנּוֹצַר בְּחָכְמָה, שֶׁסָּתוּם מִכָּל צַד וּפָתוּחַ מִלְפָנָיו, וְהָאָלֶ\"ף פְּתוּחָה מֵאַחֲרָיו. רוֹצֶה לוֹמַר, כִּי הִיא פְּתוּחָה לְקַבֵּל מִן הַכֶּתֶר, וְיֵשׁ לָהּ פֶּתַח לְהַשְׁפִּיעַ לַאֲחֵרִים: ע\"כ."],[1,"","וּמִנַּיִן לָנוּ שֶׁשָּׁמַיִם הֵם הַקָּדוֹשׁ בָּרוּךְ הוּא? שֶׁכָּתוּב (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. הַאִם שְׁלֹמֹה מִתְפַּלֵּל אֶל הַשָּׁמַיִם שֶׁיִּשְׁמְעוּ תְפִלָּתוֹ? אֶלָּא שֶׁנִּקְרָא שְׁמָן עַל שְׁמוֹ. וְלָמָּה נִקְרָא שָׁמַיִם? אֶלָּא שֶׁהוּא עָגֹל כְּמוֹ רֹאשׁ, וּמְלַמֵּד, הַמַּיִם מִימִינוֹ וְאֵשׁ מִשְּׂמֹאלוֹ וְהוּא בָּאֶמְצַע, שָׂא מַיִם, מֵאֵשׁ וּמִמַּיִם, וּמַכְנִיס בֵּינֵיהֶם שָׁלוֹם. בָּא הָאֵשׁ וּמָצָא מִצִּדּוֹ מִדַּת הָאֵשׁ. בָּא מַיִם וּמָצָא מִצִּדּוֹ מִדַּת הַמַּיִם, וְהַיְנוּ (איוב כה) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מָהֵם הַשָּׁמַיִם? מְלַמֵּד שֶׁגִּבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵשׁ וּמַיִם וּטְפָחָן זֶה בָּזֶה, וְעָשָׂה מֵהֶן רֹאשׁ לִדְבָרָיו, שֶׁנֶּאֱמַר (תהלים קיט) רֹאשׁ דְּבָרְךְ אֱמֶת: ע\"כ."],[2,"","וְהָאָרֶץ הָיְתָה תֹהוּ (בראשית א). בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה בַּקְּלִפּוֹת הָאֵלֶּה, הָיָה בּוֹנֶה עוֹלָמוֹת וּמַחֲרִיבָן, וַהֲרֵי הֵקִימוּ שֶׁאֵין הַשְׁפָּעָה בְּכָל הָעוֹלָמוֹת, וְנָהָר שֶׁהוּא צַדִּיק יֶחֱרַב וְיָבֵשׁ בִּשְׁנֵי הָעוֹלָמוֹת, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","וְיֵשׁ מִי שֶׁאוֹמֵר שֶׁעָלָה בְּמַחֲשַׁבְתּוֹ לִבְנוֹת עוֹלָמוֹת וּלְהַחֲרִיבָן, וְאָמַר זֶה מוֹעִיל לִי וְזֶה לֹא מוֹעִיל לִי. אֵלֶּה שֶׁנֶּאֱמַר בָּהֶם אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ - מוֹעִילִים לִי, וְהָאֲחֵרִים שֶׁנֶּאֱמַר בָּהֶם וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, שֶׁמַּרְאֶה עַל עוֹלָמוֹת שֶׁעָלָה בִרְצוֹנוֹ לִבְנוֹתָם וְלֹא עָשָׂה אוֹתָם - עֲלֵיהֶם נֶאֱמַר תֹּהוּ וָבהוּ."],[4,"","וּבִזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בַּקְּלִפּוֹת הַלָּלוּ, נֶאֱמַר בּוֹ (איכה ב) סַכֹּתָ בֶּעָנָן לָךְ מֵעֲבוֹר תְּפִלָּה. תֹּהוּ וָחֹשֶׁךְ, עֲלֵיהֶם נֶאֱמַר (שמות יד) וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, וְאֵלּוּ קְלִפּוֹת הָאֱגוֹז. הַמֹּחַ מִבִּפְנִים שֶׁתָּלוּי (של שלש) לְאַרְבָּעָה צְדָדִים זֶה יְהֹוָ\"ה, שֶׁהוּא לֹא מְקַבֵּל טֻמְאָה, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה כג) הֲלוֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. מָה אֵשׁ לֹא מְקַבֶּלֶת טֻמְאָה, כָּךְ שְׁמוֹ לֹא מְקַבֵּל טֻמְאָה."],[5,"","וּבִזְמַן שֶׁמִּתְגַּבְּרוֹת הַקְּלִפּוֹת הַלָּלוּ וְנִשְׁבָּרוֹת מֵהָאֱגוֹז, הַתְּפִלָּה, שֶׁהִיא שְׁכִינָה, אֲדנָ\"י, עוֹלָה לְבַעְלָהּ שֶׁהוּא יְהֹוָ\"ה, וּמַעֲלָה הַכֹּל. שֶׁבִּזְמַן שֶׁהוּא מִתְכַּסֶּה מִמֶּנָּה בַּקְּלִפּוֹת הַלָּלוּ, הִיא נִקְרֵאת עֲנִיָּה יְבֵשָׁה, וְאֵין לָהּ אֶלָּא מַה שֶּׁנּוֹתְנִים עֲבָדִים בַּחֲשַׁאי."],[6,"","וּבְאוֹתוֹ זְמַן שֶׁמִּתְפַּשֵּׁט הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הַקְּלִפּוֹת הַלָּלוּ, נֶאֱמַר (ישעיה ל) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךְ וְהָיוּ עֵינֶיךְ רֹאוֹת אֶת מוֹרֶיךְ. וּמַה שֶּׁהָיְתָה יְבֵשָׁה, נֶאֱמַר בָּהּ (שם ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ, וְנִקְרֵאת הַבְּרָכָה שֶׁלּוֹ, הַקָּרְבָּן שֶׁלּוֹ, עוֹלָה שֶׁלּוֹ שֶׁשּׂוֹרֵף כָּל הַקְּלִפּוֹת הַלָּלוּ."],[7,"","וְעוֹלָה אֶל הַקְּטֹרֶת הַקִּשּׁוּר שֶׁלּוֹ, הָעוֹלָה שֶׁלּוֹ, שֶׁכָּתוּב (ויקרא ו) זֹאת תּוֹרַת הָעֹלָה. הִיא הָעֹלָה - בִּתְפִלַּת שַׁחֲרִית, הִיא הָעֹלָה - אֵלָיו בִּתְפִלַּת מִנְחָה בְּכַמָּה רֵיחוֹת וּבְשָׂמִים שֶׁל גַּן עֵדֶן, שֶׁהִיא גַּן הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (שיר ד) גַּן נָעוּל אֲחֹתִי כַלָּה. סְתוּמָה שֶׁלֹּא נִפְתַּחַת אֶלָּא רַק לְבַעְלָהּ."],[8,"","וּכְשֶׁיָּבֹא בַּעְלָהּ, (תהלים נא) אֲדנָי שְׂפָתַי תִּפְתָּח, שֶׁהוּא דֶּלֶת עֶלְיוֹנָה נִפְתַּחַת אֵלָיו כְּתָרִים (בשני) עַמּוּדֵי אֱמֶת (נצח והוד) וּמְקַבֶּלֶת אוֹתוֹ בִּשְׁתֵּי זְרוֹעוֹת. זֶהוּ שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי."],[9,"","יְהֹוָ\"ה יוֹרֵד אֵלֶיהָ, וְזֶהוּ סוֹד אָמֵ\"ן גִּימַטְרִיָּא יאהדונה\"י, שֶׁהוּא חִבּוּר שְׁנֵי שֵׁמוֹת בְּאוֹתִיּוֹת, וְלָכֵן גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מֵהַמְבָרֵךְ, בִּזְמַן שֶׁהֵם שְׁנַיִם בְּרֹאשׁ הַצַּדִּיקִים."],[10,"","אֲבָל כְּשֶׁהֵם בְּרֹאשׁ הָרְשָׁעִים, כְּנֶסֶת יִשְׂרָאֵל אוֹמֶרֶת לָהֶם, (שם א) אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת, מֵאֵלֶּה שֶׁשּׁוֹרִים לְפַתּוֹת לִבְנֵי אָדָם, כְּמוֹ שֶׁהָיוּ מְפַתִּים אֶת יִשְׂרָאֵל בָּעֵגֶל בְּשֵׁשׁ הַשָּׁעוֹת. זֶהוּ שֶׁכָּתוּב (שמות לב) וַיַּרְא הָעָם כִּי בֹּשֵׁשׁ מֹשֶׁה לָרֶדֶת מִן הָהָר, וּבֵאֲרוּהָ, מַה זֶּה בֹּשֵׁשׁ? אֶלָּא בְּשֵׁשׁ שָׁעוֹת עָשׂוּ אֶת הָעֵגֶל, כְּדֵי לְהַפְרִידָם מִשֶּׁבַע. זֶה שֶׁכָּתוּב אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְׂאֹר. אַךְ - חִלֵּק בֵּין שֵׁשׁ לְשֶׁבַע."]]],[["וּבְגִין דָּא אָמְרָה כְּנֶסֶת לְיִשְׂרָאֵל שֶׁשְׁזָפַתְנִי הַשָׁמֶשׁ גָּרְמוּ דְאִסְתַּלַּק מִנִּי ו' דְּאִיהוּ הַשֵׁשׁ וְאוֹר הַשֵׁשׁ דַהֲוָה נָהִיר בְּסִתְרָא דְשִׁית תֵיבִין דְּאִינוּן (דברים ו׳:ד׳) שֵׁמַע יִשְׂרָאֵל יְיָ אֱלהֵינוּ יְיָ אֶחָד, בְּנֵי אִמִּי נִחֲרוּ בִּי, נִיחַר גְּרוֹנָם דְּבַטִּילוּ קְרִיַת שְׁמַע דְּאִתְּמָר בֵּיהּ (תהילים קמ״ט:ו׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם, וּבְגִין דָּא שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, דְּאִינוּן שְׁאָר אוּמִין עֶרֶב רָב. וּבְגִין דָּא כַּרְמִי שֶׁלִי לֹא נָטָרְתִי וּבְגִין דָּא אִינוּן עֶרֶב רָב מַצְלִיחִין בְּכֹלָּא.","כָּתְנוֹת עוֹר חֲשׁוֹכִין דְּעַיְינִין דְּאִתְּמָר בְּהוֹן (בראשית כ״ז:א׳) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, לְאִסְתַּכְּלָא לְאִלֵּין דְּאִתְּמָר בְּהוֹן (יחזקאל א׳:א׳-ב׳) נִפְתְּחוּ הַשָׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים דְּאִינוּן חֲמֵשׁ אוֹר דְעוֹבָדָא דִבְּרֵאשִׁית כָּתְנוֹת אוֹר אִינוּן.","וְהָאָרֶץ הָיְתָה תֹהוּ. וְהָאָרֶץ הוּא חַד. תֹהוּ תְּרֵין. בְּהוּ תְלָת. חֹשֶׁךְ אַרְבַּע. תְּהוֹם חֲמֵשׁ. וְאַרְבַּע אִינוּן דִכְלִילָן בְּגוּפָא וְאִינוּן אַרְבַּע יְסוֹדִין דְּאִינוּן קְלִיפִּין דֶּאֱגוֹזָא, וּבְגִין דָּא וְהָאָרֶץ הָיְתָה תֹהוּ. וְאוּקְמוּהָ הָיְתָה מִקַּדְמָת דְּנָא, דְהַכִי אָרְחָא דִקְלִיפִּין דְּמְקַדְמִין לְמוֹחָא. וְרוּחַ אֱלהִים דָא רוּחָא דִמְשִׁיחָא, דְּמִיָּד דִּיְהֵא מְרַחֶפֶת עַל אַנְפֵּי מַיָא דְּאוֹרַיְיתָא מִיָד יְהֵא פּוּרְקָנָא, הֲדָא הוּא דִכְתִיב (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר.","\u0003ספר הבהיר\u0004 אָמַר רִבִּי בְּרָכְיָה מַאי דִּכְתִיב וְהָאָרֶץ הָיְתָה תֹהוּ, מַאי מַשְׁמַע הָיְתָה, שֶׁכְּבָר הָיְתָה. וּמָאי תֹהוּ, דָבָר הַמָתְּהֵא אֶת בְּנֵי אָדָם. וּמָאי בֹּהוֹ, דָבָר שֶׁיְּשׁ בּוֹ מַמָּשׁ, דִכְתִיב בֹּהוֹ, בּוֹ הוּא. עַל שֵׁם מָאי דִּכְתִיב (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. בָּרָא בֹּהוֹ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע. בֹּהוֹ בְּשָׁלוֹם דִכְתִיב (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מְלַמֵּד שְׁמִכָאֵל שַׂר יְמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מָיִם וּבָרָד. וְגָבְרִיאֵל שַׂר שְׂמֹאלוֹ, אֵשׁ. וְשָׂר שָׁלוֹם בֵּינֵיהֶם מַכְרִיעֲ וְהַיְינוּ דִכְתִיב עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו.","וּמְנַלָן דְּבֹּהוֹ שָׁלוֹם, דִכְתִיב (ישעיהו מ״ה:ז׳) עוֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע, הָא כֵּיצָד רָע מִתֹּהוּ וְשָׁלוֹם מִבֹּהוֹ, בָּרָא תֹּהוּ וְשָׂם מְקוֹמוֹ בַּרָע, שֶׁנֶּאֱמַר עוֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע. בָּרָא בֹּהוֹ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם שֶׁנֶּאֱמַר עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. ע\"כ:","וַיְשַׁלְּחֵהוּ יְיָ אֱלהִים, מִיָד (למשיחא) מְשִׁיחָא דְּהוּא בְּגִנְתָּא דְעֵדֶן בְּמָה דְּאִתְּמָר בֵּיהּ וַיְשַׁלְּחֵהוּ מִגַּן עֶדֶן מֵעִדּוּן דִילֵיהּ. וְאַמָּאי לַעֲבוֹד אֶת הָאֲדָמָה דְאִיהִי שְׁכִינְתָּא בְּגִין דָּא וַיְשַׁלְּחֵהוּ מִיָד, דְּיִפּוּק מִתַּמָּן. וַיַּשְׁכֵּן מִקֶּדֶם לְגַן עֶדֶן אֶת הַכְּרוּבִים דְּאִינוּן מָשִׁיחַ בֵּן דָוִד וּמָשִׁיחַ בֵּן יוֹסֵף דְּמָשְׁכָא רוּחָא דִמְשִׁיחָא דְּאִתְּמָר בֵּיהּ, וְרוּחַ אֱלֹהִים דָא שִׁילֹ\"ה הַהוּא דְּאִתְּמָר בֵּיהּ וְאַצָלְתִּי מִן הָרוּחַ, דְהַכִי סָלִיק שִׁילֹה מֹשֶׁה בְּחוּשְׁבָּנָא. וַיַּשְׁכֵּן מִקֶּדֶם, דְאַקְדִּים שִׁילה לִתְרָוָויְהוּ בְּגִין דִּיְהֵא מְרַחֶפֶת עַל אַנְפּוֹי דְּאוֹרַיְיתָא וּפוּרְקָנָא בֵּיהּ תַלְיָּיא וְהָא אוּקְמוּהָ.","וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת מִיָד יְהֵא בִּידֵיהּ. וּמָאי נִיהוּ, מַטֵה מטט\"רון דְאִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וְעוֹד מַטֶּה דָא שְׁכִינְתָּא תַּתָּאָה וְאִם זָכוּ יִשְׂרָאֵל כְּלַפֵּי חֶסֶד לִימִינָא וְיִפְקוּן בְּרַחֲמֵי. וְאִם לָאו מַטֵה כְּלַפֵּי חוֹבָה לְסִטְרָא דִּגְבוּרָ\"ה דְּתַמָּן נָחָשׁ, אֵל אַחֵר. דְּתַבָע לִשְׁפּוֹךְ דָּמָא וְאִתְקְטִיל מָשִׁיחַ וְסַגִּיאִין מִיִּשְׂרָאֵל.","וּבְגִין דָּא אִתְּמָר (רות ג׳:י״ג) שִׁכְבִי עַד הַבֹּקֶר דְּאִיהוּ בֹקֶר דְּאַבְרָהָם דִּיְהֵא מַטֵה כְּלַפֵּי חֶסֶד וּבְגִין דָּא וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת וְכֹלָא לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים דְאִיהִי אוֹרַיְיתָא דְּאִתְּמָר בָּהּ עֵץ חַיִּים הִיא","וְאִיהִי אוֹרַיְיתָא דְּבְעַל פֶּה. אִם זָכָה בַּר נָשׁ, אִיהִי סַם חַיִּים דִילֵיהּ. וְאִם לָאו, הִיא מִתְהַפֶּכֶת לֵיהּ לְסַם הַמָּוֶת. וְהָא אוּקְמוּהָ מָארֵי מַתְנִיתִין הֲכִי, כְּגווָֹנָא דְמַטֶּה דְאִתְהַפַּךְ לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וּבְזִמְנָא הַהוּא יִתְמַחוּן מִן עַלְמָא כָּל אִינוּן דְּאִתְּמָר בְּהוֹן (שמות ז׳:כ״ב) וַיַּעֲשׂוֹּ כֵּן חַרְטוּמֵי מִצְרָיִם בְּלַטֵיהֶם:","יָשָׁב רִבִּי בּוֹן וְדַּרָשׁ מָהוּ דִּכְתִיב (ישעיהו מ״ה:ז׳) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ. אֶלָּא אוֹר שֶׁיֶּשׁ בּוֹ מַמָּשׁ כְּתִיב בּוֹ יְצִירָה. חֹשֶׁךְ שֶׁאֵין בּוֹ מַמָּשׁ כְּתִיב בּוֹ בְּרִיאָה כְּמָה דְּאַתְּ אָמֵר (עמוס ד׳:י״ג) יוֹצֵר הָרִים וּבוֹרֵא רוּחַ. אִי בָּעִית אִימָא אוֹר שֶׁיֶּשׁ בּוֹ מַמָּשׁ, כְּתִיב בּוֹ עֲשִׂיָּה. דִכְתִיב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וְאֵין הֲוָיָה אֶלָּא עֲשִׂיָּה וְקָרֵי בֵּיהּ יְצִירָה. חֹשֶׁךְ דְלָא הֲוָה בֵּיהּ עֲשִׂיָּה אֶלָּא הַבְדָּלָה וְהַפְרָשָׁה קָרֵי בֵּיהּ בְּרִיאָה כְּמָה דְּאַתְּ אָמֵר הִבְרִיא פְּלוֹנִי וְכוּ'. אָמַר רִבִּי בְּרָכְיָה מָהוּ דִּכְתִיב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר וְלֹא אָמַר וְהָיָה. מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ חֵפֶץ נָאָה וְהִקְצָהוּ עַד שֶׁזִימֵן לוֹ מָקוֹם וְשָׂמַהוּ שָׁם הֲדָא הוּא דִכְתִיב יְהִי אוֹר וַיְהִי אוֹר שֶׁכְּבָר הָיָה. ע\"כ:"],[],[[0,"","וְלָכֵן אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ. גָּרְמוּ שֶׁהִסְתַּלֵּק מִמֶּנִּי ו' (תפארת), שֶׁהוּא הַשֵּׁשׁ, וְאוֹר הַשֵּׁשׁ שֶׁהָיָה מֵאִיר בַּסֵּתֶר שֶׁל שֵׁשׁ תֵּבוֹת, שֶׁהֵם שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, בְּנֵי אִמִּי נִחֲרוּ בִּי, נִחַר גְּרוֹנָם שֶׁבִּטְּלוּ קְרִיאַת שְׁמַע, שֶׁנֶּאֱמַר בָּהּ (תהלים קמט) רוֹמְמוֹת אֵל בִּגְרוֹנָם, וְלָכֵן שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים, שֶׁהֵם שְׁאָר אֻמּוֹת עֵרֶב רַב. וְלָכֵן כַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי, וְלָכֵן אוֹתָם עֵרֶב רַב מַצְלִיחִים בַּכֹּל."],[1,"","כָּתְנוֹת עוֹר חֲשׁוּכֵי הָעֵינַיִם, שֶׁנֶּאֱמַר בָּהֶם (בראשית כז) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, לְהִסְתַּכֵּל עַל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (יחזקאל א) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים, שֶׁהֵם חָמֵשׁ פְּעָמִים אוֹר שֶׁבְּמַעֲשֵׂה בְרֵאשִׁית, כָּתְנוֹת אוֹר הֵם."],[2,"","וְהָאָרֶץ הָיְתָה תֹהוּ. וְהָאָרֶץ - הֲרֵי אֶחָד, תֹּהוּ - שְׁנַיִם, בּהוּ - שְׁלֹשָׁה. חֹשֶׁךְ - אַרְבָּעָה. תְּהוֹם - חֲמִשָּׁה. וְאַרְבָּעָה הֵם שֶׁכְּלוּלִים בַּגּוּף, וְהֵם אַרְבָּעָה יְסוֹדוֹת שֶׁהֵם קְלִפּוֹת הָאֱגוֹז, וְלָכֵן וְהָאָרֶץ הָיְתָה תֹהוּ. וּבֵאֲרוּהָ הָיְתָה - מִקֹּדֶם לָכֵן, שֶׁכָּךְ דֶּרֶךְ הַקְּלִפּוֹת שֶׁקּוֹדְמוֹת לַמֹּחַ. וְרוּחַ אֱלֹהִים - זוֹ רוּחוֹ שֶׁל מָשִׁיחַ, מִיָּד שֶׁתְּהֵא מְרַחֶפֶת עַל פְּנֵי מֵי הַתּוֹרָה, מִיָּד תִּהְיֶה גְּאֻלָּה. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר."],[3,"","אָמַר רַבִּי בְּרַכְיָה, מַה זֶּה שֶׁכָּתוּב וְהָאָרֶץ הָיְתָה תֹהוּ? מַה מַּשְׁמִיעַ הָיְתָה? שֶׁכְּבָר הָיְתָה, וּמַה זֶּה תֹּהוּ? דָּבָר הַמַּתְהֶה אֶת בְּנֵי אָדָם. וּמַה זֶּה בֹּהוּ? דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ, שֶׁכָּתוּב בּהוּ - בּוֹ הוּא, עַל שֵׁם מַה שֶּׁכָּתוּב (קהלת ז) גַּם אֶת זֶה לְעֻמּת זֶה עָשָׂה הָאֱלֹהִים. בָּרָא בהוּ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע. בֹהוּ בְּשָׁלוֹם, שֶׁכָּתוּב (איוב כה) עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. מְלַמֵּד שֶׁמִּיכָאֵל שַׂר יְמִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא - מַיִם וּבָרָד, וְגַבְרִיאֵל שַׂר שְׂמֹאלוֹ - אֵשׁ. וְשָׂם שָׁלוֹם בֵּינֵיהֶם מַכְרִיעַ, וְהַיְנוּ שֶׁכָּתוּב עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו."],[4,"","וּמִנַּיִן לָנוּ שֶׁבּהוּ שָׁלוֹם? שֶׁכָּתוּב (ישעיה מה) עֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע, הָא כֵיצַד? רָע מִתֹּהוּ, וְשָׁלוֹם מִבֹּהוּ. בָּרָא תֹהוּ וְשָׂם מְקוֹמוֹ בְּרָע, שֶׁנֶּאֱמַר עֹשֶׂה שָׁלוֹם וּבוֹרֵא רָע. בָּרָא בהוּ וְשָׂם מְקוֹמוֹ בְּשָׁלוֹם, שֶׁנֶּאֱמַר עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו:"],[5,"","וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים, מִיָּד (ולמשיח) אֶת הַמָּשִׁיחַ שֶׁהָיָה בְּגַן עֵדֶן, כְּמוֹ שֶׁנֶּאֱמַר בּוֹ (בראשית ג) וַיְשַׁלְּחֵהוּ (וגו') מִגַּן עֵדֶן, מֵעִדּוּנוֹ, וְלָמָּה? לַעֲבֹד אֶת הָאֲדָמָה, שֶׁהִיא שְׁכִינָה. בִּגְלַל זֶה וַיְשַׁלְּחֵהוּ, מִיָּד שֶׁיֵּצֵא מִשָּׁם. וַיַּשְׁכֵּן מִקֶּדֶם - לַגָּן - אֶת הַכְּרוּבִים, מָשִׁיחַ בֶּן דָּוִד וּמָשִׁיחַ בֶּן יוֹסֵף שֶׁמּוֹשֵׁךְ רוּחַ הַמָּשִׁיחַ, שֶׁנֶּאֱמַר בּוֹ וְרוּחַ אֱלֹהִים, זֶה שִׁילֹ\"ה, אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (במדבר יא) וְאָצַלְתִּי מִן הָרוּחַ, שֶׁכָּךְ עוֹלֶה שִׁילֹה כְּחֶשְׁבּוֹן מֹשֶׁה. וַיַּשְׁכֵּן מִקֶּדֶם, שֶׁמַּקְדִּים שִׁילֹה לִשְׁנֵיהֶם, כְּדֵי שֶׁתִּהְיֶה מְרַחֶפֶת עַל פְּנֵי הַתּוֹרָה, וְהַגְּאֻלָּה תְּלוּיָה בּוֹ, וַהֲרֵי פֵּרְשׁוּהָ."],[6,"","וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, מִיָּד יִהְיֶה בְיָדוֹ, וּמַהוּ? הַמַּטֶּה. מטטרו\"ן מִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וְעוֹד, מַטֶּה זוֹ שְׁכִינָה תַּחְתּוֹנָה, וְאִם זָכוּ יִשְׂרָאֵל - כְּלַפֵּי חֶסֶד, לְיָמִין, וְיֵצְאוּ בְרַחֲמִים. וְאִם לָאו - מַטֶּה כְּלַפֵּי חוֹבָה, לְצַד הַגְּבוּרָה, שֶׁשָּׁם הַנָּחָשׁ אֵל אַחֵר שֶׁמְּבַקֵּשׁ לִשְׁפֹּךְ דָּם, וְנֶהֱרָג מָשִׁיחַ וְרַבִּים מִיִּשְׂרָאֵל,"],[7,"","וְלָכֵן נֶאֱמַר (רות ג) שִׁכְבִי עַד הַבּקֶר, שֶׁהוּא בֹּקֶר שֶׁל אַבְרָהָם שֶׁיִּהְיֶה מַטֶּה כְּלַפֵּי חֶסֶד. וּבִגְלַל זֶה וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, וְהַכֹּל כְּדֵי לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים, שֶׁהִיא תּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (משלי ג) עֵץ חַיִּים הִיא,"],[8,"","וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. אִם זָכָה אָדָם - הִיא סַם חַיִּים שֶׁלּוֹ, וְאִם לָאו - הִיא מִתְהַפֶּכֶת לוֹ לְסַם הַמָּוֶת. וַהֲרֵי פֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה כָּךְ, כְּמוֹ שֶׁהַמַּטֶּה שֶׁהִתְהַפֵּךְ לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה. וּבְאוֹתוֹ זְמַן יִמָּחוּ מִן הָעוֹלָם כָּל אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שמות ז) וַיַּעֲשׂוּ כֵן חַרְטֻמֵּי מִצְרַיִם בְּלָטֵיהֶם:"],[9,"","יָשַׁב רַבִּי בוֹן וְדָרַשׁ, מַהוּ שֶׁכָּתוּב (ישעיה מה) יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ? אֶלָּא אוֹר שֶׁיֵּשׁ בּוֹ מַמָּשׁ כָּתוּב בּוֹ יְצִירָה, חֹשֶׁךְ שֶׁאֵין בּוֹ מַמָּשׁ כָּתוּב בּוֹ בְּרִיאָה, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ד) יוֹצֵר הָרִים וּבֹרֵא רוּחַ. אִם תִּרְצֶה אֹמַר, אוֹר שֶׁיֵּשׁ בּוֹ מַמָּשׁ כָּתוּב בּוֹ עֲשִׂיָּה, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְאֵין הֲוָיָה אֶלָּא עֲשִׂיָּה, וְקוֹרֵא בּוֹ יְצִירָה. חֹשֶׁךְ שֶׁלֹּא הָיָה בּוֹ עֲשִׂיָּה אֶלָּא הַבְדָּלָה וְהַפְרָשָׁה, קוֹרֵא בּוֹ בְּרִיאָה, כְּמוֹ שֶׁאַתָּה אוֹמֵר הִבְרִיא פְלוֹנִי וְכוּ'. אָמַר רַבִּי בְּרַכְיָה, מַהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְלֹא אָמַר וְהָיָה? מָשָׁל לְמֶלֶךְ שֶׁהָיָה לוֹ חֵפֶץ נָאֶה וְהִקְצָהוּ, עַד שֶׁזִּמֵּן לוֹ מָקוֹם וְשָׂמָהוּ שָׁם. זֶהוּ שֶׁכָּתוּב יְהִי אוֹר וַיְהִי אוֹר, שֶׁכְּבָר הָיָה:"]]],[["שְׁבִיעִי הֲוֵי בְּמִזְרָחוֹ שֶׁל עוֹלָם וּמִשָׁם בָּא זָרְעַם שֶׁל יִשְׂרָאֵל כִּי חוּט הַשִׁדְרָה מָשׁוּךְ מִן הַמוֹחַ שֶׁל אָדָם וּבָא לַאָמָּה וּמִשָׁם הוּא הַזֶרַע דִכְתִיב (ישעיהו מ״ג:ה׳) מִמִּזְרָח אַבִיא זַרְעֲךָ, כְּשֶׁיִשְׂרָאֵל טוֹבִים מִזֶּה הַמָּקוֹם אַבִיא זַרְעֲךָ יִתְחַדֵּשׁ לְךָ זְרַע חָדָשׁ,","וּכְּשֶׁיִשְׂרָאֵל רָעִים מִן הַזֶּרַע שֶׁכְּבָר בָּא לְעוֹלָם דִכְתִיב (קהלת א׳:ד׳) הוֹלֵךְ וְדוֹר בָּא. דוֹר שֶׁכְּבָר בָּא. וּמָאי מִמָעֲרָב אֲקַבְּצֵךְ, מֵאוֹתָה מִדָּה שׁנוֹטֶה תָּמִיד לְמַעֲרָב. וְלָמָּה אִיקְרֵי מַעֲרָב, מִפְּנֵי שֶׁשָּׁם מִתְעָרֵב כָּל הַזֶּרַע.","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְבֵן מֶלֶךְ שֶׁהָיָה לוֹ כַלָּה נָאָה וּצְנוּעָה בְּחַדְרוֹ, וְהָיָה לוֹקֵחַ מִבֵּית אָבִיו עוֹשֶׁר וּמֵבִיא לָהּ תָּמִיד וְלוֹקַחַת הַכֹּל וּמָצְנָעַת אוֹתוֹ תָּמִיד וּמְעַרֶבֶת הַכֹּל. לְסוֹף יַמִּים בִּיקֵשׁ לִרְאוֹת מָה אֲסָף וּמָה קִיבֵּץ הַיְינוּ דִכְתִיב וּמִמָעֲרָב אֲקַבְּצֵךְ. וּמַאי נִיהוּ בֵּית אָבִיו דִכְתִיב מִמִּזְרָח אַבִיא זַרְעֲךָ מְלַמֵּד שְׁמִמִזְרָח מֵבִיא וְזוֹרֵעַ בַּמָעֲרָב וְאַחַר כָּךְ הוּא מְקַבֵּץ מָה שְׁזָרָע. ע\"כ:","זי\"ן מַאי עֲבִידְתֵּיהּ, כְּמִנְיָן יְמֵי הַשָׁבוּעַ. לְלַמֶּדְךָ שֶׁכָּל יוֹם יֶשׁ לוֹ כֹּחַ. וּמָאי עֲבִידְתֵּיהּ הַכָא לְלַמֶּדְךָ שְׁכְּשֵׁם שֶׁיֶּשׁ חָכְמָה גְּדוֹלָה בַּאוֹזֶן לְאֵין תַּכְלִית, כָּךְ יֶשׁ הַכֹּחַ הַהוּא בְּכָל הַאֵבָרִים, וּמָאי אֵבָרִים, שֶׁבַע שֶׁיֶּשׁ בָּאָדָם. דִכְתִיב כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. ע\"כ:","נִשְׁמַת הַזָכָר, מִן הַזָכָר. וְנִשְׁמַת הַנְקֵבָה, מִן הַנְקֵבָה. וְהַיְינוּ דְּקָא אֲזִיל נָחָשׁ בַּתְרָה דְחַוָּה. אָמַר, הוֹאִיל וְנִשְׁמָתָה מִן הַצָּפוֹן אֲסִיתֵנָה מְהֵרָה. וּמָאי הַסָתָה הֲוָה, מִשׁוּם דְּבָּא עָלֵיהּ. שָׁאֲלוּ תַּלְמִידוֹי, עוֹבָדָא הֵיכִי הֲוָה. אָמַר לָהֶם, סמ\"אל הָרָשָׁע קַשָׁר עִם כָּל צְבָאוֹת מַעְלָה עַל רַבּוֹ. מִשׁוּם דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם. אָמַר, הֵיאָךְ אוּכַל לְהַחְטִיאוֹ וּלְגָרְשׁוֹ מִלְפָנָיו. יָרַד עִם כָּל חַיָּילוֹתָיו וּבִיקֵשׁ לוֹ בָּאָרֶץ חָבֵר כְּמוֹתוֹ וּמַנוּ נָחָשׁ, וְהָיָה לוֹ דְּמוּת גָמָל. רָכָב עָלָיו וּבָא לוֹ אֵצֶל הַאִשָׁה.","אָמַר לָהּ, אַף כִּי אָמַר אֱלֹהִים לא תֹאכְלוּ מִכָּל עֵץ הַגָּן. אָמַר אֲבָקֵשׁ יוֹתֵר וְאוֹסִיף, כְּדֵי שֶׁתִגְרָע הִיא. אָמְרָה, לֹא מֵנַעֲנוּ אֶלָּא מֵעֵץ הַדַּעַת אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִמֶּנּוּ וְלֹא תִּגְעוּ בּוֹ פֶּן תְּמוּתוּן. וְהוֹסִיפָה ב' דְּבָרִים, אָמְרָה מִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלהִים לא תֹאכְלוּ, וְלֹא נֶאֱמַר לָהּ אֶלָּא מֵעֵץ הַדַּעַת. וְאָמְרָה, לא תִּגְעוּ פֶּן תְּמוּתוּן.","מָה עָשָׂה סמ\"אל הָרָשָׁע הָלַךְ וְנָגַע בְּאִילָן וַהֲוָה הַאִילָן צוִֹוִחַ וְאֹמֵר (תהילים ל״ו:י״ב) אַל תְּבוֹאֵנִי רֶגֶל גָאַוָה וְיָד רְשָׁעִים אַל תְּנִידֵנִי, אַל תִּגַּע בִּי. שֶׁנֶּאֱמַר וְיָד רְשָׁעִים אַל תְּנִידֵנִי. הָלַךְ וְאָמַר לְאִשָׁה, הֲרֵי נָגַעְתִּי בְּאִילָן וְלָא מָתִּי, אַף אַתְּ תִּגְעִי בְּאִילָן וְלֹא תָּמוּתִי. הֲלְכָה הַאִשָׁה וְנָגְעָה בְּאִילָן וְרָאֲתָה מַלְאַךְ הַמָּוֶת בָּא כְּנֶגְדָה, אָמְרָה אוּלַי עַכְשָׁיו אֲנִי מֵתָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לוֹ אִשָּׁה אַחֶרֶת וְנוֹתְנָה לְאָדָם הַרֵינִי גוֹרֶמֶת לוֹ שֶׁיֹאכַל עִמִי אִם נָמוּת, נָמוּת שְׁנֵינוּ. וְאִם נִחְיֶּה, נִחְיֶּה שְׁנִינוּ. וְלַקְחָה מִפִּרְיוֹ וְנָתְּנָה גַּם לְבַעְלָה,","נִתְפָּקְחוּ עֵינֵי שְׁנֵיהֶם וְקָהוּ שִׁנָּיו. אָמַר לָהּ מַהוּ זֶה שְׁהֶאֵכַלְתָּנִי שֶׁקָהוּ שִׁינָי, כָּךְ קָהוּ שִׁינֵי כָּל הַבְּרִיוֹת. יָשָׁב לוֹ בְּדִין אֱמֶת שֶׁנֶּאֱמַר (תהילים ט׳:ה׳) יָשַׁבְתָּ לְכִּסֵא שׁוֹפֵט צֶדֶק. קָרָא לְאָדָם וְאָמַר לוֹ, לָמָה בָּרַחְתָּ מִפָּנָי. אָמַר לוֹ, אֶת קוֹלֶךָ שָׁמָעְתִּי בַּגָּן וְרָעַדוּ עַצְמוֹתָי וָאִירָא כִּי עֵירוֹם אָנֹכִי וָאֵחָבֵא. כִּי עֵירוֹם אָנֹכִי, מִפֹּעֲלִי. כִּי עֵירוֹם אָנֹכִי, מִצִווּיִּי. כִּי עֵירוֹם אָנֹכִי, מִמַעֲשָׂי וָאֵחָבֵא.","מָה הָיָה לְבוּשׁוֹ שֶׁל אָדָם עוֹר שֶׁל צִפּוֹרֶן, וְהִפְשִׁיטוֹ מֵעָלָיו. רָאָה עַצְמוֹ עֵרוֹם, שֶׁנְּאֱמַר מִי הִגִּיד לְךָ כִּי עֵירוֹם אַתָּה. אָמַר אָדָם לִפְנִי הַקָּדוֹשׁ בָּרוּךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם, כְּשֶׁהָיִיתִי לְבַדִּי שֶׁמָּא חֲטָאתִי לְךָ, אֶלָּא הַאִשָׁה שֶׁהֵבֶאתָּ לִּי הִיא הֵדִיחָה אוֹתִי מִדְּבָרֶיךָ. שֶׁנֶּאֱמַר הַאִשָׁה אֲשֶׁר נָתַתָּ עִמָּדִי הִיא נָתְּנָה לִּי מִן הָעֵץ.","אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לא דָּיֵּיךְ שֶׁחַטָּאת אֶלָּא שֶׁהֶחֶטֵאת לְאָדָם. אָמְרָה לְפָנָיו רִבּוֹנוֹ שֶׁל עוֹלָם, הַנָּחָשׁ הִשִׁיאַנִי לַחֲטוֹא לְפָנֶיךָ. הֵבִיא שְׁלָשְׁתָּן וְגָזַר עֲלֵיהֶן גְּזֵרוֹת דִּין ט' קְלַלוֹת וּמָוֶת וְהִפִּיל סמ\"אל וְאֶת הַכַּת שֶׁלּוֹ מִמָקוֹם קְדוּשָׁתָן מִן הַשָׁמַיִם, וְקִצֵץ רַגְלָיו שֶׁל נָּחָשׁ וְאִירְרוֹ מִכֹּל חַיָּה וּמִכָּל בְּהֵמָה וּפָקַּד עָלָיו שֶׁיִּהְיֶה מָפְשִׁיט אֶת עוֹרוֹ אַחַר שְׁבַע שָׁנִים. ע\"כ:"],[],[[0,"","שְׁבִיעִי הָיָה בְּמִזְרָחוֹ שֶׁל עוֹלָם, וּמִשָּׁם בָּא זַרְעָם שֶׁל יִשְׂרָאֵל, כִּי חוּט הַשִּׁדְרָה מָשׁוּךְ מִן הַמֹּחַ שֶׁל אָדָם וּבָא לָאַמָּה, וּמִשָּׁם הוּא הַזֶּרַע, שֶׁכָּתוּב (ישעיה מג) מִמִּזְרָח אָבִיא זַרְעֶךְ. כְּשֶׁיִּשְׂרָאֵל טוֹבִים - מִזֶּה הַמָּקוֹם אָבִיא זַרְעֶךְ, יִתְחַדֵּשׁ לְךְ זֶרַע חָדָשׁ."],[1,"","וּכְשֶׁיִּשְׂרָאֵל רָעִים - מִן הַזֶּרַע שֶׁכְּבָר בָּא לָעוֹלָם, שֶׁכָּתוּב (קהלת א) דּוֹר הֹלֵךְ וְדוֹר בָּא. דּוֹר שֶׁכְּבָר בָּא. וּמַהוּ מִמַּעֲרָב אֲקַבְּצֶךָּ? מֵאוֹתָהּ מִדָּה שֶׁנּוֹטָה תָּמִיד לַמַּעֲרָב. וְלָמָּה נִקְרָא מַעֲרָב? מִפְּנֵי שֶׁשָּׁם מִתְעָרֵב כָּל הַזֶּרַע."],[2,"","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְבֶן מֶלֶךְ שֶׁהָיְתָה לוֹ כַּלָּה נָאָה וּצְנוּעָה בְּחַדְרוֹ, וְהָיָה לוֹקֵחַ מִבֵּית אָבִיו עֹשֶׁר וּמֵבִיא לָהּ תָּמִיד, וְלוֹקַחַת הַכֹּל וּמַצְנַעַת אוֹתוֹ תָּמִיד וּמְעָרֶבֶת הַכֹּל. לְסוֹף יָמִים בִּקֵּשׁ לִרְאוֹת מָה אָסַף וּמַה קִּבֵּץ. הַיְנוּ שֶׁכָּתוּב (ישעיה מג) וּמִמַּעֲרָב אֲקַבְּצֶךָּ. וּמַה הוּא בֵּית אָבִיו? שֶׁכָּתוּב מִמִּזְרָח אָבִיא זַרְעֶךְ. מְלַמֵּד שֶׁמִּמִּזְרָח מֵבִיא, וְזוֹרֵעַ בַּמַּעֲרָב, וְאַחַר כָּךְ הוּא מְקַבֵּץ מַה שֶּׁזָּרַע: ע\"כ."],[3,"","זַיִ\"ן, מַה מַּעֲשֵׂהוּ? כְּמִנְיַן יְמוֹת הַשָּׁבוּעַ, לְלַמֶּדְךְ שֶׁכָּל יוֹם יֵשׁ לוֹ כֹּחַ. וּמַה מַּעֲשֵׂהוּ כָּאן? לְלַמֶּדְךְ שֶׁכְּשֵׁם שֶׁיֵּשׁ חָכְמָה גְּדוֹלָה בָּאֹזֶן לְאֵין תַּכְלִית, כָּךְ יֵשׁ הַכֹּחַ הַהוּא בְּכָל הָאֵבָרִים. וְאֵיזֶה אֵבָרִים? שֶׁבַע שֶׁיֵּשׁ בָּאָדָם, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם:"],[4,"","נִשְׁמַת הַזָּכָר מִן הַזָּכָר, וְנִשְׁמַת הַנְּקֵבָה מִן הַנְּקֵבָה, וְהַיְנוּ שֶׁהָלַךְ הַנָּחָשׁ אַחֲרֵי חַוָּה. אָמַר: הוֹאִיל וְנִשְׁמָתָהּ מִן הַצָּפוֹן, אֲסִיתֶנָּה מְהֵרָה. וּמָה הַהֲסָתָה שֶׁהָיְתָה? מִשּׁוּם שֶׁבָּא עָלֶיהָ. שָׁאֲלוּ תַּלְמִידָיו: אֵיךְ הָיָה הַמַּעֲשֶׂה? אָמַר לָהֶם: סמא\"ל הָרָשָׁע קָשַׁר עִם כָּל צִבְאוֹת מַעְלָה עַל רַבּוֹ, מִשּׁוּם שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא וּרְדוּ בִדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם. אָמַר, הֵיאַךְ אוּכַל לְהַחֲטִיאוֹ וּלְגָרְשׁוֹ מִלְּפָנָיו? יָרַד עִם כָּל חֵילוֹתָיו וּבִקֵּשׁ לוֹ בָּאָרֶץ חָבֵר כְּמוֹתוֹ. וּמִי הוּא? נָחָשׁ, וְהָיָה לוֹ דְּמוּת גָּמָל. רָכַב עָלָיו וּבָא לוֹ אֵצֶל הָאִשָּׁה."],[5,"","אָמַר לָהּ: אַף כִּי אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִכֹּל עֵץ הַגָּן. אָמַר, אֲבַקֵּשׁ יוֹתֵר וְאוֹסִיף, כְּדֵי שֶׁתִּגְרַע הִיא. אָמְרָה: לֹא מְנָעָנוּ אֶלָּא - מֵעֵץ הַדַּעַת אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִמֶּנּוּ וְלֹא תִגְּעוּ בּוֹ פֶּן תְּמֻתוּן. וְהוֹסִיפָה שְׁנֵי דְבָרִים. אָמְרָה, מִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ, וְלֹא נֶאֱמַר לָהּ אֶלָּא מֵעֵץ הַדַּעַת. וְאָמְרָה, לֹא תִגְּעוּ בּוֹ פֶּן תְּמֻתוּן."],[6,"","מֶה עָשָׂה סמא\"ל הָרָשָׁע? הָלַךְ וְנָגַע בָּאִילָן, וְהָיָה הָאִילָן צוֹוֵחַ וְאוֹמֵר: (תהלים לו) אַל תְּבוֹאֵנִי רֶגֶל גַּאֲוָה וְיַד רְשָׁעִים אַל תְּנִדֵנִי, אַל תִּגַּע בִּי, שֶׁנֶּאֱמַר וְיַד רְשָׁעִים אַל תְּנִדֵנִי. הָלַךְ וְאָמַר לָאִשָּׁה: הֲרֵי נָגַעְתִּי בָּאִילָן וְלֹא מַתִּי, אַף אַתְּ תִּגְּעִי בָּאִילָן וְלֹא תָמוּתִי. הָלְכָה הָאִשָּׁה וְנָגְעָה בָּאִילָן, וְרָאֲתָה מַלְאַךְ הַמָּוֶת בָּא כְּנֶגְדָּהּ. אָמְרָה: אוּלַי עַכְשָׁו אֲנִי מֵתָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לוֹ אִשָּׁה אַחֶרֶת וְנוֹתְנָהּ לָאָדָם, אֶלָּא הֲרֵינִי גּוֹרֶמֶת לוֹ שֶׁיֹּאכַל עִמִּי. אִם נָמוּת - נָמוּת שְׁנֵינוּ, וְאִם נִחְיֶה - נִחְיֶה שְׁנֵינוּ. וְלָקְחָה מִפִּרְיוֹ וְנָתְנָה גַּם לְבַעְלָהּ."],[7,"","נִתְפַּקְּחוּ עֵינֵי שְׁנֵיהֶם וְקָהוּ שִׁנָּיו. אָמַר לָהּ: מַה שֶׁהֶאֱכַלְתִּנִי שֶׁקָּהוּ שִׁנַּי? כָּךְ קָהוּ שִׁנֵּי כָּל הַבְּרִיּוֹת. יָשַׁב לוֹ בְּדִין אֱמֶת, שֶׁנֶּאֱמַר (שם ט) יָשַׁבְתָּ לְכִסֵּא שׁוֹפֵט צֶדֶק. קָרָא לָאָדָם וְאָמַר לוֹ: לָמָּה בָּרַחְתָּ מִפָּנַי? אָמַר לוֹ: אֶת קֹלְךְ שָׁמַעְתִּי בַּגָּן, וְרָעֲדוּ עַצְמוֹתַי, וָאִירָא כִּי עֵירֹם אָנֹכִי וָאֵחָבֵא. כִּי עֵירֹם אָנֹכִי - מִפֹּעֲלִי. כִּי עֵירֹם אָנֹכִי - מִצִּוּוּיִי, כִּי עֵירֹם אָנֹכִי - מִמַּעֲשַׂי, וָאֵחָבֵא."],[8,"","מֶה הָיָה לְבוּשׁוֹ שֶׁל אָדָם? עוֹר שֶׁל צִפֹּרֶן, וְהִפְשִׁיטוֹ מֵעָלָיו. רָאָה עַצְמוֹ עָרֹם, שֶׁנֶּאֱמַר מִי הִגִּיד לְךְ כִּי עֵירֹם אָתָּה. אָמַר אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, כְּשֶׁהָיִיתִי לְבַדִּי שֶׁמָּא חָטָאתִי לָךְ, אֶלָּא הָאִשָּׁה שֶׁהֵבֵאתָ לִי הִיא הִדִּיחָה אוֹתִי מִדְּבָרֶיךְ, שֶׁנֶּאֱמַר הָאִשָּׁה אֲשֶׁר נָתַתָּה עִמָּדִי הִוא נָתְנָה לִּי מִן הָעֵץ."],[9,"","אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֹא דַּיֵּךְ שֶׁחָטָאת, אֶלָּא שֶׁהֶחֱטֵאת לָאָדָם? אָמְרָה לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם, הַנָּחָשׁ הִשִּׁיאַנִי לַחֲטֹא לְפָנֶיךְ. הֵבִיא שְׁלָשְׁתָּם וְגָזַר עֲלֵיהֶם גְּזֵרוֹת דִּין. תִּשְׁעָה וּשְׁלֹשִׁים קְלָלוֹת וּמָוֶת, וְהִפִּיל סמא\"ל וְאֶת הַכַּת שֶׁלּוֹ מִמְּקוֹם קְדֻשָּׁתָם מִן הַשָּׁמַיִם, וְקִצֵּץ רַגְלָיו שֶׁל נָחָשׁ, וְאֵרְרוּ מִכָּל חַיָּה וּמִכָּל בְּהֵמָה, וּפָקַד עָלָיו שֶׁיִּהְיֶה מַפְשִׁיט אֶת עוֹרוֹ אַחַר שֶׁבַע שָׁנִים: ע\"כ."]]],[["(ישעיהו נ״ה:א׳) וּבְלָא מְחִיר יַיִן וְחָלָב, מָה עִנְיָן זֶה אֵצֶל זֶה. אֶלָּא מְלַמֵּד שֶׁהַיָּיִן הוּא פַּחַד וְחָלָב הוּא חֶסֶד. וּמִפְּנִי מָה הִזְכִּיר יַיִן תְּחִילָה, מִפְּנֵי שֶׁהוּא קָרוֹב אֵלֵינוּ יוֹתֵר, יַיִן וְחָלָב סַלְקָא דַּעְתָּךְ, אֶלָּא אֵימָא דְמוּת יַיִן וְחָלָב. ע\"כ.","רַבִּי חִיָּיא אָמַר מֵעוֹלָם דָא הֲווּ, וְגוּבְרִין גִבָּרִין דְּסִטְרָא בִישָׁא הֲווּ, דִּכְתִיב אַנְשֵׁי הַשֵׁם. אַנְשֵׁי שֵׁם לָא כְּתִיב, אֶלָּא אַנְשֵׁי הַשֵׁם כְּגווָֹנָא דָא כְּתִיב, זְכוֹר רָחֲמֶיךָ יְיָ וַחֲסָדֶּיךָ כִּי מֵעוֹלָם הֵמָּה, מֵעוֹלָם וַדָּאי נָטַל לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וְאִינוּן אֲבָהָן קַדְמָאֵי לְמֶהֱוֵי רְתִיכָא קַדִּישָׁא לְעֵילָא. אָמַר רַבִּי יִצְחָק מֵעוֹלָם דָא אִיהוּ מִטָּתוֹ שְׁלִשְׁלֹמָה דִּכְתִיב וְכוּ':","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, וְאָמַר רַבִּי יוֹחָנָן שְׁנֵי אוֹרִים הַגְּדוֹלִים הָיוּ, דִּכְתִיב וַיְהִי אוֹר. וְעָלָיו נֶּאֱמַר כִּי טוֹב. וְלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא הָאֶחָד וּגְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבֹא דִּכְתִיב מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם.","מְלַמֵּד שֶׁאוֹר הָרִאשׁוֹן אֵין כָּל בִּרְיָה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ דִּכְתִיב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב וַיַּרְא אֱלהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֲשֶׁר עָשָׂה, רָאָה טוֹב מְאֹד, מָזְהִיר וּבָּהִיר. וְלָקַח מֵאוֹרוֹ הַטּוֹב וְכָלַל שְׁלשִׁים וּשְׁתַּיִם נְתִיבוֹת הַחָכְמָה וּנְתָנוֹ לְעוֹלָם הַזֶּה.","וְהַיְינוּ דִּכְתִיב (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִּי אַל תַּעֲזוֹבוּ. הֱוֵי אוֹמֵר אוֹצָרָה שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם יִשְׁמֶרוּ זֹאת הַמִּדָּה בָּעוֹלָם הַזֶּה שֶׁזֹאת הַמִּדָּה נֶחְשֶׁבֶת בִּכְלַל הָעוֹלָם הַזֶּה, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה. יִזְכּוּ לְחַיֵּי הַעוֹלָם הַבָּא שֶׁהוּא הַטּוֹב הַגָּנוּז. וּמָאי נִיהוּ עוּזוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא,","דִּכְתִיב (חבקוק ג׳:ד׳) וְנֹגַהּ כָּאוֹר תִּהְיֶה. עָתִיד הַנֹּגַהּ שְׁנִלְקַח מֵהָאוֹר הָרִאשׁוֹן לִהְיוֹת כָּאוֹר, אִם יֵקַיְימוּ בָּנַי הַתּוֹרָה וְהַמִּצְוָה אֲשֶׁר כַּתָּבְתִּי לְהוֹרוֹתָּם. וּכְתִיב (משלי א׳:ח׳) שְׁמַע בְּנִי מוּסַר אָבִיךָ וְאַל תִיטוֹשׁ תּוֹרַת אִמֶּךָ.","וּכְתִיב (חבקוק ג׳:ד׳) קַרְנַיִם מִיָּדוֹ לוֹ וְשָׁם חֶבְיוֹן עֻזֹּהּ, וּמָאי חֶבְיוֹן עֻזּוֹ. אֶלָּא אוֹתוֹ הָאוֹר שֶׁגָנַז וְהֵחְבִּיא שֶׁנֶּאֱמַר (תהלים ל\"ד) צָפַנְתָּ לִירֵאֶיךָ, וְזֶה שֶׁנִשְׁאַר לָנוּ. (תהלים ל\"ד) פָּעַלְתָּ לַחוֹסִים בָּךְ, אוֹתָם שֶׁחוֹסִים בְּצִלְּךָ בָּעוֹלָם הַזֶּה וְשׁוֹמְרִים תּוֹרָתֶּךָ וּמְקַיְימִים מִצְוֹתֶּיךָ וּמְקַדְּשִׁים שִׁמְךָ הַגָּדוֹל וּמְיָּיחַדִּים בַּסֵּתֶר וּבַגָּלוּי, שְׁנֶּאֱמַר, נֶגֶד בְּנֵי אָדָם.","אָמַר רַבִּי רְחוּמָאי, מְלַמֵּד שֶׁהִיא אוֹרָה לְיִשְׂרָאֵל וְתוֹרָה אוֹרָה. שְׁנֶּאֱמַר, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר, וְאָמַר נֵר זוֹ מִצְוָה. וּמִצְוָה זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. אוֹר, זוֹ תּוֹרָה שֶׁבִּכְתָב. אֶלָּא מִתּוֹךְ שֶׁכְּבָר נִתְקַיָים הָאוֹר קָרֵי לָהּ אוֹר. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְאָדָם צָנוּעַ בְּסִיפֵי הַבַּיִת אַף עַל פִּי שְׁיוֹם הוּא וְאוֹר גָּדוֹל בָּעוֹלָם, אֵין אָדָם רוֹאֶה בְּתוֹךְ בֵּיתוֹ אֶלָּא אִם כֵּן הִכְנִיס בּוֹ נֵר. נֵר תּוֹרָה שֶׁבְּעַל פֶּה, אַף עַל פִּי שֶׁהִיא נֵר, צְרִיכָה לָהּ תּוֹרָה לְפָרֵק קוּשִׁיוֹתֶיהָ וּלְבָאֵר סוֹדוֹתֵּיהָ.","וּמָאי נִיהוּ יִרְאַת יְיָ, זֶה הָאוֹר הָרִאשׁוֹן. דְּאָמַר ר' מֵאִיר מָהוּ דִּכְתִיב וַיֹּאמֶר אֱלהִים יְהִי אוֹר וַיְהִי אוֹר וְלָא אָמַר לֵיהּ וַיְהִי כֵן. מְלַמֵּד שֶׁהָאוֹר הַהוּא גָּדוֹל וְאֵין כָּל בִּרְיָה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ. גְנָזוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים לֶעָתִיד לָבֹא","וְהִיא מִדַּת כָּל סְחוֹרָה שֶׁבָּעוֹלָם וְהוּא כֹּחַ אֶבֶן יְקָרָה שְׁקוֹרִין סוֹחָרֶת. וְדָר וְעַל מָה הִיא מִדַּת דָר, אֶלָּא מְלַמֵּד שְׁלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא מִזִיוָה אַחַת מֵאֲלְפָּיִם, וּבָנָה מִמֶּנָּה אֶבֶן יְקָרָה נָאָה וּמְקוּשֶׁטֶת וְכָלַל בָּהּ כָּל הַמִּצְוֹת. בָּא אַבְרָהָם וּבִיקֵשׁ כֹּחוֹ לָתֵת לוֹ, נָתְנוּ לוֹ אֶבֶן יְקָרָה זוֹ וְלא רָצָה אוֹתָהּ, זָכָה וְנָטַל מִדַתּוֹ שְׁנֶּאֱמַר (מיכה ז׳:כ׳) תִתֵּן אֱמֶת ליַעֲקֹב חֶסֶד לְאַבְרָהָם.","בָּא יִצְחָק וּבִיקֵשׁ כֹּחוֹ וְנָתְנוּ לוֹ, וְלא רָצָה בָּהּ. זָכָה וְנָטַל מִדַתּוֹ שֶׁהִיא מִדַּת הַגְּבוּרָה דְּהַיְינוּ הַפָּחַ\"ד. דִּכְתִיב (בראשית ל״א:נ״ג-נ״ד) וַיִּשָׁבַע יַעֲקֹב בְּפָחַד אָבִיו יִצְחָק. בָּא יַעֲקֹב וְרָצָה בָּהּ וְלֹא נְתַּנוּהוּ לוֹ, אָמַר לֵיהּ הוֹאִיל ואַבְרָהָם מִלְמַעְלָה וְיִצְחָק לְמַטָּה, אַתָּה תִּהְיֶה בְּאֶמְצַע וְתִכְלוֹל שְׁלָשְׁתַּם דִּכְתִיב תִתֵּן אֱמֶת ליַעֲקֹב.","וּמָאי אֱמְצָע, הַיְינוּ שָׁלוֹם. וְהָא כְּתִיב תִתֵּן אֱמֶת לְיַעֲקֹב, אֱמֶת וְשָׁלוֹם חַד הֲוִי. כְּמָה דְאַתְּ אָמֵר (אסתר ט׳:ל׳) דִּבְרֵי שָׁלוֹם וְאֱמֶת (ישעיהט'ל) כִּי שָׁלוֹם וֶאֱמֶת יִהְיֶה בִּימֵי וְהַיְינוּ דִּכְתִיב (ישעיהו נ״ח:י״ד) וְהַאָכַלְתִּיךָ נָחֲלַת יַעֲקֹב אָבִיךָ. דְּהַיְינוּ נָחַלָה גְמוּרָה דְּאִית לֵיהּ הַחֶסֶ\"ד וְהַפָּחַד וְהַאֶמֶת וְהַשָׁלוֹם.","וּלְפִיכָּךְ אָמַר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּינָה. אֶבֶן מָאֲסוּ אַבְרָהָם ויִצְחָק שְׁבָּנוּ אֶת הָעוֹלָם, הָיְתָה עַתָּה לְרֹאשׁ פִּינָה. וְלָמָּה מָאֲסוּ בָּהּ וַהֲלא נֶּאֱמַר (בראשית כ״ו:ה׳) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקוֹלִי וַיִשְׁמוֹר מִשְׁמָרְתִּי מִצְוֹתָי חֻקוֹתָי וְתוֹרוֹתָי. מָאי מִשְׁמָרְתִּי, אָמַר מִדַּת חֶסֶ\"ד. כָּל יְמֵי היוֹת אַבְרָהָם בָּעוֹלָם לא הוּצְרָכְתִּי אֲנִי לַעֲשׂוֹת מֵלַאכְתִּי, שֶׁהֲרֵי אַבְרָהָם עָמָד שָׁם בִּמְקוֹמִי. וַיִשְׁמוֹר מִשְׁמָרְתִּי, בְּמִדָּה זוֹ הָיְתָה מֵלַאכְתִּי שֶׁאֲנִי מֵזָכֵּה אֶת הָעוֹלָם כֻּלּוֹ וְאֲפִילוּ נִתְחַיְיבוּ, אֲנִי מֵזָכֵּה אוֹתָם."],[],[[0,"","וּבְלוֹא מְחִיר יַיִן וְחָלָב (ישעיה נה). מַהוּ יַיִן וְחָלָב? מָה עִנְיַן זֶה אֵצֶל זֶה? אֶלָּא מְלַמֵּד שֶׁהַיַּיִן הוּא פַּחַד, וְחָלָב הוּא חֶסֶד. וּמִפְּנֵי מָה הִזְכִּיר יַיִן תְּחִלָּה? מִפְּנֵי שֶׁהוּא קָרוֹב אֵלֵינוּ יוֹתֵר. יַיִן וְחָלָב עוֹלֶה עַל דַּעְתְּךְ? אֶלָּא אֱמֹר, דְּמוּת יַיִן וְחָלָב: ע\"כ."],[1,"","רַבִּי חִיָּיא אָמַר, מֵעוֹלָם זֶה הָיוּ, וּגְבָרִים גִּבּוֹרִים שֶׁל צַד הָרָע הָיוּ, שֶׁכָּתוּב (בראשית ו) אַנְשֵׁי הַשֵּׁם. אַנְשֵׁי שֵׁם לֹא כָתוּב, אֶלָּא אַנְשֵׁי הַשֵּׁם. כְּמוֹ זֶה כָּתוּב (תהלים כה) זְכֹר רַחֲמֶיךְ ה' וַחֲסָדֶיךְ כִּי מֵעוֹלָם הֵמָּה. מֵעוֹלָם וַדַּאי לָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֵם הָאָבוֹת הָרִאשׁוֹנִים לִהְיוֹת מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה. אָמַר רַבִּי יִצְחָק, מֵעוֹלָם - זוֹהִי מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, שֶׁכָּתוּב וְכוּ': ע\"כ."],[2,"","וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. וְאָמַר רַבִּי יוֹחָנָן, שְׁנֵי אוֹרוֹת הַגְּדוֹלִים הָיוּ, שֶׁכָּתוּב וַיְהִי אוֹר, וְעָלָיו נֶאֱמַר כִּי טוֹב. וְלָקַח הַקָּדוֹשׁ בָּרוּךְ הוּא הָאֶחָד וּגְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבא, שֶׁכָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם."],[3,"","מְלַמֵּד שֶׁאוֹר הָרִאשׁוֹן אֵין כָּל בְּרִיָּה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ, שֶׁכָּתוּב וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד. רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אֲשֶׁר עָשָׂה, רָאָה טוֹב מְאֹד מַזְהִיר וּבָהִיר. וְלָקַח מֵאוֹרוֹ הַטּוֹב, וְכָלַל שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת הַחָכְמָה, וּנְתָנוֹ לָעוֹלָם הַזֶּה,"],[4,"","וְהַיְנוּ שֶׁכָּתוּב (משלי ד) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם תּוֹרָתִי אַל תַּעֲזבוּ. הֱוֵי אוֹמֵר: אוֹצָרָהּ שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה. וְאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אִם יִשְׁמְרוּ זֹאת הַמִּדָּה בָּעוֹלָם הַזֶּה, שֶׁ את הַמִּדָּה נֶחְשֶׁבֶת בִּכְלַל הָעוֹלָם הַזֶּה, וְהִיא תּוֹרָה שֶׁבְּעַל פֶּה, יִזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא שֶׁהוּא הַטּוֹב הַגָּנוּז. וּמָה הוּא עֻזּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא?"],[5,"","שֶׁכָּתוּב (חבקוק ג) וְנֹגַהּ כָּאוֹר תִּהְיֶה. עָתִיד הַנֹּגַהּ שֶׁנִּלְקַח מֵהָאוֹר הָרִאשׁוֹן לִהְיוֹת כָּאוֹר, אִם יְקַיְּמוּ בָנַי הַתּוֹרָה וְהַמִּצְוָה אֲשֶׁר כָּתַבְתִּי לְהוֹרוֹתָם. וְכָתוּב (משלי א) שְׁמַע בְּנִי מוּסַר אָבִיךְ וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ,"],[6,"","וְכָתוּב (חבקוק ג) וְקַרְנַיִם מִיָּדוֹ לוֹ, וְשָׁם חֶבְיוֹן עֻזֹּה. וּמַהוּ חֶבְיוֹן עֻזֹּהּ? אֶלָּא אוֹתוֹ הָאוֹר שֶׁגָּנַז וְהֶחְבִּיא, שֶׁנֶּאֱמַר צָפַנְתָּ לִּירֵאֶיךְ. וְזֶה שֶׁנִּשְׁאָר לָנוּ - פָּעַלְתָּ לַחוֹסִים בָּךְ, אוֹתָם שֶׁחוֹסִים בְּצִלְּךְ בָּעוֹלָם הַזֶּה וְשׁוֹמְרִים תּוֹרָתְךְ וּמְקַיְּמִים מִצְווֹתֶיךְ, וּמְקַדְּשִׁים שִׁמְךְ הַגָּדוֹל וּמְיַחֲדִים בַּסֵּתֶר וּבַגָּלוּי, שֶׁנֶּאֱמַר נֶגֶד בְּנֵי אָדָם."],[7,"","אָמַר רַבִּי רְחוּמַאי, מְלַמֵּד שֶׁהִיא אוֹרָה לְיִשְׂרָאֵל, וְתוֹרָה אוֹרָה, שֶׁנֶּאֱמַר (משלי ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. וְאָמַר נֵר - זוֹ מִצְוָה, וּמִצְוָה - זוֹ תּוֹרָה שֶׁבְּעַל פֶּה. אוֹר - זֶה תּוֹרָה שֶׁבִּכְתָב. אֶלָּא מִתּוֹךְ שֶׁכְּבָר נִתְקַיֵּם הָאוֹר, קוֹרֵא לוֹ אוֹר. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאָדָם צָנוּעַ בְּסִפֵּי הַבַּיִת, אַף עַל פִּי שֶׁיּוֹם הוּא וְאוֹר גָּדוֹל בָּעוֹלָם, אֵין אָדָם רוֹאֶה בְּתוֹךְ בֵּיתוֹ אֶלָּא אִם כֵּן הִכְנִיס בּוֹ נֵר. נֵר - תּוֹרָה שֶׁבְּעַל פֶּה. אַף עַל פִּי שֶׁהִיא נֵר, צְרִיכָה לָהּ תּוֹרָה לְפָרֵק קֻשְׁיוֹתֶיהָ וּלְבָאֵר סוֹדוֹתֶיהָ,"],[8,"","וּמִי הוּא? יִרְאַת ה', זֶה הָאוֹר הָרִאשׁוֹן. שֶׁאָמַר רַבִּי מֵאִיר, מַהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר, וְלֹא אָמַר לוֹ וַיְהִי כֵן? מְלַמֵּד שֶׁהָאוֹר הַהוּא גָּדוֹל, וְאֵין כָּל בְּרִיָּה יְכוֹלָה לְהִסְתַּכֵּל בּוֹ, גְּנָזוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לָצַּדִּיקִים לֶעָתִיד לָבא,"],[9,"","וְהִיא מִדַּת כָּל סְחוֹרָה שֶׁבָּעוֹלָם, וְהוּא כֹּחַ אֶבֶן יְקָרָה שֶׁקּוֹרִין סֹחָרֶת וְדָר. וְעַל מָה הִיא מִדַּת דָּר? אֶלָּא מְלַמֵּד שֶׁלָּקַח הַקָּדוֹשׁ בָּרוּךְ הוּא מִזִּיוָהּ אַחַת מֵאַלְפַּיִם, וּבָנָה מִמֶּנָּה אֶבֶן יְקָרָה נָאָה וּמְקֻשֶּׁטֶת, וְכָלַל בָּהּ כָּל הַמִּצְווֹת. בָּא אַבְרָהָם וּבִקֵּשׁ כֹּחוֹ לָתֵת לוֹ, נָתְנוּ לוֹ אֶבֶן יְקָרָה זוֹ וְלֹא רָצָה אוֹתָהּ. זָכָה וְנָטַל מִדָּתוֹ, שֶׁנֶּאֱמַר (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב חֶסֶד לְאַבְרָהָם."],[10,"","בָּא יִצְחָק וּבִקֵּשׁ כֹּחוֹ, וְנָתְנוּ לוֹ וְלֹא רָצָה בָּהּ. זָכָה וְנָטַל מִדָּתוֹ, שֶׁהָיָה מִדַּת הַגְּבוּרָה, דְּהַיְנוּ הַפַּחַד, שֶׁכָּתוּב (בראשית לא) וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בָּא יַעֲקֹב וְרָצָה בָּהּ וְלֹא נְתָנוּהוּ לוֹ. אָמַר לוֹ, הוֹאִיל וְאַבְרָהָם מִלְמַעְלָה וְיִצְחָק לְמַטָּה, אַתָּה תִהְיֶה בָּאֶמְצַע וְתִכְלֹל שְׁלָשְׁתָּם, שֶׁכָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב."],[11,"","וּמַהוּ הָאֶמְצַע? הַיְנוּ שָׁלוֹם, וַהֲרֵי כָּתוּב תִּתֵּן אֱמֶת לְיַעֲקֹב? אֱמֶת וְשָׁלוֹם הֵם אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (אסתר ט) דִּבְרֵי שָׁלוֹם וֶאֱמֶת, (ישעיה לט) כִּי יִהְיֶה שָׁלוֹם וֶאֱמֶת בְּיָמָי, וְהַיְנוּ שֶׁכָּתוּב (שם נח) וְהַאֲכַלְתִּיךְ נַחֲלַת יַעֲקֹב אָבִיךְ. דְּהַיְנוּ נַחֲלָה גְּמוּרָה שֶׁיֵּשׁ לוֹ הַחֶסֶד וְהַפַּחַד וְהָאֱמֶת וְהַשָּׁלוֹם."],[12,"","וּלְפִיכָךְ אָמַר (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. אֶבֶן מָאֲסוּ - אַבְרָהָם וְיִצְחָק, שֶׁבָּנוּ אֶת הָעוֹלָם, הָיְתָה עַתָּה לְרֹאשׁ פִּנָּה. וְלָמָּה מָאֲסוּ בָּהּ, וַהֲלֹא נֶאֱמַר (בראשית כו) עֵקֶב אֲשֶׁר שָׁמַע אַבְרָהָם בְּקֹלִי וַיִּשְׁמֹר מִשְׁמַרְתִּי מִצְותַי חֻקּוֹתַי וְתוֹרֹתַי? מַה זֶּה מִשְׁמַרְתִּי? אָמְרָה מִדַּת חֶסֶד: שֶׁכָּל יְמֵי הֱיוֹת אַבְרָהָם בָּעוֹלָם לֹא הֻצְרַכְתִּי אֲנִי לַעֲשׂוֹת מְלַאכְתִּי, שֶׁהֲרֵי אַבְרָהָם עָמַד שָׁם בִּמְקוֹמִי. וַיִּשְׁמֹר מִשְׁמַרְתִּי - בְּמִדָּה זוֹ הָיְתָה מְלַאכְתִּי, שֶׁאֲנִי מְזַכֶּה אֶת הָעוֹלָם כֻּלּוֹ, וַאֲפִלּוּ נִתְחַיְּבוּ אֲנִי מְזַכֶּה אוֹתָם."]]],[["וְעוֹד מֵשִׁיבָם וּמֵבִיא בִּלְבַבָם לַעֲשׂוֹת רָצוֹן אֲבִיהֶם. כָּל זֶה עָשָׂה אַבְרָהָם וּכְתִיב (בראשית כ״א:ל״ג) וַיִּטַּע אֶשֶׁל בִּבְאֵר שָׁבַע. סִידֵר לַחְמוֹ וּמֵימָיו לְכָל בָּאֵי עוֹלָם וְהָיָה מֵזָכֵּה וּמְדַבֶּר עַל לִבָּם, לְמִי אַתֶּם עוֹבְדִּים, עִבְדוּ אֶת יְיָ אֱלֹהֵי הַשָׁמַיִם וְהָאָרֶץ. וְהָיָה דוֹרֵשׁ לָהֶם, עַד שֶׁהָיוּ בָּאִים וְשָׁבִים.","וּמְנַלָן שְׁאַף הַחַיָבִים הָיָה מֵזָכֵּה, שְׁנֶּאֱמַר הַמְכַסֶּה אֲנִי מְאַבְרָהָם וְאַבְרָהָם הָיֹה יִהְיֶה וְגוֹ'. אֶלָּא אֲזָכֶּהוּ שְׁיְבַקֵּשּׂ עֲלֵיהֶם רַחֲמִים וְיִזְכֶּה. וְכִי אֶפְשָׁר לוֹמַר שֶׁלּא יָדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלּא יָכְלוּ לְהִנָצֵל. אֶלָּא זְכוּתוֹ קָאָמַר. מִכָּאן אֲמְרוּ בָּא לִיטָהֵר מֵסָיְיעִין אוֹתוֹ. בָּא לִיטָמֵא פּוֹתְחִין לוֹ מָאי פּוֹתְחִין לוֹ, אוֹתָן הַפְּתוּחִים תָּמִיד.","מִצְוֹתָי חֻקוֹתָי וְתוֹרוֹתָי, אָמַר, הוֹאִיל וְלֹא חֲפָצְתִי בָּהּ אֱשְׁמוֹר מִצְוֹתֶיהָ. מָאי תוֹרוֹתָי, אֶלָּא אֲפִילוּ הוֹרָאוֹת וּפִּלְפּוּלִים שְׁמּוּרִים לְמָעְלָה, הוּא יְדָעֲם וּפִלְפֵּל וְקִיְימָם.","וּמָאי מִשָׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל, הֱוֵי אוֹמֶר צֶדֶק הַעֶלְיוֹן. וּמָאי הָאוֹר הַגָּדוֹל הַצָּפוּן, הַיְינוּ סוֹחָרֶת. וְהָאֶבֶן שְׁדָרָה לְמַטָּה הֵימֵּנָה נִקְרֵאת דָר, וּמָאי הוּא מִיָדוֹ לוֹ, הַיְינוּ חֲמֵשׁ אֶצְבָּעוֹת שֶׁל יָד יָמִין:","שֶׁבַע צוּרוֹת קְדוֹשׁוֹת יֶשׁ לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְכוּלָן כְּנֶגֶדָן בַּאָדָם, שְׁנֶּאֱמַר בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ זָכָר וּנְקֵבָה בָּרָא אוֹתָם. וְאֵלּוּ הֵן שׁוֹק יָמִין וּשְׁמֹאל. יָד יְמִין וּשְׁמֹאל גּוּף וּבְרִית הֲרֵי שֵׁשׁ. וְהָא אֲמַרְתָּ שִׁבְעָה. שֶׁבַע הֲוֵי בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד.","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שְׁעָלָה בְּלִבּוֹ לִיטָע בְּגָנוֹ תִשְׁעָה אִילָנִין זְכָרִים וְהָיוּ כֻּלָּם דְקַלִים, אָמַר כְּשְׁיִהְיוּ כֻּלָּם מִין אֶחָד, אִי אֶפְשָׁר לְהִתְקַיֵּים. מָה עָשָׂה, נָטַע אֶתְרוֹג בְּינֵיהֶם וְהוּא אֶחָד מֵאוֹתָן הַתִשְׁעָה שְׁעָלָה בְּלִבּוֹ לִהְיוֹת זְכָרִים וְאֶתְרוֹג מָאי הֲוֵי, נְקֵבָה וְהַיְינוּ דִּכְתִיב (ויקרא כ״ג:מ׳) פֶּרִי עֵץ הֲדַר כָּפֹּת תְּמָרִים (ע\"כ).","זָכָר וּנְקֵבָה בְּרָאָם. אֶפְשָׁר לוֹמַר כֵּן וְהָא כְּתִיב וַיִּבְרָא אֱלהִים אֶת הַאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ וְגוֹ' וְאַחַר כָּךְ אֱעֶשֶׂה לוֹ עֵזֶר כְּנֶגְדוֹ. וַיִּקַּח אַחַת מִצַּלְעוֹתָיו וַיִסְגֹר בָּשָׂר תַּחְתֵּנָה. אֶלָּא אֵימָא, דִּכְתִיב יְצִירָה וּכְתִיב בָּהֵן עֲשִׂיָּה וּכְתִיב בָּהֵן בְּרִיאָה. עֲשִׂיָּה דִּכְתִיב זָכָר וּנְקֵבָה בָּרָא אוֹתָם, בְּעֵת הִרְכִּיב הַנְּשָׁמָה עַל הַגּוּף וְאַסָף הַכֹּל. וּמְנַלָן דְּהָאי יְצִירָה לִישְׁנָא דְּאַסוֹפֵי הוּא דִּכְתִיב, וַיּיִצֶר יְיָ אֱלֹהִים כָּל חַיַּת הַשָּׂדֶה וְכָל עוֹף הַשָׁמַיִם וַיָּבֵא אֶל הַאָדָם, וְהַיְינוּ דִּכְתִיב עַל הַאָדָם זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אוֹתָם (ע\"כ).","בְּצֶלֶם אֱלהִים בָּרָא אוֹתוֹ בְּכָל אֵבָרָיו וְכָל חֲלָקַיו, וְהָא אֲמְרִינָן וא\"ו וּלְמָה הוּא דּוֹמֶה לְעוֹטֶה אוֹר כַּשַּׂלְמָה וְהַאי וא\"ו אֵינָה אֶלָּא שֵׁשׁ קְצָווֹת. אָמַר לֵיהּ, בְּרִית מִילָה וְזִווּגוֹ שֶׁל הַאָדָם חַשְׁבֵינַן אֶחָד. שְׁתֵּי יָדָיו ג'. רֹאשׁוֹ וְגוּפוֹ ה'. שְׁתֵּי שׁוֹקָיו ו'. וּכְּנְגְדָם כְּמוֹתָם בַּשָׁמַיִם דִכְתִיב (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְהַיְינוּ יַמִּים (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יַמִּים עָשָׂה יְיָ אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ וְלֹא אָמַר בְּשֵׁשֶׁת יַמִּים מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ כֹּחוֹ (ע\"כ):","וַיֹּאמֶר אֱלֹהִים פְּרוּ וּרְבוּ וְגוֹ'. פִקּוּדָא דָא לְאִתְעַסְקָא בְּהַאי עָלְמָא בְּפִרְיָה וְרִבְיָה וּלְמֶעֱבָּד תּוֹלָדִין לְאִתְפַּשְּׁטָא שֶׁמָּא קַדִּישָׁא לְכָל סִטְרִין וּלְמִלְקַּט רוּחִין וְנִשְׁמָתִין לְמֶהֱוֵי יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא עֵילָא וְתַתָּא. דְּכָל מָאן דְּלָא אִתְעַסַּק בְּפִרְיָה וְרִבְיָה אֲזְעִיר דִּיּוּקְנָא דְּמָרֵיהּ דְּלָא אִשְׁתְּכַח בְּהַאי עָלְמָא. וְגָרִים דְּלָא שַׁרְיָיא שְׁכִינְתָּא בְּהַאי עָלְמָא דְּכְּמָה דְאִתוֹסְפָן רוּחִין וְנִשְׁמָתִין, הֲכִי אִתּוֹסַף לְנַחֲתָא (נ\"א דוגמתא) בְּהַאי עָלְמָא זִיו יְקָרָא דְמַלְכָּא דִּכְתִיב (משלי י״ד:כ״ח) בְּרֹב עַם הֲדְרָת מֶלֶךְ וּבְּאֶפֶס לְאֹם מַחְתָּת רָזוֹן.","הֲדְרָת מֶלֶךְ דָא זִּיו יְקָרָא דְמַלְכָּא דְּאִתּוֹסַף לְנַחֲתָא בְּהַאי עָלְמָא, מַחְתָּת רָזוֹן דָא זְעִירוּ דְּדִיּוּקְנָא דְמַלְכָּא דְּאַזְעִיר מֵהָאי עָלְמָא, הֲכִי אֲזְעִיר מֵעֵילָא. דְּהָא הַהוּא זִיוָא לָא נָחִית, וְאִתְחַשָׁב עַל הַהוּא בָּר נָשׁ כְּאִילוּ אוֹשִׁיד דָּמִין דְּגָרַע דִּיּוּקְנָא דִלְתַתָּא כְּגווָֹנָא דִּלְעֵילָא דִּכְתִיב כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הַאָדָם, וְאִיהוּ אֲזְעִיר צֶלֶם אֱלֹהִים לְתַתָּא, וּדְמוּת וּדְיוּקְנָא לְעֵילָא. וְעַל דָא אִצְטְרִיךְ בַּר נָשׁ לְאִתְעַסְקָא בְּפִרְיָה וְרִבְיָה וּלְמֶעֱבַד צֶלֶם אֱלהִים לְאַסְגָּאָה יְקָרָא דְּיְיָ בְּכָל סִטְרִין:","\u0003רעיא מְהֵימְנָא\u0004 פִקּוּדָא דָּא לְקַיִּים פִּרְיָה וְרִבְיָה לְקַיֵּים בֵּן וּבַת. בְּגִין דְּאָב תַמָּן י', וְאֵם תַמָּן ה', בֵּן תַמָּן ו', בַּת תַמָּן ה'. ואָב ואֵם דְּלֵית לוֹן בֵּן וּבַת, גַּם יְיָ' לָא שַׁרְיָא עָלַיְיהוּ, וּכְגַוונָא דָּא בְּעוֹבָדָא דְּבְּרֵאשִׁית אָמַר פְּרוּ וּרְבוּ. פְּרוּ מִסִּטְרָא דִיְמִינָא וּרְבוּ מִסִּטְרָא דִשְׂמָאלָא דְבֵּיהּ בָּרָא אֱלקִים כֹּלָּא, וּבְרָא דָּא עַמּוּדָא דְאֶמְצָּעִיתָא. אֶת הָאָרֶץ דָּא שְׁכִינְתָּא. ואַמָּאי צָּרִיךְ ד', בְּאָב וְאֵם בֵּן וּבַת. בְּגִין דְּהָא אִתְקַדָשׁוּ וְאִתְבָּרְכוּ בְּשָׁלֹשׁ קְדוּשׁוֹת וְשֶׁבַע בִּרְכָאָן דְּאִינּוּן י', צְּרִיכִין לְמֶהֱוִי ד' אַתְוון דְּשַׁרְיָין עָלַיְיהוּ עֲשָׂרָה, לְמֶהֱוִי בָּר נָשׁ רְשׁוּת הַיָּחִיד לְמָארֵיהּ, דְּרָחְבּוֹ ד' וגָבְהוֹ י'."],[],[[0,"","וְעוֹד מְשִׁיבָם וּמֵבִיא בִּלְבָבָם לַעֲשׂוֹת רְצוֹן אֲבִיהֶם. כָּל זֶה עָשָׂה אַבְרָהָם, וְכָתוּב (שם כא) וַיִּטַּע אֵשֶׁל בִּבְאֵר שָׁבַע. סִדֵּר לַחְמוֹ וּמֵימָיו לְכָל בָּאֵי עוֹלָם, וְהָיָה מְזַכֶּה וּמְדַבֵּר עַל לִבָּם: לְמִי אַתֶּם עוֹבְדִים? עִבְדוּ אֶת ה' אֱלֹהֵי הַשָּׁמַיִם וְהָאָרֶץ! וְהָיָה דּוֹרֵשׁ לָהֶם, עַד שֶׁהָיוּ בָּאִים וְשָׁבִים."],[1,"","וּמִנַּיִן לָנוּ שֶׁאַף הַחַיָּבִים הָיָה מְזַכֶּה? שֶׁנֶּאֱמַר (שם יח) הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם, וְאַבְרָהָם הָיוֹ יִהְיֶה וְגוֹמֵר. אֶלָּא אֲזַכֵּהוּ שֶׁיְּבַקֵּשׁ עֲלֵיהֶם רַחֲמִים וְיִזְכֶּה. וְכִי אֶפְשָׁר לוֹמַר שֶׁלֹּא יָדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יָכְלוּ לְהִנָּצֵל? אֶלָּא זְכוּתוֹ הוּא אָמַר. מִכָּאן אָמְרוּ, בָּא לִטָּהֵר - מְסַיְּעִין אוֹתוֹ. בָּא לִטָּמֵא - פּוֹתְחִים לוֹ. מַה זֶּה פּוֹתְחִים לוֹ? אוֹתָם הַפְּתוּחִים תָּמִיד."],[2,"","מִצְותַי חֻקּוֹתַי וְתוֹרֹתַי - אָמַר, הוֹאִיל וְלֹא חָפַצְתִּי בָהּ, אֶשְׁמֹר מִצְותֶיהָ. מַה זֶּה תּוֹרֹתַי? אֶלָּא אֲפִלּוּ הוֹרָאוֹת וּפִלְפּוּלִים שְׁמוּרִים לְמַעְלָה הוּא יְדָעָם וּפִלְפֵּל וְקִיְּמָם."],[3,"","וּמַה זֶּה מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל? הֱוֵי אוֹמֵר, צֶדֶק הָעֶלְיוֹן. וּמַהוּ הָאוֹר הַגָּדוֹל הַצָּפוּן? וְהַיְנוּ סֹחָרֶת. וְהָאֶבֶן שֶׁדָּרָה לְמַטָּה הֵימֶנָּה נִקְרֵאת דָּר, וּמַה הוּא? מִיָּדוֹ לוֹ, הַיְנוּ חָמֵשׁ אֶצְבָּעוֹת שֶׁל יַד יָמִין: ע\"כ מההשמטות."],[4,"","שֶׁבַע צוּרוֹת קְדוֹשׁוֹת יֵשׁ לוֹ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכֻלָּן כְּנֶגְדָּן בָּאָדָם, שֶׁנֶּאֱמַר (בראשית א) בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, זָכָר וּנְקֵבָה בָּרָא אֹתָם. וְאֵלּוּ הֵן: שׁוֹק יָמִין וּשְׂמֹאל, יַד יָמִין וּשְׂמֹאל, גּוּף וּבְרִית - הֲרֵי שֵׁשׁ. וַהֲרֵי אָמַרְתָּ שֶׁבַע? שֶׁבַע הֵם בְּאִשְׁתּוֹ, (שם ב) וְהָיוּ לְבָשָׂר אֶחָד."],[5,"","מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁעָלָה בְּלִבּוֹ לִטַּע בְּגַנּוֹ תִּשְׁעָה אִילָנוֹת זְכָרִים, וְהָיוּ כֻלָּם דְּקָלִים. אָמַר, כְּשֶׁיִּהְיוּ כֻלָּם מִין אֶחָד, אֵי אֶפְשָׁר לְהִתְקַיֵּם. מֶה עָשָׂה? נָטַע אֶתְרוֹג בֵּינֵיהֶם, וְהוּא אֶחָד מֵאוֹתָם הַתִּשְׁעָה שֶׁעָלָה בְּלִבּוֹ לִהְיוֹת זְכָרִים. וְאֶתְרוֹג מַה נִּהְיָה? נְקֵבָה, וְהַיְנוּ שֶׁכָּתוּב (ויקרא כג) פְּרִי עֵץ הָדָר כַּפֹּת תְּמָרִים:"],[6,"","זָכָר וּנְקֵבָה בְּרָאָם (בראשית ה). אֶפְשָׁר לוֹמַר כֵּן? וַהֲרֵי כָּתוּב (שם א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ וְגוֹמֵר, וְאַחַר כָּךְ (שם) אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. וַיִּקַּח אַחַת מִצַּלְעֹתָיו וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה. אֶלָּא אֱמֹר, שֶׁכָּתוּב יְצִירָה, וְכָתוּב בָּהֶן עֲשִׂיָּה, וְכָתוּב בָּהֶן בְּרִיאָה. עֲשִׂיָּה, שֶׁכָּתוּב זָכָר וּנְקֵבָה בָּרָא אֹתָם, בְּעֵת הִרְכִּיב הַנְּשָׁמָה עַל הַגּוּף וְאָסַף הַכֹּל. וּמִנַּיִן לָנוּ שֶׁיְצִירָה זוֹ הִיא לְשׁוֹן אִסּוּף הוּא שֶׁכָּתוּב (שם ב) וַיִּצֶר ה' אֱלֹהִים וְגוֹ' כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם וַיָּבֵא אֶל הָאָדָם, וְהַיְנוּ שֶׁכָּתוּב עַל הָאָדָם - זָכָר וּנְקֵבָה בָּרָא אֹתָם. וַיְבָרֶךְ אֹתָם."],[7,"","בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ. בְּכָל אֵבָרָיו וּבְכָל חֲלָקָיו, וַהֲרֵי אָמוּר, וָא\"ו לְמַה הוּא דּוֹמֶה? (תהלים קד) לְעֹטֶה אוֹר כַּשַּׂלְמָה, וַהֲרֵי וָא\"ו אֵינָהּ אֶלָּא שֵׁשׁ קְצָווֹת. אָמַר לוֹ, בְּרִית מִילָה וְזִוּוּגוֹ שֶׁל אָדָם חֲשׁוּבִים אֶחָד. שְׁתֵּי יָדָיו שְׁלֹשָׁה. רֹאשׁוֹ וְגוּפוֹ חֲמִשָּׁה. שְׁתֵּי שׁוֹקָיו שִׁשָּׁה. וּכְנֶגְדָּם כְּמוֹתָם בַּשָּׁמַיִם, שֶׁכָּתוּב (קהלת ז) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים. וְהַיְנוּ יָמִים, (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְלֹא אָמַר בְּשֵׁשֶׁת יָמִים, מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ כֹּחוֹ:"],[8,"","וַיֹּאמֶר אֱלֹהִים פְּרוּ וּרְבוּ וְגוֹמֵר. מִצְוָה זוֹ לְהִתְעַסֵּק בָּעוֹלָם הַזֶּה בִּפְרִיָּה וּרְבִיָּה וְלַעֲשׂוֹת תּוֹלָדוֹת, שֶׁיִּתְפַּשֵּׁט הַשֵּׁם הַקָּדוֹשׁ לְכָל הַצְּדָדִים, וְלִלְקֹט רוּחוֹת וּנְשָׁמוֹת, שֶׁיִּהְיֶה כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּלְמַטָּה. שֶׁכָּל מִי שֶׁלֹּא מִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה, מַקְטִין אֶת הַדְּמוּת שֶׁל רִבּוֹנוֹ שֶׁלֹּא יִמָּצֵא בָּעוֹלָם הַזֶּה, וְגוֹרֵם שֶׁלֹּא תִשְׁרֶה שְׁכִינָה בָּעוֹלָם הַזֶּה. כְּמוֹ שֶׁמִּתּוֹסְפוֹת רוּחוֹת וּנְשָׁמוֹת, כָּךְ מִתּוֹסֵף לָרֶדֶת (נ\"א: דגמא) לָעוֹלָם הַזֶּה כְּבוֹד הַמֶּלֶךְ, שֶׁכָּתוּב (משלי יד) בְּרָב עָם הַדְרַת מֶלֶךְ וּבְאֶפֶס לְאֹם מְחִתַּת רָזוֹן."],[9,"","הַדְרַת מֶלֶךְ - זֶה זִיו כְּבוֹד הַמֶּלֶךְ שֶׁמִּתּוֹסֵף לָרֶדֶת לָעוֹלָם הַזֶּה. מְחִתַּת רָזוֹן - זֶה הַקְטָנַת דְּמוּת הַמֶּלֶךְ שֶׁמַּקְטִין מֵהָעוֹלָם הַזֶּה, כָּךְ מַקְטִין גַּם לְמַעְלָה, שֶׁהֲרֵי אוֹתוֹ זִיו לֹא יוֹרֵד, וְנֶחְשָׁב עַל אוֹתוֹ אָדָם כְּאִלּוּ שָׁפַךְ דָּמִים, שֶׁגָּרַע הַדְּמוּת שֶׁלְּמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (בראשית ט) כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. וְהוּא מַקְטִין צֶלֶם אֱלֹהִים לְמַטָּה וְהַדְּמוּת וּדְיוֹקָן לְמַעְלָה, וְלָכֵן צָרִיךְ אָדָם לְהִתְעַסֵּק בִּפְרִיָּה וּרְבִיָּה וְלַעֲשׂוֹת צֶלֶם אֱלֹהִים לְהַגְדִּיל כְּבוֹד ה' בְּכָל הַצְּדָדִים: ע\"כ מההשמטות."],[10,"","מִצְוָה זוֹ לְקַיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה לְקַיֵּם בֵּן וּבַת, מִשּׁוּם שֶׁאָב שָׁם י', וְאֵם שָׁם ה', בֵּן שָׁם ו', בַּת שָׁם ה', וְאָב וָאֵם שֶׁיֵּשׁ לָהֶם בֵּן וּבַת, גַּם ה' לֹא שׁוֹרֶה עֲלֵיהֶם. וּכְמוֹ זֶה בְּמַעֲשֵׂה בְרֵאשִׁית אָמַר (בראשית א) פְּרוּ וּרְבוּ, פְּרוּ מִצַּד הַיָּמִין, וּרְבוּ מִצַּד הַשְּׂמֹאל, שֶׁבּוֹ בָּרָא אֱלֹהִים הַכֹּל, וּבָרָא זֶה עַמּוּד הָאֶמְצָעִי, אֵת הָאָרֶץ - זוֹ שְׁכִינָה. וְלָמָּה צָרִיךְ אַרְבַּע, בְּאָב וָאֵם בֵּן וּבַת? מִשּׁוּם שֶׁהֲרֵי הִתְקַדְּשׁוּ וְהִתְבָּרְכוּ בְּשָׁלֹשׁ קְדֻשּׁוֹת וְשֶׁבַע בְּרָכוֹת שֶׁהֵם י', צְרִיכוֹת לִהְיוֹת אַרְבַּע אוֹתִיּוֹת שֶׁשּׁוֹרוֹת עֲלֵיהֶם עֲשָׂרָה, לִהְיוֹת אָדָם רְשׁוּת הַיָּחִיד לַאֲדוֹנוֹ, שֶׁרָחְבּוֹ אַרְבָּעָה וְגָבְהוֹ עֲשָׂרָה."]]],[["וּמָאן דְּמִתְעַסֵּק בְּאוֹרַיְיתָא וּבְמִצְּוָה בִּדְחִילוּ וּבִרְחִימוּ דְּמָארֵיהּ בְּאֲתַר דְּיִרְאָה שַׁרְיָא תַמָּן י', בְּאֲתַר דְּאַהֲבָה שַׁרְיָא תַמָּן ה'. בְּאֲתַר דְתוֹרָה שַׁרְיָא ו', וּבְאֲתַר דְמִצְּוָה שַׁרְיָא ה'. בְּאֲתַר דְמַחֲשָׁבָה דְאִתְמָר בָּהּ (שמואל ב ז׳:י״ט) וְזֹאת תּוֹרַת הַאָדָם, כַּלִיל מִכֹּלָא. שַׁרְיָא בֵּיה יוֹ\"ד הֵ\"א וא\"ו הֵ\"א. (תהילים קכ״ז:א׳) אִם יְיָ לֹא יִבְנֶה בַּיִת שָׁוְא עָמְלוּ בּוֹנָיו בּוֹ, מָאי שָׁוְא עָמְלוּ בּוֹנָיו בּוֹ, אִינוּן סַמָּאֵ\"ל וְנָחָשׁ ע\"כ:","יָשָׁב רַבִּי בְּרָכְיָה וְדָּרַשׁ מָאי הַאי דְּקָא אֲמְרִינָן כָּל יוֹמָא הַעוֹלָם הַבָּא, וְלֹא יָדְעִינָן מָאי קָאָמַר, הַעוֹלָם הַבָּא מְתַּרְגֵּם עָלְמָא דְּאָתֵי מְלַמֵּד שְׁקוֹדֶם שֶׁנִּבְרָא הָעוֹלָם עָלָה בְּמַחְשָׁבָה לִבְרוֹא אוֹר גָּדוֹל לְהָאִיר וְנִבְרָא אוֹר גָּדוֹל שֶׁאֵין כָּל בִּרְיָה יְכוֹלָה לִשְׁלוֹט בּוֹ, צָפָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינָן יְכוֹלִין לְסוֹבְלוֹ לָקַח שְׁבִיעִי וְשָׂם לָהֶם בִּמְקוֹמוֹ וְהַשְׁאָר גְנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבֹא. אָמַר אִם יִזְכּוּ בָּזֶה הַשְׁבִיעִי וְיִשְׁמְרוּהוּ, אֶתֶּן לָהֶם זֶה לְעוֹלָם אַחֲרוֹן. וְהַיְינוּ דִּכְתִיב, הַעוֹלָם הַבָּא. שֶׁכְּבָר בָּא מִקוֹדֶם שֵׁשֶׁת יְמֵי בְּרִאשִׁית. הֲדָא הוּא דִכְתִיב, (שם ל\"א) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם:","שְׁמִינִי מָאי הֲוֵי, יֶשׁ לוֹ להַקָּדוֹשׁ בָּרוּךְ הוּא צַדִּיק אֶחָד בָּעוֹלָם וְחֲבִיב לוֹ מִפְּנֵי שְׁמְקַיֵּים כָּל הָעוֹלָם כֻּלּוֹ וְהוּא יְסוֹדוֹ וְהוּא מְכַלְכְּלוֹ וּמַצְמִיחוֹ וּמְגַּדְּלוֹ וּמְשָׂמְחוֹ. אֲהוּב וְחֲבִיב לְמַעְלָה, נוֹרָא וְאַדִּיר לְמַטָּה. מְתוּקַן וּמְקוּבָּל לְמַעְלָה, מְתוּקַן וּמְקוּבָּל לְמַטָּה. וְהוּא יְסוֹד הַנְפָשׁוֹת כֻּלָּם.","אֲמַרְתָּ שְׁמִינִי וְאָמַרְתָּ יְסוֹד הַנְפָשׁוֹת כֻּלָּם, וְהָא כְּתִיב וּבְיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ. אִין שְׁבִיעִי הֲוִי, אֶלָּא מִשׁוּם דְּמַכְרִיעַ בֵּינַיְיהוּ, וְיֵשׁ אִינוּן תְלָת לְרָע וּתְלָת לְעֵיל, וְהוּא דְּאַכְרָע בֵּינַיְיהוּ.","וּמָאי טַעְמָא אִקְרֵי שְׁבִיעִי, וְכִי הוּא בַּשְׁבִיעִי, לֹא. אֶלָּא מִפְּנֵי שהַקָּדוֹשׁ בָּרוּךְ הוּא שַׁבָת בְּשַׁבָּת בְּאוֹתָה הַמִּדָּה. דִּכְתִיב (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָׁמַיִם וְאֶת הָאָרֶץ וּבַיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ. מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֶשׁ לוֹ מַאֲמָר אֶחָד שֶׁהוּא אֲדוֹן לוֹ, לא מִפְּנֵי שֶׁהוּא נִבְרָא בּוֹ, אֶלָּא מִפְּנִי שֶׁהוּא פּוֹעֵל בָּעוֹלָם פְּעוּלָה הַמְסוּרָה לוֹ בְּיָדוֹ. פָּעַלוּ כֻּלָּם פְּעוּלָתָם וְקִיֵּימוּ מַעֲשֵׂיהֶם לְבָד, בָּא יוֹם הַשְׁבִיעִי וּפָעָל פְּעוּלָתוֹ. שָׂמְחוּ כֻּלָּם וְאַף הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלֹא עוֹד אֶלָּא שְׁגַּדְלָה נִשְׁמָתוֹ, דִּכְתִיב וּבְיוֹם הַשְׁבִיעִי שַׁבָּת וַיִּנָּפַשׁ.","וּמָאי הֲוֵי שְׁבִיתָה זוֹ דְּלָא הֲוֵי בָּהּ מְלָאכָה, וַהֲוֵי הַנָחַה. דִּכְתִיב שַׁבָּת. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיוּ לוֹ שִׁבְעָה גָּנוֹת, וּבַגָּן הָאֶמְצָעִי מַעְיָן נָאֶה נוֹבֵעַ מִמָקוֹר מַיִם חַיִּים, ג' מִימִינוֹ וג' מִשְׂמֹאלוֹ. וּמִיָּד שׁפּוֹעֶל בָּעוֹלָם, אָז מִתְמָלֵא וְשְׂמֵחִים כֻּלָּם. וְאוֹמְרִים לְצֹרְכֵנוּ הוּא מִתְמָלֵא וְהוּא מָשְׁקֵה אוֹתָם וּמֵגַּדְלָם וְהֵם מָמְתִינִין וְשׁוֹבְתִין וְהוּא מָשְׁקֵה אֶת הַשִׁבְעָה.","וְהָא כְּתִיב (ישעיהו מ״ג:ה׳) מִמִּזְרָח אֲבִיא זַרְעֲךָ וַהֲוֵי חַד מִנְהוֹן וּמָשְׁקֵה לֵיהּ. אֶלָּא אֵימָא הוּא מָשְׁקֵה אֶת הַלֵּב וְהַלֵּב מָשְׁקֵה אַחַר כֵּן כֻּלָּם. וּמָאי נִיהוּ מִדָּה שְׁבִיעִית הוֵי אוֹמֶר זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.","מָאי טַעְמָא אָמַר אֶת שַׁבְּתוֹתַי, וְלֹא אָמַר אֶת שַבָּתַי. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְמֶלֶךְ שֶׁהָיָה לוֹ כַלָּה נָאָה וְכָל שָׁבוּעַ וְשָׁבוּעַ מָזְמִינָה יוֹם אֶחָד לִהְיוֹת עִמּוֹ. וְהַמֶּלֶךְ יֶשׁ לוֹ בָּנִים נָאִים וְאַהוּבִים אָמַר לָהֶם הוֹאִיל וְכֵן שִׂמְחוּ אַתֶּם גַם כֵּן בְּיוֹם שִׂמְחַתִי כִּי אֲנִי בְּשְׁלָכֶם אֲנִי מִשְׁתַּדֵּל וְאַתֶּם גַּם כֵּן הֲדְרוּ אוֹתוֹ.","וּמָאי זָכוֹר וְשָׁמוֹר זָכוֹר לַזָּכָר וְשָׁמוֹר לַנְּקֵבָה. מָאי טַעְמָא (ויקרא י״ט:ל׳) וּמִקְדָשִׁי תִּירָאוּ. שִׁמְרוּ עַצְמְכֶם מֵהִרְהוּר, כִּי מִקְדָשִׁי קָדוֹשׁ הוּא לָמָה (ויקרא כ׳:ח׳) כִּי אֲנִי יְיָ מֵקַדִשְׁכֶם, אֲנִי בְּכָל צָד. ע\"כ:","תָּאנָא עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים וּכְּשְׁיִשְׂרָאֵל צַדִּיקִים מִתְגַבֵּר וְאִם לָאו מִתְחַלֵשׁ וְהוּא סוֹבֵל כָּל הָעוֹלָם דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְאִם חָלַשׁ לֹא יוּכַל לְהִתְקַיֵּים הָעוֹלָם. עד כאן:","רַבִּי חֲנִינָא פָּרִישׁ כָּל חַד עַל קִיוּמָא. שָׂשׂוֹן חַד. שִׂמְחָה תְרֵין. חָתָן תְלָת. כַלָּה אַרְבַּע. גִּילָה דִּיצָה אַהֲבָה אַחְוָה שָׁלוֹם וְרֵיעוּת י' כְּנֶגֶד עֲשָׂרָה מַאֲמָרוֹת שְׁבָּהֵן נִבְרָא הָעוֹלָם. ע\"כ:"],[],[[0,"","וּמִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה וּבַמִּצְוָה בְּיִרְאָה וּבְאַהֲבַת אֲדוֹנוֹ, בִּמְקוֹם יִרְאָה שְׁרוּיָה שָׁם י', בִּמְקוֹם אַהֲבָה שְׁרוּיָה שָׁם ה', בִּמְקוֹם תּוֹרָה שְׁרוּיָה ו', וּבִמְקוֹם מִצְוָה שְׁרוּיָה ה', בִּמְקוֹם הַמַּחֲשָׁבָה שֶׁנֶּאֱמַר בָּהּ (שמואל ב יט) וְזֹאת תּוֹרַת הָאָדָם, כָּלוּל מֵהַכֹּל, שׁוֹרָה בּוֹ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. מַה זֶּה שָׁוְא עָמְלוּ בוֹנָיו בּוֹ? אֵלּוּ סמא\"ל וְנָחָשׁ: ע\"כ מההשמטות."],[1,"","יָשַׁב רַבִּי בְּרֶכְיָה וְדָרַשׁ, מַה זֶּה שֶׁאָנוּ אוֹמְרִים כָּל יוֹם הָעוֹלָם הַבָּא, וְלֹא יוֹדְעִים מָה אָמַר, הָעוֹלָם הַבָּא מְתֻרְגָּם עָלְמָא דְאָתֵי (העולם הבא), מְלַמֵּד שֶׁקֹּדֶם שֶׁנִּבְרָא הָעוֹלָם עָלָה בְמַחֲשָׁבָה לִבְרֹא אוֹר גָּדוֹל לְהָאִיר, וְנִבְרָא אוֹר גָּדוֹל שֶׁאֵין כָּל בְּרִיָּה יְכוֹלָה לִשְׁלֹט בּוֹ. צָפָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵינָם יְכוֹלִים לְסָבְלוֹ, לָקַח שְׁבִיעִי וְשָׂם לָהֶם בִּמְקוֹמוֹ, וְהַשְּׁאָר גְּנָזוֹ לַצַּדִּיקִים לֶעָתִיד לָבא. אָמַר, אִם יִזְכּוּ בְּזֶה הַשְּׁבִיעִי וְיִשְׁמְרוּהוּ - אֶתֵּן לָהֶם זֶה לְעוֹלָם אַחֲרוֹן, וְהַיְנוּ שֶׁכָּתוּב הָעוֹלָם הַבָּא, שֶׁכְּבָר בָּא מִקֹּדֶם שֵׁשֶׁת יְמֵי בְרֵאשִׁית. זֶהוּ שֶׁכָּתוּב (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ פָּעַלְתָּ לַחוֹסִים בָּךְ נֶגֶד בְּנֵי אָדָם: ע\"כ מההשמטות."],[2,"","שְׁמִינִי מַה הוּא? יֵשׁ לוֹ לַקָּדוֹשׁ- בָּרוּךְ-הוּא צַדִּיק אֶחָד בָּעוֹלָם וְחָבִיב לוֹ, מִפְּנֵי שֶׁמְּקַיֵּם כָּל הָעוֹלָם כֻּלּוֹ, וְהוּא יְסוֹדוֹ, וְהוּא מְכַלְכְּלוֹ וּמַצְמִיחוֹ וּמְגַדְּלוֹ וּמְשַׂמְּחוֹ, אָהוּב וְחָבִיב לְמַעְלָה, נוֹרָא וְאַדִּיר לְמַטָּה, מְתֻקָּן וּמְקֻבָּל לְמַעְלָה, מְתֻקָּן וּמְקֻבָּל לְמַטָּה, וְהוּא יְסוֹד הַנְּפָשׁוֹת כֻּלָּם."],[3,"","אָמַרְתָּ שְׁמִינִי, וְאָמַרְתָּ יְסוֹד הַנְּפָשׁוֹת כֻּלָּם, וַהֲרֵי כָּתוּב וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ? כֵּן שְׁבִיעִי הוּא אֶלָּא מִשּׁוּם שֶׁמַּכְרִיעַ בֵּינֵיהֶם, וְיֶשְׁנָם שָׁלֹשׁ לְמַטָּה וְשָׁלֹשׁ מִמַּעַל, וְהוּא שֶׁמַּכְרִיעַ בֵּינֵיהֶם."],[4,"","וּמָה הַטַּעַם נִקְרָא שְׁבִיעִי? וְכִי הוּא בַּשְּׁבִיעִי? לֹא, אֶלָּא מִפְּנֵי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁבַת בְּשַׁבָּת בְּאוֹתָהּ הַמִּדָּה, שֶׁכָּתוּב (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ. מְלַמֵּד שֶׁכָּל יוֹם וָיוֹם יֵשׁ לוֹ מַאֲמָר אֶחָד שֶׁהוּא אָדוֹן לוֹ, לֹא מִפְּנֵי שֶׁהוּא נִבְרָא בּוֹ, אֶלָּא מִפְּנֵי שֶׁהוּא פּוֹעֵל בָּעוֹלָם פְּעֻלָּה הַמְּסוּרָה לוֹ בְּיָדוֹ. פָּעָלוּ כֻלָּם פְּעֻלָּתָם וְקִיְּמוּ מַעֲשֵׂיהֶם לְבַד - בָּא יוֹם הַשְּׁבִיעִי וּפָעַל פְּעֻלָּתוֹ. שָׂמְחוּ כֻלָּם, אַף הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עוֹד אֶלָּא שֶׁגָּדְלָה נִשְׁמָתוֹ, שֶׁכָּתוּב וּבַיּוֹם הַשְּׁבִיעִי שָׁבַת וַיִּנָּפַשׁ."],[5,"","וּמַהִי שְׁבִיתָה זוֹ? שֶׁאֵין בָּהּ מְלָאכָה, וְהִיא מְנוּחָה, שֶׁכָּתוּב שָׁבַת. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיוּ לוֹ שִׁבְעָה גַנּוֹת, וּבַגַּן הָאֶמְצָעִי מַעְיָן נָאֶה נוֹבֵעַ מִמְּקוֹר מַיִם חַיִּים, שְׁלֹשָׁה מִימִינוֹ וּשְׁלֹשָׁה מִשְּׂמֹאלוֹ, וּמִיָּד שֶׁפּוֹעֵל בָּעוֹלָם אָז מִתְמַלֵּא, וּשְׂמֵחִים כֻּלָּם וְאוֹמְרִים: לְצָרְכֵּנוּ הוּא מִתְמַלֵּא. וְהוּא מַשְׁקֶה אוֹתָם וּמְגַדְּלָם, וְהֵם מַמְתִּינִים וְשׁוֹבְתִים, וְהוּא מַשְׁקֶה אֶת הַשִּׁבְעָה."],[6,"","וַהֲרֵי כָּתוּב (ישעיה מג) מִמִּזְרָח אָבִיא זַרְעֶךְ, וְהִנֵּה אֶחָד מֵהֶם מַשְׁקֶה אוֹתוֹ? אֶלָּא אֱמֹר, הוּא מַשְׁקֶה אֶת הַלֵּב, וְהַלֵּב מַשְׁקֶה אַחַר כֵּן כֻּלָּם. וּמַהִי מִדָּה שְׁבִיעִית? הֱוֵי אוֹמֵר, זוֹ מִדַּת טוּבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","מָה הַטַּעַם אָמַר אֶת שַׁבְּתֹתַי וְלֹא אָמַר אֶת שַׁבַּתִּי? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיָה לוֹ כַּלָּה נָאָה, וְכָל שָׁבוּעַ וְשָׁבוּעַ מַזְמִינָהּ יוֹם אֶחָד לִהְיוֹת עִמּוֹ, וְהַמֶּלֶךְ יֵשׁ לוֹ בָּנִים נָאִים וְאוֹהֲבָם, אָמַר לָהֶם: הוֹאִיל וְכֵן, שִׂמְחוּ אַתֶּם גַּם כֵּן בְּיוֹם שִׂמְחָתִי, כִּי אֲנִי בְּשֶׁלָּכֶם אֲנִי מִשְׁתַּדֵּל, וְאַתֶּם גַּם כֵּן הַדְּרוּ אוֹתוֹ."],[8,"","וּמַה זֶּה זָכוֹר וְשָׁמוֹר? זָכוֹר לַזָּכָר, וְשָׁמוֹר לַנְּקֵבָה. מָה הַטַּעַם (ויקרא יט) וּמִקְדָּשִׁי תִּירָאוּ? שִׁמְרוּ עַצְמְכֶם מֵהִרְהוּר, כִּי מִקְדָּשִׁי קָדוֹשׁ הוּא. לָמָּה? (שם כ) אֲנִי ה' מְקַדִּשְׁכֶם, אֲנִי ה' בְּכָל צַד: ע\"כ מההשמטות."],[9,"","שָׁנִינוּ, עַמּוּד אֶחָד מִן הָאָרֶץ עַד לָרָקִיעַ וְצַדִּיק שְׁמוֹ עַל שֵׁם הַצַּדִּיקִים, וּכְשֶׁיִּשְׂרָאֵל צַדִּיקִים - מִתְגַּבֵּר, וְאִם לָאו - מִתְחַלֵּשׁ, וְהוּא סוֹבֵל כָּל הָעוֹלָם, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, וְאִם חַלָּשׁ, לֹא יוּכַל לְהִתְקַיֵּם הָעוֹלָם: ע\"כ."],[10,"","רַבִּי חֲנִינָא פֵּרַשׁ כָּל אֶחָד עַל עָמְדוֹ. שָׂשׂוֹן - אֶחָד. שִׂמְחָה - שְׁתַּיִם. חָתָן - שָׁלֹשׁ. כַּלָּה - אַרְבַּע. גִּילָה, דִּיצָה, אַהֲבָה, אַחֲוָה, שָׁלוֹם וְרֵעוּת - עֶשֶׂר, כְּנֶגֶד עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם: ע\"כ מההשמטות."]]],[["ס\"א יֵצֶר טוֹב וְיֵצֶר רָע דְּאִיהוּ חֶדְוָה וְאַיְיתֵי לָהּ לְגַבֵּיהּ, וּלְעֵילָא סִטְרָא דְּצָפוֹן מַמָּשׁ דְּאִיהוּ חֶדְוָה בְּלֹא זוֹהֲמָא דְיֶצֶר הַרָע אֲחִיד בֵּיה (נ\"א בה). בְּקַדְמִיתָא דִּכְתִיב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וּלְבָתָר וִימִינוֹ תְּחַבְּקֵנִי וְאִתְיְּיהִיבַת בֵּין יְמִינָא לִשְׂמָאלָא (נ\"א ושמאלא) (לאתזנא) וְעַל דָא וַיּיִצֶר (יי אלהים שם מלא לגבי תרין סטרין אלין. את האדם וכו')","אָמַר לֵיהּ (שיר השירים ז׳:י״ב) לְכָה דּוֹדִי נֵצֶא הַשָּׂדֶה לְכוּ לְהַקָּדוֹשׁ בָּרוּךְ הוּא לְטָיֵּיל וְאַל אֶשֵׁב תָּמִיד בְּמָקוֹם אֶחָד וּמָאי ל\"ב אָמַר לֵיהּ, אִם כֵּן בֵּן זוֹמָא מִבַּחוּץ וְאַתָּה עִמּוֹ ל\"ב הוּא (והוא) שְׁלשִׁים וּשְׁתַּיִם וְהָיוּ סְתוּמִים וּבָהֵם נִבְרָא הָעוֹלָם. וּמָאי שְׁלשִׁים וּשְׁתַּיִם אָמַר לֵיהּ לֵ\"ב נְתִיבוֹת","מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּחַדְרֵי חֲדָרִים וּמִנְיָן הַחֲדָרִים לֵ\"ב. וּלְכָל אֶחָד מִן הַחֲדָרִים יֶשׁ נָתִיב נָאֶה לְמֶלֶךְ זֶה לְהִכָּנֵס (הכל) בְּחֲדְּרוֹ עַל דֶּרֶךְ נְתִיבוֹת. אָמַר, לֹא נָאֶה לוֹ שֶׁלּא לְגַלּוֹת פְּנִינָיו וּמִשְׁכְּנוֹתָיו וּגְנָזָיו וְחֲמוּדוֹתָיו. אֲמַרְתָּ לא. מָה עָשָׂה, נָגַע בְּבַת וְכָּלַל בָּהּ כָּל הַנְתִיבוֹת וּמַלְבּוּשֵׁיהָ וְהַרוֹצֶה לְהִכָּנֵס (ס\"א להסתכל בעיניה) בִּפְנִים, יִסְתַּכֵּל הֵנָּה. וּנְשָׂאָה לַמֶּלֶךְ. גַּם נִתָּנָה לוֹ בְּמַתָּנָה. וְלִפְעֲמִים קוֹרֵא אוֹתָהּ בְּאַהֲבָתוֹ, (בת) אֲחוֹתִי כִּי מִמָקוֹם אֶחָד הָיוּ וְלִפְעֲמִים קוֹרֵא אוֹתָהּ בִּתִּי, כִּי בִּתּוֹ הִיא. וְלִפְעֲמִים קוֹרֵא אוֹתָהּ אִמִּי.","וְעוֹד כִּי אֵין דִּין אִם אֵין חָכְמָה, שֶׁהֲרֵי נֶּאֱמַר (מלכים א ה׳:כ״ו) ויְיָ נָתַן חָכְמָה לִשׁלֹמֹה. וְאַחַר כָּךְ דָן אֶת הַדִּין עַל מַתְכּוּנְתּוֹ דִּכְתִיב (מלכים ג') וַיִּשְׁמְעוּ כָּל יִשְׂרָאֵל אֶת הַמִּשְׁפָּט וְגוֹ' כִּי רָאוּ כִּי חָכְמָה אֱלהִים בְקִרְבּוֹ וְגוֹ'.","וּמָה חָכְמָה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה. שְׁלֹמֹה נָשָׂא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדְּאַמְרִינָן, כָּל שְׁלֹמֹה שְׁבְּשִׁיר הַשִׁירִים קֹדֶשׁ, לְבָד מֵאֶחָד. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹאִיל וְשִׁמְךָ כִּשְׁמִי, אֲשִׂיא לְךָ בִּתִּי. וְהָא נְשׁוֹּאָה הִיא, אָמַר לֵיהּ, בְּמַתָּנָה נְתָּנָה לוֹ הַשֵׁם. וַיְיָ נָתַן חָכְמָה לִשְׁלֹמֹה וְלָא פֵּירַשׁ. וְהֵיכָן פֵּירַשׁ, לְהַלָן. כִּי רָאוּ כִּי חָכְמַת אֱלהִים בְקִרְבּוֹ לַעֲשׂוֹת מִשְׁפָּט (נ\"א ומאי משפט אלא כל זמן שאדם עושה משפט חכמת אלחים בקרבו) וּמָאי לַעֲשׂוֹת מִשְׁפָּט, הֱוִי אוֹמֶר שְׁאוֹתָה חָכְמָה שְׁנְתָנָה אֱלהִים וְשְׁהִיא עִמּוֹ בְּחֲדְּרוֹ, הִיא בְקִרְבּוֹ. זֹאת עוֹזְרָתוֹ וּמְקַרְבָתוֹ וְאִם לָאו מַרְחֲקַתוֹ וְלֹא עוֹד אֶלָּא מֵיָסְרָתוֹ דִּכְתִיב (ויקרא כ״ו:כ״ח) וְיִסַּרְתִּי אֶתְכֶם אַף אֲנִי:","בְּשַׂעְרָא, בְּגּווָֹנִין דְּשַׂעְרָא. בַּאֲרִיכוּ דְּשַׂעְרָא. בְּקְמִיטוּ דְּשַׂעְרָא. בְּמִצְּחָא, בִּקְמִיטוּ דְּמִצְּחָא, בַּאֲרִיכוּ, בְּשִּׂרְטוּטִין. בְּפוּתְיָא. בְּאוּדְנִין, בְּשַׂעְרָא דְּנָחִית עָלַיְיהוּ, אוֹ תְּחוֹתַיְיהוּ, אוֹ אַבַּתְרַיְיהוּ דְּאוּדְנִין. בְּאַנְפִּין. בְּעַיְינִין. בְּגּווָֹנִין דְּעַיְינִין. בִּקְרִיצִּין דְּעַל עַיְינִין.","וכֹל נְבִיאַיָּא לָא הֲווּ מָשִׂיגִין לִנְבוּאָה דְּאִיהִי בְּרַתָּא דְמַלְכָּא, וְלָא מָשִׂיגִין לָהּ בְּכָל אֲתַר, כְּמוֹ מֹשֶׁה. אֶלָּא, מִנְהוֹן הֲווּ מָשִׂיגִין לָהּ בְּרֵישָׁ\"א. מִנְהוֹן בְּאֻדְנִי\"ן בִּשְׁמִיעָה. מִנְהוֹן בְּעַיְינִין בִּרְאִיָה. מִנְהוֹן בְּחוֹטָמָא בְּרֵיחָא. מִנְהוֹן בְּאַנְפִּין בְּדִבּוּ\"ר מִנְהוֹן בְּיָדִי\"ן לְקַבְּלָא דוֹרוֹן. מִנְהוֹן בְּרָגְלִין הֲדָא הוּא דִכְתִיב (יחזקאל ב׳:א׳) בֵּן אָדָם עֲמוֹד עַל רַגְלֶךָ. בִּצְּלוֹתָא","אִלֵּין דְּקָיְמִין בַּעֲמִידָה וּמַטְרוֹנִיתָא קָמַת בְּגִינַיְיהוּ בְּגִין דְאִלֵּין דְּאִתְקְרִיאוּ רַגְלִין אִינוּן עַבֲדִין בְג' רִאשׁוֹנוֹת וּבְג' וּבְאֶמְצָּעִיוֹת אַחֲרוֹנוֹת דִּצְּלוֹתָא וּבְגִין דָא צָּרִיךְ עַבְדָא לְמֶהֱוִי בַּעֲמִידָה קֳדָם מַטְרוֹנִיתָא אוֹ קֳדָם מַלְכָּא וּמַטְרוֹנִיתָא דְּתְהֵא יַתְבָא","וּבְזִמְנָא דְּנַפְקוּ יִשְׂרָאֵל מִמִּצְּרַיִם כֻּלְּהוּ נַפְקֵי רַגְלִין וּכְּמָה דְאַתְּ אָמֵר (שמות ו' י\"ב) כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי וְכֻלְּהוּ הֲווּ עַבְדִין כְּמָה דְאַתְּ אָמֵר (ויקרא כ\"ה) כִּי לִי בְּנֵי יִשְׂרָאֵל עֲבָדִים, מִיָּד דְּאָתָא מֹשֶׁה קָרָא לוֹן בְּנִין. הֲדָא הוּא דִכְתִיב (שמות ד') בְּנִי בְּכֹרִי יִשְׂרָאֵל:","קָם חַד סָבָא מֵאִלֵּין דְּנַחְתּוּ וְאָמַר מִמְתִיבְתָא בּוֹצִּינָא קַדִּישָׁא וְהָא בָתָר דְּנַפְקֵי יִשְׂרָאֵל מִמִּצְּרָיִם, קָרָא לוֹן עֲבָדִין. אָמַר, וַדָּאי הֲכִי הוּא. אֲבָל הֲווּ בְּהוֹן דְאִתְקְרִיאוּ בְּנִין וּבְהוֹן הֲווּ עֲבָדִין, וּבְהוֹן עַם. כְּמָה דְאַתְּ אָמֵר, שָׁלַח אֶת עַמִי אֲבָל עֲבָדִין הֲווּ שֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי.","אָמַר זַכָּאָה חוּלָקָא דְבּוּצִּינָא קַדִּישָׁא דְהַכִי נַהֲרָא בֵּיה אוֹרַיְיתָא. לְבָתָר דַהֲווּ נַפְקִין פַלִּיג לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִתְלַת סִטְרִין. בְּנִין לְסִטְרָא חַד. עֲבָדִין לְסִטְרָא חַד. עַמָּא לְסִטְרָא חַד. וְהָא אוּקְמוּהָ. וּבְגִין דָא רַגְלִי\"ן. עָלַייהוּ אִתְמָר (יחזקאל ב׳:א׳) בֵּן אָדָם עֲמוֹד עַל רַגְלֶיךָ וְאִי עָאלִין בִּצְּלוֹתָא בִּדְחִילוּ וּרְחִימוּ דְי\"ה הָא הֵיכָלָא אִתְפַּתְּחַת לְגַבַּיְיהוּ כְּמָה דְאַתְּ אָמֵר (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח:"],[],[[0,"","ס\"א יּצִּר טוב וְיֵצֶר רָע שֶׁהוּא חֶדְוָה וּמֵבִיא אוֹתָהּ אֵלָיו, וּלְמַעְלָה צַד הַצָּפוֹן מַמָּשׁ, שֶׁהוּא חֶדְוָה בְּלִי זֻהֲמָה שֶׁהַיֵּצֶר הָרָע אָחוּז בּוֹ (בה). בַּתְּחִלָּה, שֶׁכָּתוּב (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי, וְאַחַר כָּךְ וִימִינוֹ תְּחַבְּקֵנִי, וְנִתֶּנֶת בֵּין יָמִין לִשְׂמֹאל (ושמאל) (להזון), וְלָכֵן וַיִּיצֶר ה' אֱלֹהִים, שֵׁם מָלֵא לְגַבֵּי שְׁנֵי צְדָדִים אֵלּוּ. אֶת הָאָדָם וְכוּ': ע\"כ מההשמטות."],[1,"","אָמַר לוֹ, לְכָה דוֹדִי נֵצֵא הַשָּׂדֶה, לְכוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא לְטַיֵּל, וְאַל אֵשֵׁב תָּמִיד בְּמָקוֹם אֶחָד. וּמַה זֶּה לֵב? אָמַר לוֹ, אִם כֵּן, בֶּן זוֹמָא מִבַּחוּץ וְאַתָּה עִמּוֹ. לֵ\"ב הוּא (והוא) שְׁלֹשִׁים וּשְׁתַּיִם, וְהָיוּ סְתוּמִים וּבָהֶם נִבְרָא הָעוֹלָם. וּמַהוּ לֵ\"ב? אָמַר לוֹ, שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת."],[2,"","מָשָׁל לְמֶלֶךְ שֶׁהָיָה יוֹשֵׁב בְּחַדְרֵי חֲדָרִים, וּמִנְיַן הַחֲדָרִים שְׁלֹשִׁים וּשְׁנַיִם, וּלְכָל אֶחָד מִן הַחֲדָרִים יֵשׁ נָתִיב, נָאֶה לְמֶלֶךְ זֶה לְהִכָּנֵס (הכל) בְּחַדְרוֹ עַל דֶּרֶךְ נְתִיבוֹת. אָמַר, לֹא נָאֶה לוֹ שֶׁלֹּא לְגַלּוֹת פְּנִינָיו וּמִשְׁכְּנוֹתָיו וּגְנָזָיו וַחֲמוּדוֹתָיו? אָמַרְתָּ לֹא. מֶה עָשָׂה? נָגַע בַּבַּת וְכָלַל בָּהּ כָּל הַנְּתִיבוֹת וּמַלְבּוּשֶׁיהָ, וְהָרוֹצֶה לְהִכָּנֵס (ס\"א להסתכל בעיניה) בִּפְנִים, יִסְתַּכֵּל הֵנָּה. וּנְשָׂאָהּ לַמֶּלֶךְ. גַּם נִתְּנָה לוֹ בְּמַתָּנָה, וְלִפְעָמִים קוֹרֵא אוֹתָהּ בְּאַהֲבָתוֹ (בת) אֲחוֹתִי, כִּי מִמָּקוֹם אֶחָד הָיוּ, וְלִפְעָמִים קוֹרֵא אוֹתָהּ בִּתִּי, כִּי בִתּוֹ הִיא, וְלִפְעָמִים קוֹרֵא אוֹתָהּ אִמִּי."],[3,"","וְעוֹד, כִּי אֵין דִּין אִם אֵין חָכְמָה, שֶׁהֲרֵי נֶאֱמַר (מלכים א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. וְאַחַר כָּךְ דָּן אֶת הַדִּין עַל מַתְכֻּנְתּוֹ, שֶׁכָּתוּב (שם ג) וַיִּשְׁמְעוּ כָּל יִשְׂרָאֵל אֶת הַמִּשְׁפָּט וְגוֹמֵר, כִּי רָאוּ כִּי חָכְמַת אֱלֹהִים בְּקִרְבּוֹ וְגוֹמֵר."],[4,"","וּמֶה חָכְמָה נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁלֹמֹה? שְׁלֹמֹה נָשָׂא שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁאָנוּ אוֹמְרִים, כָּל שְׁלֹמֹה שֶׁבְּשִׁיר הַשִּׁירִים קֹדֶשׁ לְבַד מֵאֶחָד. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הוֹאִיל וְשִׁמְךְ כִּשְׁמִי, אַשִּׂיא לְךְ בִּתִּי, וַהֲרֵי נְשׂוּאָה הִיא. אָמַר לוֹ, בְּמַתָּנָה נְתָנָהּ לוֹ הַשֵּׁם, וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, וְלֹא פֵרַשׁ. וְהֵיכָן פֵּרַשׁ? לְפָנָיו, כִּי רָאוּ כִּי חָכְמַת אֱלֹהִים בְּקִרְבּוֹ לַעֲשׂוֹת מִשְׁפָּט. (ומה זה משפט? אלא כל זמן שאדם עושה משפט, חכמת אלהים בקרבו) וּמַה זֶּה לַעֲשׂוֹת מִשְׁפָּט? הֱוֵי אוֹמֵר, שֶׁאוֹתָהּ חָכְמָה שֶׁנְּתָנָהּ אֱלֹהִים וְשֶׁהִיא עִמּוֹ בְּחַדְרוֹ, הִיא בְּקִרְבּוֹ. זאת עוֹזַרְתּוֹ וּמְקָרַבְתּוֹ, וְאִם לָאו - מְרַחַקְתּוֹ, וְלֹא עוֹד אֶלָּא מְיַסַּרְתּוֹ, שֶׁכָּתוּב (ויקרא כו) וְיִסַּרְתִּי אֶתְכֶם אַף אָנִי: ע\"כ מההשמטות."]]],[["אָמַר רַבִּי רְחוּמָאי כָּבוֹד וְלֵב הֲרֵי הֵן אֶחָד אֶלָּא שְׁכָּבוֹד נִקְרָא עַל שֵׁם מַעְלָה וְלֵב אִתְקְרֵי עַל שֵׁם פְּעוּלַת מַטָּה. וְהַיְינוּ כְּבוֹד הַשֵׁם וְהַיְינוּ לֵב הַשָׁמַיִם. מָאי נִיהוּ (ישעיהו ו׳:ג׳) מְלֹא כָּל הָאָרֶץ כְּבוֹדוֹ אֶלָּא כָּל אוֹתָהּ אֶרֶץ שְׁנִבְרֵאת בְּיוֹם רִאשׁוֹן שֶׁהוּא לְמָעְלָה כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל מְלֵאָה מִכְּבוֹד הַשֵׁם וּמָאי נִינְהוּ חֲכָמִים דִּכְתִיב (משלי ג׳:ל״ה) כָּבוֹד חֲכָמִים יִנְחָלוּ וּכְתִיב (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ מִמְּקוֹמוֹ.","וּמָאי הֲוֵי כָּבוֹד זֶה. מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ שֶׁהָיָה לוֹ מַטְרוֹנִיתָא בְּחַדְרוֹ שֶׁכָּל חַיָּילָיו מִשְׁתַעֲשְׁעִין בָּהּ וְהָיוּ לָהּ בָּנִים וּבָאִים כָּל הַיּוֹם לִרְאוֹת פְּנֵי הַמֶּלֶךְ וּמְבָרְכִין אוֹתוֹ אֲמְרוּ לוֹ אָנָה אִמֵנוּ אָמַר לָהֶם לא תּוּכְלוּ לִרְאוֹתָהּ עַתָּה. אֲמְרוּ בְּרוּכָה תְּהֵא בְּכָל מָקוֹם שֶׁהִיא.","וּמָאי דִּכְתִיב מִמְּקוֹמוֹ מִכְּלַל דְּלִיכָּא דְּיָדַע אֶת מְקוֹמוֹ מָשָׁל לְמַטְרוֹנִיתָא שְׁבָּאָה מִמָקוֹם רָחוֹק וְלֹא יָדְעוּ מֵאַיִן בָּאָה עַד שְׁרָאוּ שֶׁהִיא אֵשֶׁת חַיִל נָאָה וְהַגּוּנָה בְּכָל מַעֲשֶׂיהָ, אֲמְרוּ זֹאת וַדָּאי מִן הָאוֹר נִלְקְחָה כַּךְ בְּמַעֲשֶׂיהָ הֵאִירָה אֶת הָעוֹלָם. שָׁאֲלוּ אוֹתָהּ מֵאַיִן אַתְּ אָמְרָה לָהֶם מִמְקוֹמִי אֲמְרוּ אִם כֵּן גְּדוֹלִים אַנְשֵׁי מְקוֹמֶךְ בְּרוּכָה תִּהְיִּי וּמְבוֹרָךְ מְקוֹמֶךְ.","וְכִי אֵין כְּבוֹד יְיָ אֶחָד מִצִבְאוֹתָיו לא גָּרַע אַמָּאי מְבָרְכִין לֵיהּ. אֶלָּא מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְאִישׁ שֶׁהָיָה לוֹ גָן נָאָה וְחוּץ לְגַן בְּקַרוֹב מִמֶּנּוּ חַתִּיכַת שָׂדֶה. וְאִם הִשְׁקָה הַגָּן בִּתְּחִלַּת שָׁקְיוּתוֹ הָלְכוּ לָהֶם הַמָּיִם עַל כָּל הַגָּן. אַךְ אוֹתָהּ חַתִּיכָה שֶׁל שָׂדֶה שֶׁהִיא אֵינָה דְבוּקָה, אַף עַל פִּי שְׁהַכֹּל אֶחָד הוּא לְפִיכָךְ פָּתַח לָהּ מָקוֹם וְהִשְׁקָה לָהּ לְבַדָּהּ.","עַל יַמִּים יָסְדָה, אִלֵּין חַכִּימִין דְּיִשְׂרָאֵל רַבְרְבַיָּא דְּיָסְדָן אוֹרַיְיתָא וְחָכְמָתָא דְּאִתְקְרִיאַת הַיָּם הַגָּדוֹל וְכֵן הוּא אוֹמֵר (קהלת א') וְעַל נְהַרוֹת אִלֵּין תַּלְמִידָיָּיא דְּאִינוּן רַבְרְבִין מִן נַהֲרָא. וְכֵן הַרָב גָּדוֹל מִן הַתָלְמִידִים. וְאִינוּן מְחַדְדִין אֶת הַרָב בְּקוּשִׁיוֹתֵיהֶן. וְהוּא מְתָרֵץ לוֹן כָּל הַקוּשִׁיוֹת וְאֵינוֹ מִתְרָשֵׁל. כְּמוֹ הַנְהַרוֹת שְׁנִמְשָׁכִין לַיָּם וְאֵינוֹ מָלֵא שְׁנֶּאֱמַר כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. וְהַרְאָיָּה אֲמְרוּ אָחֲרֵי כֵן מִי יַעֲלֶה בְּהַר יְיָ. כִּי אֵין מַעֲשֶׂה בְּלָא חָכְמָה. כִּי הַתַלְמוּד מֵבִיא לִידֵי מַעֲשֶׂה:","שְׁכִינְתָּא אִתְקְרִיאַת אוֹת בְּרִית מִסִּטְרָא דְצַדִיק יְסוֹד עוֹלָם זֹאת אוֹת הַבְּרִית בְּסִינַי (ס\"א ביני). עַמּוּדָא דְאֶמְצָעִיתָא. וּבֵין בְּנֵי יִשְׂרָאֵל נֶצַ\"ח הוֹ\"ד. אוֹת דָא צַדִּיק, הִיא דָא שְׁכִינְתָּא (שמות ל״א:י״ז) כִּי שֵׁשֶׁת יָמִים עָשָׂה יְיָ אֶת הַשָׁמַיִם מִכֶּתֶ\"ר עַד עַמּוּדָא דְאֶמְצָעִיתָא. דְּלֵית שִׁית בְּכָל אֲתַר אֶלָּא מִסִּטְרָא דְּאָתְּ ו' וְלֵית שְׁבִיעִי אֶלָּא מִטְרָא דְּאָתְּ י' עֲטָרָה עַל רֵישֵׁיהּ חָכְמָ\"ה עִלָּאָה אוֹת הִיא חָכְמָה תַתָּאָה אוֹת הִיא. וְתַּקִינוּ לְמִגְזָר לִתְמָנְיָּיא דְּאִיהוּ תַמָּן חָכְמָ\"ה עַד יְסוֹד לְקָבְּלָא בְּהוֹן י' זְעִירָא לְסַלְקָא לָהּ עַד כֶּתֶר לְמֶהוֵי עֲטָרָה עַל רָאשֵׁיהוֹן וְתַּקִינוּ לְשָׁוְיָּיא עָרְלָה בְּמָנָא וְעַפְרָא לְקַיֵּים (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ:","אהניאל \"ברקיאל \"גדיאל \"דומיאל \"הדריאל \"ודרגזיה \"זהריאל \"חניאל \"טהריאל \"יעזריאל \"כרעיאל \"למדיאל \"מלכיאל \"נהריאל \"סניה \"ענאל \"פּתּחיאל \"צּוריאל \"קנאל \"רמיאל \"שעריאל \"תּבכיאל: סדר תּשר\"ק \"תּפּוריא \"שכניאל \"רנאל \"קמריה \"צּוריה \"פּסיסיה \"עיריאל \"סמכיאל \"נריאל \"מדוניה \"לסניה \"כמסריה \"יריאל \"טסמסיה \"חניאל \"זכראל \"ודריאל \"הניאל \"דנבאל \"גדיאל \"בדאל \"אדירירון אדני על כולהו וכו':"],[],[[0,"","אָמַר רַבִּי רְחוּמַאי, כָּבוֹד וְלֵב הֲרֵי הֵם אֶחָד, אֶלָּא שֶׁכָּבוֹד נִקְרָא עַל שֵׁם מַעְלָה, וְלֵב נִקְרָא עַל שֵׁם פְּעֻלַּת מַטָּה, וְהַיְנוּ כְּבוֹד הַשֵּׁם, וְהַיְנוּ לֵב הַשָּׁמַיִם. מַה הוּא (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ? אֶלָּא כָּל אוֹתָהּ אֶרֶץ שֶׁנִּבְרֵאת בְּיוֹם רִאשׁוֹן, שֶׁהִיא לְמַעְלָה כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל, מְלֵאָה מִכְּבוֹד הַשֵּׁם, וּמַה הֵם? חֲכָמִים, שֶׁכָּתוּב (משלי יג) כָּבוֹד חֲכָמִים יִנְחָלוּ, וְכָתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ."],[1,"","וּמֶה הָיָה הַכָּבוֹד הַזֶּה? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיְתָה לוֹ גְּבִירָה בְּחַדְרוֹ שֶׁכָּל חַיָּלָיו מִשְׁתַּעְשְׁעִין בָּהּ, וְהָיוּ לָהּ בָּנִים, וּבָאִים כָּל הַיּוֹם לִרְאוֹת פְּנֵי הַמֶּלֶךְ וּמְבָרְכִין אוֹתוֹ. אָמְרוּ לוֹ: אָנָה אִמֵּנוּ? אָמַר לָהֶם: לֹא תוּכְלוּ לִרְאוֹתָהּ עַתָּה. אָמְרוּ: בְּרוּכָה תְּהֵא בְּכָל מָקוֹם שֶׁהִיא."],[2,"","וּמַה שֶּׁכָּתוּב מִמְּקוֹמוֹ, מִכְּלָל שֶׁאֵין יוֹדֵעַ אֶת מְקוֹמוֹ. מָשָׁל לִגְבִירָה שֶׁבָּאָה מִמָּקוֹם רָחוֹק וְלֹא יָדְעוּ מֵאַיִן בָּאָה. עַד שֶׁרָאוּ שֶׁהִיא אֵשֶׁת חַיִל נָאָה וַהֲגוּנָה בְּכָל מַעֲשֶׂיהָ, אָמְרוּ: זאת וַדַּאי מִן הָאוֹר נִלְקְחָה, כִּי בְמַעֲשֶׂיהָ הֵאִירָה אֶת הָעוֹלָם. שָׁאֲלוּ אוֹתָהּ: מֵאַיִן אַתְּ? אָמְרָה לָהֶם: מִמְּקוֹמִי. אָמְרוּ: אִם כֵּן, גְּדוֹלִים אַנְשֵׁי מְקוֹמֵךְ, בְּרוּכָה תִּהְיִי וּמְבֹרָךְ מְקוֹמֵךְ."],[3,"","וְכִי אֵין כְּבוֹד ה' אֶחָד מִצִּבְאוֹתָיו לֹא גָרַע, לָמָּה מְבָרְכִים אוֹתוֹ? אֶלָּא מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאִישׁ שֶׁהָיָה לוֹ גַּן נָאֶה, וְחוּץ לַגָּן בְּקָרוֹב מִמֶּנּוּ חֲתִיכַת שָׂדֶה, וְאִם הִשְׁקָה הַגָּן בִּתְחִלַּת שַׁקְיוּתוֹ - הָלְכוּ לָהֶם הַמַּיִם עַל כָּל הַגָּן, אַךְ אוֹתָהּ חֲתִיכָה שֶׁל שָׂדֶה שֶׁהִיא אֵינָהּ דְּבוּקָה, אַף עַל פִּי שֶׁהַכֹּל אֶחָד הוּא, לְפִיכָךְ פָּתַח לָהּ מָקוֹם וְהִשְׁקָה אוֹתָהּ לְבַדָּהּ: ע\"כ מההשמטות."],[4,"","עֵל יַמִּים יְסָדָהּ (תהלים כד) - אֵלּוּ חַכְמֵי יִשְׂרָאֵל הַגְּדוֹלִים שֶׁיִּסְּדוּ תּוֹרָה וְחָכְמָה שֶׁנִּקְרֵאת הַיָּם הַגָּדוֹל, וְכֵן הוּא אוֹמֵר, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וְעַל נְהָרוֹת - אֵלּוּ הַתַּלְמִידִים שֶׁהֵם הַגְּדוֹלִים מֵהַנָּהָר, וְכֵן הָרַב גָּדוֹל מִן הַתַּלְמִידִים, וְהֵם מְחַדְּדִים אֶת הָרַב בְּקֻשְׁיוֹתֵיהֶן, וְהוּא מְתָרֵץ לָהֶם כָּל הַקֻּשְׁיוֹת וְאֵינוֹ מִתְרַשֵּׁל, כְּמוֹ הַנְּהָרוֹת שֶׁנִּמְשָׁכִים לַיָּם וְאֵינוֹ מָלֵא, שֶׁנֶּאֱמַר כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. וְהָרְאָיָה - אָמְרוּ אַחֲרֵי כֵן, מִי יַעֲלֶה בְּהַר ה', כִּי אֵין מַעֲשֶׂה בְּלֹא חָכְמָה, כִּי הַתַּלְמוּד מֵבִיא לִידֵי מַעֲשֶׂה:"],[5,"","שְׁכִינָה נִקְרֵאת אוֹת בְּרִית מִצַּד שֶׁל צַדִּיק יְסוֹד עוֹלָם. זאת אוֹת הַבְּרִית - בְּסִינַי. (בין) הָעַמּוּד הָאֶמְצָעִי, וּבֵין בְּנֵי יִשְׂרָאֵל - נֵצַח הוֹד. אוֹת - זֶה צַדִּיק. הִיא - זוֹ שְׁכִינָה. (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם - מִכֶּתֶר עַד הָעַמּוּד הָאֶמְצָעִי, שֶׁאֵין שֵׁשׁ בְּכָל מָקוֹם אֶלָּא מִצַּד הָאוֹת ו', וְאֵין שְׁבִיעִי אֶלָּא מִצַּד הָאוֹת י', עֲטָרָה עַל רֹאשׁוֹ. הַחָכְמָה הָעֶלְיוֹנָה הִיא אוֹת, הַחָכְמָה הַתַּחְתּוֹנָה הִיא אוֹת, וְתִקְּנוּ לָמוּל לִשְׁמֹנָה שֶׁשָּׁם הִיא חָכְמָה עַד הַיְסוֹד, לְקַבֵּל בָּהֶם י' קְטַנָּה לְהַעֲלוֹתָהּ עַד הַכֶּתֶר לִהְיוֹת עֲטָרָה עַל רֹאשָׁם, וְתִקְּנוּ לָשִׂים הָעָרְלָה בִּכְלִי וְעָפָר, לְקַיֵּם וְנָחָשׁ עָפָר לַחְמוֹ: ע\"כ מההשמטות."],[6,"","'אהניאל \"ברקיאל \"גדיאל \"דומיאל \"הדריאל \"ודרגזיה \"זהריאל \"חניאל \"טהריאל \"יעזריאל \"כרעיאל \"למדיאל \"מלכיאל \"נהריאל \"סניה \"ענאל \"פתחיאל \"צוריאל \"קנאל \"רמיאל \"שעריאל \"תבכיאל: סדר תשר\"ק \"תפוריא \"שכניאל \"רנאל \"קמריה \"צוריה \"פסיסיה \"עיריאל \"סמכיאל \"נריאל \"מדוניה \"לסניה \"כמסריה \"יריאל \"טסמסיה \"חניאל \"זכראל \"ודריאל \"הניאל \"דנבאל \"גדיאל \"בדאל \"אדירירון אדני על כולהו וכו': (עד כאן מההשמטות)"]]],[["\u0003רַעֲיָא מְהֵימְנָא\u0004 וַיַּחֲלוֹם וְהִנֵּה סוּלָם מֻצָּב אַרְצָּה. וְהִנֵּה סוּלָם דָא צְּלוֹתָא, מֻצָּב אַרְצָּה, דְּמָצְּלָאן בְּנֵי נָשָׁא לֵיהּ בְּאַרְעָא דְּאִיהִי שְׁכִינְתָּא וּמַטָא לִשְׁמַיָּא דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא דְאִתְמָר בֵּיה (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָׁמַיִם וְרָזָא דְּמִלָה (תהילים ח׳:ב׳) יְהוָֹ\"ה אֲדֹנֵינוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ וגוֹ'.","וּבְזִמְנָא דְּמוֹדָע לוֹן קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ דְּסָלְקָא בְּהַהוּא צְּלוֹתָא, מִיָד וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ. בּוֹ בְּהַהוּא בַּר נָשׁ. כֻּלְּהוּ פַּתְחִין גַדְפַיְיהוּ לְקָבְּלָא שְׁכִינְתָּא בְּהַהִיא צְּלוֹתָא, הֲדָא הוּא דִכְתִיב (יחזקאל א׳:י״א) וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמַעְלָה וְהַאי אִיהוּ עוֹלִים שְׁכִינְתָּא עַל גַדְפַיְיהוּ וְיוֹרְדִים בּוֹ. מָאי בּוֹ, בְּקוּדְשָׁא בְּרִיךְ הוּא. דְקוּדְשָׁא בְּרִיךְ הוּא נָחִית עָלַיְיהוּ לְקָבְּלָא שְׁכִינְתֵּיהּ וּמְיַיחֵד קוּדְשָׁא בְּרִיךְ הוּא בֵּיה בְּהַהוּא בַּר נָשׁ בִּצְּלוֹתֵיהּ.","דִשְׁכִינְתָּא אִיהִי מִצְּוָה כְּלִילָא בְּשֵׁם יְהוָֹ\"ה אִיהִי חַיָּה דִילֵיהּ. וּמִצְּוָה בְּלא מַחֲשָׁבָה לֵית לָהּ סְלִיקוּ. וּמַחֲשָׁבָה אִיהוּ אָדָ\"ם יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א תִפְאֶרְ\"ת. מִצְּוָה מַלְכוּתָא כְּלִילָא מֵאַרְבַּע חֵיוָון דְמֶרְכַּבְתָּא, כְּלִילָא מֵאַרְבַּע אַתְוון. אִיהִי נוּקְבָא דִילֵיהּ, אַנְפִּין דִילֵיהּ, אַנְפּוֹי דְּרַחֲמֵי. בְּגִינָהּ אֲמֵינָא (שמות ל״ג:ט״ו) אִם אֵין פָּנֶיךָ הוֹלְכִים וְגוֹ'.","וּמִסִּטְרָא דְצַּדִיק אִתְקַרְיָא אֲחוֹרוֹי חַיָּה כְּלִילָא חָ\"י חוּלְיָין דְּאֲחוֹרוֹי דְּבָּר נָשׁ, דְּדָמֵי לְשִׁדְרָה דְּבֵיהּ חָ\"י חוּלְיָין. אִיהִי אָחוֹר לְעוֹבַדָא דְּבְּרֵאשִׁית וְקֵדֶם לְמַחֲשָׁבָה דְאִתְמָר בָּהּ, עֲלָהּ בְּמַחֲשָׁבָה. מָה דְּלָאו הֲכִי בַּאָדָם, דְּאֲחוֹר דְּעֵץ הַדַּעַת טוֹב וָרָע דְּאִיהוּ אָחוֹר לְמַעֲשֶׂה בְּרִאשִׁית, וקֵדֶם לְפּוּרְעֲנוּת.","קָמוּ תַּנָּאִין וְאֱמוֹרָאִין וְאָמְרוּ רַעְיָא מְהֵימְנָא בְּרִיךְ אֲנְתְ לֵאֱלָהָא עִלָּאָה, הוּא יְקָם לָךְ בַּעוּתָךְ בְּכֹלָּא. קָם סָבָא עִלָּאָה בְּינֵיהוֹן וְאָמַר רַעְיָא מְהֵימְנָא בָּךְ אִתְקָיָּים הַאי קְרָא דְאִתְמָר (ישעיהו ס״ב:ז׳) וְאַל תִּתְנוּ דֹּמִי לוֹ דְּהָא עִלָּאִין וְתַתָּאִין מֵקַנְנֵי בְּצּוּלְמָא דִּידָךְ מַשִׁירְיָין דְקוּדְשָׁא בְּרִיךְ הוּא דְּאִינוּן מְתִיבְתָּא עִלָּאָה וּמַשִּׁירְיָין דְּמַטְרוֹנִיתָא דְּאִינוּן מִמְתִּיבְתָא תַתָּאָה עֲלָךְ אִתְמָר וְהִנֵּה מַלְאֲכֵי אֱלהִים עוֹלִים וְיוֹרְדִים בּוֹ","בָּךְ סָלְקִין מַשִׁירְיָין דִשְׁכִינְתָּא בִּצְּלוֹתָא וְנָחֲתִין מַשִׁירְיָין דְקוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּי שְׁכִינְתֵּיהּ בְּכַמָּה שִׁירִין וְנִגּוּנִין דִּצְּלוֹתָא. אֲנְתְ הוּא קְרִיבָא דְקוּדְשָׁא בְּרִיךְ הוּא בִּצְּלוֹתָא דִּילָךְ, דְּאִיהוּ קָרְבָּנָא דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּאֵיזְהוּ מְקוֹמָן בְּצַּו אֶת בְּנֵי יִשְׂרָאֵל וְכוּ' דְּתַקִּינוּ מָארֵי מַתְנִיתִין קָרְבָּנִין דִּצְּלוֹתָא מִסִּטְרָא דִיְמִינָא דְּתַמָּן כֹּהֵן אִישׁ חֶסֶ\"ד","וְתַּקִינוּ זְּמִירוֹת דְּאִינוּן שִׁיר דִלְוִיִּם אַבַּתְרַיְיהוּ מִסִּטְרָא דִּגְבוּרָ\"ה. וְהוֹ\"ד דַרְגָּא דְּדָוִד אִתְקַשַׁר בִּשְׂמָאלָא דִּגְבוּרָ\"ה. וְאַהֲרֹן דְדַרְגָא דִילֵיהּ בְּהוֹ\"ד אִתְקַשַׁר בְּחֶסֶ\"ד. הֲדָא הוּא דִכְתִיב (תהלים י\"ז) נְעִימוֹת בִּימִינְךָ נֶצַּח.","שְׁמַע יִשְׂרָאֵל דְּיִחוּדָא כָּלִיל בָּרְכוּ וּקְדוּשָׁה. דְּאִיהוּ קָדוֹשׁ. קָדוֹשׁ. קָדוֹשׁ. וּבְרָכָה מִסִּטְרָא דִיְמִינָא הֲדָא הוּא דִכְתִיב (במדבר ו׳:כ״ג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרְכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדוּשָׁה מִסִּטְרָא דִלְוִיִּם עַמּוּדָא דְאֶמְצָּעִיתָא קִשׁוּרָא דִיְמִינָא וּשְׂמָאלָא וְאִיהוּ קִשׁוּרָא דִתְפִלִּין דְּרֵישָׁא דְּאִיהוּ אִימָא עִלָּאָה. תְּפִילִין עַל רֵישֵׁיהּ, כְּמָה דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין. תְפִלִּין דְמָארֵי עָלְמָא, מָה כְּתִיב בְּהוּ. וְאִיהוּ קִשׁוּרָא דִתְפִלִּין דְיַד, דְּאִיהִי שְׁכִינְתָּא תַתָּאָה. וְהַאי אִיהוּ דְּאוּקְמוּהַ מָארֵי מַתְנִיתִין הֵרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְפִלִּין","ש דִּילָךְ מֹשֶׁה כָלִיל תְלָת אַנְפֵּי אֲבָהָן לְעֵילָא דְּתַקִּינוּ ג' צְּלוֹתִין דְּאִיהוּ סִימָנָם שַׁחֲרִית מִנְחָה עַרְבִית. מִשׁוּם הֲכִי דִּידָךְ צְּלוֹתָא דְּשַׁבָּת דְאִתְמָר בֵּיהּ (בה) (בראשית א׳:כ״ו) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ","וְאִתְכְּלִיל מֵרְכָּבְתָא תַתָּאָה דְאֲהַרֹן דָוד וּשְׁלֹמֹה ואָדָם קַדְמָאָה לְעֵילָא וּבַת זוּגִיהּ לְתַתָּא אֵם כָּל חָי דְּאִיהוּ צַּדִּיק חָ\"י עָלְמִין. וּבְגִין דָא אַהֲרֹן אַף עַל גַּב דְּאִיהוּ יְמִינָא אוּקְמוּהָ רָבַּנָן בֵּיהּ, אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא הֲוָה. רַעְיָא מְהֵימְנָא, יַעֲקֹב אִיהוּ כָּלִיל תְלָת אֲבָהָן דְבֵּיהּ רָכִיב אָדָם קַדְמָאָה וְלָאו לְמַגָּנָא אוּקְמוּהָ מָארֵי מַתְנִיתִין שׁוּפְרֵיהּ דְּיַעֲקֹב כְּשׁוּפְרָא דְּאָדָם קַדְמָאָה.","אָמַר בּוֹצִּינָא קַדִּישָׁא רַעְיָא מְהֵימְנָא חָזֵינָא דְּכַּפָל קוּדְשָׁא בְּרִיךְ הוּא שְׁמָךְ וְאָמַר מֹשֶׁה מֹשֶׁה לְאַכְלָלָא לָךְ בְּמֶרְכַּבְתָּא עִלָּאָה תַתָּאָה. וּבְּמֶרְכַּבְתָּא לְאַכְלָלָא בָּךְ אָדָם קַדְמָאָה מִסִּטְרָא דְּאַבְרָהָם וּלְאַכְלָלָא בָּךְ חַוָּה מִסִּטְרָא דְאֲהַרֹן דָוִד וּשְׁלֹמֹה.","לָמָה לֹא כָּפָל שְׁמֵיהּ דְּיַעֲקֹב הֲכִי אָמַר לֵיהּ בּוֹצִּינָא קַדִּישָׁא בְּגִין דְקָרָא לֵיהּ יַעֲקֹב וְקָרָא לֵיהּ יִשְׂרָאֵל. יַעֲקֹב לִישָׁנָא דְּעוּקְבָא דְּהַיְינוּ נוּקְבָא, דְאִתְמָר עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן מַכְהֵה גַלְגַּל חַמָּה. וְאִקְרֵי יִשְׂרָאֵל, דְּתַמָּן רֹאשׁ דְכוּרָא, רֵישָׁא לְנוּקְבָא, דְּהַיְינוּ עָקֵב. וְהַאי אִיהוּ דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְחִוְיָּיא (בראשית ג׳:ט״ו) הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנוּ עָקֵב. וְדָא גָרַם שְׁכִינְתָּא בְּגָלוּתָא דְאִתְמָר בֵּיה (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת יְיָ."],[],[[0,"","וַיַּחֲלוֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה (בראשית כח). וְהִנֵּה סֻלָּם - זוֹ תְפִלָּה. מֻצָּב אַרְצָה - שֶׁמִּתְפַּלְלִים בְּנֵי אָדָם לוֹ בָּאָרֶץ, שֶׁהִיא שְׁכִינָה, וּמַגִּיעַ לַשָּׁמַיִם שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר בּוֹ (מלכים א ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, וְסוֹד הַדָּבָר - (תהלים ח) ה' אֲדנֵנוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ וְגוֹמֵר."],[1,"","וּבַזְּמַן שֶׁמּוֹדִיעַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ שֶׁעוֹלָה בְּאוֹתָהּ הַתְּפִלָּה, מִיָּד - וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. בּוֹ - בְּאוֹתוֹ אָדָם. כֻּלָּם פּוֹתְחִים כַּנְפֵיהֶם לְקַבֵּל שְׁכִינָה בְּאוֹתָהּ תְּפִלָּה. זֶהוּ שֶׁכָּתוּב (יחזקאל א) וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. וְזֶה עֹלִים, שְׁכִינָה עַל כַּנְפֵיהֶם, וְיֹרְדִים בּוֹ. מַה זֶּה בּוֹ? בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹרֵד עֲלֵיהֶם לְקַבֵּל שְׁכִינָתוֹ, וּמְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ הָאִישׁ בִּתְפִלָּתוֹ,"],[2,"","שֶׁשְּׁכִינָה הִיא מִצְוָה כְּלוּלָה בְּשֵׁם יהו\"ה, הִיא הַחַיָּה שֶׁלּוֹ, וּמִצְוָה בְּלִי מַחֲשָׁבָה אֵין לָהּ עֲלִיָּה. וּמַחֲשָׁבָה הִיא אָדָם, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, תִּפְאֶרֶת מִצְוָה, הַמַּלְכוּת כְּלוּלָה מֵאַרְבַּע חַיּוֹת הַמֶּרְכָּבָה, כְּלוּלָה מֵאַרְבַּע אוֹתִיּוֹת, הִיא הַנְּקֵבָה שֶׁלּוֹ, הַפָּנִים שֶׁלּוֹ, פְּנֵי הָרַחֲמִים, עֲבוּרָהּ אָמַרְתִּי (שמות לג) אִם אֵין פָּנֶיךְ הֹלְכִים וְגוֹמֵר."],[3,"","וּמִצַד הַצַּדִּיק נִקְרֵאת אֲחוֹרָיו, חַיָּה כְּלוּלָה שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת שֶׁאֲחוֹרֵי הָאָדָם, שֶׁדּוֹמֶה לַשִּׁדְרָה שֶׁבָּהּ שְׁמוֹנֶה עֶשְׂרֵה חֻלְיוֹת, הִיא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית, וְקָדַם לַמַּחֲשָׁבָה, שֶׁנֶּאֱמַר בָּהּ עָלָה בְּמַחֲשָׁבָה, מַה שֶּׁאֵין כֵּן בְּאָדָם שֶׁל אָחוֹר, שֶׁל עֵץ הַדַּעַת טוֹב וָרָע, שֶׁהוּא אָחוֹר לְמַעֲשֵׂה בְרֵאשִׁית וְקָדַם לַפֻּרְעָנוּת."],[4,"","קָמוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, בָּרוּךְ אַתָּה לְאֵל עֶלְיוֹן, הוּא יָקִים לְךְ בַּקָּשָׁתְךְ בַּכֹּל. קָם זָקֵן עֶלְיוֹן בֵּינֵיהֶם וְאָמַר, רוֹעֶה הַנֶּאֱמָן, בְּךְ הִתְקַיֵּם פָּסוּק זֶה שֶׁנֶּאֱמַר (ישעיה סב) וְאַל תִּתְּנוּ דֳמִי לוֹ, שֶׁהֲרֵי עֶלְיוֹנִים וְתַחְתּוֹנִים מְקַנְּנִים בְּצַלְמְךְ, מַחֲנוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֵם מֵהַיְשִׁיבָה הָעֶלְיוֹנָה, וּמַחֲנוֹת הַגְּבִירָה שֶׁהֵם מֵהַיְשִׁיבָה הַתַּחְתּוֹנָה, עָלֶיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ."],[5,"","בְּךְ עוֹלִים מַחֲנוֹת הַשְּׁכִינָה בִּתְפִלָּה, וְיוֹרְדִים מַחֲנוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁכִינָתוֹ בְּכַמָּה שִׁירִים וְנִגּוּנִים שֶׁל תְּפִלָּה. אַתָּה הוּא הַקָּרוֹב לַקָּדוֹשׁ-בָּרוּךְ- הוּא בִּתְפִלָּתְךְ, שֶׁהִיא קָרְבָּן לַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּאֵיזֶהוּ מְקוֹמָן, בְּצַו אֶת בְּנֵי יִשְׂרָאֵל וְכוּ'. שֶׁתִּקְּנוּ בַּעֲלֵי הַמִּשְׁנָה קָרְבְּנוֹת הַתְּפִלָּה מִצַּד הַיָּמִין, שֶׁשָּׁם כֹּהֵן אִישׁ חֶסֶד,"],[6,"","וְתִקְּנוּ זְמִירוֹת שֶׁהֵם שִׁיר הַלְוִיִּם אַחֲרֵיהֶם מִצַּד הַגְּבוּרָה, וְהוֹד דַּרְגָּה שֶׁל דָּוִד נִקְשְׁרָה בִּשְׂמֹאל שֶׁל גְּבוּרָה. וְאַהֲרֹן דַּרְגָּתוֹ בְּהוֹד נִקְשָׁר בְּחֶסֶד, זֶהוּ שֶׁכָּתוּב (תהלים טז) נְעִמוֹת בִּימִינְךְ נֶצַח."],[7,"","שְׁמַע יִשְׂרָאֵל שֶׁל הַיִּחוּד כּוֹלֵל בָּרְכוּ וּקְדֻשָּׁה, שֶׁהוּא קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, וּבְרָכָה מִצַּד הַיָּמִין, זֶהוּ שֶׁכָּתוּב (במדבר ו) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. וּקְדֻשָּׁה מִצַּד הַלְוִיִּם עַמּוּד הָאֶמְצָעִי, הַקֶּשֶׁר שֶׁל יָמִין וּשְׂמֹאל, וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל רֹאשׁ, שֶׁהוּא הָאֵם הָעֶלְיוֹנָה. תְּפִלִּין עַל רֹאשׁוֹ כְּמוֹ שֶׁבֵּאֲרוּהוּ בַּעֲלֵי הַמִּשְׁנָה, תְּפִלִּין שֶׁל רִבּוֹן הָעוֹלָם מַה כָּתוּב בָּהֶן? וְהוּא קֶשֶׁר שֶׁל תְּפִלִּין שֶׁל יָד, שְׁכִינָה תַּחְתּוֹנָה. וְזֶה שֶׁבֵּאֲרוּ בַּעֲלֵי הַמִּשְׁנָה, הֶרְאָהוּ לְמֹשֶׁה קֶשֶׁר שֶׁל תְּפִלִּין."],[8,"","שׁ' שֶׁלְּךְ מֹשֶׁה, כּוֹלֵל שְׁלֹשׁ פְּנֵי הָאָבוֹת לְמַעְלָה שֶׁתִּקְּנוּ שָׁלֹשׁ תְּפִלּוֹת, שֶׁסִּימָנָם: \"שַׁחֲרִית \"מִנְחָה \"עַרְבִית. מ\"ה שֶׁלְּךְ תְּפִלַּת הַשַּׁבָּת, שֶׁנֶּאֱמַר בָּהּ (בראשית א) וּרְדוּ בִּדְגַת הַיָּם וּבְעוֹף הַשָּׁמַיִם וּבַבְּהֵמָה וּבְכָל הָאָרֶץ,"],[9,"","וְנִכְלְלָה מֶרְכָּבָה הַתַּחְתּוֹנָה שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה, וְאָדָם הָרִאשׁוֹן לְמַעְלָה, וּבַת זוּגוֹ לְמַטָּה, אֵם כָּל חַי, שֵׁהוּא צַדִּיק חַי הָעוֹלָמִים. וְלָכֵןֹ, אַהֲרֹן אַף עַל גַּב שֶׁהוּא יָמִין, בֵּאֲרוּהוּ רַבּוֹתֵינוּ, אַהֲרֹן שׁוֹשְׁבִין הַגְּבִירָה הָיָה. רוֹעֶה הַנֶּאֱמָן, יַעֲקֹב הוּא הַכּוֹלֵל שְׁלֹשֶׁת הָאָבוֹת, שֶׁבּוֹ רוֹכֵב אָדָם הָרִאשׁוֹן, וְלֹא לְחִנָּם הֵקִימוּ בַּעֲלֵי הַמִּשְׁנָה, יָפְיוֹ שֶׁל יַעֲקֹב כְּיָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן."],[10,"","אָמַר הַמְּנוֹרָה הַקְּדוֹשָׁה, רוֹעֶה הַנֶּאֱמָן, רָאִינוּ שֶׁכָּפַל הַקָּדוֹשׁ בָּרוּךְ הוּא שִׁמְךְ וְאָמַר מֹשֶׁה מֹשֶׁה, לִכְלֹל אוֹתְךְ בַּמֶּרְכָּבָה הָעֶלְיוֹנָה וּבַמֶּרְכָּבָה הַתַּחְתּוֹנָה, לְהַכְלִיל בְּךְ אָדָם הָרִאשׁוֹן מִצִּדּוֹ שֶׁל אַבְרָהָם, וּלְהַכְלִיל בְּךְ חַוָּה מִצַּד שֶׁל אַהֲרֹן דָּוִד וּשְׁלֹמֹה."],[11,"","לָמָּה לֹא כָפַל אֶת שֵׁם יַעֲקֹב כָּךְ? אָמַר לוֹ מְנוֹרָה הַקְּדוֹשָׁה, מִשּׁוּם שֶׁקָּרָא לוֹ יַעֲקֹב וְקָרָא לוֹ יִשְׂרָאֵל. יַעֲקֹב לְשׁוֹן לְשׁוֹן עָקֵב, שֶׁהַיְנוּ נְקֵבָה, שֶׁלָּמַדְנוּ, עֲקֵבוֹ שֶׁל אָדָם הָרִאשׁוֹן מַכְהֶה גַּלְגַּל חַמָּה. וְנִקְרָא יִשְׂרָאֵל, שֶׁשָּׁם רֹאשׁ זָכָר רֹאשׁ לַנְּקֵבָה, שֶׁהַיְנוּ עָקֵב. וְזֶהוּ שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ, (שם ג) הוּא יְשׁוּפְךְ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב, וְזֶה גָּרַם שְׁכִינָה בַּגָּלוּת, שֶׁנֶּאֱמַר בָּהּ (משלי כב) עֵקֶב עֲנָוָה יִרְאַת ה'."]]],[["חָדָא רַבִּי שִׁמְעוֹן וְחַדּוּ מָארֵי מְתִיבְתָּא ואָמְרוּ קַמֵּיהּ. פּוּמָא דִשְׁכִינְתָּא סִינַי, מָאן יָכִיל לְמֵיקָם (קמיה) דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ מְמַלְּלָן בֵּיה וְשִׁתִּין רִבְבָן דִּמְתִיבְתָּא תַתָּאָה מְמַלְלִין בֵּיה וְאוּף שִׁתִּין רִבּוֹא דִּמְתִיבְתָּא עִלָּאָה הֲכִי מְמַלְלִין בֵּיה. עַל פּוּמָךְ אִתְמַר והִנֵּה מַלְאֲכֵי אֱלהִים עוֹלִים וגוֹ'.","דָּבָר אַחֵר וַיַּחֲלוֹם וְהִנֵּה סֻלָּם. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר סִינָ\"י דָא סֻלָּ\"ם וְאִיהוּ קַ\"ל וְרָזָא דְמִלָה (ישעיהו י״ט:א׳) הִנֵּה יְיָ רוֹכֵב עַל ע\"ב קַ\"ל. ע\"ב דָא יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י וְעוֹד יוֹ\"ד. יוֹ\"ד הֵ\"א. יוֹ\"ד הֵ\"א וא\"ו. יוֹ\"ד הֵ\"א וא\"ו הֵ\"א, דָא קַ\"ל. אַתְוון קַדְמָאַן סָלְקִין לְע\"ב אַתְוון דְּאִינוּן תּוֹלָדִין דִּילְהוֹן סָלְקִין קַ\"ל. ע\"ב קַ\"ל מָאתַן וּתְרֵין כְּחֻשְׁבָּן ב\"ר. אֲנְתְ הוּא בָּר, רַעְיָא מְהֵימְנָא עֲלַךְ אִתְמַר (תהלים ב') נַשְׁקוּ בָּר, אֲנְתְ הוּא רַבָּן דְּיִשְׂרָאֵל רָב לְתַתָּא רַבָּן דְּמַלְאֲכֵי הַשָׁרֵת ב\"ר לְעֵילָא בְּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ","(חס\"ר ג\"ם לאשלמא רמ\"ה) עָלַיְיהוּ אִתְמַר לְגַבֵּי מָשִׁיחַ בֶּן יוֹסֵף (שמואל ב י״ב:י״ג) גַּם יְהוָֹ\"ה הֶעְבִיר חֲטָאתְךָ לֹא תָּמוּת. בְּהַאי גָּ\"ם אִתְכַּפָּר דָוִד והָאי אִיהוּ שִׁיעוּרָא דְּחַלָּה מ\"ג בֵּיצִּים וְתוֹסֶפֶת חוֹמֵשׁ בֵּיצָּה רָמִיז (ויקרא ה׳:ט״ז) וחֲמִישִׁיתוֹ יוֹסֵף עַלָּיו.","זַכָּאָה צְּלוֹתָא דְנָפִיק מִפּוּמָךְ כְּגווָֹנָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּנָחִית עַל טוּרָא דְסִינָי וְאִתְּמַר בֵּיה (דברים כ״ט:י״ד) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עוֹמֵד הַיּוֹם וְאֶת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם, הֲכִי כַּד אַתְּ מִשְׁתַּדֵּל בְּאוֹרַיְיתָא וּבִצְּלוֹתָא, קוּדְשָׁא בְּרִיךְ הוּא כָּנִישׁ עִלָּאִין וְתַתָּאִין. וְכָל אִלֵּין נִשְׁמָתִין דַהֲווּ וּדְּעֲתִדִין לְמֶהֱוִי, וְכָל מַשִׁירְיָין דְּמַלְאָכִין. וְנָחִית בְּצּוּלְמָא דִּילָךְ, לְקָבְּלָא צְּלוֹתָא דִּילָךְ, אוֹרַיְיתָא דִּילָךְ. בְּגִין דְּמַחֲשָׁבְתָא דִּילָךְ לְיַחֲדָא לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּכָל מַשִׁירְיָין דִּילֵיהּ לְעֵילָא וְתַתָּא","בְּאוֹרָיְיתָךְ וּבִצְּלוֹתָךְ קוּדְשָׁא בְּרִיךְ הוּא מְצָּרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה. וּכְגַוְונָא דְּאִיהוּ אָמַר אָנֹכִי, וְאִינְהוּ אַמְרִי (שמות כ״ד:ז׳) נַעֲשֶׂה וְנִשְׁמָע. הֲכִי קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד לְכֻלְּהוּ מַשִׁירְיָין וְאִינְהוּ שָׁתְקִין ושָׁמְעִין לְמִלוּלָךְ בְּגִין דִּרְעוּתָךְ בְּהוֹן לְיַחֲדָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ בְּכָל מַשִׁירְיָין דִּילֵיהּ","וְכָל מָה דְּקוּדְשָׁא בְּרִיךְ הוּא אַבְטַח וְאוֹדֵי לְמֶעְבָּד לָךְ חָכְמָה מִכַּמָּה טָבִין דְּלֵית לוֹן סוֹף כֻּלְּהוּ אָמְרִין נַעֲשֶׂה וְנִשְׁמָע. וּבְגִין דָא אֲמְרוּ (תהילים ק״ג:כ׳) בָּרְכוּ יְיָ מַלְאָכָיו גִּבּוֹרֵי כֹּחַ וְגוֹ' וְאִתְתַּקַּף בָךְ דְּהָא קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִנְתֵּיהּ וְכָל מַשִׁירְיָין דִּילֵיהּ וּדְּשְׁכִנְתֵּיהּ אִסְתַּכְּמוּ לְמֶעְבָּד כָּל רְעוּתָךְ, וְיַתִּיר מִדָּאי הוּא כְּתִיב עַל יְדָךְ ולא נָפַל מִלָּה זְעִירָא מִכְּתִיבָת יְדָךְ דְלָא אִתְקָיָּים. זַכָּאָה בַּר נָשׁ דְּמָרֵיהּ חָשִׁיב לֵיהּ כְּגוּפֵיהּ וְעָבִיד לֵיהּ יְקָרָא כְּדִיּוּקְנֵיהּ לְמֶהֱוִי שָׁקִיל מִלּוּלִין דְּפּוּמוֹי בְּאוֹרַיְיתָא בִּצְּלוֹתָא בְּלִימוּד בְּטוּרָא דְסִינָי. וְלֵית חַד דְּפָּתָח פּוּמֵיהּ לְקַטְרְגָא, אֶלָּא עִלָּאִין ותַתָּאִין בְּאַסְכָּמוּתָא חֲדָא בִּרְעוּתָא חֲדָא. ע\"כ: (עד כאן רעיא מהימנא מההשמטות)","וַיִּזְכּוֹר אֱלהִים אֶת רָחֵל, בְּשָׂרָה כְּתִיב פְּקִידָה, וּבְּרָחֵל כְּתִיב זְכִירָה. אַמָּאי, בְּגִין דְּזָכוֹר אִתְרְשִׁים בְּיַעֲקֹב דְּאִיהוּ בְּרִית שָׁלוֹם כָּד אִתְעֲבִיד יוֹסֵף, וּבְמָה כַּד נָטַל שׁוֹר בַּהֲדֵיהּ דְלָא יַתְקִיף לְסִטְרָא אַחֲרָא. וּבְגִין כָּךְ אִתְקְרֵי יוֹסֵף בְּכוֹר, דְּהַהוּא שׁוֹר דְנָטַל, בְּכוֹר שׁוֹרוֹ וַדָּאי, וְהַהוּא שׁוֹר, שׁוֹר תַּם וְיַעֲקֹב אִישׁ תַּם. רִבּוֹן וְשָׁלִיט מָארִיהּ דְּבֵיתָא, דְּהַהוּא שׁוֹר תַּם שָׁארֵי בְּגַוִּיהּ:","לִי הַכֶּסֶף וְלִי הַזָּהָב. מָאי לִי הַכֶּסֶף וְלִי הַזָּהָב, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְמֶלֶךְ שֶׁהָיוּ לוֹ שְׁתֵּי אוֹצָרוֹת, אַחַת שֶׁל כֶּסֶף וְאַחַת שֶׁל זָהָב. שָׂם שֶׁל כֶּסֶף בִּימִינוֹ וְשֶׁל זָהָב בִּשְׂמֹאלוֹ אָמַר זֶה יִהְיֶה מְזוּמָן וְקַל לְהוֹצָאָה וְעוֹשֶׂה דְבָרָיו בְּנָחָת וְהוּא יִהְיֶה דַבֵק עִם הַעֲנִיִּים וּמָנְהִיגָּם בְּנָחָת. כְּהַהִיא דְאַמְרֵינָן, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ נֶאְדָּרִי בַּכֹּחַ. וְאִם שָׂמֵחַ אָדָם בְּחֶלְקוֹ טוֹב,","וְאִם לָאו, (שמות ט״ו:ו׳) יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב. מָאי יְמִינְךָ יְיָ תִּרְעַץ אוֹיֵב, אָמַר לוֹ, זֶה הַזָּהָב דִּכְתִיב לִי הַכֶּסֶף וְלִי הַזָּהָב. לָמָה נִקְרָא שְׁמוֹ זָהָב שְׁבּוֹ כְּלוּלוֹת שְׁלשׁ מִדּוֹת. הַז', ז' מִדּוֹת. הַה', ה' אַחֲדוֹת אַחֲרוֹנוֹת (ס\"א אחרונה) הַב' חָכְמָ\"ה וּבִינָ\"ה וְנִקְרֵאת נְשָׁמָה זוֹ עַל שֵׁם אַצִילוּת ה' סְפִירוֹת אַחֲרוֹנוֹת וְה' שֶׁמוֹת לְנְשָׁמָה (ס\"א נר\"ן ח\"י סימנא נפש רוח נשמה חיה יחידה). רוּחַ, חַיָּה, יְחִידָה, נְשָׁמָה, נֶפֶשׁ.","מָאי עֲבִידְתֵּיהּ כִּסֵּא הִיא ה' לְז'. דִּכְתִיב כִּי גָּבוֹהּ מֵעַל גָּבוֹהּ שׁוֹמֵר וּגְבוֹהִים עֲלֵיהֶם וּב' הִיא קִיוּמָם כְּמָה דְאַתְּ אָמֵר בְּבְּרֵאשִׁית. וּמָאי עֲבִידְתֵּיהּ הַכָא, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה לְאֶחָד שֶׁהָיָה לוֹ בַּת טוֹבָה וּנְעִימָה וּשְלֵמָה וְנָאָה וְהִשִׂיאָה לְבֵן מֶלֶךְ וְהִלְבִּישָׁה וְעִיטְרָה וְקִישְׁטָה וּנְתָּנָה לוֹ עִם מָמוֹן רַב. אָמַר אֶפְשָׁר לְמֶלֶךְ זֶה לָשֶׁבֶת חוּץ מִבֵּיתוֹ, אֲמַרְתָּ לֹא. אֶפְשָׁר לוֹ לָשֶׁבֶת כָּל הַיּוֹם תָּמִיד עִמָּהּ, אֲמַרְתָּ לֹא. הָא כֵּיצָד שָׂם חַלּוֹן בֵּינוֹ לְבֵינָהּ וְכָל שָׁעָה שֶׁצְרִיכָה הַבַּת לְאָבִיהָ אוֹ הָאָב לְבִּתּוֹ מִתְחַבְּרִין יַחַד בַּחַלוֹן. הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:י״ד) כָּל כְּבוּדָה בַּת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ ע\"כ."],[],[[0,"","שָׂמַח רַבִּי שִׁמְעוֹן וְשָׂמְחוּ רָאשֵׁי הַיְשִׁיבָה וְאָמְרוּ לְפָנָיו, פֵּה הַשְּׁכִינָה, סִינַי, מִי יָכוֹל לַעֲמֹד (לפניו), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ מְדַבְּרִים עִמּוֹ, וְשִׁשִּׁים רְבָבוֹת שֶׁל הַיְשִׁיבָה הַתַּחְתּוֹנִים מְדַבְּרִים עִמּוֹ, וְאַף שִׁשִּׁים רִבּוֹא שֶׁל הַיְשִׁיבָה הָעֶלְיוֹנָה כָּךְ מְדַבְּרִים עִמּוֹ. עַל פִּיךְ נֶאֱמַר וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְגוֹמֵר."],[1,"","דָּבָר אַחֵר וַיַּחֲלֹם וְהִנֵּה סֻלָּם. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, סִינַ\"י זֶה סֻלָּם, וְהוּא קַ\"ל, וְסוֹד הַדָּבָר - (ישעיה יט) הִנֵּה ה' רֹכֵב עַל עָ\"ב קַ\"ל. עָב זֶה יוֹ\"ד הֵ\"י וָי\"ו הֵ\"י. וְעוֹד - יוֹ\"ד. יוֹ\"ד הֵ\"א. יוֹ\"ד הֵ\"א וָא\"ו. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א - זֶה מֵאָה וּשְׁלֹשִׁים. הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת עוֹלוֹת לְשִׁבְעִים וּשְׁנַיִם. הָאוֹתִיּוֹת שֶׁהֵן תּוֹלְדוֹתֵיהֶן עוֹלוֹת לְמֵאָה וּשְׁלֹשִׁים. עָ\"ב קַ\"ל מָאתַיִם וּשְׁתַּיִם כְּחֶשְׁבּוֹן בָּ\"ר. אַתָּה הוּא הַבֵּן, הָרוֹעֶה הַנֶּאֱמָן, עָלֶיךְ נֶאֱמַר (תהלים ב) נַשְּׁקוּ בַר. אַתָּה הוּא רַבָּן שֶׁל יִשְׂרָאֵל, גָּדוֹל לְמַטָּה, רַבָּן שֶׁל מַלְאֲכֵי הַשָּׁרֵת, בַּ\"ר לְמַעְלָה, בֵּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ,"],[2,"","(חסר \"גם\" להשלים למאתים ארבעים וחמשה) עֲלֵיהֶם נֶאֱמַר לְגַבֵּי מָשִׁיחַ בֶּן יוֹסֵף (שמות ב) גַּם יְהֹוָ\"ה הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. בַּ\"גַּם\" הַזֶּה הִתְכַּפֵּר דָּוִד, וְזֶהוּ שִׁעוּר שֶׁל הַחַלָּה, אַרְבָּעִים וְשָׁלֹשׁ בֵּיצִים וְתוֹסֶפֶת חֹמֶשׁ בֵּיצָה, רָמוּז (ויקרא ה) וַחֲמִשִׁתָיו יֹסֵף עָלָיו."],[3,"","אַשְׁרֵי הַתְּפִלָּה הַיּוֹצֵאת מִפִּיךְ, כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָרַד עַל הַר סִינַי וְנֶאֱמַר בּוֹ (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ עֹמֵד הַיּוֹם (וגו') וְאֵת אֲשֶׁר אֵינֶנּוּ פֹּה עִמָּנוּ הַיּוֹם, כָּךְ כְּשֶׁאַתָּה מִשְׁתַּדֵּל בְּתוֹרָה וּבִתְפִלָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְכַנֵּס עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָל הַנְּשָׁמוֹת הַלָּלוּ שֶׁהָיוּ וְשֶׁעֲתִידִין לִהְיוֹת, וְכָל מַחֲנוֹת הַמַּלְאָכִים, וְיוֹרֵד בְּצַלְמְךְ לְקַבֵּל תְּפִלָּתְךְ וְתוֹרָתְךְ, מִשּׁוּם שֶׁמַּחֲשַׁבְתְּךְ לְיַחֵד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם שְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ לְמַעְלָה וּלְמַטָּה,"],[4,"","בְּתוֹרָתְךְ וּבִתְפִלָּתְךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה, וּכְמוֹ שֶׁהוּא אָמַר אָנֹכִי, וְהֵם אָמְרוּ (שמות כד) נַעֲשֶׂה וְנִשְׁמָע. כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְכָל הַמַּחֲנוֹת, וְהֵם שׁוֹתְקִים וְשׁוֹמְעִים לִדְבָרְךְ, מִשּׁוּם שֶׁרְצוֹנְךְ בָּהֶם לְיַחֵד הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ בְּכָל הַמַּחֲנוֹת שֶׁלּוֹ. וְכָל מַה שֶּׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִבְטִיחַ וְהוֹדָה לַעֲשׂוֹת לְךְ חָכְמָה מִכַּמָּה טוֹבוֹת שֶׁאֵין לָהֶם סוֹף, כֻּלָּם אוֹמְרִים נַעֲשֶׂה וְנִשְׁמָע."],[5,"","וּמִשּׁוּם זֶה אָמְרוּ (תהלים קג) בָּרְכוּ ה' (כל) מַלְאָכָיו גִּבֹּרֵי כֹחַ וְגוֹמֵר, וְהֶחֱזִיק בְּךְ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ וְכָל הַמַּחֲנוֹת שֶׁלּוֹ וְשֶׁל שְׁכִינָתוֹ הִסְכִּימוּ לַעֲשׂוֹת כָּל רְצוֹנְךְ, וְיוֹתֵר מִדַּאי הוּא כָּתוּב עַל יָדְךְ, וְלֹא נָפַל דָּבָר קָטָן מִכְּתִיבַת יָדְךְ שֶׁלֹּא הִתְקַיֵּם. אַשְׁרֵי הָאִישׁ שֶׁאֲדוֹנוֹ מַחֲשִׁיב אוֹתוֹ כְּגוּפוֹ וְעוֹשֶׂה לוֹ כָּבוֹד כִּדְמוּתוֹ לִהְיוֹת שׁוֹקֵל דִּבְרֵי פִיו בְּתוֹרָה וּבִתְפִלָּה כְּמוֹ לִמּוּד בְּהַר סִינַי, וְאֵין אֶחָד שֶׁפּוֹתֵחַ פִּיו לְקַטְרֵג, אֶלָּא עֶלְיוֹנִים וְתַחְתּוֹנִים בְּהַסְכָּמָה אַחַת בְּרָצוֹן אֶחָד: ע\"כ מההשמטות."],[6,"","וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל. בְּשָׂרָה כָּתוּב פְּקִידָה, וּבְרָחֵל כָּתוּב זְכִירָה, לָמָּה? מִשּׁוּם שֶׁזָּכוֹר נִרְשַׁם בְּיַעֲקֹב שֶׁהוּא בְּרִית שָׁלוֹם כְּשֶׁנַּעֲשָׂה יוֹסֵף, וּבַמֶּה? כְּשֶׁנָּטַל שׁוֹר עִמּוֹ שֶׁלֹּא יֶחֱזַק אוֹתוֹ הַצַּד הָאַחֵר, וְלָכֵן נִקְרָא יוֹסֵף בְּכוֹר, שֶׁאוֹתוֹ שׁוֹר שֶׁנָּטַל בְּכוֹר שׁוֹרוֹ וַדַּאי, וְאוֹתוֹ שׁוֹר שׁוֹר תָּם, וְיַעֲקֹב אִישׁ תָּם רִבּוֹן וְשַׁלִּיט, בַּעַל הַבַּיִת שֶׁאוֹתוֹ שׁוֹר תָּם שׁוֹרֶה בְתוֹכוֹ: רעיא מהימנא פתח רבי שמעון השייךָּ לדף קס\"ה ע\"א אצל ויַעֲקֹב הלךָּ תמצא בחלק ג' דף רכ\"ה ע\"ב"],[7,"","לִי הַכֶּסֶף וְלִי הַזָּהָב. מַה זֶּה לִי הַכֶּסֶף וְלִי הַזָּהָב? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְמֶלֶךְ שֶׁהָיוּ לוֹ שְׁנֵי אוֹצָרוֹת, אֶחָד שֶׁל כֶּסֶף וְאֶחָד שֶׁל זָהָב, שָׂם שֶׁל כֶּסֶף בִּימִינוֹ, וְשֶׁל זָהָב בִּשְׂמֹאלוֹ. אָמַר, זֶה יִהְיֶה מְזֻמָּן וְקַל לְהוֹצָאָה. וְעוֹשֶׂה דְבָרָיו בְּנַחַת, וְהוּא יִהְיֶה דָבֵק עִם הָעֲנִיִּים וּמַנְהִיגָם בְּנַחַת, כְּאוֹתָהּ שֶׁאָמַרְנוּ יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. וְאִם שָׂמֵחַ אָדָם בְּחֶלְקוֹ - טוֹב,"],[8,"","וְאִם לָאו - יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. מַה זֶּה יְמִינְךְ ה' תִּרְעַץ אוֹיֵב? אָמַר לוֹ, זֶה הַזָּהָב, שֶׁכָּתוּב לִי הַכֶּסֶף וְלִי הַזָּהָב. וְלָמָּה נִקְרָא שְׁמוֹ זָהָב? שֶׁבּוֹ כְּלוּלוֹת שָׁלֹשׁ מִדּוֹת. הַז' - שֶׁבַע מִדּוֹת, הַה' - חָמֵשׁ אֲחָדוֹת אַחֲרוֹנוֹת (אחרונה), הַב' - חָכְמָה וּבִינָה. וְנִקְרֵאת נְשָׁמָה זוֹ עַל שֵׁם אֲצִילוּת, חָמֵשׁ סְפִירוֹת אַחֲרוֹנוֹת, וְחָמֵשׁ שֵׁמוֹת לַנְּשָׁמָה (נר\"ן ח\"י הסימן נפש רוח נשמה חיה יחידה) - רוּחַ חַיָּה יְחִידָה נְשָׁמָה נֶפֶשׁ."],[9,"","מַה מַּעֲשֵׂהוּ? כִּסֵּא הִיא ה', לְז', שֶׁכָּתוּב כִּי גָבהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וּגְבהִים עֲלֵיהֶם, וּב' הִיא קִיּוּמָם, כְּמוֹ שֶׁנֶּאֱמַר בִּבְרֵאשִׁית. וּמַה מַּעֲשֵׂהוּ כָּאן? מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְאֶחָד שֶׁהָיָה לוֹ בַּת טוֹבָה וּנְעִימָה וּשְׁלֵמָה וְנָאָה, וְהִשִּׂיאָהּ לְבֶן מֶלֶךְ, וְהִלְבִּישָׁהּ וְעִטְּרָהּ וְקִשְּׁטָהּ, וּנְתָנָהּ לוֹ עִם מָמוֹן רַב. אָמַר, אֶפְשָׁר לְמֶלֶךְ זֶה לָשֶׁבֶת חוּץ מִבֵּיתוֹ? אָמַרְתָּ לֹא. אֶפְשָׁר לוֹ לָשֶׁבֶת כָּל הַיּוֹם תָּמִיד עִמָּהּ? אָמַרְתָּ לֹא. הָא כֵּיצַד? שָׂם חַלּוֹן בֵּינוֹ לְבֵינָהּ, וְכָל שָׁעָה שֶׁצְּרִיכָה הַבַּת לְאָבִיהָ אוֹ הָאָב לְבִתּוֹ, מִתְחַבְּרִים יַחַד בַּחַלּוֹן. זֶהוּ שֶׁכָּתוּב כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה מִמִּשְׁבְּצוֹת זָהָב לְבוּשָׁהּ (ע\"כ). (וכתוב) (וויהם כסף) וְאַדְנֵיהֶם נְחֹשֶׁת, שֶׁהֵם כְּלֵי שִׁמּוּשׁ שֶׁהַמִּשְׁכָּן יִשְׁתַּמֵּשׁ בָּהֶם."]]],[["(וכתיב) (וויהם כסף) (שמות כ״ז:י״ז) וְאֲדְנֵיהֶם נְחשֶׁת דְּאִינוּן מָאנֵי שִׁמוּשָא לְאִשְׁתַּמְשָׁא מַשְׁכְּנָא בְּהוּ. אֲבָל הַכָא בְּאִלֵּין לְבוּשִׁין דִּיְקָר לָא בָּעֵי לְאִשְׁתַּמְשָׁא בְּהוּ בַּר נָשׁ אַחֲרָא בָּר כַּהֲנָא (נ\"א מכהנא) רַבָּא, דְּרְבוּ מְשַׁח קוּדְשָׁא עַל רֵישָׁא. דִּכְתִיב (שמות כ״ח:ב׳) (ועשית) בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךָ לְכָבוֹד וּלְתִפְאָרֶ\"ת, דְּבְּאִינוּן לְבוּשִׁין דָמֵי לְגּווָֹנָא דִּלְעֵילָא:","מַאי פֶּרִי עֵץ הֲדַר אִילָנָא דְּאֶתְרוֹגָּא וּמָאי הֲדַר הַיְינוּ הֲדַר עַל הַכֹּל וְהַיְינוּ הֲדַר דְּשִׁיר הַשִׁירִים דִּכְתִיב בֵּיה (שיר השירים ו׳:י׳) מִי זֹאת הַנִשְׁקַפָה כְּמוֹ שָׁחַר. וְהַיְינוּ עַל שֵׁם נְקֵבָה וְעַל שְׁמָהּ נִלְקְחָה נְקֵבָה מֵאָדָם שְׁאִי אֶפְשָׁר לְהִתְקַיֵּים עוֹלָם הֲתַחְתוֹן בְּלָא נְקֵבָה. וּמָאי טַעְמָא אִקְרֵי נְקֵבָה עַל שֵׁם שֶׁנְקַבֵיהָ רְחֲבִים וְיֵשׁ לָהּ נִקַבִים יֵתְרִים עַל הָאִישׁ. וּמָאי נִינְהוּ נְקַבִים שָׁדַיִם וֻרְחֶם וּבֵית קִיבּוּל הַוְלָד.","וּמָאי נִיהוּ שֶׁאָמְרוּ שִׁיר הַשִׁירִים שֶׁהוּא הֲדַר לְכָל סִפְרֵי הַקֹּדֶשׁ אִין דְּאָמַר רַבִּי יוֹחָנָן כָּל הַסְפָרִים קֹדֶשׁ וְשִׁיר הַשִׁירִים קֹדֶשׁ קֳדָשִׁים, וּמָאי נִיהוּ קֹדֶשׁ קֳדָשִׁים. אֶלָּא קֹדֶשׁ, שֶׁהוּא קֹדֶשׁ לְקֳדָשִׁים. וּמָאי הֵם קֳדָשִׁים אֵלּוּ שֶׁכְּנֶגֶד שֵׁשׁ קְצָווֹת שֶׁבַּאָדָם וְקֹדֶשׁ הֲוֵי לְהוּ קֹדֶשׁ לְכֻלְּהוּ.","וּמָאי נִיהוּ קֹדֶשׁ זֶה, אֶתְרוֹג שֶׁהוּא הֲדַר הַכֹּל. וְלָמָּה נִקְרָא שְׁמוֹ הֲדַר אַל תִקְרֵי הֲדַר אֶלָּא ה' דָר זֶה אֶתְרוֹג שֶׁהוּא נִפְרָד מֵאֶגֶד הַלוּלָב וְאֵין מִצְוַת לוּלָב קַיְימֶת אֶלָּא בּוֹ, וְהוּא גַּם כֵּן אֲגּוּד עִם הַכֹּל. שְׁעִם כָּל אֶחָד הוּא וְעִם כּוּלָן יַחַד הוּא.","וּמָאי לוּלָב כְּנֶגֶד חוּט הַשִּׂדְרָה. וְעַנָף עֵץ עֲבוֹת שְׁעֲנָפָיו חוֹפִין אֶת רוּבּוֹ וְאִם אֵין עֲנָפָיו חוֹפִין אֶת רוּבּוֹ אֵינוֹ כְּלוּם. מִפְּנֵי מָה, מָשָׁל לְאָדָם שְׁבִּזְרוֹעוֹתָיו יָגֵן עַל רֹאשׁוֹ הֲרֵי זְרוֹעוֹתָיו שְׁנַיִם וְרֹאשׁוֹ שְׁלשָׁה וְהַיְינוּ עֲנָף לִשְׂמֹאל עֲבוֹת לְיָמִין וְנִמְצָא עֵץ בְּאֶמְצַע. וְלָמָּה נֶּאֱמַר בּוֹ עֵץ שֶׁהוּא שֹׁרֶשׁ הֲאִילָן.","וּמָאי עַרְבֵי נַחַל שׁוֹקֵי הַאָדָם שֶׁהֵם שְׁתַּיִם. וּמָאי נִינְהוּ לִישָׁנָא דְּעֲרְבֵי נַחַל, מִשׁוּם דְּגָדוֹל שֶׁבָּהֶם הֲוֵי לְמַעֲרָב וּמִשָׁם יוֹנֵק כֹּחוֹ. וְשֶׁל צָפוֹן הוּא קָטָן מִמֶּנּוּ מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה וְהוּא בְּרוּחַ צְפוֹנִית מָעֲרָבִית וּבוֹ פּוֹעֵל וְנִקְרָא עַל שְׁמוֹ וְהֵם שְׁנֵיהֶם עֵצִים.","דָבָר אַחֵר עַרְבֵי שְׁפְּעֲמִים מֵעַרְבִין פְּעוּלָתָן זֶה עִם זֶה מָאי עַרְבֵי נַחַל, נַחַל הֲוִי עַל שֵׁם הַמָּקוֹם שֶׁהֵם קְבוּעִים בּוֹ שֶׁשְׁמוֹ נַחַל כְּדִכְתִיב (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. מָאי נִיהוּ יָם, הֱוֵי אוֹמֶר זֶה אֶתְרוֹג. וּמְנָא לָן דְּכָל מִדָּה וּמִדָּה מֵאֶלוּ הַשִׁבְעָה אִיקְרֵי נַחַל שְׁנְּאֱמַר (במדבר כ״א:י״ט) וּמְמָתַנָה נָחֲלִיאֵל אַל תִקְרֵי נָחֲלִיאֵל אֶלָּא נַחֲלֵי אֵל.","וְעוֹד שָׁם, מָה לֵב, הֲדַר פֶּרִי הַגּוּף, אַף יִשְׂרָאֵל פֶּרִי עֵץ הֲדַר. מָה אִילָן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בְּאֶמְצַע, אַף יִשְׂרָאֵל נָטְלוּ גּוּף הֲאִילָן הַזֶּה שֶׁהוּא לִבּו וּכְּנְגֶד הַגּוּף חוּט הַשִּׂדְרָה בָּאָדָם שֶׁהוּא עִיקָר הַגּוּף. וּמָה לוּלָב זֶה כְּתִיב לוֹ לֵב אַף לֵב מָסוּר לוֹ. וּמָה לֵב זֶה שְׁלשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בּוֹ, אַף בְּכָל נְתִיב מֶהֵן צוּרָה שׁוֹמֶרֶת שְׁנֶּאֱמַר (בראשית ג׳:כ״ד) לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים:"],[],[[0,"","אֲבָל כָּאן בִּלְבוּשֵׁי הַכָּבוֹד הַלָּלוּ לֹא צָרִיךְ לְהִשְׁתַּמֵּשׁ בָּהֶם אִישׁ אַחֵר פְּרָט כֹּהֵן (מהכהן) הַגָּדוֹל, שֶׁשֶּׁמֶן מִשְׁחַת קֹדֶשׁ עַל רֹאשׁוֹ, שֶׁכָּתוּב (ועשית) בִּגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךְ לְכָבוֹד וּלְתִפְאָרֶת, בְּאוֹתָם לְבוּשִׁים דּוֹמֶה לְגָוֶן עֶלְיוֹן: ע\"כ מההשמטות"],[1,"","מַהוּ פְּרִי עֵץ הָדָר? עֵץ הָאֶתְרוֹג. וּמַהוּ הָדָר? הָדָר עַל הַכֹּל, וְהַיְנוּ הָדָר שֶׁל שִׁיר הַשִּׁירִים, שֶׁכָּתוּב בּוֹ מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר. וְהַיְנוּ עַל שֵׁם נְקֵבָה, וְעַל שְׁמָהּ נִלְקְחָה נְקֵבָה מֵאָדָם שֶׁאִי אֶפְשָׁר לְהִתְקַיֵּם עוֹלָם הַתַּחְתּוֹן בְּלֹא נְקֵבָה. וּמָה הַטַּעַם נִקְרֵאת נְקֵבָה? עַל שֵׁם שֶׁנְּקָבֶיהָ רְחָבִים, וְיֵשׁ לָהּ נְקָבִים יְתֵרִים עַל הָאִישׁ, וּמַה הֵם הַנְּקָבִים: שָׁדַיִם וָרֶחֶם וּבֵית קִבּוּל הַוָּלָד."],[2,"","וּמַה שֶׁאָמְרוּ, שִׁיר הַשִּׁירִים שֶׁהוּא הָדָר לְכָל סִפְרֵי הַקֹּדֶשׁ - כֵּן. שֶׁאָמַר רַבִּי יוֹחָנָן, כָּל הַסְּפָרִים קֹדֶשׁ, וְשִׁיר הַשִּׁירִים קֹדֶשׁ קָדָשִׁים. וּמַהוּ קֹדֶשׁ קָדָשִׁים? אֶלָּא קֹדֶשׁ שֶׁהוּא קֹדֶשׁ לְקָדָשִׁים. וּמַה הֵם קָדָשִׁים? אֵלּוּ שֶׁכְּנֶגֶד שֵׁשׁ קְצָווֹת שֶׁבָּאָדָם, וְקֹדֶשׁ יִהְיֶה לָהֶם קֹדֶשׁ לְכֻלָּם."],[3,"","וּמַהוּ קֹדֶשׁ? זֶה אֶתְרוֹג, שֶׁהוּא הָדָר לַכֹּל. וְלָמָּה נִקְרָא שְׁמוֹ הָדָר? אַל תִּקְרֵי הָדָר אֶלָּא ה' דָּר, זֶה אֶתְרוֹג שֶׁהוּא נִפְרָד מֵאֶגֶד הַלּוּלָב, וְאֵין מִצְוַת לוּלָב קַיֶּמֶת אֶלָּא בּוֹ, וְהוּא גַּם כֵּן אָגוּד עִם הַכֹּל, שֶׁעִם כָּל אֶחָד הוּא, וְעִם כֻּלָּם יַחַד הוּא."],[4,"","וּמַהוּ הַלּוּלָב? כְּנֶגֶד חוּט הַשִּׁדְרָה. וַעֲנַף עֵץ עָבת - שֶׁעֲנָפָיו חוֹפִים אֶת רֻבּוֹ, וְאִם אֵין עֲנָפָיו חוֹפִים אֶת רֻבּוֹ - אֵינוֹ כְלוּם. מִפְּנֵי מָה? מָשָׁל לְאָדָם שֶׁבִּזְרוֹעוֹתָיו יָגֵן עַל רֹאשׁוֹ, הֲרֵי זְרוֹעוֹתָיו שְׁנַיִם וְרֹאשׁוֹ שְׁלֹשָׁה, וְהַיְנוּ עָנָף לִשְׂמֹאל, עָבֹת לְיָמִין, וְנִמְצָא עֵץ בָּאֶמְצַע. וְלָמָּה נֶאֱמַר בּוֹ עֵץ? שֶׁהוּא שֹׁרֶשׁ הָאִילָן."],[5,"","וּמַה זֶּה עַרְבֵי נָחַל? שׁוֹקֵי הָאָדָם שֶׁהֵם שְׁתַּיִם. וּמַהוּ לָשׁוֹן שֶׁל עַרְבֵי נָחַל? מִשּׁוּם שֶׁגָּדוֹל שֶׁבָּהֶם הוּא לַמַּעֲרָב, וּמִשָּׁם יוֹנֵק כֹּחוֹ, וְשֶׁל צָפוֹן הוּא קָטָן מִמֶּנּוּ מַהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנָה, וְהוּא בְּרוּחַ צְפוֹנִית מַעֲרָבִית, וּבוֹ פוֹעֵל וְנִקְרָא עַל שְׁמוֹ, וְהֵם שְׁנֵיהֶם עֵצִים."],[6,"","דָּבָר אַחֵר עַרְבֵי - שֶׁפְּעָמִים מְעָרְבִים פְּעֻלָּתָם זֶה עִם זֶה. מַה זֶּה עַרְבֵי נָחַל? נַחַל הוּא עַל שֵׁם הַמָּקוֹם שֶׁהֵם קְבוּעִים בּוֹ שֶׁשְּׁמוֹ נַחַל, כְּמוֹ שֶׁכָּתוּב כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם. מַהוּ יָם? הֱוֵי אוֹמֵר זֶה אֶתְרוֹג. וּמִנַּיִן לָנוּ שֶׁכָּל מִדָּה וּמִדָּה מֵאֵלּוּ הַשִּׁבְעָה נִקְרֵאת נַחַל? שֶׁנֶּאֱמַר וּמִמַּתָּנָה נַחֲלִיאֵל, אַל תִּקְרֵי נַחֲלִיאֵל אֶלָּא נַחֲלֵי אֵל."],[7,"","וְעוֹד שָׁם, מָה לֵּב, הָדָר פְּרִי הַגּוּף, אַף יִשְׂרָאֵל פְּרִי עֵץ הָדָר. מָה אִילַן תָּמָר, עֲנָפָיו סְבִיבָיו וְלוּלָבוֹ בָּאֶמְצַע, אַף יִשְׂרָאֵל נָטְלוּ גוּף הָאִילָן הַזֶּה שֶׁהוּא לִבּוֹ, וּכְנֶגֶד הַגּוּף חוּט הַשִּׁדְרָה בָּאָדָם שֶׁהוּא עִקַּר הַגּוּף. וּמַה לּוּלָב זֶה כָּתוּב לוֹ לֵב, אַף לֵב מָסוּר לוֹ. וּמַה לֵּב זֶה שְׁלֹשִׁים וּשְׁתַּיִם נְתִיבוֹת חָכְמָה בּוֹ, אַף בְּכָל נָתִיב מֵהֶן צוּרָה שׁוֹמֶרֶת, שֶׁנֶּאֱמַר לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים: ע\"כ מההשמטות"]]]]};
